insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَمَ: أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ، قَالَ: مَا لَهُ؟ مَا لَهُ؟ وَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَرَبٌ مَا لَهُ، تَعْبُدُ اللَّهَ وَلَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصِلُ الرَّحِمَ". (خ)', 'അബുഅയ്യുബ്(റ): ഒരാൾ നബി(സ)യുടെയടുക്കൽ വന്നുകൊണ്ട് പറഞ്ഞു: സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാൻ എന്നെ സഹായിക്കുന്ന ഒരു സുകൃതം അവിടന്ന് പറഞ്ഞുതന്നാലും. ''അയാൾക്കെന്തുപറ്റി? അയാൾക്കെന്തുപറ്റി?'' എന്ന് സദസ്യരിൽ ചിലർ ചോദിക്കാൻ തുടങ്ങി. ഇതു കേട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അവനെന്തോ ഒരാവശ്യമുണ്ട്." അവിടന്ന് ഉപദേശിച്ചു: "നീ അല്ലാഹുവിന് ഇബാദത്ത് ചെയ്യുക, അവനോട് ഒരു വസ്തുവിനെയും പങ്കുചേർക്കാതിരിക്കുക, നിസ്കാരം നിലനിർത്തുക. സകാത്ത് നൽകുക, കുടുംബബന്ധം പുലർത്തുക." (ബു)', 'أَبِي أَيُّوبَ', 'അബുഅയ്യുബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أَعْرَابِيًّا أَتَى النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَقَالَ: دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ دَخَلْتُ الْجَنَّةَ، قَالَ: "تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ الْمَكْتُوبَةَ، وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومُ رَمَضَانَ". قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لَا أَزِيدُ عَلَى هَذَا، فَلَمَّا وَلَّى قَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ فَلْيَنْظُرْ إِلَى هَذَا". (خ)', 'അബുഹുറൈറ(റ): ഒരു ഗ്രാമീണൻ തിരുമേനി(സ)യുടെയടുക്കൽ വന്ന് പറഞ്ഞു: സ്വർഗത്തിൽ പ്രവേശിക്കാൻ എന്നെ സഹായിക്കുന്ന ഒരു കർമ്മം പറഞ്ഞുതന്നാലും. നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിന് ഇബാദത്തു ചെയ്യുക, അവനോട് ഒന്നിനെയും പങ്ക് ചേർക്കാതിരിക്കുക, നിർബന്ധനിസ്കാരം നിലനിർത്തുക, നിർബന്ധമായ സകാത്ത് നൽകുക, റമളാനിൽ നോമ്പനുഷ്ഠിക്കുക." അപ്പോഴദ്ദേഹം പറഞ്ഞു: എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനിൽ സത്യം, ഇതിൽ കൂടുതലായി ഞാനൊന്നും ചെയ്യില്ല, അദ്ദേഹം പോകുമ്പോൾ പ്രവാചകർ(സ) പറഞ്ഞു: "ഒരു സ്വർഗ്ഗാവകാശിയെ കാണാൻ ആരെങ്കിലും ആഗ്രഹിക്കുന്നുവെങ്കിൽ അദ്ദേഹത്തെ നോക്കിക്കൊള്ളട്ടെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يَقْبَلُ الصَّدَقَةَ وَيَأْخُذُهَا بِيَمِينِهِ، فَيُرَبِّيهَا لِأَحَدِكُمْ كَمَا يُرَبِّي أَحَدُكُمْ مُهْرَهُ، حَتَّى إِنَّ اللُّقْمَةَ لَتَصِيرُ مِثْلَ أُحُدٍ". وَتَصْدِيقُ ذَلِكَ فِي كِتَابِ اللَّهِ عَزَّ وجَلَّ: {أَلَمْ يَعْلَمُوا أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَأْخُذُ الصَّدَقَاتِ} وَ: {يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ}. [البقرة: ٢٧٦] (ت)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ദാനധർമ്മം സ്വീകരിക്കുകയും അത് വലതുകൈകൊണ്ട് ഏറ്റെടുക്കുകയും ചെയ്യും. എന്നിട്ടു നിങ്ങളിലൊരാൾ തന്റെ അരുമസന്താനത്തെ പോറ്റിവളർത്തുംപോലെ അതിനെ നിങ്ങൾക്കായി അവൻ വളർത്തിക്കൊണ്ടുവരും. അങ്ങനെ ഒരു പിടി ദാനം ചെയ്തത് അല്ലാഹുവിങ്കൽ ഉഹ്ദ് മല(വലിയമല)യോളമാകും." ഇതിന്റെ സ്ഥിരീകരണം ഖുർആനിലെ ഈ സൂക്തങ്ങളിൽ കാണാം: (അല്ലാഹു തന്നെയാണ് തന്റെ ദാസന്മാരുടെ പശ്ചാത്താപം സ്വീകരിക്കുന്നതും, ദാനധർമ്മങ്ങൾ ഏറ്റുവാങ്ങുന്നതും എന്ന് അവർ മനസ്സിലാക്കിയിട്ടില്ലേ?) (അല്ലാഹു പലിശയെ ക്ഷയിപ്പിക്കുകയും ദാനധർമ്മങ്ങളെ പോഷിപ്പിക്കുകയും ചെയ്യും.) (തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], 'البقرة: ٢٧٦', null, 145, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: أَيُّ الصَّوْمِ أَفْضَلُ بَعْدَ رَمَضَانَ؟ فَقَالَ: "شَعْبَانُ لِتَعْظِيمِ رَمَضَانَ". قِيلَ: فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "صَدَقَةٌ فِي رَمَضَانَ". (ت)', 'അനസ്(റ): റമളാൻ കഴിഞ്ഞാൽ ഏറ്റവും പുണ്യമുള്ള നോമ്പേതാണെന്നു ചോദിക്കപ്പെട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "റമളാന്റെ മഹത്വത്താൽ ശഅ്ബാനിലെ നോമ്പാണ്". വീണ്ടും ചോദിക്കപ്പെട്ടു: ഏതു ദാനമാണ് ഏറ്റവും പുണ്യകരം? നബി(സ) പറഞ്ഞു: "റമദാനിലെ ദാനധർമ്മമാണ്". (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "إِنَّ الصَّدَقَةَ لَتُطْفِئُ غَضَبَ الرَّبِّ، وَتَدْفَعُ عَنْ مِيتَةِ السُّوءِ". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, ദാനം ദൈവകോപത്തെ അണച്ചുകളയുകയും, ദുർമരണത്തെ പ്രതിരോധിക്കുകയും ചെയ്യുന്നു." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ أَزْوَاجَ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ اجْتَمَعْنَ عِنْدَهُ فَقُلْنَ: أَيَّتُنَا بِكَ أَسْرَعُ لُحُوقًا؟ فَقَالَ: "أَطْوَلُكُنَّ يَدًا". فَأَخَذْنَ قَصَبَةً فَجَعَلْنَ يَذْرَعْنَهَا، فَكَانَتْ سَوْدَةُ أَسْرَعَهُنَّ بِهِ لُحُوقًا، فَكَانَتْ أَطْوَلَهُنَّ يَدًا، فَكَانَ ذَلِكَ مِنْ كَثْرَةِ الصَّدَقَةِ. (خ,ن)', 'ആഇശ(റ): പ്രവാചകപത്നിമാർ നബി(സ)യുടെ അടുത്ത് ഒരുമിച്ചുകൂടി അവിടത്തോടു ചോദിച്ചു: നബിയേ, ഞങ്ങളിൽ ആരാണ് (മരണാനന്തരം) ആദ്യമായി അവിടത്തോട് ചേരുക? നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ കൂടുതൽ കൈ നീളമുള്ളവൾ." അങ്ങനെ അവർ ഒരു മുളക്കഷ്ണമെടുത്ത് നീളമളക്കാൻ തുടങ്ങി. അവരിൽ സൗദ(റ)യായിരുന്നു ഏറ്റവുമാദ്യം നബിയോടു ചേർന്നത്. അവർ തന്നെയായിരുന്നു അവരിൽ കൂടുതൽ കൈ നീളമുള്ളവർ, ദാനധർമ്മങ്ങൾ അധികരിപ്പിച്ചതുകൊണ്ടായിരുന്നു അത്. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَا تَصَدَّقَ أَحَدٌ بِصَدَقَةٍ مِنْ طَيِّبٍ، وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبَ، إِلَّا أَخَذَهَا الرَّحْمَنُ بِيَمِينِهِ وَإِنْ كَانَتْ تَمْرَةً، فَتَرْبُو فِي كَفِّ الرَّحْمَنِ حَتَّى تَكُونَ أَعْظَمَ مِنَ الْجَبَلِ، وَيُرَبِّيهَا لَهُ كَمَا يُرَبِّي أَحَدُكُمْ فُلُوَّهُ أَوْ فَصِيلَهُ". (ق,ت,ن,جه)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവരും തന്റെ പരിശുദ്ധമായ – പരിശുദ്ധമല്ലാത്തത് അല്ലാഹു സ്വീകരിക്കില്ല – ധനത്തിൽ നിന്ന് ഒരു കാരക്കയോളം ദാനം ചെയ്താലും അല്ലാഹു അവന്റെ വലതുകൈ കൊണ്ടതിനെ സ്വീകരിക്കും. പിന്നീട് അല്ലാഹുവിന്റെ കരങ്ങളിൽ മലയെക്കാൾ വലുതായി അത് വളരും. നിങ്ങളിലൊരാൾ തന്റെ സന്താനത്തെ വളർത്തിക്കൊണ്ടുവരുന്നതുപോലെ അല്ലാഹു അതിനെ വളർത്തിക്കൊണ്ടിരിക്കും." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ، لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ: فَيَنْظُرُ أَمَامَهُ فَتَسْتَقْبِلُهُ النَّارُ، وَيَنْظُرُ عَنْ أَيْمَنَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ، وَيَنْظُرُ عَنْ أَشْأَمَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ، فَمَن اسْتَطَاعَ مِنْكُمْ أَنْ يَتَّقِيَ النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَلْيَفْعَلْ". (جه)', 'അദിയ്യുബ്നു ഹാതിം(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളോരോരുത്തരോടും (വിധിനാളിൽ) അല്ലാഹു സംസാരിക്കാതിരിക്കില്ല. നിങ്ങളുടെയും അവന്റെയുമിടയിൽ ഒരു പരിഭാഷകൻ ഉണ്ടാവില്ല. മുന്നോട്ടു നോക്കുമ്പോൾ നരകമാണവനെ അഭിമുഖീകരിക്കുന്നത്. വലതുവശത്തേക്ക് നോക്കുമ്പോൾ അവൻ ചെയ്ത പ്രവർത്തനങ്ങളാണുള്ളത്. ഇടത്തോട്ടുനോക്കുമ്പോൾ അവൻ ചെയ്ത പ്രവർത്തനങ്ങളാണുള്ളത്. അതിനാൽ നിങ്ങളിൽ ഒരു കാരക്കച്ചുള കൊണ്ടെങ്കിലും നരകം സൂക്ഷിക്കാൻ കഴിയുന്നവർ അതു ചെയ്തുകൊള്ളട്ടെ." (ജ)', 'عَدِيِّ بْنِ حَاتِمٍ قَالَ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 146, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ نُودِيَ فِي الْجَنَّةِ: يَا عَبْدَ اللَّهِ هَذَا خَيْرٌ، فَمَنْ كَانَ مِنْ أَهْلِ الصَّلَاةِ دُعِيَ مِنْ بَابِ الصَّلَاةِ، وَمَنْ كَانَ مِنْ أَهْلِ الْجِهَادِ دُعِيَ مِنْ بَابِ الْجِهَادِ، وَمَنْ كَانَ مِنْ أَهْلِ الصَّدَقَةِ دُعِيَ مِنْ بَابِ الصَّدَقَةِ، وَمَنْ كَانَ مِنْ أَهْلِ الصِّيَامِ دُعِيَ مِنْ بَابِ الرَّيَّانِ". قَالَ أَبُو بَكْرٍ الصِّدِّيقُ: يَا رَسُولَ اللَّهِ، مَا عَلَى أَحَدٍ يُدْعَى مِنْ تِلْكَ الْأَبْوَابِ مِنْ ضَرُورَةٍ، فَهَلْ يُدْعَى أَحَدٌ مِنْ تِلْكَ الْأَبْوَابِ كُلِّهَا؟ قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "نَعَمْ، وَأَرْجُو أَنْ تَكُونَ مِنْهُمْ". وَفِي رِوَايَةٍ: يَعْنِي أَبَا بَكْرٍ. (م,ن)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ആരെങ്കിലും ഒരു ജോടി കുതിരകളെ ചെലവഴിച്ചാൽ സ്വർഗ്ഗത്തിൽ അവനോടു പറയപ്പെടും: അല്ലാഹുവിന്റെ ദാസാ, ഇതാണു നിനക്കു ഗുണകരം. അവൻ നിസ്കരിക്കുന്നവരുടെ കൂട്ടത്തിലാണെങ്കിൽ നിസ്കാരത്തിന്റെ കവാടത്തിലൂടെ അവനെ വിളിക്കപ്പെടും. ജിഹാദി(ധർമ്മസമരം)ന്റെയാളാണ് അവനെങ്കിൽ ജിഹാദിന്റെ കവാടത്തിലൂടെയാവും അവൻ വിളിക്കപ്പെടുക. അയാൾ ധർമ്മം ചെയ്തവരുടെ കൂട്ടത്തിലാണെങ്കിൽ അതിന്റെ കവാടത്തിലൂടെ വിളിക്കപ്പെടും, അവൻ നോമ്പനുഷ്ഠിക്കുന്നവരിൽ പെട്ടവനാണെങ്കിൽ ''റയ്യാൻ'' എന്ന കവാടത്തിലൂടെയാവും അവൻ വിളിക്കപ്പെടുക." അപ്പോൾ അബുബക്കർ സിദ്ദീഖ്(റ) ചോദിച്ചു: റസൂലേ, ആ കവാടങ്ങളിലൂടെ വിളിക്കപ്പെടുന്ന ഒരാൾക്കും പ്രയാസമേതുമുണ്ടാവുകയില്ല. എന്നാൽ മുഴുവൻ കവാടങ്ങളിലൂടെയും ആരെങ്കിലും വിളിക്കപ്പെടുമോ പ്രവാചകരേ? നബി(സ) പറഞ്ഞു: "അതെ, വിളിക്കപ്പെടും; താങ്കൾ അത്തരക്കാരുടെ കൂട്ടത്തിൽപ്പെട്ടവരാകാൻ ഞാൻ ആഗ്രഹിക്കുന്നു." മറ്റൊരു നിവേദനത്തിൽ: അഥവാ അബുബക്കർ(റ). (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: يَعْنِي أَبَا بَكْرٍ. (م,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: അഥവാ അബുബക്കർ(റ). (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَنْ أَصْبَحَ مِنْكُمُ الْيَوْمَ صَائِمًا". قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَا، قَالَ: "فَمَنْ تَبِعَ مِنْكُمُ الْيَوْمَ جَنَازَةً". قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَا، قَالَ: "فَمَنْ أَطْعَمَ مِنْكُمُ الْيَوْمَ مِسْكِينًا". قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَا، قَالَ: "فَمَنْ عَادَ مِنْكُمُ الْيَوْمَ مَرِيضًا". قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَا اجْتَمَعْنَ فِي امْرِئٍ إِلَّا دَخَلَ الْجَنَّةَ". (م)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇന്നു നിങ്ങളിലാരെങ്കിലും നോമ്പുകാരുണ്ടോ?" അബുബക്കർ(റ) പറഞ്ഞു: അതെ, ഞാനുണ്ട് പ്രവാചകരേ. പ്രവാചകർ(സ) വീണ്ടും ചോദിച്ചു: "ഇന്നു മയ്യിത്തിനെ അനുഗമിച്ചവർ നിങ്ങളിൽ ആരുണ്ട്?" അബുബക്കർ(റ) പറഞ്ഞു: ഞാനുണ്ട്. പ്രവാചകർ(സ) വീണ്ടും ചോദിച്ചു: "എങ്കിൽ നിങ്ങളിൽ ഇന്ന് പാവപ്പെട്ടവന്ന് ഭക്ഷണം നൽകിയ വ്യക്തി ആരാണ്?" അബുബക്കർ(റ): ഞാൻ. വീണ്ടും പ്രവാചകർ ചോദിച്ചു: "നിങ്ങളിലാരാണ് ഇന്ന് രോഗിയെ സന്ദർശിച്ചവർ?" അബുബക്കർ(റ) പറഞ്ഞു: ഞാൻ. അപ്പോൾ പ്രവാചകർ(സ) പറഞ്ഞു: "ഇവയെല്ലാം ചെയ്ത ഒരാൾക്ക് സ്വർഗ്ഗപ്രവേശം ഉറപ്പാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَى كُلِّ مُسْلِمٍ صَدَقَةٌ". فَقَالُوا: يَا نَبِيَّ اللَّهِ فَمَنْ لَمْ يَجِدْ؟ قَالَ: "يَعْمَلُ بِيَدِهِ فَيَنْفَعُ نَفْسَهُ وَيَتَصَدَّقُ". قَالُوا: فَإِنْ لَمْ يَجِدْ؟ قَالَ: "يُعِينُ ذَا الْحَاجَةِ الْمَلْهُوفَ". قَالُوا: فَإِنْ لَمْ يَجِدْ؟ قَالَ: "فَلْيَعْمَلْ بِالْمَعْرُوفِ، وَلْيُمْسِكْ عَنِ الشَّرِّ، فَإِنَّهَا لَهُ صَدَقَةٌ". (خ)', 'അബുമൂസ(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ മുസ്‌ലിമും ദാനധർമ്മം ചെയ്യൽ അനിവാര്യമാണ്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ദാനം ചെയ്യാൻ കഴിവില്ലാത്തവൻ എന്തു ചെയ്യും? നബി(സ) പറഞ്ഞു: "അവൻ സ്വകരങ്ങളാൽ അദ്ധ്വാനിച്ചു സ്വയം ഉപകാരംചെയ്തു ധർമ്മം ചെയ്തുകൊള്ളട്ടെ." അവർ ചോദിച്ചു: അതിനും കഴിഞ്ഞില്ലെങ്കിലോ? നബി(സ) പറഞ്ഞു: "അവൻ പ്രയാസമനുഭവിക്കുന്ന ആവശ്യക്കാരെ സഹായിച്ചുകൊള്ളട്ടെ." അവർ ചോദിച്ചു: അതിനും കഴിഞ്ഞില്ലെങ്കിലോ? നബി(സ) പറഞ്ഞു: "അവൻ നല്ലതു പ്രവർത്തിക്കുകയും ചീത്ത പ്രവർത്തനങ്ങൾ നിയന്ത്രിക്കുകയും ചെയ്യട്ടെ. അങ്ങനെ ചെയ്യൽ അവന്ന് സ്വദഖ(ധർമ്മം)യാണ്." (ബു)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ مَعْرُوفٍ صَدَقَةٌ". (م)', 'ഹുദൈഫ(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ നല്ല കാര്യങ്ങളും സ്വദഖ(ധർമ്മം)യാണ്." (മു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَى كُلِّ مُسْلِمٍ صَدَقَةٌ". قِيلَ: أَرَأَيْتَ إِنْ لَمْ يَجِدْهَا؟ قَالَ: "يَعْتَمِلُ بِيَدِهِ فَيَنْفَعُ نَفْسَهُ وَيَتَصَدَّقُ". قِيلَ: أَرَأَيْتَ إِنْ لَمْ يَفْعَلْ؟ قَالَ: "يُعِينُ ذَا الْحَاجَةِ الْمَلْهُوفَ". قِيلَ: فَإِنْ لَمْ يَفْعَلْ؟ قَالَ: "يَأْمُرُ بِالْخَيْرِ". قِيلَ: أَرَأَيْتَ إِنْ لَمْ يَفْعَلْ؟ قَالَ: "يُمْسِكُ عَنِ الشَّرِّ، فَإِنَّهَا صَدَقَةٌ". (ن)', 'അബുമൂസ(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ മുസ്‌ലിംകളും ദാനം നൽകൽ അനിവാര്യമാണ്." ചോദിക്കപ്പെട്ടു: ദാനം നൽകാനൊന്നും ലഭിച്ചില്ലെങ്കിലോ നബിയേ? നബി(സ) പറഞ്ഞു: "സ്വന്തം കൈകൊണ്ടദ്ധ്വാനിക്കുകയും അതിൽ നിന്നുപയോഗിക്കുകയും ദാനം ചെയ്യുകയും ചെയ്യുക. അതും ചെയ്തില്ലെങ്കിലോ നബിയേ? നബി(സ) പറഞ്ഞു: "ബുദ്ധിമുട്ടുന്ന ആവശ്യക്കാരെ സഹായിക്കുക." ചോദിക്കപ്പെട്ടു: അതും ചെയ്തില്ലെങ്കിലോ നബിയേ? നബി(സ) പറഞ്ഞു: "നന്മകൊണ്ട് കൽപിക്കുക." ചോദിക്കപ്പെട്ടു: നബിയേ, അതും ചെയ്തില്ലെങ്കിലോ? നബി(സ) പറഞ്ഞു: "ഉപദ്രവം ചെയ്യാതിരിക്കുക. നിശ്ചയം, അതൊരു സ്വദഖയാണ്." (ന)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَاسًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالُوا لِلنَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ، قَالَ: "أَوَ لَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟". إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ". قَالُوا: يَا رَسُولَ اللَّهِ، أَيَأْتِي أَحَدُنَا شَهْوَتَهُ، وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: "أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ، أَكَانَ عَلَيْهِ فِيهَا وِزْرٌ؟ فَكَذَلِكَ إِذَا وَضَعَهَا فِي الْحَلَالِ كَانَ لَهُ أَجْرًا". (م)', 'അബുദർറ(റ): പ്രവാചകാനുചരരിൽ ചിലർ നബി(സ)യോടു പറഞ്ഞു: നബിയേ, പ്രതിഫലങ്ങളെല്ലാം സമ്പന്നർ കൊണ്ടുപോയി. ഞങ്ങൾ നിസ്കരിക്കുന്നതുപോലെ അവരും നിസ്കരിക്കുന്നു. ഞങ്ങൾ നോമ്പനുഷ്ഠിക്കുന്നതു പോലെ അവരും നോമ്പനുഷ്ഠിക്കുന്നു. അവരുടെ സമ്പത്തിൽനിന്നവർ ദാനം ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "ദാനം ചെയ്യാനുള്ള വസ്തു നാഥൻ നിങ്ങൾക്കും നൽകിയിട്ടില്ലേ?. എല്ലാ തസ്ബീഹുകളും തക്ബീറുകളും സ്തുതികളും ദാനമാണ്. എല്ലാ തഹ്‌ലീലുകളും സ്വദഖയാണ്. നന്മ കൽപിക്കലും തിന്മ വിരോധിക്കലും ദാനമാണ്. നിങ്ങളുടെ ഭാര്യയുമായി ബന്ധപ്പെട്ടാൽ അതും ദാനമാണ്." അവർ ചോദിച്ചു: നബിയേ, ഞങ്ങളിലൊരാൾ തന്റെ വികാര ശമനത്തിനായി ഭാര്യയെ സമീപിച്ചാൽ അതിലും പ്രതിഫലമുണ്ടോ? അപ്പോൾ നബി(സ) ചോദിച്ചു: "അതവൻ നിഷിദ്ധമായ രീതിയിൽ ചെയ്താൽ അതിനു ശിക്ഷയില്ലേ? അപ്രകാരം അനുവദനീയമായ രൂപത്തിൽ ചെയ്താൽ പ്രതിഫലവുമുണ്ട്." (മു)', 'أَبِي ذَرٍّ', 'അബുദർറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 148, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "أَرْبَعُونَ خَصْلَةً، أَعْلَاهُنَّ مَنِيحَةُ الْعَنْزِ، مَا يَعْمَلُ رَجُلٌ بِخَصْلَةٍ مِنْهَا – رَجَاءَ ثَوَابِهَا وَتَصْدِيقَ مَوْعُودِهَا – إِلَّا أَدْخَلَهُ اللَّهُ بِهَا الْجَنَّةَ". قَالَ حَسَّانُ بْنُ عَطِيَّةَ: فَعَدَدْنَا مَا دُونَ مَنِيحَةِ الْعَنْزِ: مِنْ رَدِّ السَّلَامِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِمَاطَةِ الْأَذَى عَنِ الطَّرِيقِ، وَنَحْوَهُ، فَمَا اسْتَطَعْنَا أَنْ نَبْلُغَ خَمْسَةَ عَشَرَ خَصْلَةً. (خ,د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നാൽപതു കാര്യങ്ങൾ പ്രതിഫലേച്ഛയോടെയും വാക്പാലന പ്രതീക്ഷയോടെയും ആരെങ്കിലും പ്രവർത്തിച്ചാൽ അക്കാരണത്താൽ അല്ലാഹു അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകതന്നെ ചെയ്യും. അതിലേറ്റവും ഉത്തമമായത് ആടിനെ ദാനംചെയ്യലാണ്." ഹസ്സാനുബ്നു അതിയ്യ(റ) പറഞ്ഞു: അതിനു താഴെയുള്ളതിനെ ഞങ്ങൾ എണ്ണിയതിപ്രകാരമാണ്: സലാം മടക്കൽ, തുമ്മിയവന്നു ഗുണംകൊണ്ട് പ്രാർത്ഥിക്കൽ, വഴിയിലെ വിഷമതകൾ നീക്കൽ. എന്നാൽ പതിനഞ്ചു കാര്യങ്ങളെണ്ണിത്തീർക്കാൻ ഞങ്ങൾക്കു സാധിച്ചില്ല. (ബു,ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ، وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ". (ق,ت,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "സമ്പത്തിന്റെ (ഭൗതികസുഖസൗകര്യം) ആധിക്യമല്ല ഐശ്വര്യം. ആത്മാവിന്റെ ഐശ്വര്യമാണ് ഐശ്വര്യം." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ قَالَ', 'അനസ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "يَهْرَمُ ابْنُ آدَمَ وَتَشِبُّ مِنْهُ اثْنَتَانِ: الْحِرْصُ عَلَى الْمَالِ، وَالْحِرْصُ عَلَى الْعُمُرِ". (م,ت,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ആദം സന്തതികൾക്കു വാർദ്ധക്യമായിക്കൊണ്ടിരിക്കുന്നു. എന്നാൽ അവനിൽ രണ്ടു കാര്യങ്ങൾ യുവത്വം പ്രാപിക്കുന്നു: ധനമോഹവും ആയുസ്സിനോടുള്ള മോഹവുമാണത്." (മു,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 149, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي الْأَسْوَدِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ أَبُو مُوسَى الْأَشْعَرِيُّ إِلَى قُرَّاءِ أَهْلِ الْبَصْرَةِ، فَدَخَلَ عَلَيْهِ ثَلَاثُ مِائَةِ رَجُلٍ قَدْ قَرَءُوا الْقُرْآنَ، فَقَالَ: أَنْتُمْ خِيَارُ أَهْلِ الْبَصْرَةِ وَقُرَّاؤُهُمْ، فَاتْلُوهُ، وَلَا يَطُولَنَّ عَلَيْكُمُ الْأَمَدُ فَتَقْسُوَ قُلُوبُكُمْ كَمَا قَسَتْ قُلُوبُ مَنْ كَانَ قَبْلَكُمْ، وَإِنَّا كُنَّا نَقْرَأُ سُورَةً كُنَّا نُشَبِّهُهَا فِي الطُّولِ وَالشِّدَّةِ ب{بَرَاءَةَ} فَأُنْسِيتُهَا، غَيْرَ أَنِّي قَدْ حَفِظْتُ مِنْهَا: ''لَوْ كَانَ لِابْنِ آدَمَ وَادِيَانِ مِنْ مَالٍ لَابْتَغَى وَادِيًا ثَالِثًا، وَلَا يَمْلَأُ جَوْفَ ابْنِ آدَمَ إِلَّا التُّرَابُ''. وَكُنَّا نَقْرَأُ سُورَةً [كُنَّا] نُشَبِّهُهَا بِإِحْدَى الْمُسَبِّحَاتِ فَأُنْسِيتُهَا، غَيْرَ أَنِّي حَفِظْتُ مِنْهَا: "يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ، فَتُكْتَبُ شَهَادَةً فِي أَعْنَاقِكُمْ، فَتُسْأَلُونَ عَنْهَا يَوْمَ الْقِيَامَةِ". (م)', 'അബുൽ അസ്‌വദ്(റ): ബസ്റയിലെ ഖുർറാഉകളിലേക്ക് (ഖുർആൻ പാരായണ പണ്ഡിതർ) അബുമൂസൽ അശ്അരി(റ) പറഞ്ഞയച്ചു. അപ്പോൾ അദ്ദേഹത്തിന്റെയടുത്ത് ഖുർആൻ പഠിച്ച മുന്നൂറ് ആളുകൾ വന്നു. അപ്പോൾ അവരോട് പറഞ്ഞു: നിങ്ങൾ ബസറക്കാരിലെ നല്ലവരാണ്, അവരുടെ ഖുർറാഉകളുമാണ്. അതുകൊണ്ട് നിങ്ങളത് പാരായണം ചെയ്യുക, ഖുർആൻ ഓതാത്ത ഒരു കാലം നിങ്ങൾക്ക് ദീർഘിച്ചുപോകരുത്. കാരണം നിങ്ങളുടെ ഹൃദയം കടുത്തുപോകും, നിങ്ങളുടെ മുമ്പുള്ളവരുടെ ഹൃദയം കഠിനമായതുപോലെ. ബറാഅത്ത് സൂറത്തിനോട് ദൈർഘ്യത്തിലും കാഠിന്യത്തിലും സാമ്യമായി തോന്നുന്ന ഒരു സൂറത്ത് ഞങ്ങൾ ഓതാറുണ്ടായിരുന്നു. അങ്ങനെ ഞാനത് മറന്നുപോയി. ഈ വാക്യം ഒഴികെ: ''ആദമിന്റെ മകന് ധനത്തിന്റെ രണ്ട് മലകളുണ്ടായാലും മൂന്നാമതൊന്നു കൂടി അവൻ ആഗ്രഹിക്കും, ആദമിന്റെ മകന്റെ വയറ് മണ്ണല്ലാതെ നിറക്കുകയില്ല''. മുസബ്ബിഹാതുകളിലൊന്നുമായി സാമ്യപ്പെടുത്താറുള്ള മറ്റൊരു സൂറത്ത് ഞങ്ങളോതാറുണ്ടായിരുന്നു. അങ്ങനെ ഞാനത് മറന്നു. ഈ വാക്യം ഒഴികെ: ''സത്യവിശ്വാസികളേ, പ്രവർത്തിക്കാത്തത് നിങ്ങളെന്തിനാണ് പറയുന്നത്, കാരണം അത് സത്യസാക്ഷ്യമായി നിങ്ങളുടെ മുതുകുകളിൽ എഴുതപ്പെടും, അതിനെക്കുറിച്ച് അന്ത്യനാളിൽ നിങ്ങൾ ചോദിക്കപ്പെടും.'' (മു)', 'أَبِي الْأَسْوَدِ', 'അബുൽ അസ്‌വദ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'كُنَّا', null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ جَلَسَ ذَاتَ يَوْمٍ عَلَى الْمِنْبَرِ وَجَلَسْنَا حَوْلَهُ، فَقَالَ: "إِنِّي مِمَّا أَخَافُ عَلَيْكُمْ مِنْ بَعْدِي مَا يُفْتَحُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا". فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ؟ فَسَكَتَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ، فَقِيلَ لَهُ: مَا شَأْنُكَ؟ تُكَلِّمُ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ وَلَا يُكَلِّمُكَ؟ فَرَأَيْنَا أَنَّهُ يُنْزَلُ عَلَيْهِ الْوَحْيُ، قَالَ: فَمَسَحَ عَنْهُ الرُّحَضَاءَ، فَقَالَ: "أَيْنَ السَّائِلُ". وَكَأَنَّهُ حَمِدَهُ، فَقَالَ: "إِنَّهُ لَا يَأْتِي الْخَيْرُ بِالشَّرِّ، وَإِنَّ مِمَّا يُنْبِتُ الرَّبِيعُ يَقْتُلُ أَوْ يُلِمُّ إِلَّا آكِلَةَ الْخَضْرَاءِ، أَكَلَتْ حَتَّى إِذَا امْتَدَّتْ خَاصِرَتَاهَا اسْتَقْبَلَتْ عَيْنَ الشَّمْسِ فَثَلَطَتْ وَبَالَتْ وَرَتَعَتْ، وَإِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةٌ، فَنِعْمَ صَاحِبُ الْمُسْلِمِ، مَا أَعْطَى مِنْهُ الْمِسْكِينَ وَالْيَتِيمَ وَابْنَ السَّبِيلِ". أَوْ كَمَا قَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "وَإِنَّهُ مَنْ يَأْخُذُهُ بِغَيْرِ حَقِّهِ، كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ، وَيَكُونُ شَهِيدًا عَلَيْهِ يَوْمَ الْقِيَامَةِ". (ق,ن)', 'അബുസഈദിൽ ഖുദ്‌രി(റ): ഒരു ദിവസം നബി(സ) മിമ്പറിലും ഞങ്ങൾ അവിടത്തെ ചുറ്റും ഇരിന്നു. ശേഷം നബി(സ) പറഞ്ഞു: "എനിക്കു ശേഷം നിങ്ങൾക്ക് വന്നെത്തിയേക്കുമെന്ന് ഞാൻ ഭയപ്പെടുന്ന കാര്യങ്ങളിലൊന്ന് ഐഹിക ആർഭാടങ്ങളുടെയും അലങ്കാരങ്ങളുടെയും വാതിലുകൾ നിങ്ങളുടെ മുമ്പിൽ തുറക്കപ്പെടും എന്നതാണ്." അപ്പോൾ ഒരാൾ ചോദിച്ചു: റസൂലേ, നന്മയിൽ നിന്ന് തിന്മ ഉടലെടുക്കുമോ? അപ്പോൾ റസൂൽ(സ) മൗനം ദീക്ഷിച്ചു. ചിലർ അയാളോട് ചോദിച്ചു: നിനക്കെന്തു പറ്റി? നീ നബി(സ)യോട് സംസാരിക്കുന്നു. നബി(സ) നിന്നോട് സംസാരിക്കുന്നില്ലല്ലോ? റസൂൽ(സ)ക്ക് ദൈവിക സന്ദേശം വന്നുകൊണ്ടിരിക്കുകയാണെന്ന് ഞങ്ങൾക്കു തോന്നി. ഒടുവിൽ നബി(സ) തന്റെ ശരീരത്തിൽ നിന്നു വിയർപ്പു തുടച്ച ശേഷം ചോദിച്ചു: "ചോദ്യകർത്താവെവിടെ?" ചോദ്യകർത്താവിനെ റസൂൽ(സ) അഭിനന്ദിക്കുകയാണെന്നു ഞങ്ങൾക്കു തോന്നി. നബി(സ) പറഞ്ഞു: "നന്മയിൽ നിന്നും തിന്മ ഉടലെടുക്കില്ല, ശരി തന്നെ. പക്ഷേ, വസന്തകാലത്ത് മുളക്കുന്ന സസ്യങ്ങളിലും പുല്ലിലും കാലികൾക്കു ജീവഹാനി വരുത്തുകയോ അവയെ രോഗത്തിലകപ്പെടുത്തുകയോ ചെയ്യുന്നവയുമുണ്ട്. ചില കാലികളെ അത്തരം നാശങ്ങളൊന്നും ബാധിക്കുകയില്ല. അവ പച്ചപ്പുല്ലും സസ്യങ്ങളും വയറു നിറയെ തിന്നുന്നു. സൂര്യന്റെ മുന്നിൽ നിന്നു വെയിൽ കൊണ്ടു കാഷ്ടിക്കുകയും മൂത്രിക്കുകയും ചെയ്യുന്നു. വീണ്ടും മേഞ്ഞു തിന്നുന്നു. നിങ്ങളോർക്കുക, ഇപ്രകാരം ഈ ധനം പച്ചപിടിച്ചതും മധുരമുള്ളതുമാണ്. അഗതിക്കും അനാഥബാലനും വഴിയാത്രക്കാരനും കൊടുക്കുന്ന കാലത്തോളം മുസ്‌ലിമിന്റെ നല്ല കൂട്ടുകാരനാണ് സമ്പത്ത്. എന്നാൽ അന്യായമായ മാർഗ്ഗത്തിലൂടെ വല്ലവനും ധനം കരസ്ഥമാക്കിയാൽ അവന്റെ സ്ഥിതി, ഭക്ഷിച്ചിട്ടും വയറു നിറയാത്തവനെപ്പോലെയാണ്. ആ സ്വത്ത് പുനരുത്ഥാന നാളിൽ അവനെതിരായി സാക്ഷി പറയാൻ ഹാജരാകും." (ബു,മു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 150, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ أَشْيَاءَ كُنْتُ أَتَحَنَّثُ بِهَا فِي الْجَاهِلِيَّةِ مِنْ صَدَقَةٍ أَوْ عَتَاقَةٍ وَصِلَةِ رَحِمٍ، فَهَلْ فِيهَا مِنْ أَجْرٍ؟ فَقَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "أَسْلَمْتَ عَلَى مَا سَلَفَ مِنْ خَيْرٍ". (خ)', 'ഹകീമുബ്നു ഹിസാം(റ): ഞാൻ ചോദിച്ചു: നബിയേ, ഞാൻ അജ്ഞതയുടെ കാലത്ത് പുണ്യകർമ്മമെന്ന നിലക്കു ദാനം ചെയ്യുകയും അടിമകളെ മോചിപ്പിക്കുകയും കുടുംബ ബന്ധം പുലർത്തുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഇക്കാര്യത്തിൽ അങ്ങെന്തു പറയുന്നു? എനിക്കു പ്രതിഫലം ലഭിക്കുമോ? നബി(സ) പറഞ്ഞു: "മുമ്പ് (ജാഹിലിയ്യത്തിന്റെ കാലത്ത്) നിർവ്വഹിച്ച സുകൃതങ്ങളോടെത്തന്നെയാണ് നീ ഇസ്‌ലാമിൽ പ്രവേശിച്ചത്." (ബു)', 'حَكِيمِ بْنِ حِزَامٍ', 'ഹകീമുബ്നു ഹിസാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الصَّدَقَةِ أَعْظَمُ أَجْرًا؟ قَالَ: "أَنْ تَصَدَّقَ وَأَنْتَ صَحِيحٌ شَحِيحٌ، تَخْشَى الْفَقْرَ وَتَأْمُلُ الْغِنَى، وَلَا تُمْهِلُ حَتَّى إِذَا بَلَغَتِ الْحُلْقُومَ، قُلْتَ: لِفُلَانٍ كَذَا، وَلِفُلَانٍ كَذَا، وَقَدْ كَانَ لِفُلَانٍ". (ق,د,ن)', 'അബുഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തു വന്നുചോദിച്ചു: തിരുദൂതരേ, കൂടുതൽ പ്രതിഫലം ലഭിക്കുന്ന ദാനമേതാണ്. നബി(സ) പറഞ്ഞു: "നീ ആരോഗ്യവാനായിരിക്കുമ്പോൾ ധനം നൽകാൻ നിനക്കു മടിയും ദാരിദ്ര്യത്തെകുറിച്ച് ഭയവും ധനത്തോടുള്ള ആഗ്രഹവും നിനക്കുണ്ടായിരിക്കെ നീ നൽകുന്ന ദാനമാണ് ഏറ്റവും പുണ്യമുള്ളത്. അന്നേരം നീ ദാനത്തെ പിന്നിലേക്കു തട്ടിനീക്കിക്കൊണ്ടു പോകരുത്. പോയാൽ, ജീവൻ കണ്ഠനാളത്തിൽ എത്തുമ്പോൾ നീ പറയും; ഇന്നയാൾക്ക് ഇത്ര, ഇന്നവനിത്ര കൊടുക്കണം. യഥാർത്ഥത്തിൽ ആ ഘട്ടത്തിൽ ''ഇന്നവന്റേത്'' (അനന്തരാവകാശിയുടേത്) ആയിക്കഴിഞ്ഞിരിക്കും." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 151, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ، فَجَاءَهُ رَجُلَانِ، أَحَدُهُمَا يَشْكُو الْعَيْلَةَ، وَالْآخَرُ يَشْكُو قَطْعَ السَّبِيلِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "أَمَّا قَطْعُ السَّبِيلِ، فَإِنَّهُ لَا يَأْتِي عَلَيْكَ إِلَّا قَلِيلٌ حَتَّى تَخْرُجَ الْعِيرُ إِلَى مَكَّةَ بِغَيْرِ خَفِيرٍ، وَأَمَّا الْعَيْلَةُ، فَإِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى يَطُوفَ أَحَدُكُمْ بِصَدَقَتِهِ، لَا يَجِدُ مَنْ يَقْبَلُهَا مِنْهُ، ثُمَّ لَيَقِفَنَّ أَحَدُكُمْ بَيْنَ يَدَيِ اللَّهِ، لَيْسَ بَيْنَهُ وَبَيْنَهُ حِجَابٌ، وَلَا تَرْجُمَانٌ يُتَرْجِمُ لَهُ، ثُمَّ لَيَقُولَنَّ لَهُ: أَلَمْ أُوتِكَ مَالًا؟ فَلَيَقُولَنَّ: بَلَى، ثُمَّ لَيَقُولَنَّ: أَلَمْ أُرْسِلْ إِلَيْكَ رَسُولًا؟ فَلَيَقُولَنَّ: بَلَى، فَيَنْظُرُ عَنْ يَمِينِهِ فَلَا يَرَى إِلَّا النَّارَ، ثُمَّ يَنْظُرُ عَنْ شِمَالِهِ فَلَا يَرَى إِلَّا النَّارَ، فَلْيَتَّقِيَنَّ أَحَدُكُمُ النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَإِنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ". (خ)', 'അദിയ്യുബ്നു ഹാതിം(റ): ഒരിക്കൽ ഞാൻ നബി(സ)യോടൊപ്പമിരിക്കുമ്പോൾ രണ്ടാളുകൾ അടുത്തു വന്നു. ഒരാൾ ദാരിദ്ര്യത്തെ കുറിച്ചും മറ്റെയാൾ വഴിയിലെ കൊള്ളക്കാരുടെ ശല്യത്തെകുറിച്ചും ആവലാതിപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "വഴികൊള്ളക്കാരുടെ ശല്യം അൽപകാലത്തേക്കു മാത്രമേയുണ്ടാവുകയുള്ളൂ. അതിനുശേഷം മദീനയിൽ നിന്നു മക്കയിലേക്ക് യാതൊരു സംരക്ഷകന്റെയും സഹായം കൂടാതെ കച്ചവടസംഘം യാത്രചെയ്യും. ദാരിദ്ര്യത്തിന്റെ സ്ഥിതി പറയേണ്ടതുമില്ല. നിങ്ങളിലൊരാൾ സകാത്തുമായി ചുറ്റിനടക്കും. എന്നാൽ അതു സ്വീകരിക്കാൻ ഒരാളെയും കാണാത്ത ഒരു കാലഘട്ടം വന്നെത്തുവോളം ലോകാവസാനം സംഭവിക്കില്ല. നിങ്ങളിലോരോരുത്തരും അല്ലാഹുവിന്റെ മുന്നിൽ ചെന്നു നിൽക്കും. മനുഷ്യനോ അല്ലാഹുവിനോ ഇടയിൽ ഒരു മറയോ തർജമ ചെയ്യുന്ന പരിഭാഷകനോ ഉണ്ടാവില്ല. അല്ലാഹു മനുഷ്യനോടു ചോദിക്കും: നിനക്കു ഞാൻ ധനം നൽകിയിരുന്നില്ലേ? മനുഷ്യൻ പറയും: അതെ. അല്ലാഹു ചോദിക്കും: നിന്നിലേക്കു ഞാൻ ദൂതനെ അയച്ചിരുന്നില്ലേ? ''അതെ'' എന്നവൻ മറുപടി പറയും. പിന്നീട് വലത്തോട്ടു നോക്കുമ്പോൾ നരകത്തെയല്ലാതെ അവൻ കാണില്ല. ഇടത്തോട്ടു നോക്കുമ്പോഴും അവൻ കാണുന്നതു നരകം തന്നെ. അതിനാൽ ഒരു കാരക്കത്തുണ്ട് ദാനം ചെയ്തിട്ടെങ്കിലും നിങ്ങളിലോരോരുത്തരും നരകത്തെ സൂക്ഷിക്കുക, അതിനവസരമുണ്ടായില്ലെങ്കിൽ ഒരു നല്ല വാക്കുകൊണ്ട്." (ബു)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "مَا يَسُرُّنِي أَنَّ لِي أُحُدًا ذَهَبًا، تَأْتِي عَلَيَّ ثَالِثَةٌ وَعِنْدِي مِنْهُ دِينَارٌ، إِلَّا دِينَارٌ أَرْصُدُهُ لِدَيْنٍ عَلَيَّ". (م)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ കയ്യിൽ ഉഹ്ദ് മലയോളം സ്വർണ്ണം ഉണ്ടാകുകയും മൂന്നു ദിവസത്തിനു ശേഷം ഞാൻ കടം വീട്ടാൻ സൂക്ഷിച്ചതല്ലാതെ മറ്റു വല്ലതും ആ സ്വർണ്ണത്തിൽ നിന്ന് എന്റെ കയ്യിൽ ബാക്കിയിരിക്കുന്നതും എന്നെ സന്തോഷിപ്പിക്കുന്നില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 152, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ إِذَا أَمَرَنَا بِالصَّدَقَةِ انْطَلَقَ أَحَدُنَا إِلَى السُّوقِ فَيُحَامِلُ فَيُصِيبُ الْمُدَّ، وَإِنَّ لِبَعْضِهِمُ الْيَوْمَ لَمِائَةَ أَلْفٍ. (خ)', 'അബുമസ്ഊദിൽ അൻസാരി(റ): നബി(സ) ഞങ്ങളോടു ദാനം ചെയ്യാനാജ്ഞാപിച്ചാൽ ഞങ്ങളിൽ ചിലർ അങ്ങാടിയിൽ പോയി ചുമടു ചുമക്കും. അങ്ങനെ ലഭിക്കുന്ന ഒരു ''മുദ്ദ്'' ധാന്യം ഞങ്ങൾ ദാനം ചെയ്യും. എന്നാൽ, ഇന്നു പലരുടെയും കയ്യിൽ ലക്ഷം തന്നെയുണ്ട്. (ബു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബുമസ്ഊദിൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 152, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَتِ امْرَأَةٌ مَعَهَا ابْنَتَانِ لَهَا تَسْأَلُ، فَلَمْ تَجِدْ عِنْدِي شَيْئًا غَيْرَ تَمْرَةٍ فَأَعْطَيْتُهَا إِيَاهَا، فَقَسَمَتْهَا بَيْنَ ابْنَتَيْهَا، وَلَمْ تَأْكُلْ مِنْهَا، ثُمَّ قَامَتْ فَخَرَجَتْ، فَدَخَلَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَلَيْنَا، فَأَخْبَرْتُهُ، فَقَالَ: "مَنِ ابْتُلِيَ مِنْ هَذِهِ الْبَنَاتِ بِشَيْءٍ كُنَّ لَهُ سِتْرًا مِنَ النَّارِ". (خ)', 'ആഇശ(റ): ഒരിക്കൽ ഒരു സ്ത്രീ രണ്ടു പെൺകുട്ടികളോടൊപ്പം ഭിക്ഷ യാചിച്ചു വന്നു. എന്റെ കയ്യിൽ ഒരു കാരക്ക മാത്രമാണുണ്ടായിരുന്നത്. ഞാനതവൾക്കു നൽകി. അവളതു ഭാഗിച്ച് രണ്ടു കുട്ടികൾക്കും നൽകി. അവളതിൽ നിന്ന് ഒന്നും ഭക്ഷിച്ചില്ല. അവൾ എഴുന്നേറ്റു പോയി. അപ്പോൾ നബി(സ) ഞങ്ങളുടെയടുത്തുവന്നു. ഞാനീ വിവരം നബി(സ)യോടു പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "വല്ലവനും ഈ അനാഥ പെൺകുട്ടികളെ കൊണ്ട് പരീക്ഷണ വിധേയമാക്കപ്പെട്ടാൽ അത് നരകത്തിൽ നിന്നവനെ തടയുന്ന മറയായിരിക്കും." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ النَّارَ، فَأَعْرَضَ وَأَشَاحَ، ثُمَّ قَالَ: "اتَّقُوا النَّارَ". ثُمَّ أَعْرَضَ وَأَشَاحَ، حَتَّى ظَنَنَّا أَنَّهُ كَأَنَّمَا يَنْظُرُ إِلَيْهَا، ثُمَّ قَالَ: "اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ". (م,ن)', 'അദിയ്യുബ്നു ഹാതിം(റ): നബി(സ) ഒരിക്കൽ നരകത്തെ കുറിച്ചു സംസാരിക്കുകയും പിന്തിരിഞ്ഞ് ദൂരെയാവുകയും ചെയ്തു. ശേഷം അവിടുന്നരുളി: "നിങ്ങൾ നരകത്തെ സൂക്ഷിക്കുക." വീണ്ടും പിന്തിരിയുകയും ദൂരെയാവുകയും ചെയ്തു. നബി(സ) നരകത്തിലേക്കു നോക്കിക്കൊണ്ടിരിക്കുകയാണോ എന്നു ഞങ്ങൾക്കു തോന്നിപ്പോയി. ശേഷം അവിടുന്നരുളി: "ഒരു കാരക്കച്ചുള കൊണ്ടെങ്കിലും നിങ്ങൾ നരകത്തെ സൂക്ഷിക്കുവിൻ, അതില്ലെങ്കിൽ നല്ലവാക്കു കൊണ്ട്". (മു,ന)', 'عَدِيِّ بْنِ حَاتِمٍ قَالَ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فِي صَدْرِ النَّهَارِ، قَالَ: فَجَاءَ قَوْمٌ حُفَاةٌ عُرَاةٌ مُجْتَابِي النِّمَارِ – أَوِ الْعِبَاءِ – مُتَقَلِّدِي السُّيُوفِ، عَامَّتُهُمْ مِنْ مُضَرَ، بَلْ كُلُّهُمْ مِنْ مُضَرَ، فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ لِمَا رَأَى بِهِمْ مِنَ الْفَاقَةِ، فَدَخَلَ ثُمَّ خَرَجَ، فَأَمَرَ بِلَالًا فَأَذَّنَ فَأَقَامَ، فَصَلَّى، ثُمَّ خَطَبَ فَقَالَ: "{يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} وَ: {يَا أَيُّهَا الذين آمنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ}. تَصَدَّقَ رَجُلٌ مِنْ دِينَارِهِ، مِنْ دِرْهَمِهِ، مِنْ ثَوْبِهِ، مِنْ صَاعِ بُرِّهِ، مِنْ صَاعِ تَمْرِهِ، حَتَّى قَالَ: وَلَوْ بِشِقِّ تَمْرَةٍ". قَالَ: فَجَاءَ رَجُلٌ مِنَ الْأَنْصَارِ بِصُرَّةٍ كَادَتْ كَفُّهُ تَعْجِزُ عَنْهَا، بَلْ قَدْ عَجَزَتْ، ثُمَّ تَتَابَعَ النَّاسُ، حَتَّى رَأَيْتُ كَوْمَيْنِ مِنْ طَعَامٍ وَثِيَابٍ، حَتَّى رَأَيْتُ وَجْهَ رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَتَهَلَّلُ كَأَنَّهُ مُذْهَبَةٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَيْءٌ. وَمَنْ سَنَّ [فِي الْإِسْلَامِ] سُنَّةً سَيِّئَةً فَعَلَيْهِ وِزْرُهَا، وَوِزْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَوْزَارِهِمْ شَيْئًا". (م,ن)', 'ജരീറുബ്നു അബ്ദുല്ലാഹി(റ): ഒരു ദിവസം രാവിലെ ഞങ്ങൾ നബി(സ) യുടെ അടുത്തിരിക്കുമ്പോൾ ഒരു സമൂഹം പാദരക്ഷ ധരിക്കാതെ കമ്പിളി വസ്ത്രം, അല്ലെങ്കിൽ മുൻവശം തുറന്നിട്ട വസ്ത്രം ധരിക്കുകയും വാളുകൾ ഉറകളിൽ ബന്ധിക്കുകയും ചെയ്തനിലയിൽ വന്നു. അവർ ഭൂരിഭാഗവും അല്ല മുഴുവൻപേരും മുളർ ഗോത്രക്കാരായിരുന്നു. അവരുടെ ദാരിദ്ര്യാവസ്ഥ കണ്ട പ്രവാചകരുടെ മുഖം വിവർണ്ണമായി. ഉടൻ നബി(സ) അകത്തുകടന്ന് പിന്നെ പുറത്തു വന്ന് ബിലാൽ(റ)നോട് ബാങ്ക് വിളിക്കാൻ കൽപിച്ചു. ബിലാൽ(റ) ബാങ്കും ഇഖാമത്തും വിളിച്ചു. നിസ്കാരം നിർവ്വഹിച്ച ശേഷം നബി(സ) ഒരു പ്രഭാഷണം നടത്തി: "മനുഷ്യരേ, നിങ്ങളെ ഒരേ ആത്മാവിൽ നിന്ന് സൃഷ്ടിക്കുകയും, അതിൽനിന്നു തന്നെ അതിന്റെ ഇണയെയും സൃഷ്ടിക്കുകയും, അവർ ഇരുവരിൽ നിന്നുമായി ധാരാളം പുരുഷന്മാരെയും സ്ത്രീകളെയും വ്യാപിപ്പിക്കുകയും ചെയ്തവനായ നിങ്ങളുടെ രക്ഷിതാവിന് നിങ്ങൾ തഖ്‌വാ ചെയ്യുക. ഏതൊരു അല്ലാഹുവിന്റെ പേരിൽ നിങ്ങൾ അന്യോന്യം ചോദിച്ചുകൊണ്ടിരിക്കുന്നുവോ അവനെ നിങ്ങൾ സൂക്ഷിക്കുക, കുടുംബബന്ധങ്ങളെയും. തീർച്ചയായും അല്ലാഹു നിങ്ങളെ നിരീക്ഷിച്ചുകൊണ്ടിരിക്കുന്നവനാകുന്നു'' എന്നും ''സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിന് തഖ്‌വാ ചെയ്യുക. ഓരോ മനുഷ്യനും അവന്റെ നാളേക്കു വേണ്ടി എന്താണു മുൻകൂട്ടി ചെയ്തുവച്ചിട്ടുള്ളത് എന്നു ചിന്തിച്ചു കൊള്ളട്ടെ'' എന്നും പാരായണം ചെയ്തു. അപ്പോൾ ഒരാൾ ദീനാർ, ഒരാൾ ദിർഹം, ഒരാൾ തന്റെ വസ്ത്രം, മറ്റൊരാൾ തന്റെ ഗോതമ്പ്, ഒരാൾ തന്റെ കാരക്ക എന്നിങ്ങനെ ഓരോരുത്തർ ദാനം ചെയ്യട്ടെ." "ഒരു കാരക്കയുടെ അംശമെങ്കിലും" എന്നുവരെ റസൂൽ(സ) പറഞ്ഞു. നിവദകൻ: അങ്ങനെ അൻസാരികളിലൊരാൾ തന്റെ കൈ കുഴയുമാറ് ഒരു സഞ്ചി നിറയെ സാധനവുമായെത്തി. എന്നല്ല കൈ കുഴഞ്ഞു. പിന്നീട് ജനങ്ങൾ അപ്രകാരം തുടർച്ചയായി സാധനങ്ങൾ കൊണ്ടുവന്നുകൊണ്ടിരുന്നു. അങ്ങനെ ഭക്ഷണത്തിന്റെയും വസ്ത്രത്തിന്റെയും രണ്ടു കൂമ്പാരങ്ങൾ ഞാൻ കണ്ടു. നബി(സ)യുടെ തിരുമുഖം സ്വർണം പൂശിയതുപോലെ പ്രകാശിക്കുന്നത് ഞാൻ കണ്ടു. അവിടന്ന് പറഞ്ഞു: "ഇസ്‌ലാമിൽ ആരെങ്കിലും ഒരു നല്ല ചര്യ നടപ്പിൽ വരുത്തിയാൽ അവനതിന്റെ കൂലിയും ശേഷം അതുകണ്ട് പ്രവർത്തിക്കുന്നവരുടെ കൂലിയും അവനു ലഭിക്കുന്നതാണ്. പ്രവർത്തിക്കുന്നവരുടെ കൂലിയിൽ നിന്ന് ഒന്നും ചുരുങ്ങാതെ തന്നെ. വല്ലവരും ചീത്ത ചര്യ കൊണ്ടു വന്നാൽ അതിന്റെ തെറ്റും അതനുകരിച്ചു പ്രവർത്തിക്കുന്നവരുടെ തെറ്റും അവന് ലഭിക്കുന്നതാണ്, അനുകരിക്കുന്നവരുടെ തെറ്റിൽ നിന്നൊന്നും കുറയാതെ തന്നെ." (മു,ന)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ قَالَ', 'ജരീറുബ്നു അബ്ദുല്ലാഹി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'فِي الْإِسْلَامِ', null, 153, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، يَبْلُغُ بِهِ [إِلى النبي صَلَّى الله عَلَيْهِ وَسَلَّمَ]: "أَلَا رَجُلٌ يَمْنَحُ أَهْلَ بَيْتٍ نَاقَةً، تَغْدُو بِعُسٍّ وَتَرُوحُ بِعُسٍّ، إِنَّ أَجْرَهَا لَعَظِيمٌ". (م)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അറിയുക, രാവിലെയും വൈകുന്നേരവും വലിയ കോപ്പ നിറയെ പാൽ കറക്കുന്ന തന്റെ ഒട്ടകത്തെ മറ്റൊരു കുടുംബത്തിനു കറവിനായി നൽകുന്ന ആരുണ്ടോ, അവനതിനു മഹത്തായ പ്രതിഫലമാണുള്ളത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'إِلى النبي صَلَّى الله عَلَيْهِ وَسَلَّمَ', null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "اشْفَعُوا تُشَفَّعُوا، وَيَقْضِي اللَّهُ عَزَّ وَجَلَّ عَلَى لِسَانِ نَبِيِّهِ مَا شَاءَ". (ن)', 'അബുമൂസ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ശുപാർശ ചെയ്യൂ, ശിപാർശ സ്വീകരിക്കപ്പെടും (പ്രതിഫലം നൽകപ്പെടും) അല്ലാഹു അവനുദ്ദേശിച്ചത് അവന്റെ നബിയുടെ നാവിലൂടെ വിധിക്കും." (ന)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 154, 154, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الرَّجُلَ لَيَسْأَلُنِي الشَّيْءَ فَأَمْنَعُهُ حَتَّى تَشْفَعُوا فِيهِ فَتُؤْجَرُوا". وَإِنَّ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "اشْفَعُوا تُؤْجَرُوا". (ن)', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ എന്നോട് വല്ലതും ചോദിച്ചാൽ നിങ്ങളതിൽ ശിപാർശ ചെയ്യുന്നതുവരെ ഞാനത് അവനിൽ നിന്ന് തടഞ്ഞുവെക്കും. ശിപാർശ ചെയ്താൽ നിങ്ങൾക്ക് കൂലിനൽകപ്പെടും." തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ശിപാർശ ചെയ്യുക, കൂലി നൽകപ്പെടുക തന്നെ ചെയ്യും." (ന)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ يَوْمٍ يُصْبِحُ العِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلَانِ، فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا وَيَقُولُ الْآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا". (ق)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഓരോ ദിവസവും നേരം പുലർന്നാൽ രണ്ടു മലക്കുകൾ ഭൂമിയിലേക്കിറങ്ങി വരും. അവരിലൊരാൾ പറയും: അല്ലാഹുവേ ചിലവഴിക്കുന്നവനു നീ പകരം നൽകേണമേ. രണ്ടാമൻ പറയും: സമ്പത്തു പിടിച്ചുവെക്കുന്നവനു നീ നാശം വരുത്തേണമേ." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ – يَبْلُغُ بِهِ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ – قَالَ: "قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى: يَا ابْنَ آدَمَ أَنْفِقْ أُنْفِقْ عَلَيْكَ، وَقَالَ: يَمِينُ اللَّهِ مَلْأَى – وَقَالَ ابْنُ نُمَيْرٍ: مَلْآنُ – سَحَّاءُ لَا يَغِيضُهَا شَيْءٌ، اللَّيْلَ وَالنَّهَارَ". (م)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞു: ആദം സന്തതികളേ, നിങ്ങൾ ചെലവഴിക്കുക, ഞാൻ നിങ്ങളുടെ മേൽ ചെലവഴിക്കും (നിനക്കു നൽകും) റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഖജനാവ് നിറഞ്ഞതാണ്." ഇബ്നുനുമൈർ(റ): നിറഞ്ഞതെന്നാൽ നന്നായി നൽകുന്നതും രാത്രിയിലോ പകലിലോ അതിൽ നിന്നൊന്നും കുറയാത്തതുമാകുന്നു". (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ حَارِثَةَ بْنِ وَهْبٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَقُولُ: "تَصَدَّقُوا، فَإِنَّهُ يَأْتِي عَلَيْكُمْ زَمَانٌ، يَمْشِي الرَّجُلُ بِصَدَقَتِهِ، فَلَا يَجِدُ مَنْ يَقْبَلُهَا يَقُولُ الرَّجُلُ لَوْ جِئْتَ بِهَا بِالْأَمْسِ لَقَبِلْتُهَا فَأَمَّا الْيَوْمَ فَلَا حَاجَةَ لِي بِهَا". (ق,ن)', 'ഹാരിസതുബ്നു വഹബ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങൾ ദാനം ചെയ്യുക. നിശ്ചയം ഒരാൾ അവന്റെ ദാനമുതലുമായി നടക്കും. എന്നാൽ അത് സ്വീകരിക്കാൻ ആരെയും കാണുകയുമില്ല. ഇന്നലെ നീ കൊണ്ടു വന്നിരുന്നുവെങ്കിൽ ഞാൻ അതു സ്വീകരിക്കുമായിരുന്നു, ഇന്ന് എനിക്കത് ആവശ്യമില്ല എന്ന് അവൻ (സ്വീകരിക്കേണ്ടവർ) പറയുകയും ചെയ്യുന്ന ഒരു കാലം പിന്നീട് നിങ്ങൾക്കു വരും." (ബു,മു,ന)', 'حَارِثَةَ بْنِ وَهْبٍ قَالَ', 'ഹാരിസതുബ്നു വഹബ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَكْثُرَ فِيكُمُ الْمَالُ، فَيَفِيضَ حَتَّى يُهِمَّ رَبَّ الْمَالِ، مَنْ يَقْبَلُ صَدَقَتَهُ وَحَتَّى يَعْرِضَهُ، فَيَقُولَ الَّذِي يَعْرِضُهُ عَلَيْهِ لَا أَرَبَ لِي". (خ)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ സമ്പത്ത് വർധിച്ചു കവിഞ്ഞ് സകാത്തിന്റെ അവകാശിയുടെ കാര്യത്തിൽ സമ്പത്തിന്റെ ഉടമ വ്യാകുലനാകും വരെ അന്ത്യനാൾ ഉണ്ടാവുകയില്ല. സകാതിന്റെ അവകാശികൾ ''എനിക്ക് ആവശ്യമില്ല'' എന്നു പറഞ്ഞു ഒഴിഞ്ഞുമാറുന്നതുമാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 155, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ، يَطُوفُ الرَّجُلُ فِيهِ بِالصَّدَقَةِ مِنَ الذَّهَبِ، ثُمَّ لَا يَجِدُ أَحَدًا يَأْخُذُهَا مِنْهُ، وَيُرَى الرَّجُلُ الْوَاحِدُ يَتْبَعُهُ أَرْبَعُونَ امْرَأَةًيَلُذْنَ بِهِ، مِنْ قِلَّةِ الرِّجَالِ وَكَثْرَةِ النِّسَاءِ". (خ)', 'അബുമൂസ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ സ്വർണ്ണത്തിന്റെ ദാനമുതലുമായി ചുറ്റിനടന്നിട്ടും അതു സ്വീകരിക്കാൻ ഒരാളെയും കണ്ടെത്താതിരിക്കുകയും സ്ത്രീകളുടെ ആധിക്യത്താലും പുരുഷന്മാരുടെ കുറവു കാരണത്താലും ലൈംഗിക സുഖാസ്വാദനത്തിന് ഒരു പുരുഷനു പിന്നിൽ നാൽപതു സ്ത്രീകളെ കാണപ്പെടുകയും ചെയ്യുന്ന ഒരു കാലം ജനങ്ങൾക്കു വരും." (ബു)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ وَأَكْثِرْنَ الِاسْتِغْفَارَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ". فَقَالَتِ امْرَأَةٌ مِنْهُنَّ جَزْلَةٌ: وَمَا لَنَا يَا رَسُولَ اللَّهِ أَكْثَرَ أَهْلِ النَّارِ؟ قَالَ: "تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ، وَمَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَغْلَبَ لِذِي لُبٍّ مِنْكُنَّ". قَالَتْ: يَا رَسُولَ اللَّهِ، وَمَا نُقْصَانُ الْعَقْلِ وَالدِّينِ؟ قَالَ: "أَمَّا نُقْصَانُ الْعَقْلِ فَشَهَادَةُ امْرَأَتَيْنِ تَعْدِلُ شَهَادَةَ رَجُلٍ، فَهَذَا نُقْصَانُ الْعَقْلِ. وَتَمْكُثُ اللَّيَالِي مَا تُصَلِّي، وَتُفْطِرُ فِي رَمَضَانَ، فَهَذَا نُقْصَانُ الدِّينِ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "സ്ത്രീ സമൂഹമേ, നിങ്ങൾ ദാനംചെയ്യുകയും പൊറുക്കലിനെ തേടൽ അധികരിപ്പിക്കുകയും ചെയ്യുക. നിശ്ചയം, ഞാൻ നിങ്ങളെയാണു നരകത്തിന്റെ അവകാശികളിൽ കൂടുതലായി കണ്ടത്." അവരിൽ നിന്ന് ഒരു ബുദ്ധിയുള്ള സ്ത്രീ ചോദിച്ചു: തിരുദൂതരേ, ഞങ്ങൾ നരകാവകാശികളിൽ കൂടുതൽ ആവാൻ കാരണം എന്താണ്? നബി(സ) പ്രതിവചിച്ചു: "നിങ്ങൾ കൂടുതൽ ശപിക്കുന്നു, ദാമ്പത്യബന്ധം മുറിക്കുന്നു, മതപരവും ബുദ്ധിപരവുമായ ന്യൂനതകളിൽ നിങ്ങളെ അതിജയിക്കുന്നവരായി ഞാൻ ആരെയും കണ്ടിട്ടില്ല." അവർ ചോദിച്ചു: തിരുദൂതരേ, മതപരവും ബുദ്ധിപരവുമായ ന്യൂനതകൾ എന്തൊക്കെയാണ്? നബി(സ) പറഞ്ഞു: "ബുദ്ധിപരമായ ന്യൂനത, രണ്ടു സ്ത്രീകളുടെ സാക്ഷ്യം ഒരു പുരുഷന്റെ സാക്ഷ്യത്തോടു സമമാണ്. ഇതാണ് ബുദ്ധിപരമായ ന്യൂനത. രാത്രികളിൽ നിസ്കരിക്കാറില്ല, റമദാനിൽ നോമ്പ് മുറിക്കുന്നു. ഇതാണു മതപരമായ ന്യൂനത." (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "تَقِيءُ الْأَرْضُ أَفْلَاذَ كَبِدِهَا أَمْثَالَ الْأُسْطُوَانِ مِنَ الذَّهَبِ وَالْفِضَّةِ، فَيَجِيءُ الْقَاتِلُ فَيَقُولُ: فِي هَذَا قَتَلْتُ، وَيَجِيءُ الْقَاطِعُ فَيَقُولُ: فِي هَذَا قَطَعْتُ رَحِمِي، وَيَجِيءُ السَّارِقُ فَيَقُولُ: فِي هَذَا قُطِعَتْ يَدِي، ثُمَّ يَدَعُونَهُ، فَلَا يَأْخُذُونَ مِنْهُ شَيْئًا". (م)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഭൂമി സ്വർണ്ണത്താലും വെള്ളിയാലുമുള്ള തൂണുകൾ പോലുള്ള അതിന്റെ കരളിന്റെ കഷ്ണങ്ങളെ ഛർദ്ധിക്കും. ശേഷം കൊലയാളി വന്നുപറയും: ഇന്ന കാര്യത്തിനാണു ഞാൻ കൊന്നത്, കുടുംബബന്ധം വിഛേദിച്ചവൻ വന്നുപറയും: ഇന്ന വിഷയത്തിലാണു ഞാൻ കുടുംബബന്ധം വിഛേദിച്ചത്, കള്ളൻ വന്നുപറയും: ഇന്ന വിഷയത്തിലാണ് എന്റെ കൈ മുറിക്കപ്പെട്ടത്. പിന്നെ അവർ അതിനുവേണ്ടി വാദിക്കും. പക്ഷേ, അതിൽനിന്ന് ഒന്നും അവർക്കുപകരിക്കുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْبَخِيلِ وَالْمُنْفِقِ كَمَثَلِ رَجُلَيْنِ عَلَيْهِمَا جُبَّتَانِ مِنْ حَدِيدٍ مِنْ ثَدْيِهِمَا إِلَى تَرَاقِيهِمَا، فَأَمَّا الْمُنْفِقُ فَلَا يُنْفِقُ إِلَّا سَبَغَتْ أَوْ وَفَرَتْ عَلَى جِلْدِهِ حَتَّى تُخْفِيَ بَنَانَهُ، وَتَعْفُوَ أَثَرَهُ. وَأَمَّا الْبَخِيلُ فَلَا يُرِيدُ أَنْ يُنْفِقَ شَيْئًا إِلَّا لَزِقَتْ كُلُّ حَلْقَةٍ مَكَانَهَا فَهُوَ يُوَسِّعُهَا وَلَا تَتَّسِعُ". (خ,ن)', 'അബുഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ധർമ്മിഷ്ഠന്റെയും ലുബ്ധന്റെയും ഉദാഹരണം, മാറു മുതൽ കഴുത്തിലെ തോളെല്ലുവരെ ഇരുമ്പ് കൊണ്ടുള്ള അങ്കി അണിഞ്ഞ രണ്ടാളുകളെപ്പോലെയാണ്. ധർമ്മിഷ്ഠൻ ധർമ്മം ചെയ്യുമ്പോഴെല്ലാം അവന്റെ കാൽപാടുകൾ മായ്ച്ചുകളയുവോളവും അവന്റെ കൈവിരൽതുമ്പുകൾ മൂടുവോളവും അങ്കി വളർന്നു പൂർണ്ണമാകും. അല്ലെങ്കിൽ നീണ്ടു പൊതിയും. ലുബ്ധൻ ദാനം ചെയ്യാൻ ഉദ്ദേശിക്കുമ്പോഴെല്ലാം അവന്റെ അങ്കിയുടെ ഓരോ കണ്ണിയും അതിന്റെ സ്ഥാനത്ത് ഇടുങ്ങി നിൽക്കും. അവനതു വിശാലമാക്കാനൊരുങ്ങും, പക്ഷേ അതു വിശാലമാകുകയില്ല." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ آيَةُ الصَّدَقَةِ كُنَّا نُحَامِلُ، فَجَاءَ رَجُلٌ فَتَصَدَّقَ بِشَيْءٍ كَثِيرٍ، فَقَالُوا: مُرَائِي، وَجَاءَ رَجُلٌ فَتَصَدَّقَ بِصَاعٍ، فَقَالُوا: إِنَّ اللَّهَ لَغَنِيٌّ عَنْ صَاعِ هَذَا، فَنَزَلَتْ: {الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ} الْآيَةَ. (م)', 'അബുമസ്ഊദ്(റ): സകാത്തിനെക്കുറിച്ചുള്ള സൂക്തമവതരിച്ചപ്പോൾ ഞങ്ങൾ ധർമ്മം ചെയ്യാനുള്ള സാധനങ്ങൾ വഹിക്കാൻ സഹായിക്കാറുണ്ടായിരുന്നു. അപ്പോൾ ഒരാൾ വന്ന് ധാരാളം ദാനം ചെയ്തു. ജനങ്ങൾ പറഞ്ഞു: അയാൾ ജനങ്ങളെ കാണിക്കാൻ ചെയ്യുകയാണ്. ഒരാൾ വന്ന് ഒരു സ്വാഅ് ദാനം ചെയ്തു. ജനങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന് ഈ ഒരു സ്വാഇന്റെ ആവശ്യമില്ല. ഈ സമയം ഖുർആനിലെ സൂക്തമവതരിച്ചു: ''വിശ്വാസികളിൽ നിന്ന് വഴിപ്പെടുന്നവരെയും തന്റെ അധ്വാനം മാത്രം ലഭിക്കുന്നവരെയും ദാനത്തിന്റെ കാര്യത്തിൽ നിർബന്ധിക്കുന്നവർ.'' (മു)', 'أَبِي مَسْعُودٍ', 'അബുമസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَسْمَاءَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ لِي النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "لَا تُوكِي فَيُوكَى عَلَيْكِ". وَفِي رِوَايَةٍ: "لَا تُحْصِي فَيُحْصِيَ اللَّهُ عَلَيْكِ". (خ,ن)', 'അസ്മാഅ്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "(ദാരിദ്ര്യം ഭയന്നു ചെലവഴിക്കാതെ) നീ കൈ മുറുകെ പിടിക്കരുത്. (അങ്ങനെ ചെയ്താൽ) അല്ലാഹു നിനക്കു ഭക്ഷണം കുടുസ്സാക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: "നീ ക്ലിപ്തമാക്കരുത്. അങ്ങനെയായാൽ നിനക്ക് അല്ലാഹുവും ക്ലിപ്തമാക്കും." (ബു,ന)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=40), 1, 'وَفِي رِوَايَةٍ: "لَا تُحْصِي فَيُحْصِيَ اللَّهُ عَلَيْكِ". (خ,ن)', 'മറ്റൊരു നിവേദനിൽ: "നീ ക്ലിപ്തമാക്കരുത്. അങ്ങനെയായാൽ നിനക്ക് അല്ലാഹുവും ക്ലിപ്തമാക്കും." (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهَا جَاءَتِ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا نَبِيَّ اللَّهِ، لَيْسَ [لِي] شَيْءٌ إِلَّا مَا أَدْخَلَ عَلَيَّ الزُّبَيْرُ، فَهَلْ عَلَيَّ جُنَاحٌ أَنْ أَرْضَخَ مِمَّا يُدْخِلُ عَلَيَّ؟ فَقَالَ: "ارْضَخِي مَا اسْتَطَعْتِ، وَلَا تُوعِي فَيُوعِيَ اللَّهُ عَلَيْكِ". (ق,د,ت,ن)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): അവർ നബി (സ)യുടെ അടുത്തുചെന്നു ചോദിച്ചു: പ്രവാചകരേ, എന്റെ ഭർത്താവു സുബൈർ തന്നതല്ലാതെ എന്റെ പക്കൽ ഒന്നുമില്ല. അതിനാൽ, അതിൽനിന്ന് എനിക്കു വല്ല ചെറിയ ദാനവും ചെയ്യൽ അനുവദനീയമാണോ? അവിടുന്നരുളി: "കഴിയുന്നിടത്തോളം ദാനം ചെയ്യുക. നീ പിശുക്കു കാണിക്കരുത്. (പിശുക്കു കാണിച്ചാൽ) അല്ലാഹു ഭക്ഷണം കുടുസ്സാക്കും." (ബു,മു,ദ,തു,ന)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], 'لِي', null, 157, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَطَبَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِيَّاكُمْ وَالشُّحَّ، فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِالشُّحِّ: أَمَرَهُمْ بِالْبُخْلِ فَبَخِلُوا، وَأَمَرَهُمْ بِالْقَطِيعَةِ فَقَطَعُوا، وَأَمَرَهُمْ بِالْفُجُورِ فَفَجَرُوا". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പ്രസംഗിക്കവെ പറഞ്ഞു: "ലുബ്ധതയെ നിങ്ങൾ സൂക്ഷിക്കുക. നിങ്ങളുടെ പൂർവ്വീകർ നശിച്ചത് ലുബ്ധത കാരണമാണ്. അവരോടു പിശുക്കുകാണിക്കാൻ ആരോ കൽപിച്ചു, അവർ പിശുക്കു കാണിച്ചു. ബന്ധം മുറിക്കാൻ കൽപിച്ചു, ബന്ധം മുറിച്ചു. തെമ്മാടിത്തം കൽപ്പിച്ചപ്പോൾ അവർ തെമ്മാടികളായി." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا ذَكَرَتْ عِدَّةً مِنْ مَسَاكِينَ، أَوْ: عِدَّةً مِنْ صَدَقَةٍ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعْطِي، وَلَا تُحْصِي فَيُحْصَى عَلَيْكِ". (د)', 'ആഇശ(റ): അവർ നബി(സ)യോട് ചില ദരിദ്രരെക്കുറിച്ച് അല്ലെങ്കിൽ കുറച്ച് സ്വദഖയെ കുറിച്ച് പറഞ്ഞപ്പോൾ നബി(സ) അരുളി: "നീ നൽകുക, പരിമിതപ്പെടുത്തരുത്. പരിമിതമാക്കിയാൽ അല്ലാഹുവും അങ്ങനെ ചെയ്യും." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا يَوْمًا فِي الْمَسْجِدِ جُلُوسًا، وَنَفَرٌ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، فَأَرْسَلْنَا رَجُلًا إِلَى عَائِشَةَ لِيَسْتَأْذِنَ، فَدَخَلْنَا عَلَيْهَا، قَالَتْ: دَخَلَ عَلَيَّ سَائِلٌ مَرَّةً وَعِنْدِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرْتُ لَهُ بِشَيْءٍ، ثُمَّ دَعَوْتُ بِهِ فَنَظَرْتُ إِلَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا تُرِيدِينَ أَنْ لَا يَدْخُلَ بَيْتَكِ شَيْءٌ وَلَا يَخْرُجَ إِلَّا بِعِلْمِكِ". قُلْتُ: نَعَمْ، قَالَ: "مَهْلًا يَا عَائِشَةُ، لَا تُحْصِي فَيُحْصِيَ اللَّهُ عَزَّ وَجَلَّ عَلَيْكِ". (ن)', 'അബുഉമാമതുബ്നു സഹ്‌ലിബ്നി ഹുനൈഫ്(റ): മുഹാജിറിലെയും അൻസാരികളിലെയും ഒരു സംഘത്തോടൊപ്പം ഞങ്ങൾ പള്ളിയിലിരിക്കുകയായിരുന്നു. അപ്പോൾ സന്ദർശനാനുമതി തേടി ആഇശ(റ)യുടെ അടുത്തേക്ക് ഞങ്ങളൊരാളെ അയച്ചു. ഞങ്ങൾ അവിടെ ചെന്നപ്പോൾ ആഇശ(റ) പറഞ്ഞു: നബി(സ) എന്റടുത്തുണ്ടായിരിക്കെ ഒരു യാചകൻ വന്നു. വല്ലതും കൊടുക്കാൻ ഞാൻ കൽപിച്ചു. ശേഷം ഞാനയാളെ വിളിച്ച് അയാൾക്ക് കൊടുത്ത സാധനത്തിലേക്ക് ഒന്നുനോക്കി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിന്റെ അറിവുകൂടാതെ നിന്റെ വീട്ടിലേക്ക് ഒന്നും വരരുതെന്നും പോവരുതെന്നും നീ ഉദ്ദേശിക്കുന്നുവോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "സാവകാശം ചെയ്യൂ ആഇശാ, നീ പരിമിതമാക്കരുത്. അപ്പോൾ അല്ലാഹുവും പരിമിതമാക്കും." (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബുഉമാമതുബ്നു സഹ്‌ലിബ്നി ഹുനൈഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا رَضِيَ اللَّهُ عَنْهُ إِلَى الْيَمَنِ، فَقَالَ: "ادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ: أَنَّ اللَّهَ قَدِ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ، فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِي أَمْوَالِهِمْ، تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ، وَتُرَدُّ عَلَى فُقَرَائِهِمْ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): മുആദ്(റ)നെ യമനിലേക്കയക്കുമ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അവന്റെ ദൂതനാണെന്നുമുള്ള സത്യ സാക്ഷ്യത്തിലേക്കു നീയവരെ ക്ഷണിക്കുക. അതിനവർ കീഴ്പ്പെട്ടാൽ ദിവസേന രാപ്പകലുകളിലായി അഞ്ചുനേരത്തെ നിസ്കാരം അല്ലാഹു അവരുടെ മേൽ നിർബന്ധമാക്കിയിരിക്കുന്നു എന്നറിയിക്കുക. അതിനും അവർ കീഴ്പെട്ടാൽ അവരിൽനിന്നുള്ള ധനികരിൽ നിന്നു ധനം പിടിക്കുകയും ദരിദ്രർക്കു നൽകുകയും ചെയ്യുന്ന ദാനം അവർക്ക് അല്ലാഹു നിർബന്ധമാക്കിയിരിക്കുന്നു എന്നും അവരെ അറിയിക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 158, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتُخْلِفَ أَبُو بَكْرٍ بَعْدَهُ، وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ، قَالَ عُمَرُ بْنُ الْخَطَّابِ لِأَبِي بَكْرٍ: كَيْفَ تُقَاتِلُ النَّاسَ؟ وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللَّهُ، فَمَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ، إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ عَزَّ وَجَلَّ". فَقَالَ أَبُو بَكْرٍ: وَاللَّهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللَّهِ، لَوْ مَنَعُونِي عِقَالًا – وَفِي رِوَايَةٍ: عَنَاقًا – كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: فَوَاللَّهِ، مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ، قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ، قَالَ: فَعَرَفْتُ أَنَّهُ الْحَقُّ. وفي رِوَايَةٍ: قَالَ أَبُو بَكْرٍ: إِنَّ حَقَّهُ أَدَاءُ الزَّكَاةِ. (ق,د,ت,ن,جه)', 'അബുഹുറൈറ(റ): നബി(സ) മരണമടഞ്ഞു, അബുബക്കർ(റ) ഖലീഫയായി നിയമിതനായി, അറബികളിൽ പലരും സത്യനിഷേധികളായി. ആ സന്ദർഭത്തിൽ ഉമർ(റ) അബുബക്കർ(റ)വിനോടു ചോദിച്ചു: നിങ്ങൾ എങ്ങനെ ജനങ്ങളോടു യുദ്ധം ചെയ്യും? നബി(സ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നു ജനങ്ങൾ സാക്ഷ്യം വഹിക്കുന്നതുവരെ യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ വല്ലവനും പറഞ്ഞാൽ അവന്റെ സമ്പത്തും ശരീരവും എന്നിൽനിന്ന് സംരക്ഷിച്ചിരിക്കുന്നു. ഇസ്‌ലാമിന്റെ ബാധ്യതയൊഴികെ. അവന്റെ വിചാരണ അല്ലാഹുവിന്റെ മേലാണ്." അപ്പോൾ അബുബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം! നിസ്കാരം, സകാത്ത് എന്നിവക്കിടയിൽ ഭിന്നത പുലർത്തുന്നവനോടു ഞാൻ യുദ്ധം ചെയ്യും, കാരണം, നിർബന്ധദാനം സമ്പത്തിന്റെ ബാധ്യതയാണ്. അല്ലാഹുവാണ് സത്യം! റസൂൽ(സ)ക്ക് നൽകിയിരുന്ന ഒട്ടകക്കയർ പോലും എനിക്കവർ തടഞ്ഞാൽ ഞാനതിന്റെ പേരിൽ അവരോടു യുദ്ധം ചെയ്യും. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം! യുദ്ധത്തിന് അല്ലാഹു അബുബക്കറിന്റെ മനസ്സു തുറന്നതായല്ലാതെ ഞാൻ അഭിപ്രായപ്പെടുന്നില്ല. ഉമർ(റ) പറയുന്നു: അതു സത്യമാണെന്നു ഞാൻ മനസ്സിലാക്കി. മറ്റൊരു നിവേദനത്തിൽ: അബുബക്കർ(റ) പറയുന്നു: നിശ്ചയം സമ്പത്തിന്റെ ബാധ്യത സകാത്ത് കൊടുത്തുവീട്ടലാണ്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=46), 1, 'وَفِي رِوَايَةٍ: عَنَاقًا – كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: فَوَاللَّهِ، مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ، قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ، قَالَ: فَعَرَفْتُ أَنَّهُ الْحَقُّ.', 'മറ്റൊരു നിവേദനത്തിൽ: അബുബക്കർ(റ) പറയുന്നു: നിശ്ചയം സമ്പത്തിന്റെ ബാധ്യത സകാത്ത് കൊടുത്തുവീട്ടലാണ്. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=46), 2, 'وَفِي رِوَايَةٍ: قَالَ أَبُو بَكْرٍ: إِنَّ حَقَّهُ أَدَاءُ الزَّكَاةِ. (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا إِلَى الْيَمَنِ، فَقَالَ: "إِنَّكَ تَأْتِي قَوْمًا أَهْلَ كِتَابٍ، فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ: أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ: أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِي أَمْوَالِهِمْ: تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ فِي فُقَرَائِهِمْ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ. وَاتَّقِ دَعْوَةَ الْمَظْلُومِ، فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മുആദ്(റ)വിനെ യമനിലേക്കയച്ച സന്ദർഭത്തിൽ പറഞ്ഞു: "താങ്കൾ പോകുന്നത് വേദക്കാരിലേക്കാണ്. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അവന്റെ ദൂതനാണെന്നുമുള്ള സത്യസാക്ഷ്യത്തിലേക്കു താങ്കളവരെ ക്ഷണിക്കണം. അതിനവർ കീഴടങ്ങിയാൽ, രാപകലുകളിലായി അവരുടെ മേൽ അഞ്ചു നിസ്ക്കാരത്തെ അല്ലാഹു നിർബന്ധമാക്കിയിരിക്കുന്നുവെന്നറിയിക്കണം. അതിനുമവർ കീഴൊതുങ്ങിയാൽ അവരോട് പറയുക: അവരിൽനിന്നുള്ള സമ്പന്നരിൽനിന്ന് പിടിക്കപ്പെടുകയും ദരിദ്രർക്ക് നൽകപ്പെടുകയും ചെയ്യുന്ന ദാനത്തെ അല്ലാഹു അവരുടെ മേൽ നിർബന്ധമാക്കിയിരിക്കുന്നു. അതിനുമവർ കീഴൊതുങ്ങിയാൽ അവരുടെ സമ്പത്തിലെ ഉൽകൃഷ്ഠമായത് താങ്കൾ സൂക്ഷിക്കുക. അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥനയെ താങ്കൾ സൂക്ഷിക്കുക. കാരണം, അല്ലാഹുവിന്റെയും അവന്റെയും ഇടയിൽ മറയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 159, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ قَالَ: قُلْتُ: يَا نَبِيَّ اللَّهِ، مَا أَتَيْتُكَ حَتَّى حَلَفْتُ أَكْثَرَ مِنْ عَدَدِهِنَّ – لِأَصَابِعِ يَدَيْهِ – أَلَّا آتِيَكَ وَلَا آتِيَ دِينَكَ، وَإِنِّي كُنْتُ امْرَأً لَا أَعْقِلُ شَيْئًا إِلَّا مَا عَلَّمَنِي اللَّهُ عَز وجَلّ وَرَسُولُهُ، وَإِنِّي أَسْأَلُكَ بِوَحْيِ اللَّهِ، بِمَا بَعَثَكَ رَبُّكَ إِلَيْنَا؟ قَالَ: "بِالْإِسْلَامِ". قُلْتُ: وَمَا آيَاتُ الْإِسْلَامِ؟ قَالَ: "أَنْ تَقُولَ: أَسْلَمْتُ وَجْهِي إِلَى اللَّهِ عَزَّ وَجَلَّ، وَتَخَلَّيْتُ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ". (ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ പറഞ്ഞു: റസൂലേ, താങ്കളിലേക്കും താങ്കളുടെ മതത്തിലേക്കും വരില്ലെന്ന് ഈ വിരലുകളുടെ എണ്ണത്തേക്കാൾ തവണ സത്യം ചെയ്ത ശേഷമാണു ഞാൻ അങ്ങയിലേക്ക് വന്നിരിക്കുന്നത്. അല്ലാഹുവും അവന്റെ ദൂതരും പഠിപ്പിച്ചതൊഴികെ മനസ്സിലാക്കാത്ത ഒരു മനുഷ്യനായിരിക്കുന്നു ഞാൻ. അല്ലാഹുവിന്റെ വഹ്‌യിനെ (വെളിപാട്) സാക്ഷിനിർത്തി ഞാൻ ചോദിക്കുന്നു, എന്തുമായാണു താങ്കളെ അല്ലാഹു നിയോഗിച്ചത്? അവിടുന്നരുളി: "ഇസ്‌ലാംകൊണ്ട്." ഞാൻ ചോദിച്ചു: ഇസ്‌ലാമിന്റെ തത്വങ്ങൾ എന്തെല്ലാമാണ്?. അവിടുന്ന് പറഞ്ഞു: "ഞാൻ എന്റെ മുഖം അല്ലാഹുവിന് കീഴ്പെടുത്തിയിരിക്കുന്നു എന്നും എല്ലാം അവന് അർപ്പിച്ചു എന്നും നിസ്കാരം നിലനിർത്തുകയും നിർബന്ധദാനം നിർവ്വഹിക്കുകയും ചെയ്യുമെന്നും നീ പറയലാണ്." (ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ قَالَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِسْبَاغُ الْوُضُوءِ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَالتَّسْبِيحُ وَالتَّكْبِيرُ يَمْلَأُ السَّمَوَاتِ وَالْأَرْضَ، وَالصَّلَاةُ نُورٌ، وَالزَّكَاةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ". (م,ت,ن,جه)', 'അബുമാലികിൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "വുളു പൂർത്തിയാക്കി ചെയ്യൽ, വിശ്വാസത്തിന്റെ പകുതിയാണ്. ''അൽഹംദു ലില്ലാഹി'' തുലാസ് നിറക്കും. തസ്ബീഹും, തക്ബീറും ആകാശഭൂമികളെ നിറക്കും. നിസ്കാരം പ്രകാശമാണ്. സകാത്ത് തെളിവാണ്. ക്ഷമ വെളിച്ചമാണ്. ഖുർആൻ നിനക്കനുകൂലമോ പ്രതികൂലമോ ആയ നിന്റെ സാക്ഷിയാണ്." (മു,തു,ന,ജ)', 'أَبِي مَالِكٍ الْأَشْعَرِيِّ', 'അബുമാലികിൽ അശ്അരി(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ قَالَا: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَقَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ". ثَلَاثَ مَرَّاتٍ، ثُمَّ أَكَبَّ، فَأَكَبَّ كُلُّ رَجُلٍ مِنَّا يَبْكِي، لَا نَدْرِي عَلَى مَاذَا حَلَفَ، ثُمَّ رَفَعَ رَأْسَهُ فِي وَجْهِهِ الْبُشْرَى، فَكَانَتْ أَحَبَّ إِلَيْنَا مِنْ حُمْرِ النَّعَمِ، ثُمَّ قَالَ: "مَا مِنْ عَبْدٍ يُصَلِّي الصَّلَوَاتِ الْخَمْسَ، وَيَصُومُ رَمَضَانَ، وَيُخْرِجُ الزَّكَاةَ، وَيَجْتَنِبُ الْكَبَائِرَ السَّبْعَ، إِلَّا فُتِّحَتْ لَهُ أَبْوَابُ الْجَنَّةِ، فَقِيلَ لَهُ: ادْخُلْ بِسَلَامٍ". (ن)', 'അബുഹുറൈറ(റ), അബുസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) ഒരു ദിവസം പ്രസംഗിക്കവെ ഞങ്ങളോടു പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനിൽ സത്യം." (മൂന്നുതവണ ആവർത്തിച്ചു.) ശേഷം അവിടന്ന് തലതാഴ്ത്തി. ഞങ്ങളെല്ലാവരും കരഞ്ഞുകൊണ്ട് തലതാഴ്ത്തി. എന്തിനാണ് അവിടന്ന് സത്യം ചെയ്തതെന്നു ഞങ്ങൾക്കറിയില്ല. പിന്നെ സന്തോഷവാനായി തലയുയർത്തി. ആ മുഖമായിരുന്നു ഞങ്ങൾക്കു ചുവന്ന ഒട്ടകത്തേക്കാൾ പ്രിയം. പിന്നെ പറഞ്ഞു: "അഞ്ചു നിസ്ക്കാരങ്ങൾ നിർവ്വഹിക്കുകയും, റമളാൻ വ്രതമെടുക്കുകയും, സകാത്ത് നൽകുകയും, ഏഴു വൻദോഷങ്ങൾ വെടിയുകയും ചെയ്യുന്ന ഒരടിമയുടെ മുമ്പിലും സ്വർഗവാതിലുകൾ തുറക്കപ്പെടാതിരിക്കില്ല. അപ്പോൾ അവനോടു പറയപ്പെടും. ശാന്തിയോടെ പ്രവേശിക്കുക." (ന)', 'أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ قَالَا', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمَ عَلَيْنَا مُصَدِّقُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ الصَّدَقَةَ مِنْ أَغْنِيَائِنَا، فَجَعَلَهَا فِي فُقَرَائِنَا، وَكُنْتُ غُلَامًا يَتِيمًا، فَأَعْطَانِي مِنْهَا قَلُوصًا. (ت)', 'അബുജുഹൈഫ(റ): നബി (സ)യുടെ സകാത്ത് പിരിക്കുന്നയാൾ ഞങ്ങളുടെ അടുത്തുവന്നു. ഞങ്ങളിലെ ധനികരിൽനിന്നു ദാനം സ്വീകരിച്ച് ദരിദ്രർക്കിടയിൽ വിതരണം ചെയ്തു. ഞാനൊരു അനാഥ ബാലനായിരുന്നു. ആയതിനാൽ എനിക്കൊരു ഒട്ടകക്കുട്ടിയെ ലഭിച്ചു. (തു)', 'أَبِي جُحَيْفَةَ', 'അബുജുഹൈഫ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِلَحْمٍ، قَالَ: "مَا هَذَا؟". قَالُوا: شَيْءٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، فَقَالَ: "هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ". (ق,د,ن)', 'അനസ്(റ): നബി(സ)യുടെയടുക്കൽ മാംസം കൊണ്ടുവരപ്പെട്ടു. നബി(സ) ചോദിച്ചു: "ഇതെന്താണ്?" അവർ പറഞ്ഞു: ബരീറക്ക് ദാനമായി ലഭിച്ചതാണ്. നബി(സ) പറഞ്ഞു: "അതവൾക്കു ദാനവും നമുക്ക് സമ്മാനവുമാണ്." (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَأْتِي الْإِبِلُ عَلَى صَاحِبِهَا عَلَى خَيْرِ مَا كَانَتْ، إِذَا هُوَ لَمْ يُعْطِ فِيهَا حَقَّهَا تَطَؤُهُ بِأَخْفَافِهَا، وَتَأْتِي الْغَنَمُ عَلَى صَاحِبِهَا عَلَى خَيْرِ مَا كَانَتْ إِذَا لَمْ يُعْطِ فِيهَا حَقَّهَا تَطَؤُهُ بِأَظْلَافِهَا، وَتَنْطَحُهُ بِقُرُونِهَا، قَالَ: وَمِنْ حَقِّهَا أَنْ تُحْلَبَ عَلَى الْمَاءِ، قَالَ: وَلَا يَأْتِي أَحَدُكُمْ يَوْمَ الْقِيَامَةِ بِشَاةٍ يَحْمِلُهَا عَلَى رَقَبَتِهِ لَهَا يُعَارٌ، فَيَقُولُ: يَا مُحَمَّدُ، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا قَدْ بَلَّغْتُ، وَلَا يَأْتِي بِبَعِيرٍ يَحْمِلُهُ عَلَى رَقَبَتِهِ لَهُ رُغَاءٌ، فَيَقُولُ: يَا مُحَمَّدُ، فَأَقُولُ: لَا أَمْلِكُ لَكَ مِنَ اللَّهِ شَيْئًا قَدْ بَلَّغْتُ". (خ)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ബാധ്യത വീട്ടാത്ത യജമാനന്റെ ഒട്ടകം, ഭൗതികലോകത്തുണ്ടായിരുന്നതിനേക്കാൾ തടിച്ചുകൊഴുത്ത് പരലോകത്തു വരും. അവയുടെ കുളമ്പുകളെക്കൊണ്ട് അവനെ മർദ്ദിക്കും. ആടും ഇപ്രകാരം ഭൗതികലോകത്തുണ്ടായിരുന്നതിനേക്കാൾ കൂടുതൽ തടിച്ചുകൊഴുത്തു പരലോകത്തു വരും, അതിന്റെ ബാധ്യത കൊടുത്തിട്ടില്ലെങ്കിൽ അവനെ അതു കാലുകൊണ്ട് ചവിട്ടുകയും കൊമ്പുകൊണ്ടു കുത്തുകയും ചെയ്യും." നബി(സ) പറഞ്ഞു: "നദിക്കരയിൽ (പാവപ്പെട്ടവർക്ക്) അതിന്റെ പാൽ നൽകപ്പെടുകയെന്നത് അവയുടെ ബാധ്യതയിൽപെട്ടതാണ്!" അവിടന്ന് തുടർന്നു: "അന്ത്യനാളിൽ നിലവിളിക്കുന്ന ആടിനെ ചുമലിലേറ്റി നിങ്ങളിലാരും വരാതിരിക്കട്ടെ. എന്നിട്ടവൻ വിളിക്കും: മുഹമ്മദേ, (രക്ഷിക്കണേ). അപ്പോൾ ഞാൻ പറയും: അല്ലാഹുവിൽ നിന്നു നിന്നെ രക്ഷിക്കാൻ എനിക്ക് ഉത്തരവാദിത്തമില്ല. ഞാൻ എത്തിക്കേണ്ടത് എത്തിച്ചിരിക്കുന്നു. അന്ത്യനാളിൽ അട്ടഹസിക്കുന്ന ഒട്ടകത്തെ മുതുകിലേറ്റി നിങ്ങളിലാരും വരാതിരിക്കട്ടെ. എന്നിട്ടവൻ വിളിക്കും: മുഹമ്മദേ (രക്ഷിക്കണേ). അപ്പോൾ ഞാൻ പറയും: അല്ലാഹുവിൽ നിന്നു നിനക്ക് ഞാനൊന്നും ഏൽക്കുന്നില്ല. നിശ്ചയം ഞാൻ എത്തിക്കേണ്ടതു എത്തിച്ചിട്ടുണ്ട്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ صَاحِبِ ذَهَبٍ وَلَا فِضَّةٍ، لَا يُؤَدِّي مِنْهَا حَقَّهَا، إِلَّا إِذَا كَانَ يَوْمُ الْقِيَامَةِ صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ، فَأُحْمِيَ عَلَيْهَا فِي نَارِ جَهَنَّمَ، فَيُكْوَى بِهَا جَنْبُهُ وَجَبِينُهُ وَظَهْرُهُ، كُلَّمَا بَرَدَتْ أُعِيدَتْ لَهُ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ الْعِبَادِ، فَيَرَى سَبِيلَهُ، إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ». قِيلَ: يَا رَسُولَ اللهِ، فَالْإِبِلُ؟ قَالَ: "وَلَا صَاحِبُ إِبِلٍ لَا يُؤَدِّي مِنْهَا حَقَّهَا، وَمِنْ حَقِّهَا حَلَبُهَا يَوْمَ وِرْدِهَا، إِلَّا إِذَا كَانَ يَوْمُ الْقِيَامَةِ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ، أَوْفَرَ مَا كَانَتْ، لَا يَفْقِدُ مِنْهَا فَصِيلًا وَاحِدًا، تَطَؤُهُ بِأَخْفَافِهَا وَتَعَضُّهُ بِأَفْوَاهِهَا، كُلَّمَا مَرَّ عَلَيْهِ أُولَاهَا رُدَّ عَلَيْهِ أُخْرَاهَا، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ الْعِبَادِ، فَيَرَى سَبِيلَهُ: إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ». قِيلَ: يَا رَسُولَ اللهِ، فَالْبَقَرُ وَالْغَنَمُ؟ قَالَ: "وَلَا صَاحِبُ بَقَرٍ وَلَا غَنَمٍ لَا يُؤَدِّي مِنْهَا حَقَّهَا، إِلَّا إِذَا كَانَ يَوْمُ الْقِيَامَةِ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ، لَا يَفْقِدُ مِنْهَا شَيْئًا، لَيْسَ فِيهَا عَقْصَاءُ وَلَا جَلْحَاءُ وَلَا عَضْبَاءُ، تَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِأَظْلَافِهَا، كُلَّمَا مَرَّ عَلَيْهِ أُولَاهَا رُدَّ عَلَيْهِ أُخْرَاهَا، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ الْعِبَادِ، فَيَرَى سَبِيلَهُ: إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ». قِيلَ: يَا رَسُولَ اللهِ، فَالْخَيْلُ؟ قَالَ: "الْخَيْلُ ثَلَاثَةٌ: هِيَ لِرَجُلٍ وِزْرٌ، وَهِيَ لِرَجُلٍ سِتْرٌ، وَهِيَ لِرَجُلٍ أَجْرٌ. فَأَمَّا الَّتِي هِيَ لَهُ وِزْرٌ: فَرَجُلٌ رَبَطَهَا رِيَاءً وَفَخْرًا وَنِوَاءً عَلَى أَهْلِ الْإِسْلَامِ، فَهِيَ لَهُ وِزْرٌ. وَأَمَّا الَّتِي هِيَ لَهُ سِتْرٌ: فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ اللهِ، ثُمَّ لَمْ يَنْسَ حَقَّ اللهِ فِي ظُهُورِهَا وَلَا رِقَابِهَا، فَهِيَ لَهُ سِتْرٌ. وَأَمَّا الَّتِي هِيَ لَهُ أَجْرٌ: فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ اللهِ لِأَهْلِ الْإِسْلَامِ، فِي مَرْجٍ وَرَوْضَةٍ، فَمَا أَكَلَتْ مِنْ ذَلِكَ الْمَرْجِ أَوِ الرَّوْضَةِ مِنْ شَيْءٍ إِلَّا كَتَبَ [اللهُ] لَهُ عَدَدَ مَا أَكَلَتْ حَسَنَاتٍ، وَكُتِبَ لَهُ عَدَدَ أَرْوَاثِهَا وَأَبْوَالِهَا حَسَنَاتٍ، وَلَا تَقْطَعُ طِوَلَهَا فَاسْتَنَّتْ شَرَفًا أَوْ شَرَفَيْنِ، إِلَّا كَتَبَ اللهُ لَهُ عَدَدَ آثَارِهَا وَأَرْوَاثِهَا حَسَنَاتٍ، وَلَا مَرَّ بِهَا صَاحِبُهَا عَلَى نَهْرٍ فَشَرِبَتْ مِنْهُ، وَلَا يُرِيدُ أَنْ يَسْقِيَهَا، إِلَّا كَتَبَ اللهُ لَهُ عَدَدَ مَا شَرِبَتْ حَسَنَاتٍ». قِيلَ: يَا رَسُولَ اللهِ، فَالْحُمُرُ؟ قَالَ: "مَا أُنْزِلَ عَلَيَّ فِي الْحُمُرِ شَيْءٌ إِلَّا هَذِهِ الْآيَةُ الْفَاذَّةُ الْجَامِعَةُ: {فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ} [الزلزلة: ٧-٨] (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സ്വർണത്തിന്റെയും വെള്ളിയുടെയും ബാധ്യതകൾ നിർവ്വഹിക്കാത്തവനു വേണ്ടി അന്ത്യനാളിൽ ആ സ്വർണവും വെള്ളിയും തീയിലിട്ടു പഴുപ്പിച്ചു പരത്തി പലകകളാക്കി നരകത്തിലിട്ടു നന്നായി ചുട്ടുപഴുപ്പിച്ച ശേഷം, അവന്റെ നെറ്റിത്തടവും പാർശ്വവും മുതുകും ചൂടുവെക്കപ്പെടാതിരിക്കുകയില്ല. അതു തണുക്കുമ്പോഴെല്ലാം അതിനെ പൂർവ്വസ്ഥിതിയിലേക്കു മടക്കപ്പെടും. അൻപതിനായിരം വർഷം ദൈർഘ്യമുള്ള ദിനത്തിൽ ജനങ്ങൾക്കിടയിൽ വിധി കൽപിക്കുന്നതുവരെ ഇതു തുടരും. ശേഷം അവനു നരകത്തിലേക്കോ സ്വർഗത്തിലേക്കോ ഉള്ള വഴി കാണിച്ചു കൊടുക്കപ്പെടും." അപ്പോൾ ഒട്ടകത്തിന്റെ ബാധ്യത നിർവഹിക്കാത്തവന്റെ സ്ഥിതിയെന്തായിരിക്കും? എന്ന് ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒട്ടകത്തിന്റെ സകാത്ത് നൽകാത്തവൻ - അവ ജലാശയത്തിൽ ചെല്ലുമ്പോൾ അവയുടെ പാൽ ദരിദ്രർക്കു നൽകുക അതിന്റെ ബാധ്യതകളിലൊന്നാണ് - അന്ത്യനാളിൽ പരന്ന വിശാലമായ പ്രദേശത്തു മുഖം കുത്തി വീഴുകയും അവയെല്ലാം ഒരു കുട്ടിപോലും ഒഴിവാകാതെ മുമ്പത്തേക്കാളും ഏറ്റവും പൂർണമായ രൂപത്തിൽ (തടിച്ചു കൊഴുത്തു) വന്ന് അവയുടെ കുളമ്പുകൾ കൊണ്ട് അവനെ ചവിട്ടിക്കൊണ്ടിരിക്കുകയും വായകൊണ്ട് കടിച്ചുകൊണ്ടിരിക്കുകയും ചെയ്യുന്നതാണ്. ആദ്യം വന്നത് ചവിട്ടിപ്പൊട്ടി നടന്നുപോയിക്കഴിയുമ്പോഴേക്കും പിന്നിലുള്ളത് എത്തും. അമ്പതിനായിരം കൊല്ലം ദൈർഘ്യമുള്ള ദിവസം - ജനങ്ങൾക്കിടയിൽ വിധികൽപിക്കപ്പെടുന്നതുവരെ - ഈ നില തുടരും. അനന്തരം സ്വർഗത്തിലേക്കോ നരകത്തിലേക്കോ ഉള്ള അവന്റെ വഴി അവനു കാണിച്ചുകൊടുക്കും." അപ്പോൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അപ്പോൾ ബാധ്യത നിർവ്വഹിക്കാതെ പശുവിനെയും ആടിനെയും വളർത്തിയവന്റെ അവസ്ഥയെന്താണ്? നബി(സ) അരുളി: "ആടുകളുടെയും പശുക്കളുടെയും സകാത്ത് കൊടുക്കാത്തവനും അന്ത്യനാളിൽ, പരന്നു വിശാലമായ ഭൂമിയിൽ മുഖം കുത്തി വീഴ്ത്തപ്പെടുകയും എന്നിട്ട് അവ മുഴുവനും ഒന്നൊഴിയാതെ കൊമ്പു വളയുകയോ, ഒടിയുകയോ, കൊമ്പില്ലാതിരിക്കുകയോ ചെയ്യാതെ പൂർണരൂപത്തിൽ വന്നു അവയുടെ കൊമ്പുകൊണ്ട് അവനെ കുത്തുകയും കുളമ്പുകൊണ്ടു ചവിട്ടുകയും ചെയ്യും. മുന്നിലുള്ളതു പോയിക്കഴിയുമ്പോഴേക്കും പിന്നിലുള്ളതു കുത്താനും ചവിട്ടാനും തുടങ്ങിയിരിക്കും. അൻപതിനായിരം വർഷത്തിനു തുല്യമായ ദിനത്തിൽ - ജനങ്ങൾക്കിടയിൽ വിധി കൽപിക്കപ്പെടുന്നതുവരെ - ഇതു തുടരും. അനന്തരം സ്വർഗ്ഗത്തിലേക്കോ നരകത്തിലേക്കോ ഉള്ള അവന്റെ വഴി അവനു കാണിച്ചുകൊടുക്കും." അല്ലാഹുവിന്റെ ദൂതരേ, കുതിരയുടെ സകാത്ത് കൊടുക്കാത്തവന്റെ അവസ്ഥയെന്താണ്? എന്നു ചോദിച്ചപ്പോൾ അവിടന്ന് പറഞ്ഞു: "കുതിര മൂന്നിനമാണ്, ചിലർക്ക് അതു പാപമാണ്. ചിലർക്ക് ഒരു രക്ഷാകവചമാണ്. ചിലർക്കു പ്രതിഫലവുമാണ്. പാപമായത്, ദുരഭിമാനത്തിനും അഹങ്കാരത്തിനും മുസ്‌ലിംകളുടെ മേൽ ആക്രമണം നടത്തുവാനുമായി കുതിരയെ വളർത്തുന്നവന് അതു കുറ്റവും പാപവുമാണ്. രക്ഷാകവചമാകുന്ന കുതിരയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഉപയോഗിക്കാനായി വളർത്തുകയും എന്നിട്ട് അതിനുവേണ്ടവിധം തീറ്റകൊടുക്കുക, (പാവങ്ങൾക്ക്) സവാരിക്ക് സൗകര്യപ്പെടുത്തിക്കൊടുക്കുക എന്നിങ്ങനെയുള്ള ബാദ്ധ്യത നിറവേറ്റാൻ മറക്കാതിരിക്കുകയും ചെയ്യുന്നവന് അത് ഒരു രക്ഷാകവചമാണ്. എന്നാൽ, മുസ്‌ലിംകൾക്ക് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാനായി കുതിരയെ വളർത്തുന്നവന് അതു പ്രതിഫലമാണ്. അവൻ അതിനെ മേച്ചിൽ സ്ഥലത്തോ അല്ലെങ്കിൽ ഉദ്യാനത്തിലോ മേയാൻ വിടുകയും എന്നിട്ട് അത് ആ ഉദ്യാനത്തിൽ നിന്നോ മേച്ചിൽ സ്ഥലത്തുനിന്നോ വല്ലതും ഭക്ഷിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിൽ അതിന്റെ തീറ്റയുടെ എണ്ണമനുസരിച്ചും അതു കാഷ്ടിക്കുകയും മൂത്രിക്കുകയും ചെയ്യുന്നതിന്റെ എണ്ണത്തിനനുസരിച്ചുള്ള സൽകർമ്മങ്ങൾ അവന്റെ പേരിൽ രേഖപ്പെടുത്തപ്പെടുന്നതാണ്. അത് കയർ പൊട്ടിച്ച് ഒന്നോ രണ്ടോ അടി നടന്നാൽ അതിന്റെ ചവിട്ടടിയുടെയും അതിന്റെ കാഷ്ടത്തിന്റെയും എണ്ണമനുസരിച്ച് അവന് നന്മകൾ രേഖപ്പെടുത്തുന്നതാണ്. അതിന്റെ ഉടമ അതിനെ പുഴക്കരയിലൂടെ കൊണ്ടുപോകുമ്പോൾ അവൻ ഉദ്ദേശിക്കാതെ അത് ആ പുഴയിൽനിന്നും വെള്ളം കുടിച്ചാൽ അതിന്റെയും എണ്ണമനുസരിച്ച് അവനു സൽകർമ്മങ്ങൾ രേഖപ്പെടുത്തപ്പെടുന്നു." അല്ലാഹുവിന്റെ ദൂതരേ, ബാധ്യത നിറവേറ്റാത്ത കഴുതയുടെ ഉടമയെ സംബന്ധിച്ച് എന്താണഭിപ്രായം? എന്നു ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്ന് അരുളി: "ഏതൊരാൾ അണു അളവ് നന്മ പ്രവർത്തിക്കുന്നുവോ അത് അവൻ കാണും. ഏതൊരാൾ അണു അളവ് തിന്മ പ്രവർത്തിക്കുന്നുവോ അതും അവൻ കാണും'' എന്നുള്ള അതുല്യവും സമഗ്രവുമായ ഈ ആയത്ത് ഒഴികെ വേറെ യാതൊന്നും കഴുതയുടെ കാര്യത്തിൽ എനിക്ക് അവതരിച്ചു കിട്ടിയിട്ടില്ല". (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'الزلزلة: ٧-٨', null, 161, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ صَاحِب كَنْزٍ لَا يُؤَدِّي حَقَّهُ إِلَّا جَعَلَهُ اللَّهُ يَوْمَ الْقِيَامَةِ يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ، فَتُكْوَى بِهَا جَبْهَتُهُ وَجَنْبُهُ وَظَهْرُهُ، حَتَّى يَقْضِيَ اللَّهُ تَعَالَى بَيْنَ عِبَادِهِ، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ، ثُمَّ يَرَى سَبِيلَهُ: إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ. وَمَا مِنْ صَاحِبِ غَنَمٍ لَا يُؤَدِّي حَقَّهَا إِلَّا جَاءَتْ يَوْمَ الْقِيَامَةِ أَوْفَرَ مَا كَانَتْ، فَيُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ، فَتَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِأَظْلَافِهَا، لَيْسَ فِيهَا عَقْصَاء وَلَا جَلْحَاءُ، كُلَّمَا مَضَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا، حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ، ثُمَّ يَرَى سَبِيلَهُ: إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ. وَمَا مِنْ صَاحِبِ إِبِلٍ لَا يُؤَدِّي حَقَّهَا إِلَّا جَاءَتْ يَوْمَ الْقِيَامَةِ أَوْفَرَ مَا كَانَتْ، فَيُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ، فَتَطَؤُهُ بِأَخْفَافِهَا، كُلَّمَا مَضَتْ عَلَيْهِ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا، حَتَّى يَحْكُمَ اللَّهُ تَعَالَى بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ، ثُمَّ يَرَى سَبِيلَهُ: إِمَّا إِلَى الْجَنَّةِ، وَإِمَّا إِلَى النَّارِ. وَفِي رِوَايَةٍ: "وَمِنْ حَقِّهَا حَلَبُهَا يَوْمَ وِرْدِهَا". وَفِي رِوَايَةٍ: قيل لأبي هريرة: فَمَا حَقُّ الْإِبِلِ؟ قَالَ: تُعْطِي الْكَرِيمَةَ، وَتَمْنَحُ الْغَزِيرَةَ، وَتُفْقِرُ الظَّهْرَ، وَتُطْرِقُ الْفَحْلَ، وَتَسْقِي اللَّبَنَ. (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ബാധ്യത നിർവ്വഹിക്കാത്ത ഉടമയുടെ ആഭരണങ്ങൾ അല്ലാഹു അന്ത്യനാളിൽ നരകത്തിലിട്ടു പഴുപ്പിക്കും. ശേഷമവന്റെ നെറ്റിത്തടവും പാർശ്വവും മുതുകും ചൂടുവെക്കപ്പെടും. നിങ്ങൾ കണക്കാക്കുന്ന അമ്പതിനായിരം വർഷം ദൈർഘ്യമുള്ള ദിനത്തിൽ അല്ലാഹു തന്റെ ദാസന്മാർക്കിടയിൽ വിധി കൽപിക്കുന്നതുവരെ ഈ അവസ്ഥ തുടരും. പിന്നീട് ഒന്നുകിൽ സ്വർഗത്തിലേക്കോ അല്ലെങ്കിൽ നരകത്തിലേക്കോ അവനു വഴികാണിക്കപ്പെടുന്നു. ബാധ്യത വീട്ടാത്ത ആടിന്റെ ഉടമ വിധി ദിനത്തിൽ സമനിരപ്പായ സ്ഥലത്തു മുഖം കുത്തി വീഴ്ത്തപ്പെടും. അവന്റെ ആടുകൾ മുമ്പത്തേതിനേക്കാൾ തടിച്ചുകൊഴുത്തു വന്ന് അവയുടെ കൊമ്പുകൊണ്ട് കുത്തുകയും കുളമ്പുകൊണ്ട് ചവിട്ടുകയും ചെയ്യും. അവയിൽ കൊമ്പു വളഞ്ഞതോ കൊമ്പില്ലാത്തതോ ഉണ്ടായിരിക്കില്ല. അവസാനത്തേതും പോയിക്കഴിയുമ്പോഴേക്കും ആദ്യത്തേത് വീണ്ടും വരുന്നതാണ്. നിങ്ങൾ കണക്കാക്കുന്ന അമ്പതിനായിരം വർഷം നീണ്ടുനിൽക്കുന്ന ദിനത്തിൽ ദാസന്മാർക്കിടയിൽ അല്ലാഹു വിധി നിർണയിക്കുന്നതു വരെ ഈ നില തുടരും. പിന്നീടു സ്വർഗ്ഗത്തിലേക്കോ നരകത്തിലേക്കോ അവന്റെ വഴി കാണിക്കപ്പെടും. ബാധ്യത നിർവ്വഹിക്കാത്ത ഒട്ടകത്തിന്റെ ഉടമ വിധിദിനത്തിൽ സമനിരപ്പായ സ്ഥലത്ത് മുഖംകുത്തി വീഴ്ത്തപ്പെടും. അവന്റെ ആടുകൾ മുമ്പത്തേതിനേക്കാൾ തടിച്ചുകൊഴുത്തു വന്ന് അവയുടെ കുളമ്പു കൊണ്ട് ചവിട്ടും. അവസാനത്തേത് പോയിക്കഴിയുമ്പോഴേക്കും ആദ്യത്തേത് വീണ്ടും വരുന്നതാണ്. നിങ്ങൾ കണക്കാക്കുന്ന അമ്പതിനായിരം വർഷം നീണ്ടുനിൽക്കുന്ന ദിനത്തിൽ ദാസൻമാർക്കിടയിൽ അല്ലാഹു വിധിനിർണയിക്കുന്നതു വരെ ഈ നില തുടരും. പിന്നീട് സ്വർഗത്തിലേക്കോ നരകത്തിലേക്കോ അവന്റെ വഴി കാണിക്കപ്പെടും." മറ്റൊരു റിപ്പോർട്ടിൽ: "ജലാശയത്തിനരികെ അതിന്റെ പാൽ പാവങ്ങൾക്കു കുടിപ്പിക്കുകയെന്നത് അതിന്റെ ബാധ്യതയിൽപെട്ടതാണ്." മറ്റൊരു നിവേദനത്തിൽ: അബൂ ഹുറൈറ(റ)യോട് ചോദിക്കപ്പെട്ടു: ഒട്ടകത്തിനുള്ള ബാധ്യതയെന്താണ്?. അദ്ദേഹം പറഞ്ഞു: നല്ല ശക്തിയുള്ളതിനെ നൽകുക, പാൽ കൂടുതലുള്ള മൃഗത്തെ ദാനം ചെയ്യുക, (പാവങ്ങൾക്ക്) വാഹനമായി നൽകുക, ആവശ്യക്കാർക്ക് കൂറ്റൻ ചവിട്ടിക്കുക (ഇണ ചേർക്കുക), പാൽ കുടിപ്പിക്കുക. (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 163, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=55), 1, 'وَفِي رِوَايَةٍ: "وَمِنْ حَقِّهَا حَلَبُهَا يَوْمَ وِرْدِهَا".', 'മറ്റൊരു നിവേദനിൽ: "ജലാശയത്തിനരികെ അതിന്റെ പാൽ പാവങ്ങൾക്കു കുടിപ്പിക്കുകയെന്നത് അതിന്റെ ബാധ്യതയിൽപെട്ടതാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=55), 2, 'وَفِي رِوَايَةٍ: قيل لأبي هريرة: فَمَا حَقُّ الْإِبِلِ؟ قَالَ: تُعْطِي الْكَرِيمَةَ، وَتَمْنَحُ الْغَزِيرَةَ، وَتُفْقِرُ الظَّهْرَ، وَتُطْرِقُ الْفَحْلَ، وَتَسْقِي اللَّبَنَ. (ق,د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: അബൂ ഹുറൈറ(റ)യോട് ചോദിക്കപ്പെട്ടു: ഒട്ടകത്തിനുള്ള ബാധ്യതയെന്താണ്?. അദ്ദേഹം പറഞ്ഞു: നല്ല ശക്തിയുള്ളതിനെ നൽകുക, പാൽ കൂടുതലുള്ള മൃഗത്തെ ദാനം ചെയ്യുക, (പാവങ്ങൾക്ക്) വാഹനമായി നൽകുക, ആവശ്യക്കാർക്ക് കൂറ്റൻ ചവിട്ടിക്കുക (ഇണ ചേർക്കുക), പാൽ കുടിപ്പിക്കുക. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: جِئْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَهُوَ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ، قَالَ: فَرَآنِي مُقْبِلًا، فَقَالَ: "هُمُ الْأَخْسَرُونَ - وَرَبِّ الْكَعْبَةِ - يَوْمَ الْقِيَامَةِ". قَالَ: فَقُلْتُ: مَا لِي! لَعَلَّهُ أُنْزِلَ فِيَّ شَيْءٌ. قَالَ: قُلْتُ: مَنْ هُمْ؟ فِدَاكَ أَبِي وَأُمِّي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "هُمُ الْأَكْثَرُونَ، إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا". فَحَثَا بَيْنَ يَدَيْهِ وَعَنْ يَمِينِهِ وَعَنْ شِمَالِهِ. ثُمَّ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَا يَمُوتُ رَجُلٌ، فَيَدَعُ إِبِلًا أَوْ بَقَرًا لَمْ يُؤَدِّ زَكَاتَهَا، إِلَّا جَاءَتْهُ يَوْمَ الْقِيَامَةِ أَعْظَمَ مَا كَانَتْ وَأَسْمَنَهُ، تَطَؤُهُ بِأَخْفَافِهَا، وَتَنْطَحُهُ بِقُرُونِهَا، كُلَّمَا نَفِدَتْ أُخْرَاهَا عَادَتْ عَلَيْهِ أُولَاهَا، حَتَّى يُقْضَى بَيْنَ النَّاسِ". (ق,د,ت,ن,جه)', 'അബൂദർറ്(റ): നബി(സ) ഒരിക്കൽ കഅ്ബയുടെ തണലിൽ ഇരിക്കുമ്പോൾ ഞാൻ അടുത്തു ചെന്നു. അവിടന്ന് എന്നെ നോക്കി പറഞ്ഞു: "കഅ്ബയുടെ നാഥനാണ് സത്യം! അന്ത്യനാളിൽ അവർ പരാജയപ്പെട്ടവരാണ്." ഞാൻ സ്വയം പറഞ്ഞു: എനിക്കെന്തുപറ്റി? എന്നെപ്പറ്റി വല്ലതും ഇറങ്ങിയതാണോ? ഞാൻ ചോദിച്ചു: എന്റെ പിതാവിനെയും മാതാവിനെയും അങ്ങേക്കു പകരമായി നൽകുന്നു. ആരാണാ വിഭാഗം? നബി(സ) അരുളി: "ധാരാളം സമ്പത്തുള്ളവരാണവർ, ഇങ്ങനെയും ഇങ്ങനെയും ഇങ്ങനെയും ചെയ്യാത്തവരൊഴികെ." (തൽസമയം അവിടന്ന് മുന്നോട്ടും വലത്തോട്ടും ഇടത്തോട്ടും വാരിക്കൊടുക്കുന്നപോലെ കാണിച്ചിരുന്നു.) നബി(സ) തുടർന്നു: "എന്റെ ആത്മാവിനെ നിയന്ത്രിക്കുന്നവനാണ് സത്യം! ബാധ്യത നിർവ്വഹിക്കപ്പെടാത്ത നിലയിൽ ഒട്ടകത്തെയോ പശുവിനെയോ വിട്ടേച്ചു മരിച്ചു പോകുന്ന ഒരാളുടെയും അരികെ അവകൾ പുനരുത്ഥാന നാളിൽ വരാതിരിക്കില്ല. മുമ്പത്തേതിനേക്കാൾ കൂടുതൽ തടിച്ചു കൊഴുത്ത നിലയിലായിരിക്കും അവ വരിക. എന്നിട്ടവനെ അവയുടെ കുളമ്പുകൊണ്ട് ചവിട്ടുകയും കൊമ്പുകൊണ്ട് കുത്തുകയും ചെയ്യും. അവസാനത്തേത് ചവിട്ടി പോയിക്കഴിയുമ്പോഴേക്കും ആദ്യത്തേതു മടങ്ങിവരും. അങ്ങനെ ജനങ്ങൾക്കിടയിൽ വിധി നിർണയിക്കപ്പെടുന്നതുവരെ ഈ നില തുടരും". (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُود رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَا مِنْ رَجُلٍ لَهُ مَالٌ، لَا يُؤَدِّي حَقَّ مَالِهِ، إِلَّا جُعِلَ لَهُ طَوْقًا فِي عُنُقِهِ شُجَاعٌ أَقْرَعُ، وَهُوَ يَفِرُّ مِنْهُ وَهُوَ يَتْبَعُهُ". ثُمَّ قَرَأَ مِصْدَاقَهُ مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ: {وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ هُوَ خَيْرًا لَهُمْ بَلْ هُوَ شَرٌّ لَهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا بِهِ يَوْمَ الْقِيَامَةِ} الْآيَةَ [آل عمران: ١٨٠] (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "തന്റെ സമ്പത്തിന്റെ ബാധ്യത (സകാത്ത്) നിർവ്വഹിക്കാത്ത ഏതൊരു മുഴുവൻ മനുഷ്യരുടെയും പിരടിയിൽ ഉഗ്രവിഷമുള്ള സർപ്പമാല അണിയിക്കും. അവൻ അതിൽനിന്ന് ഓടിരക്ഷപ്പെടാൻ ശ്രമിക്കും. എന്നാൽ, അതവനെ പിൻതുടർന്നുകൊണ്ടേയിരിക്കും." ശേഷം ഇതിനോടു യോജിച്ച ഒരു സൂക്തം നബി(സ) ഖുർആനിൽനിന്നു പാരായണം ചെയ്തു: ''അല്ലാഹു അവന്റെ അനുഗ്രഹത്തിൽനിന്നു തങ്ങൾക്കു തന്നതിൽ പിശുക്കു കാണിക്കുന്നവർ അവർക്കത് ഗുണകരമാണെന്ന് ഒരിക്കലും വിചാരിക്കരുത്. എന്നല്ല, അവർക്ക് ദോഷകരമാണ്. അവർ പിശുക്കു കാണിച്ച ധനം കൊണ്ട് ഉയർത്തെഴുന്നേൽപ്പു നാളിൽ അവരുടെ കഴുത്തിൽ മാല ചാർത്തപ്പെടുന്നതാണ്.'' (ആലു ഇംറാൻ 180) (ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], 'آل عمران: ١٨٠', null, 164, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَيُّمَا رَجُلٍ كَانَتْ لَهُ إِبِلٌ، لَا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا". قَالُوا: يَا رَسُولَ اللَّهِ، مَا نَجْدَتُهَا وَرِسْلُهَا؟ قَالَ: "فِي عُسْرِهَا وَيُسْرِهَا، فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ كَأَغَذِّ مَا كَانَتْ وَأَسْمَنِهِ وَآشَرِهِ، يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ، فَتَطَؤُهُ بِأَخْفَافِهَا، إِذَا جَاءَتْ أُخْرَاهَا أُعِيدَتْ عَلَيْهِ أُولَاهَا، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ النَّاسِ، فَيَرَى سَبِيلَهُ. وَأَيُّمَا رَجُلٍ كَانَتْ لَهُ بَقَرٌ، لَا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا، فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ أَغَذَّ مَا كَانَتْ وَأَسْمَنَهُ وَآشَرَهُ، يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ، فَتَنْطَحُهُ كُلُّ ذَاتِ قَرْنٍ بِقَرْنِهَا، وَتَطَؤُهُ كُلُّ ذَاتِ ظِلْفٍ بِظِلْفِهَا، إِذَا جَاوَزَتْهُ أُخْرَاهَا أُعِيدَتْ عَلَيْهِ أُولَاهَا، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ النَّاسِ، فَيَرَى سَبِيلَهُ. وَأَيُّمَا رَجُلٍ كَانَتْ لَهُ غَنَمٌ، لَا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا، فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ كَأَغَذِّ مَا كَانَتْ وَأَكْثَرِهِ وَأَسْمَنِهِ وَآشَرِهِ، ثُمَّ يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ، فَتَطَؤُهُ كُلُّ ذَاتِ ظِلْفٍ بِظِلْفِهَا، وَتَنْطَحُهُ كُلُّ ذَاتِ قَرْنٍ بِقَرْنِهَا، لَيْسَ فِيهَا عَقْصَاءُ وَلَا عَضْبَاءُ، إِذَا جَاوَزَتْهُ أُخْرَاهَا أُعِيدَتْ عَلَيْهِ أُولَاهَا، فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، حَتَّى يُقْضَى بَيْنَ النَّاسِ، فَيَرَى سَبِيلَهُ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒട്ടകത്തിന്റെ - ക്ഷാമകാലത്തും ക്ഷേമകാലത്തും - ബാധ്യത (സകാത്ത്) വീട്ടാത്ത മനുഷ്യൻ.." അപ്പോൾ അനുചരർ ചോദിച്ചു: നബിയേ, ക്ഷാമം കൊണ്ടും ക്ഷേമം കൊണ്ടും ഉദ്ദേശിക്കുന്നതെന്താണ്? നബി(സ) പറഞ്ഞു: "അതിന്റെ എളുപ്പകാലത്തും പ്രയാസകാലത്തും. പുനരുത്ഥാനനാളിൽ അവകൾ കൂടുതൽ തടിച്ചതായും ശക്തിയായതായും വരും. പരന്ന വിശാലമായ സ്ഥലത്തുവെച്ച് മുഖംകുത്തി വീഴ്ത്തപ്പെടും. അപ്പോൾ അവനെ അവകൾ കാലുകൾ കൊണ്ട് ചവിട്ടും. സംഘത്തിലെ അവസാനത്തേതും ചവിട്ടിയാൽ ആദ്യത്തേത് (വീണ്ടും) ചവിട്ടാൻ തുടങ്ങും. അമ്പതിനായിരം വർഷം ദൈർഘ്യമുള്ള ദിനത്തിൽ ജനങ്ങൾക്കിടയിൽ വിചാരണചെയ്യപ്പെടും വരെ ഈ നില തുടരും. ശേഷം അവൻ തന്റെ വഴികാണും. ക്ഷാമകാലത്തും ക്ഷേമകാലത്തും പശുക്കളുടെ ബാധ്യത (സകാത്ത്) നൽകാത്ത ഏതൊരു മനുഷ്യനും ഉയർത്തെഴുന്നേൽപിന്റെ നാളിൽ അവ കൂടുതൽ തടിച്ചതായും ഉന്മേഷവത്തായും ശക്തിയാർജ്ജിച്ചവയായും വരും. പരന്ന വിശാലമായ സ്ഥലത്ത് അവൻ മുഖം കുത്തിവീഴ്ത്തപ്പെടും. കൊമ്പുള്ളവ അവനെ കൊമ്പ് കൊണ്ട് കുത്തുകയും കുളമ്പുകളുള്ളവ അവനെ കുളമ്പ് കൊണ്ട് അവനെ തൊഴിക്കുകയും ചെയ്യും. അവസാനത്തേതു വിട്ടുപിരിഞ്ഞാൽ ആദ്യത്തേതു (വീണ്ടും) മടങ്ങിവരും. അമ്പതിനായിരം വർഷത്തെ ദൈർഘ്യമുള്ള ദിനത്തിൽ ജനങ്ങൾക്കിടയിൽ വിചാരണചെയ്യപ്പെടുന്നതു വരെ ഈ നില തുടരും. ശേഷം അവ അവയുടെ വഴികാണും. ആടുകളുടെ സമൃദ്ധി കാലത്തും പ്രയാസകാലത്തും സകാത്ത് നൽകാത്ത മനുഷ്യൻ, അന്ത്യനാളിൽ അവ കൂടുതൽ ശക്തിയും ഉന്മേഷവും തടിയും ഉള്ളവയായി വരും, പരന്ന വിശാലമായ സ്ഥലത്ത് അവൻ മുഖംകുത്തി വീഴ്ത്തപ്പെടും. അപ്പോൾ കുളമ്പുകളുള്ളവ കുളമ്പുകൊണ്ടു തൊഴിക്കുകയും കൊമ്പുള്ളവ കൊമ്പുകൊണ്ട് കുത്തുകയും ചെയ്യും. അവയിൽ കൊമ്പ് പിന്നിലേക്കു പിരിഞ്ഞവയോ കൊമ്പു മുറിഞ്ഞവയോ ഉണ്ടാവില്ല. അവസാനത്തേത് അവനെ വിട്ടുപിരിഞ്ഞാൽ ആദ്യത്തേത് വീണ്ടും വരും. അമ്പതിനായിരം വർഷത്തെ ദൈർഘ്യമുള്ള ദിനത്തിൽ ജനങ്ങളിൽ വിധിനിർണയിക്കപ്പെടും വരെ ഈ നില തുടരും. ശേഷം അവൻ തന്റെ മാർഗം കാണും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 165, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "فِي كُلِّ إِبِلٍ سَائِمَةٍ مِنْ كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ، لَا تُفَرَّقُ إِبِلٌ عَنْ حِسَابِهَا، مَنْ أَعْطَاهَا مُؤْتَجِرًا لَهُ أَجْرُهَا، وَمَنْ مَنَعَهَا فَإِنَّا آخِذُوهَا وَشَطْرَ إِبِلِهِ، عَزْمَةً مِنْ عَزَمَاتِ رَبِّنَا، لَا يَحِلُّ لِآلِ مُحَمَّدٍ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنْهَا شَيْءٌ". (د,ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എല്ലാ മേഞ്ഞുനടക്കുന്ന നാൽപ്പത് ഒട്ടകങ്ങളിലും ഒരു ബിൻതു ലബൂൻ (മൂന്നാം വയസ്സിൽ പ്രവേശിച്ച ഒട്ടകം) സകാത്തായുണ്ട്, ഒരൊട്ടകത്തേയും എണ്ണത്തിൽനിന്നു മാറ്റിനിർത്താൻ പാടില്ല. ആരെങ്കിലും പ്രതിഫലം കാംക്ഷിച്ച് അതു നൽകിയാൽ അവന് അതിന്റെ പ്രതിഫലമുണ്ട്. ആരെങ്കിലും അതിനെതിരു നിന്നാൽ അവനിൽ നിന്ന് നാം അതിനെയും അവന്റെ ഒട്ടകത്തിന്റെ പകുതിയും പിടിക്കും. നാഥന്റെ നിർബന്ധങ്ങളിൽപെട്ട ഒരു നിർബന്ധമാണത്. ഇവയിലൊന്നും മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന് അനുവദനീയമല്ല." (ദ,ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ الَّذِي لَا يُؤَدِّي زَكَاةَ مَالِهِ يُخَيَّلُ إِلَيْهِ مَالُهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ لَهُ زَبِيبَتَانِ، قَالَ: فَيَلْتَزِمُهُ - أَوْ يُطَوِّقُهُ - قَالَ: يَقُولُ: أَنَا كَنْزُكَ أَنَا كَنْزُكَ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "സമ്പത്തിന് സകാത്ത് നൽകാത്തവന് അന്ത്യനാളിൽ അവന്റെ ധനം കണ്ണിന് മുകളിൽ കറുത്ത രണ്ട് പുള്ളികളുള്ള, തല വെളുത്ത ഉഗ്രസർപ്പമായി രൂപാന്തരപ്പെടും." അവിടുന്ന് പറഞ്ഞു: "അത് അവനെ വിട്ടൊഴിയുന്നതല്ല, അല്ലെങ്കിൽ (നബി(സ) പറഞ്ഞ വാക്ക്) അതവന് ഹാരമായിരിക്കും. ഞാൻ നിന്റെ നിധിയാണ്, ഞാൻ നിന്റെ നിധിയാണ് എന്ന് അത് പറഞ്ഞുകൊണ്ടിരിക്കും." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ آتَاهُ اللَّهُ عَزَّ وَجَلَّ مَالًا، فَلَمْ يُؤَدِّ زَكَاتَهُ، مُثِّلَ لَهُ مَالُهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ لَهُ زَبِيبَتَانِ، يَأْخُذُ بِلِهْزِمَتَيْهِ يَوْمَ الْقِيَامَةِ، فَيَقُولُ: أَنَا مَالُكَ، أَنَا كَنْزُكَ". ثُمَّ تَلَا هَذِهِ الْآيَةَ: {وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ} الْآيَةَ. (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "അല്ലാഹു ഒരാൾക്ക് ധനം കൊടുത്തു, അവൻ അതിലുള്ള സകാത്ത് കൊടുത്തില്ല. എങ്കിൽ പുനരുത്ഥാന ദിവസം ആ ധനം അവന്റെ മുമ്പിൽ, തലയിൽ രണ്ട് കറുത്ത പുള്ളികളോടുകൂടിയ തല വെളുത്ത ഒരു വലിയ പാമ്പിന്റെ രൂപത്തിൽ തലപൊക്കി നിൽക്കും. അവന്റെ രണ്ടു കവിൾത്തടങ്ങളിലും പിടിച്ചുകൊണ്ട് അതു പറയും: ഞാൻ നിന്റെ ധനമാണ്, നീ നിക്ഷേപിച്ചു വെച്ചിരുന്ന നിന്റെ നിധി." തുടർന്നു നബി(സ) ഈ ഖുർആൻ വാക്യം ഓതി: ''തന്റെ അനുഗ്രഹം മൂലം അല്ലാഹു നൽകിയ ധനത്തിൽ പിശുക്ക് കാണിക്കുന്നത് അവർക്ക് ഗുണകരമാണെന്ന് ഒരിക്കലും വിചാരിച്ചുപോകരുത്.''', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], '{}'::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ الْأَحْنَفِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ فِي نَفَرٍ مِنْ قُرَيْشٍ، فَمَرَّ أَبُو ذَرٍّ رضي الله عنه وَهُوَ يَقُولُ: بَشِّرِ الْكَانِزِينَ بِكَيٍّ فِي ظُهُورِهِمْ يَخْرُجُ مِنْ جُنُوبِهِمْ، وَبِكَيٍّ مِنْ قِبَلِ أَقْفَائِهِمْ يَخْرُجُ مِنْ جِبَاهِهِمْ، قَالَ: ثُمَّ تَنَحَّى فَقَعَدَ، قَالَ: قُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذَا أَبُو ذَرٍّ. قَالَ: فَقُمْتُ إِلَيْهِ، فَقُلْتُ: مَا شَيْءٌ سَمِعْتُكَ تَقُولُ قُبَيْلُ؟ قَالَ: مَا قُلْتُ إِلَّا شَيْئًا قَدْ سَمِعْتُهُ مِنْ نَبِيِّهِمْ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، قَالَ: قُلْتُ: مَا تَقُولُ فِي هَذَا الْعَطَاءِ؟ قَالَ: خُذْهُ، فَإِنَّ فِيهِ الْيَوْمَ مَعُونَةً، فَإِذَا كَانَ ثَمَنًا لِدِينِكَ فَدَعْهُ. (م)', 'അഹ്നഫുബ്നു ഖൈസ്(റ): ഒരു സംഘം ഖുറൈശികളോടൊപ്പം ഒരിക്കൽ ഞാൻ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അബൂദർറ്(റ) ഇപ്രകാരം പറഞ്ഞുകൊണ്ട് അതിലൂടെ നടന്നുപോയി: (സകാത്ത് കൊടുക്കാത്ത) സമ്പത്ത് സൂക്ഷിക്കുന്നവർക്ക്, മുതുകിൽ വെച്ച് പാർശ്വങ്ങളിൽ കൂടി പുറത്തുവരുന്ന ചൂടുവെക്കൽ കൊണ്ടും, പിരടിയിൽ വെച്ച് നെറ്റിത്തടത്തിൽ കൂടി പുറത്തുവരുന്ന ചൂടുവെക്കൽ കൊണ്ടും സന്തോഷ വാർത്ത അറിയിക്കുക. അനന്തരം അദ്ദേഹം അൽപമകലെ ഒരു സ്ഥലത്തു പോയി ഇരുന്നു. ഞാൻ ചോദിച്ചു: ഇതാരാണ്? അപ്പോൾ ആളുകൾ പറഞ്ഞു: ഇത് അബൂദർറാണ്. നിവേദകൻ: ഉടൻ ഞാനദ്ദേഹത്തിന്റെ അടുത്തുചെന്ന് ചോദിച്ചു: ഈയടുത്ത സമയത്ത് നിങ്ങളെന്ത് പറയുന്നതാണ് ഞാൻ കേട്ടത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ)യിൽ നിന്ന് കേട്ട കാര്യമല്ലാതെ ഞാൻ പറഞ്ഞിട്ടില്ല. ഞാൻ ചോദിച്ചു: ഈ ദാനത്തെക്കുറിച്ച് താങ്കൾ എന്തുപറയുന്നു? അദ്ദേഹം പറഞ്ഞു: നീയത് സ്വീകരിക്കുക. നിശ്ചയം, ഈ ദിവസം അതിലൊരു സഹായമുണ്ട്. എന്നാൽ അത് നിന്റെ മതത്തിന് വിലയായിത്തീരുകയാണെങ്കിൽ നീയതുപേക്ഷിക്കുക. (മു)', 'الْأَحْنَفِ بْنِ قَيْسٍ', 'അഹ്നഫുബ്നു ഖൈസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 166, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، إِذْ جَاءَ رَجُلٌ عَلَى نَاقَةٍ لَهُ، فَجَعَلَ يُصَرِّفُهَا يَمِينًا وَشِمَالًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ عِنْدَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا ظَهْرَ لَهُ، وَمَنْ كَانَ عِنْدَهُ فَضْلُ زَادٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لَا زَادَ لَهُ". حَتَّى ظَنَنَّا أَنَّهُ لَا حَقَّ لِأَحَدٍ مِنَّا فِي الْفَضْلِ. (م,د)', 'അബുസഈദിൽ ഖുദ്‌രി(റ): ഞങ്ങൾ ഒരു യാത്രയിൽ നബി(സ)ക്കൊപ്പമായിരിക്കുമ്പോൾ ഒരാൾ ഒട്ടകപ്പുറത്ത് വന്നു. അയാൾ അതിനെ വലതും ഇടതും തിരിക്കാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "വല്ലവരുടെയും പക്കൽ മൃഗവാഹനത്തിന്റെ ബാക്കി ഭാഗമുണ്ടെങ്കിൽ അത് ഇല്ലാത്തവനു നൽകികൊള്ളട്ടെ. ഭക്ഷണത്തിന്റെ ബാക്കി വല്ലവന്റെയും പക്കലുണ്ടെങ്കിൽ അവൻ ഇല്ലാത്തവന് നൽകിക്കൊള്ളട്ടെ." ബാക്കി വരുന്നതിൽ നമുക്കാർക്കും ഒരവകാശവുമില്ല എന്നു ഞങ്ങൾക്ക് തോന്നി. (മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: {وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ} [التوبة: ٣٤] قَالَ: كَبُرَ ذَلِكَ عَلَى الْمُسْلِمِينَ، فَقَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: أَنَا أُفَرِّجُ عَنْكُمْ. فَانْطَلَقَ، فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنَّهُ كَبُرَ عَلَى أَصْحَابِكَ هَذِهِ الْآيَةُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ لَمْ يَفْرِضِ الزَّكَاةَ إِلَّا لِيُطَيِّبَ مَا بَقِيَ مِنْ أَمْوَالِكُمْ، وَإِنَّمَا فَرَضَ الْمَوَارِيثَ لِتَكُونَ لِمَنْ بَعْدَكُمْ". فَكَبَّرَ عُمَرُ، ثُمَّ قَالَ لَهُ: "أَلَا أُخْبِرُكَ بِخَيْرِ مَا يَكْنِزُ الْمَرْءُ؟ الْمَرْأَةُ الصَّالِحَةُ: إِذَا نَظَرَ إِلَيْهَا سَرَّتْهُ، وَإِذَا أَمَرَهَا أَطَاعَتْهُ، وَإِذَا غَابَ عَنْهَا حَفِظَتْهُ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''സ്വർണ്ണവും വെള്ളിയും നിക്ഷേപമാക്കി വെക്കുകയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ അതു ചെലവഴിക്കാതിരിക്കുകയും ചെയ്യുന്നവരാരോ അവർക്കു വേദനയേറിയ ശിക്ഷയെപ്പറ്റി സന്തോഷ വാർത്ത അറിയിക്കുക'' (തൗബ: 34) എന്ന സൂക്തം അവതരിച്ചപ്പോൾ മുസ്‌ലിംകൾക്ക് അതു പ്രയാസമായി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: ഞാൻ നിങ്ങൾക്കത് ലഘുവാക്കിത്തരും. ഉമർ(റ) പോയി നബി(സ)യോടു പറഞ്ഞു: ഈ ആയത്ത് അവിടുത്തെ അനുചരർക്കു പ്രയാസം സൃഷ്ടിക്കുന്നു നബിയേ. നബി(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങളുടെ ധനത്തിൽ സകാത്ത് നിർബന്ധമാക്കിയതു ശേഷിക്കുന്നത് ശുദ്ധീകരിക്കാൻ വേണ്ടിയാണ്. അനന്തരാവകാശം നിർബന്ധമാക്കിയതു നിങ്ങളെ ശേഷക്കാർക്കു വേണ്ടി മാത്രമാണ്." അപ്പോൾ ഉമർ(റ) തക്ബീർ മുഴക്കി. പിന്നെ നബി(സ) അദ്ദേഹത്തോടു പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്കു മനുഷ്യന്റെ ഏറ്റവും നല്ല നിധിയേതെന്ന് അറിയിച്ചുതരട്ടെയോ?, സദ്‌വൃത്തയായ സ്ത്രീയാണത്. അവളെ നോക്കിയാൽ അവളവനെ സന്തോഷിപ്പിക്കും, അവളോടു കൽപിച്ചാൽ വഴിപ്പെടും. അവളെവിട്ടു വിദൂരത്തായാലും അവൾ അവനെ സൂക്ഷിക്കും." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'التوبة: ٣٤', null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ خَالِدِ بْنِ أَسْلَمَ - مَوْلَى عُمَرَ بْنِ الْخَطَّابِ - رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجْتُ مَعَ عَبْدِ اللهِ بْنِ عُمَرَ، فَلَحِقَهُ أَعْرَابِيٌّ فَقَالَ لَهُ: قَوْلُ اللَّهِ عَزَّ وَجَلَّ: {وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللهِ} قَالَ لَهُ ابْنُ عُمَرَ: مَنْ كَنَزَهَا فَلَمْ يُؤَدِّ زَكَاتَهَا فَوَيْلٌ لَهُ، إِنَّمَا كَانَ هَذَا قَبْلَ أَنْ تُنْزَلَ الزَّكَاةُ. فَلَمَّا أُنْزِلَتْ جَعَلَهَا اللهُ طَهُورًا لِلْأَمْوَالِ. ثُمَّ الْتَفَتَ فَقَالَ: مَا أُبَالِي لَوْ كَانَ لِي أُحُدٌ ذَهَبًا، أَعْلَمُ عَدَدَهُ وَأُزَكِّيهِ، وَأَعْمَلُ فِيهِ بِطَاعَةِ اللهِ عَزَّ وَجَلَّ. (خ,جه)', 'ഉമറുബ്നുൽഖത്താബ്(റ)ന്റെ അടിമ ഖാലിദുബ്നു അസ്‌ലം(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വോടൊപ്പം പുറപ്പെട്ടു. വഴിമധ്യേ ഒരു ഗ്രാമീണ അറബി അദ്ദേഹത്തിന്റെയടുത്തുവന്നു. ''സ്വർണ്ണവും വെള്ളിയും നിക്ഷേപമാക്കി വെക്കുകയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ അതു ചെലവഴിക്കാതിരിക്കുകയും ചെയ്യുന്നവരാരോ അവർക്കു വേദനയേറിയ ശിക്ഷയെപ്പറ്റി സന്തോഷവാർത്തയറിയിക്കുക'' (തൗബ: 34) എന്ന ഖുർആൻ വചനം ഉദ്ധരിച്ചു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) അദ്ദേഹത്തോടു പറഞ്ഞു: സകാത്ത് നൽകാതെ സമ്പത്തു സൂക്ഷിച്ചുവെച്ചവർക്കു നാശം. ഇത് സകാത്ത് നിർബന്ധമാക്കുന്ന സൂക്തം അവതരിക്കുന്നതിനു മുമ്പ് മാത്രമാണ്. അത് അവതരിച്ചപ്പോൾ സകാത്തിനെ നാഥൻ സമ്പത്തിന്റെ ശുദ്ധീകരണമാക്കി. പിന്നെ അദ്ദേഹം പിൻതിരിഞ്ഞശേഷം പറഞ്ഞു: ഉഹ്ദ് പർവ്വതം കണക്കെ എനിക്കു സ്വർണ്ണമുണ്ടാകുകയാണെങ്കിലും എനിക്കതു പ്രശ്നമേയല്ല. അതിന്റെ എണ്ണം ഞാൻ അറിയും. അതിനെ ശുദ്ധീകരിക്കുകയും അല്ലാഹുവിനോടുള്ള അനുസരണയോടെ ഞാൻ അതിൽ കൈകാര്യം നടത്തുകയും ചെയ്യും. (ബു,ജ)', 'خَالِدِ بْنِ أَسْلَمَ - مَوْلَى عُمَرَ بْنِ الْخَطَّابِ -', 'ഉമറുബ്നുൽഖത്താബ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَدَّيْتَ زَكَاةَ مَالِكَ فَقَدْ قَضَيْتَ مَا عَلَيْكَ". (ت جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിന്റെ ധനത്തിന്റെ സകാത്തു നൽകിയാൽ നിന്റെ ബാധ്യത നീ നിറവേറ്റിയവനായി." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَتَمَنَّى أَنْ يَأْتِيَ الْأَعْرَابِيُّ الْعَاقِلُ، فَيَسْأَلَ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَنَحْنُ عِنْدَهُ، فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ أَتَاهُ أَعْرَابِيٌّ، فَجَثَا بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، إِنَّ رَسُولَكَ أَتَانَا، فَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللَّهَ أَرْسَلَكَ، فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَبِالَّذِي رَفَعَ السَّمَاءَ وَبَسَطَ الْأَرْضَ وَنَصَبَ الْجِبَالَ، آللَّهُ أَرْسَلَكَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ: أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ: أَنَّ عَلَيْنَا صَوْمَ شَهْرٍ فِي السَّنَةِ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ: أَنَّ عَلَيْنَا فِي أَمْوَالِنَا الزَّكَاةَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ قَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَإِنَّ رَسُولَكَ زَعَمَ لَنَا أَنَّكَ تَزْعُمُ: أَنَّ عَلَيْنَا الْحَجَّ إِلَى الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللَّهُ أَمَرَكَ بِهَذَا؟ فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "نَعَمْ". فَقَالَ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَا أَدَعُ مِنْهُنَّ شَيْئًا، وَلَا أُجَاوِزُهُنَّ، ثُمَّ وَثَبَ. فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنْ صَدَقَ الْأَعْرَابِيُّ دَخَلَ الْجَنَّةَ". (ق,ت)', 'അനസ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമുണ്ടായിരിക്കെ ബുദ്ധിമാനായ ഒരു ഗ്രാമീണ അറബി വന്ന് നബി(സ)യോട് വല്ലതും ചോദിക്കണമെന്ന് ഞങ്ങൾ ആഗ്രഹിക്കാറുണ്ടായിരുന്നു. ഞങ്ങൾ (പ്രതീക്ഷിച്ചപ്രകാരം) നബി(സ)യുടെ അടുത്തായിരിക്കെ ഒരു ഗ്രാമീണ അറബി വന്നു. നബി(സ)യുമായി കാൽമുട്ടുകൾ ചേർത്ത് ഇരുന്നു. എന്നിട്ട് പറഞ്ഞു: മുഹമ്മദ്, നിങ്ങളുടെ ദൂതൻ ഞങ്ങളുടെ അടുത്തുവന്ന്, നിങ്ങളെ അല്ലാഹു ദൂതനാക്കി അയച്ചതാണെന്ന് നിങ്ങൾ വാദിക്കുന്നുവെന്ന് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ ചോദിച്ചു: പർവ്വതങ്ങൾ നാട്ടുകയും ഭൂമിയെ പരത്തുകയും ആകാശത്തെ ഉയർത്തുകയും ചെയ്ത ഒരുവനാണ, നിങ്ങളെ അല്ലാഹുവാണോ അയച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ വീണ്ടും പറഞ്ഞു: നിങ്ങളുടെ ദൂതൻ, ഞങ്ങളുടെ മേൽ രാവും പകലുമായി അഞ്ച് നേരത്തെ നിസ്കാരം നിർബന്ധമുണ്ടെന്ന് നിങ്ങൾ പറഞ്ഞതായി ഞങ്ങളോടു പറഞ്ഞു. നബി(സ) അരുളി: "അതെ". അയാൾ ചോദിച്ചു: നിങ്ങളെ അയച്ചവനാണ, അല്ലാഹുവാണോ ഇത് നിങ്ങളോട് കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ വീണ്ടും പറഞ്ഞു: നിങ്ങളുടെ ദൂതൻ, വർഷത്തിൽ ഞങ്ങൾക്കൊരു മാസം വ്രതമനുഷ്ഠിക്കൽ നിർബന്ധമാണെന്നു നിങ്ങൾ പറഞ്ഞതായി ഞങ്ങളോടു പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അദ്ദേഹം സത്യമാണ് പറഞ്ഞത്." അയാൾ ചോദിച്ചു: നിങ്ങളെ അയച്ചവനാണ, അല്ലാഹുവാണോ നിങ്ങളോട് ഇപ്രകാരം കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ വീണ്ടും ചോദിച്ചു: ഞങ്ങളുടെ ധനത്തിൽ സകാത്ത് നിർബന്ധമുണ്ടെന്നു നിങ്ങൾ പറഞ്ഞതായി നിങ്ങളുടെ ദൂതൻ ഞങ്ങളോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അവൻ സത്യം പറഞ്ഞു." അയാൾ ചോദിച്ചു: നിങ്ങളെ അയച്ചവനാണ, ഇത് അല്ലാഹുവാണോ നിങ്ങളോട് കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ വീണ്ടും ചോദിച്ചു: ഞങ്ങളിൽ കഴിവുള്ളവർക്ക് ഹജ്ജു ചെയ്യൽ നിർബന്ധമാണെന്നു നിങ്ങൾ പറഞ്ഞതായി നിങ്ങളുടെ ദൂതൻ ഞങ്ങളോടു പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അതെ." അദ്ദേഹം ചോദിച്ചു: നിങ്ങളെ അയച്ചവനാണ് സത്യം, അല്ലാഹുവാണോ നിങ്ങളോട് ഇങ്ങനെ കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: നിങ്ങളെ സത്യവുമായി അയച്ചവനാണ് സത്യം, ഞാൻ അതിൽനിന്ന് ഒന്നും ഉപേക്ഷിക്കുകയോ വിട്ടുകടക്കുകയോ ചെയ്യില്ല. ശേഷം അദ്ദേഹം പോയി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആ ഗ്രാമീണ അറബി സത്യമാണ് പറഞ്ഞതെങ്കിൽ അദ്ദേഹം സ്വർഗ്ഗത്തിൽ കടന്നു." (ബു,മു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 168, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَمِعَتْهُ - تَعْنِي النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ - يَقُولُ: "لَيْسَ فِي الْمَالِ حَقٌّ سِوَى الزَّكَاةِ". (ت,جه)', 'ഫാത്വിമാ ബിൻത് ഖൈസ്(റ): നബി(സ) പറയുന്നത് മഹതി കേട്ടു: "ധനത്തിൽ സകാത്തല്ലാത്ത മറ്റൊരു ബാധ്യതയും ഇല്ല." (തു,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമാ ബിൻത് ഖൈസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عُمَرَ بْنَ الْخَطَّابِ عَلَى الصَّدَقَةِ، فَمَنَعَ ابْنُ جَمِيلٍ وَخَالِدُ بْنُ الْوَلِيدِ، وَالْعَبَّاسُ، رَضِيَ اللهُ عَنْهُم، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَا يَنْقِمُ ابْنُ جَمِيلٍ إِلَّا أَنْ كَانَ فَقِيرًا فَأَغْنَاهُ اللَّهُ، وَأَمَّا خَالِدُ بْنُ الْوَلِيدِ فَإِنَّكُمْ تَظْلِمُونَ خَالِدًا، فَقَدِ احْتَبَسَ أَدْرَاعَهُ وَأَعْتُدَهُ فِي سَبِيلِ اللَّهِ. وَأَمَّا الْعَبَّاسُ عَمُّ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَهِيَ عَلَيَّ وَمِثْلُهَا". ثُمَّ قَالَ: "أَمَا شَعَرْتَ أَنَّ عَمَّ الرَّجُلِ صِنْوُ الْأَبِ؟ أَوْ: صِنْوُ أَبِيهِ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) ഉമർ(റ)വിനെ സകാത്ത് പിരിക്കാനയച്ചു. അപ്പോൾ ഇബ്നുജമീലും, ഖാലിദുബ്നു വലീദും, അബ്ബാസ്(റ)വും അത് നൽകാൻ വിസമ്മതിച്ചു. അപ്പോൾ നബി(സ) അരുളി: "ഇബ്നുജമീൽ ദരിദ്രനായിരുന്നു. പിന്നീട് അല്ലാഹു അദ്ദേഹത്തെ ധനികനാക്കി എന്നതല്ലാതെ അവൻ ഒന്നും ചെയ്തില്ല. ഖാലിദിനെ സംബന്ധിച്ച് പറയുകയാണെങ്കിൽ നിങ്ങൾ അദ്ദേഹത്തോട് അനീതി ചെയ്യുകയാണുണ്ടായത്. കാരണം (അദ്ദേഹത്തിനു സകാത്ത് നിർബന്ധമില്ല), തന്റെ യുദ്ധോപകരണങ്ങളും അങ്കികളുമെല്ലാം അദ്ദേഹം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വഖ്ഫ് ചെയ്തിരിക്കയാണ്. (ഇതു കച്ചവടച്ചരക്കായി കണക്കാക്കിയാണു സകാത്ത് ആവശ്യപ്പെട്ടത്). റസൂൽ(സ)യുടെ പിതൃസഹോദരനായ അബ്ബാസിന്റെ കാര്യം, അദ്ദേഹം തരേണ്ടതും അതിന്റെയത്രയും ഞാൻ തരുന്നതാണ്." ശേഷം നബി(സ) പറഞ്ഞു: "ഉമർ, ഒരാൾക്ക് അയാളുടെ പിതൃവ്യൻ പിതാവിനെപ്പോലെയാണെന്നു നിങ്ങൾക്കറിയില്ലേ? അല്ലെങ്കിൽ: അദ്ദേഹത്തിൽ പിതാവിന്റെ സ്ഥാനത്താണ്." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 169, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ الْعَبَّاسَ سَأَلَ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي تَعْجِيلِ صَدَقَتِهِ قَبْلَ أَنْ تَحِلَّ، فَرَخَّصَ لَهُ فِي ذَلِكَ. (د,ت,جه)', 'അലി(റ): സമയമെത്തുന്നതിനു മുമ്പ് സകാത്ത് മുൻകൂർ നൽകാൻ അബ്ബാസ്(റ) നബി(സ)യോട് (അനുവാദം) ആവശ്യപ്പെട്ടു. ആ വിഷയത്തിൽ അദ്ദേഹത്തിന് ഇളവ് അനുവദിക്കപ്പെട്ടു. (ദ,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 170, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ لِعُمَرَ: "إِنَّا قَدْ أَخَذْنَا زَكَاةَ الْعَبَّاسِ عَامَ الْأَوَّلِ لِلْعَامِ". (ت)', 'അലി(റ): നബി(സ) ഉമർ(റ)വിനോട് പറഞ്ഞു: "നിശ്ചയം, അബ്ബാസ്(റ)വിന്റെ രണ്ടുവർഷത്തെ സകാത്ത് നാം മുൻകൂർ വാങ്ങിയിട്ടുണ്ട്." (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 170, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ، وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبُ، فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ، ثُمَّ يُرَبِّيهَا لِصَاحِبِهِ كَمَا يُرَبِّي أَحَدُكُمْ فُلُوَّهُ، حَتَّى تَكُونَ مِثْلَ الْجَبَلِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "വല്ലവനും തന്റെ പരിശുദ്ധ സമ്പാദ്യത്തിൽനിന്നും - പരിശുദ്ധ വസ്തു മാത്രമേ അല്ലാഹു സ്വീകരിക്കുകയുള്ളൂ - ഒരു കാരക്കയോളം ധനം ദാനം ചെയ്താൽ അല്ലാഹു തന്റെ വലതുകൈകൊണ്ട് അത് സ്വീകരിക്കും. പിന്നെ നിങ്ങളിലൊരാൾ തന്റെ ശിശുവിനെ പോറ്റി വളർത്തുന്നതുപോലെ, ഒരു മലയോളം വലുതാകും വരെയും അല്ലാഹു അതിനെ വളർത്തും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 170, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَيُّهَا النَّاسُ، إِنَّ اللَّهَ طَيِّبٌ، لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ، فَقَالَ: {يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ} [المؤمنون: ٥١] وَقَالَ: {يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ} [البقرة: ١٧٢]. ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ، يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ: يَا رَبِّ يَا رَبِّ، وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لِذَلِكَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഓ ജനങ്ങളേ, നിശ്ചയം അല്ലാഹു പരിശുദ്ധനാണ്. പരിശുദ്ധമായതല്ലാതെ അവൻ സ്വീകരിക്കുകയില്ല. നിശ്ചയം, പ്രവാചകന്മാരോടു കൽപിച്ചതു തന്നെയാണ് സത്യവിശ്വാസികളോടും കൽപിച്ചിട്ടുള്ളത്." തുടർന്ന് നബി(സ) ഖുർആൻ വാക്യം ഉദ്ധരിച്ചു: ''ദൂതന്മാരേ, നിങ്ങൾ ഉത്തമമായത് ആഹരിക്കുകയും, സൽകർമ്മങ്ങൾ അനുഷ്ഠിക്കുകയും ചെയ്യുവിൻ. നിശ്ചയം, നിങ്ങൾ പ്രവർത്തിക്കുന്നതു ഞാൻ നന്നായറിയുന്നവനാണ്.'' (മുഅ്മിൻ:51). വീണ്ടും നബി(സ) ഉദ്ധരിച്ചു: ''ഹേ സത്യവിശ്വാസികളേ, നാം നിങ്ങൾക്കു നൽകിയ ഉത്തമമായതിൽ നിന്ന് നിങ്ങൾ ഭക്ഷിക്കുക.'' (അൽബഖറ:172). അനന്തരം നബി(സ) ഒരു മനുഷ്യനെക്കുറിച്ച് പറഞ്ഞു: അവൻ ദീർഘയാത്ര ചെയ്തതിനാൽ തലമുടി ജടകുത്തുകയും പാദങ്ങളിൽ പൊടിപടലങ്ങൾ പറ്റുകയും ചെയ്തിരിക്കും. അവൻ ഇരുകൈകളും വാനിലേക്കുയർത്തി ''രക്ഷിതാവേ, രക്ഷിതാവേ'' എന്നിങ്ങനെ വിളിച്ചു പ്രാർത്ഥിക്കും. നിഷിദ്ധമായ ആഹാരമാണ് അവൻ ഭക്ഷിച്ചത്. അവൻ കുടിച്ച പാനീയവും ധരിച്ച വസ്ത്രവും നിഷിദ്ധമായതാണ്. (ഇങ്ങനെ എല്ലാവിധത്തിലും) നിഷിദ്ധമായവകൊണ്ടാണ് അവൻ വളർത്തപ്പെട്ടത്. അതിനാൽ എങ്ങനെയാണ് അവന്റെ പ്രാർത്ഥനക്ക് ഉത്തരം ലഭിക്കുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'البقرة: ١٧٢', null, 170, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَتَصَدَّقُ أَحَدٌ بِتَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ إِلَّا أَخَذَهَا اللَّهُ بِيَمِينِهِ، فَيُرَبِّيهَا كَمَا يُرَبِّي أَحَدُكُمْ فَلُوَّهُ أَوْ قَلُوصَهُ، حَتَّى تَكُونَ مِثْلَ الْجَبَلِ أَوْ أَعْظَمَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പരിശുദ്ധമായ ധനത്തിൽ നിന്ന് ഒരു കാരക്കയും ഒരുവനും ധർമ്മം ചെയ്യില്ല, അല്ലാഹു വലതുകൈ കൊണ്ട് അതിനെ സ്വീകരിച്ചിട്ടല്ലാതെ. അല്ലാഹു അതിനെ പർവ്വതത്തോളം വളർത്തും. നിങ്ങൾ കുഞ്ഞുങ്ങളെ വളർത്തുംപോലെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أُسَامَةَ بْنِ عُمَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا يَقْبَلُ اللَّهُ صَلَاةً بِغَيْرِ طُهُورٍ، وَلَا صَدَقَةً مِنْ غُلُولٍ". (م,د,ت,ن,جه)', 'ഉസാമതുബ്നു ഉമൈർ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ശുദ്ധിയില്ലാത്ത നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല. വഞ്ചനയിലുള്ള ധർമ്മത്തെയും അല്ലാഹു സ്വീകരിക്കുകയില്ല." (മു,ദ,തു,ന,ജ)', 'أُسَامَةَ بْنِ عُمَيْرٍ', 'ഉസാമതുബ്നു ഉമൈർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ فِي الْآيَةِ الَّتِي قَالَ اللَّهُ عَزَّ وَجَلَّ: {وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ} قَالَ: هُوَ الْجُعْرُورُ، وَلَوْنُ حُبَيْقٍ، فَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنْ تُؤْخَذَ فِي الصَّدَقَةِ الرُّذَالَةُ. (ن)', 'അബൂഉമാമതുബ്നി സഹ്ലിബ്നി ഹുനൈഫ്(റ): ''മോശമായ സാധനങ്ങൾ ചെലവഴിക്കാനായി നിങ്ങൾ കരുതിവെക്കരുത്'' എന്ന ഖുർആനിക വചനത്തിലെ ''മോശപ്പെട്ടത്'' എന്നതിന്റെ ഉദ്ദേശ്യം ജുഅ്റൂറും ലൗനു ഹുബൈഖും (താഴ്ന്നതരം കാരക്കകൾ) ആകുന്നു. ആയതിനാൽ നബി(സ) സകാത്തിൽ മോശപ്പെട്ടതിനെ സ്വീകരിക്കുന്നത് വിലക്കി. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമതുബ്നി സഹ്ലിബ്നി ഹുനൈഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَبِيَدِهِ عَصًا، وَقَدْ عَلَّقَ رَجُلٌ قِنْوَ حَشَفٍ، فَجَعَلَ يَطْعَنُ فِي ذَلِكَ الْقِنْوِ، فَقَالَ: "لَوْ شَاءَ رَبُّ هَذِهِ الصَّدَقَةِ تَصَدَّقَ بِأَطْيَبَ مِنْ هَذَا، إِنَّ رَبَّ هَذِهِ الصَّدَقَةِ يَأْكُلُ حَشَفًا يَوْمَ الْقِيَامَةِ". (د,ن,جه)', 'ഔഫുബ്നു മാലിക്(റ): നബി(സ) കയ്യിലൊരു വടിയുമായി പുറപ്പെട്ടു. അപ്പോൾ ഒരാളുടെ കയ്യിൽ ഉണങ്ങിയ മോശമായ കാരക്കക്കുല കണ്ടു. റസൂൽ(സ) വടികൊണ്ട് ആ കുലയ്ക്കു കുത്തിക്കൊണ്ട് പറഞ്ഞു: "ഈ സ്വദഖയുടെ ഉടമസ്ഥന് ഇതിനേക്കാൾ നല്ലത് ധർമ്മം ചെയ്യാൻ സാധിക്കുമെങ്കിൽ അങ്ങനെ ചെയ്യട്ടെ. നിശ്ചയം, ഈ സ്വദഖയുടെ ഉടമ മോശമായ കാരക്കയാവും അന്ത്യനാളിൽ ഭക്ഷിക്കുക." (ദ,ന,ജ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ: فِي قَوْلِهِ سُبْحَانَهُ: {وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الْأَرْضِ وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ} [البقرة: ٢٦٧] قَالَ: نَزَلَتْ فِي الْأَنْصَارِ. كَانَتِ الْأَنْصَارُ تُخْرِجُ - إِذَا كَانَ جِدَادُ النَّخْلِ - مِنْ حِيطَانِهَا، أَقْنَاءَ الْبُسْرِ، فَيُعَلِّقُونَهُ عَلَى حَبْلٍ بَيْنَ أُسْطُوَانَتَيْنِ فِي مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَيَأْكُلُ مِنْهُ فُقَرَاءُ الْمُهَاجِرِينَ، فَيَعْمِدُ أَحَدُهُمْ فَيُدْخِلُ قِنْوًا فِيهِ الْحَشَفُ، يَظُنُّ أَنَّهُ جَائِزٌ فِي كَثْرَةِ مَا يُوضَعُ مِنَ الْأَقْنَاءِ، فَنَزَلَ فِيمَنْ فَعَلَ ذَلِكَ: {وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ} يَقُولُ: لَا تَعْمِدُوا لِلْحَشَفِ مِنْهُ تُنْفِقُونَ، {وَلَسْتُمْ بِآخِذِيهِ إِلَّا أَنْ تُغْمِضُوا فِيهِ} يَقُولُ: لَوْ أُهْدِيَ لَكُمْ مَا قَبِلْتُمُوهُ إِلَّا عَلَى اسْتِحْيَاءٍ مِنْ صَاحِبِهِ، غَيْظًا أَنَّهُ بَعَثَ إِلَيْكُمْ مَا لَمْ يَكُنْ لَكُمْ فِيهِ حَاجَةٌ {وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ} عَنْ صَدَقَاتِكُمْ. (جه)', 'ബറാഉബ്നു ആസിബ്(റ): ''ഭൂമിയിൽ നിന്ന് നിങ്ങൾക്ക് ഞാൻ പുറപ്പെടുവിച്ചതിൽ നിന്ന് മോശപ്പെട്ടത് ചെലവഴിക്കാനായി കരുതിവെക്കരുത്'' (അൽബഖറ: 267) എന്ന ഖുർആനിക സൂക്തം അവതരിച്ചത് അൻസാരികളെക്കുറിച്ചാണ്. അൻസാരികൾ ഈത്തപ്പഴത്തിന്റെ വിളവെടുപ്പായാൽ തോട്ടങ്ങളിൽ നിന്ന് പച്ച ഈത്തപ്പഴത്തിന്റെ കുലകൾ കൊണ്ടുവന്ന് നബി(സ)യുടെ പള്ളിയിലെ രണ്ട് തൂണുകൾക്കിടയിൽ ഒരു കയറിൽ കെട്ടിയിടാറുണ്ടായിരുന്നു. അതിൽ നിന്ന് മുഹാജിറുകളിലെ പാവപ്പെട്ടവർ എടുത്തു ഭക്ഷിക്കും. കുലകളുടെ ആധിക്യം കണ്ടിട്ട് അനുവദനീയമെന്നു കരുതി ചിലർ അതിൽ മോശപ്പെട്ട ഈത്തപ്പഴക്കുലകളും കൂട്ടത്തിൽ കെട്ടിവെക്കും. അങ്ങനെ ചെയ്തവരുടെ കാര്യത്തിൽ ഇറങ്ങിയതാണ് ഈ ഖുർആൻ വചനം: ''നിങ്ങൾ മോശപ്പെട്ടവ ചെലവഴിക്കാനായി കരുതിവെക്കരുത്.'' അദ്ദേഹം പറയുന്നു: താഴ്ന്ന തരം കാരക്കകളിൽ നിന്ന് ദാനംചെയ്യാൻ നിങ്ങൾ ഉദ്ദേശിക്കരുത്. ''കണ്ണടച്ചിട്ടല്ലാതെ നിങ്ങളതിനെ സ്വീകരിക്കുകയില്ല'': അദ്ദേഹം പറയുന്നു: നിങ്ങൾക്കതിനെ പാരിതോഷികമായി നൽകപ്പെടാൻ നിങ്ങൾക്കാവശ്യമില്ലാത്തത് നിങ്ങൾക്കയച്ചുതന്നുവെന്ന് ദേഷ്യപ്പെട്ടുകൊണ്ട് അയച്ച ആളോട് ലജ്ജിച്ചുകൊണ്ടല്ലാതെ നിങ്ങളത് സ്വീകരിക്കുകയില്ല. ''അറിയുക, നിശ്ചയം അല്ലാഹു ഐശ്വര്യമാണ്'' എന്നതിന്റെ വിവക്ഷ നിങ്ങളുടെ ദാനങ്ങളെത്തൊട്ട് ഐശ്വര്യവാനാണ് എന്നാണ്. (ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'البقرة: ٢٦٧', null, 171, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: بُعِثَ إِلَى نُسَيْبَةَ الْأَنْصَارِيَّةِ بِشَاةٍ، فَأَرْسَلَتْ إِلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا مِنْهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "عِنْدَكُمْ شَيْءٌ"؟ فَقُلْتُ: لَا، إِلَّا مَا أَرْسَلَتْ بِهِ نُسَيْبَةُ مِنْ تِلْكَ الشَّاةِ، فَقَالَ: "هَاتِ فَقَدْ بَلَغَتْ مَحِلَّهَا". (ق)', 'ഉമ്മുഅതിയ്യ(റ): അൻസാരി വനിത നുസൈബക്ക് ഒരാടിനെ കൊടുത്തയച്ചു. ആ ആടിൽ നിന്ന് അവർ ആഇശ(റ)ക്കു കൊടുത്തയച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ആഹാരം വല്ലതുമുണ്ടോ?" ഞാൻ പറഞ്ഞു: നുസൈബക്കു കൊടുത്തയച്ച ആടിൽനിന്ന് അവൾ കൊടുത്തയച്ചതല്ലാതെ മറ്റൊന്നുമില്ല. നബി(സ) പറഞ്ഞു: "അത് കൊണ്ടുവരിക. സകാത്ത് അതിന്റെ സ്ഥാനത്തെത്തിക്കഴിഞ്ഞു." (ബു,മു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ". وَفِي رِوَايَةٍ: "زَكَاةٌ". (ق,د,ت,ن,جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "അഞ്ചെണ്ണത്തിൽ കുറഞ്ഞതിൽ (ഒട്ടകങ്ങളിൽ) ദാനമില്ല, അഞ്ച് ''ഊഖിയ''യിൽ കുറഞ്ഞ(വെള്ളി)തിൽ ദാനമില്ല. അഞ്ചു ''വസ്ഖി''ൽ കുറഞ്ഞതിൽ (ധാന്യത്തിൽ) ദാനമില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: "സകാത്ത്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=80), 1, 'وَفِي رِوَايَةٍ: "زَكَاةٌ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "സകാത്ത്." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ: وَقَدْ قَالَ لَهُ رَجُلٌ: يَا أَبَا نُجَيْدٍ، إِنَّكُمْ لَتُحَدِّثُونَنَا بِأَحَادِيثَ مَا نَجِدُ لَهَا أَصْلًا فِي الْقُرْآنِ. فَغَضِبَ عِمْرَانُ وَقَالَ لِلرَّجُلِ: أَوَجَدْتُمْ: فِي كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ، وَمِنْ كُلِّ كَذَا وَكَذَا شَاةً شَاةٌ، وَمِنْ كُلِّ كَذَا وَكَذَا بَعِيرًا كَذَا وَكَذَا، أَوَجَدْتُمْ هَذَا فِي الْقُرْآنِ؟ قَالَ: لَا، قَالَ: أَخَذْتُمْ هَذَا؟ أَخَذْتُمُوهُ عَنَّا، وَأَخَذْنَاهُ عَنْ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَكَرَ أَشْيَاءَ نَحْوَ هَذَا. (د)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): ഒരാൾ അദ്ദേഹത്തോടു പറഞ്ഞു: അബൂനുജൈദ്, ഖുർആനിൽ അടിസ്ഥാനം കണ്ടെത്താത്ത ഹദീസുകളാണ് നിങ്ങൾ ഞങ്ങളോടു പറയുന്നത്. അപ്പോൾ ഇംറാൻ(റ) ദേഷ്യത്തോടെ ആ മനുഷ്യനോടു പറഞ്ഞു: നിങ്ങൾ കണ്ടെത്തിയോ? നാൽപതു ദിർഹമിൽ ഒരു ദിർഹം സകാത്തുണ്ട്. എല്ലാ ഇത്ര ആടിലും ഒരാട് സകാത്തുണ്ട്. എല്ലാ ഇത്ര ഒട്ടകങ്ങളിലും ഇന്നാലിന്ന ഒട്ടകം സകാത്തുണ്ട്. ഇവ നിങ്ങൾ ഖുർആനിൽ കണ്ടിട്ടുണ്ടോ? അയാൾ പറഞ്ഞു: ഇല്ല. ഇംറാൻ(റ) വീണ്ടും പറഞ്ഞു: പിന്നെ ആരിൽനിന്നാണു നിങ്ങൾക്കിതു ലഭിച്ചത്? ഇതിനെ നിങ്ങൾക്കു നമ്മിൽ നിന്നു ലഭിച്ചു, നാം നബി(സ)യിൽ നിന്നും പിടിച്ചു. പിന്നീട് ഇതു പോലുള്ള കുറെ കാര്യങ്ങളദ്ദേഹം പറഞ്ഞു. (ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ الْعَلَاءِ بْنِ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى الْبَحْرَيْنِ، أَوْ: إِلَى هَجَرٍ، فَكُنْتُ آتِي الْحَائِطَ يَكُونُ بَيْنَ الْإِخْوَةِ: يُسْلِمُ أَحَدُهُمْ، فَآخُذُ مِنَ الْمُسْلِمِ الْعُشْرَ، وَمِنَ الْمُشْرِكِ الْخَرَاجَ. [ز: في سنده مجهولان، وفي سنده انقطاع] (جه)', 'അലാഉബ്നുൽ ഹള്റമി(റ): നബി(സ) എന്നെ ബഹ്റൈനിലേക്കോ അല്ലെങ്കിൽ ഹജറിലേക്കോ (സകാത്ത് പിരിക്കാൻ) അയച്ചു. ഞാൻ രണ്ടു സഹോദരന്മാർക്കിടയിലുള്ള മതിലിനരികെ ചെന്നു. അവരിൽനിന്ന് ഒരാൾ മുസ്‌ലിമായിരുന്നു. അപ്പോൾ ഞാൻ മുസ്‌ലിമിൽ നിന്ന് പത്തിലൊന്ന് സ്വീകരിക്കും. അവിശ്വാസിയിൽനിന്നു ''ജിസ്‌യ'' (അവിശ്വാസിയിൽനിന്നു എടുക്കുന്ന നികുതി)യും പിടിക്കും. (സനദിൽ രണ്ട് മജ്ഹൂലും ഇൻഖിതാഉമുണ്ട്). (ജ)', 'الْعَلَاءِ بْنِ الْحَضْرَمِيِّ', 'അലാഉബ്നുൽ ഹള്റമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مجهولان، وفي سنده انقطاع', null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "الْوَسْقُ سِتُّونَ صَاعًا". (د,ت,ن,جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു ''വസ്ഖ്'' അറുപത് ''സ്വാഅ്'' ആകുന്നു." (ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّهُ خُلِقَ كُلُّ إِنْسَانٍ مِنْ بَنِي آدَمَ عَلَى سِتِّينَ وَثَلَاثِ مِائَةِ مَفْصِلٍ، فَمَنْ كَبَّرَ اللَّهَ، وَحَمِدَ اللَّهَ، وَهَلَّلَ اللَّهَ، وَسَبَّحَ اللَّهَ، وَاسْتَغْفَرَ اللَّهَ، وَعَزَلَ حَجَرًا عَنْ طَرِيقِ النَّاسِ، أَوْ شَوْكَةً أَوْ عَظْمًا عَنْ طَرِيقِ النَّاسِ، وَأَمَرَ بِمَعْرُوفٍ، أَوْ نَهَى عَنْ مُنْكَرٍ، عَدَدَ تِلْكَ السِّتِّينَ وَالثَّلَاثِ مِائَةِ السُّلَامَى، فَإِنَّهُ يَمْشِي يَوْمَئِذٍ وَقَدْ زَحْزَحَ نَفْسَهُ عَنِ النَّارِ". قَالَ أَبُو تَوْبَةَ: وَرُبَّمَا قَالَ: "يُمْسِي". (م)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ആദം സന്തതികളിലെ ഓരോരുത്തരും മുന്നൂറ്ററുപത് സന്ധികളോടെയാണ് സൃഷ്ടിക്കപ്പെട്ടത്. അതിനാൽ ഏതൊരാൾ ആ മുന്നൂറ്ററുപത് സന്ധികളുടെ എണ്ണത്തിനനുസരിച്ച് അല്ലാഹു അക്ബർ, അൽഹംദുലില്ലാഹി, ലാഇലാഹ ഇല്ലല്ലാഹു, സുബ്ഹാനല്ലാഹി എന്നീ സ്തുതി കീർത്തനങ്ങൾ ചൊല്ലുകയും, അല്ലാഹുവിനോടു പാപമോചനത്തിന്നായി പ്രാർത്ഥിക്കുകയും ജനങ്ങൾ നടക്കുന്ന വഴിയിൽനിന്നു കല്ല്, മുള്ള്, അല്ലെങ്കിൽ ജനങ്ങളുടെ വഴിയിൽ നിന്ന് എല്ല് എന്നിങ്ങനെയുള്ള (ഉപദ്രവകരമായ) വസ്തുക്കൾ എടുത്തുമാറ്റുകയും നന്മ കൽപിക്കുകയും തിന്മ വിരോധിക്കുകയും ചെയ്യുന്നുവോ അന്നേരം അവൻ തന്റെ ശരീരം നരകത്തിൽനിന്നു ദൂരെയാക്കിയിട്ടാണ് നടക്കുന്നത്." അബൂ തൗബ പറയുന്നു: അധികവും അവിടന്ന് പറഞ്ഞത്: "അവൻ നരകത്തിൽ ആകും" എന്നാണ്. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 173, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَبْدِ اللَّهِ بْنِ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا جَلَبَ، وَلَا جَنَبَ، وَلَا تُؤْخَذُ صَدَقَاتُهُمْ إِلَّا فِي دُورِهِمْ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "സകാത്ത് പിരിക്കുന്നവന്റെയടുത്തേക്കു മൃഗങ്ങളെ കൊണ്ടുവരികയോ ഉടമ വിദൂരത്തായ സമയത്തു സകാത്ത് പിരിക്കുന്നവൻ അങ്ങോട്ടു ചെല്ലേണ്ടതോ ഇല്ല. സകാതുകൾ അവരുടെ വീടുകളിൽ വെച്ചല്ലാതെ എടുക്കപ്പെടുകയില്ല." (ദ)', 'عَبْدِ اللَّهِ بْنِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ رَضِيَ اللهُ عَنْهُ فِي قَوْلِهِ: "لَا جَلَبَ وَلَا جَنَبَ". قَالَ: أَنْ تُصَدَّقَ الْمَاشِيَةُ فِي مَوَاضِعِهَا، وَلَا تُجْلَبَ إِلَى الْمُصَدِّقِ. وَالْجَنَبُ: يَقُولُ: وَلَا يَكُونُ الرَّجُلُ بِأَقْصَى مَوَاضِعِ أَصْحَابِ الصَّدَقَةِ فَتُجْنَبُ إِلَيْهِ، وَلَكِنْ تُؤْخَذُ فِي مَوْضِعِهِ. (د)', 'മുഹമ്മദുബ്നു ഇസ്ഹാഖ്(റ): "സകാത്ത് പിരിക്കുന്നയാളുടെ അടുത്തേക്കു മൃഗങ്ങളെ കൊണ്ടുവരികയോ സകാത്ത് പിരിക്കുന്നവന് ബുദ്ധിമുട്ടാകുന്ന വിധം ഉടമ സ്വത്ത് വിദൂരത്താകുകയോ അരുത്" എന്ന നബി(സ)യുടെ വാക്കിനെപ്പറ്റി അദ്ദേഹം പറയുന്നു: മൃഗങ്ങളെ അതിന്റെ സ്ഥാനത്തു വെച്ചു സകാത്ത് നൽകണം. അവയെ സകാത്ത് പിരിക്കുന്നയാളുടെ അടുത്തേക്ക് കൊണ്ടുവരേണ്ടതില്ല. സകാത്ത് പിരിവുകാരിൽനിന്നു സകാത്ത് വളരെ വിദൂരത്തായാൽ അവർ അങ്ങോട്ടു ചെല്ലേണ്ടതുമില്ല. മറിച്ച് അവ അവയുടെ സ്ഥാനത്തുനിന്നു പിടിക്കപ്പെടും. (ദ)', 'مُحَمَّدِ بْنِ إِسْحَاقَ', 'മുഹമ്മദുബ്നു ഇസ്ഹാഖ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَفَادَ مَالًا فَلَا زَكَاةَ عَلَيْهِ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ عِنْدَ رَبِّهِ". وَفِي رِوَايَةٍ: أَنَّ هَذَا مَوْقُوفٌ مِنْ قَوْلِ ابْنِ عُمَرَ. (ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "സമ്പാദ്യം നേടിയവനു വർഷം തികയുന്നതുവരെ അവന്റെ നാഥന്റെയടുക്കൽ സകാത്തില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: ഇത് ഇബ്നുഉമർ(റ)വിൽ നിന്നും ''മൗഖൂഫ്'' ആണ്. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=87), 1, 'وَفِي رِوَايَةٍ: أَنَّ هَذَا مَوْقُوفٌ مِنْ قَوْلِ ابْنِ عُمَرَ. (ت,جه)', 'മറ്റൊരു നിവേദനിൽ: ഇത് ഇബ്നുഉമർ(റ)വിൽ നിന്നും ''മൗഖൂഫ്'' ആണ്. (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا زَكَاةَ فِي مَالٍ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ". (جه)', 'ആഇശ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഒരു വർഷം തികയാത്ത ധനത്തിന് സകാത്തില്ല." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بَعَثَهُ إِلَى الْيَمَنِ وَقَالَ لَهُ: "خُذِ الْحَبَّ مِنَ الْحَبِّ، وَالشَّاةَ مِنَ الْغَنَمِ، وَالْبَعِيرَ مِنَ الْإِبِلِ، وَالْبَقَرَةَ مِنَ الْبَقَرِ". (ت,جه)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) അദ്ദേഹത്തെ യമനിലേക്കയച്ചപ്പോൾ പറഞ്ഞു: "ധാന്യത്തിൽനിന്നു ധാന്യത്തേയും, ആടുകളിൽ നിന്ന് ആടിനേയും, ഒട്ടകത്തിൽ നിന്ന് ഒട്ടകത്തേയും, പശുക്കളിൽ നിന്ന് പശുവിനേയും നിങ്ങൾ പിടിക്കുക." (തു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا سَنَّ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ الزَّكَاةَ فِي هَذِهِ الْخَمْسَةِ: فِي الْحِنْطَةِ، وَالشَّعِيرِ، وَالتَّمْرِ، وَالزَّبِيبِ، وَالذُّرَةِ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) സകാത്ത് ചര്യയാക്കിയത് ഗോതമ്പ്, ബാർലി, കാരക്ക, മുന്തിരി, ചോളം എന്നീ അഞ്ചിനങ്ങളിൽ മാത്രമാണ്. (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا صَدَقَةَ فِيمَا دُونَ خَمْسَةِ أَوْسَاقٍ مِنَ التَّمْرِ، وَلَا فِيمَا دُونَ خَمْسِ أَوَاقٍ، وَلَا فِيمَا دُونَ خَمْسٍ مِنَ الْإِبِلِ". (ق,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അഞ്ച് ''വസ്ഖ്'' തികയാത്ത കാരക്കയിലും, അഞ്ച് ''ഊഖിയ'' തികയാത്ത വെള്ളിയിലും, അഞ്ചെണ്ണത്തിൽ താഴെയുള്ള ഒട്ടകങ്ങളിലും സകാത്തില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسَاقٍ صَدَقَةٌ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "എണ്ണം അഞ്ച് തികയാത്തതിലും, ''ഊഖിയ'' അഞ്ച് തികയാത്തതിലും, ''വസഖ്'' അഞ്ച് തികയാത്തതിലും സകാത്തില്ല." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَّا بَعْدُ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ كَانَ يَأْمُرُنَا أَنْ نُخْرِجَ الصَّدَقَةَ مِنَ الَّذِي نُعِدُّ لِلْبَيْعِ. (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം, കച്ചവടത്തിനായി നീക്കിവെച്ച ധനത്തിൽ നിന്ന് സകാത്ത് നൽകാൻ നബി(സ) ഞങ്ങളോടു കൽപിക്കാറുണ്ടായിരുന്നു. (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ بِمِثْلِ بَيْضَةٍ مِنْ ذَهَبٍ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَصَبْتُ هَذِهِ مِنْ مَعْدِنٍ، فَخُذْهَا فَهِيَ صَدَقَةٌ، مَا أَمْلِكُ غَيْرَهَا. فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، ثُمَّ أَتَاهُ مِنْ قِبَلِ رُكْنِهِ الْأَيْمَنِ فَقَالَ مِثْلَ ذَلِكَ، فَأَعْرَضَ عَنْهُ، ثُمَّ أَتَاهُ مِنْ قِبَلِ رُكْنِهِ الْأَيْسَرِ، فَأَعْرَضَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، ثُمَّ أَتَاهُ مِنْ خَلْفِهِ، فَأَخَذَهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَحَذَفَهُ بِهَا، فَلَوْ أَصَابَتْهُ لَأَوْجَعَتْهُ، أَوْ لَعَقَرَتْهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "يَأْتِي أَحَدُكُمْ بِمَا يَمْلِكُ فَيَقُولُ هَذِهِ صَدَقَةٌ، ثُمَّ يَقْعُدُ يَسْتَكِفُّ النَّاسَ، خَيْرُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى". وَفِي رِوَايَةٍ زَادَ: "خُذْ عَنَّا مَالَكَ، لَا حَاجَةَ لَنَا بِهِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുണ്ടായിരിക്കെ ഒരാൾ ഒരു സ്വർണ്ണമുട്ടയെപ്പോലെയുള്ള ഒരു വസ്തുവുമായി വന്നു. അദ്ദേഹം പറഞ്ഞു: "നബിയേ, എനിക്കിതു ഖനിയിൽ നിന്നു ലഭിച്ചതാണ്. താങ്കളിത് ധർമ്മമായി സ്വീകരിക്കുക. ഇതല്ലാതെ മറ്റൊന്നും എനിക്കു സ്വന്തമായിട്ടില്ല. അപ്പോൾ നബി(സ) അദ്ദേഹത്തിൽനിന്നു തിരിഞ്ഞുകളഞ്ഞു. പിന്നെ അദ്ദേഹം നബി(സ)യുടെ വലതുഭാഗത്തുകൂടെ കടന്നുവന്ന് മുമ്പു പറഞ്ഞപോലെ പറഞ്ഞു. അപ്പോഴും നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. അപ്പോഴദ്ദേഹം ഇടതുഭാഗത്തൂടെ വന്നു. അപ്പോഴും നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. പിന്നീടദ്ദേഹം നബി(സ)യുടെ പിന്നിലൂടെ വന്നു. അപ്പോൾ നബി(സ) അതു വാങ്ങി, അതുകൊണ്ടവനെ എറിഞ്ഞു. നിവേദകൻ പറയുന്നു: ആ എറിയൽ അദ്ദേഹത്തിന്റെ ദേഹത്തു തട്ടിയിരുന്നെങ്കിൽ അദ്ദേഹത്തിനു വേദനിക്കുമായിരുന്നു, അല്ലെങ്കിൽ മുറിവേൽക്കുമായിരുന്നു. തുടർന്ന് നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ തന്റെ ഉടമസ്ഥതയിലുള്ള വസ്തുവുമായി വന്നുപറയും, ഇതു ദാനമാണെന്ന്. പിന്നെയവൻ ഇരുന്ന് ജനങ്ങളോടു കൈനീട്ടി യാചിക്കും. ഏറ്റവും ഉത്തമമായ ദാനം സമൃദ്ധിയിൽ ചെയ്യുന്ന ദാനമാണ്." മറ്റൊരു നിവേദനത്തിൽ കൂടുതൽ വന്നിട്ടുണ്ട്: "നിനക്കു വേണ്ടത് ഞങ്ങളിൽ നിന്ന് പിടിക്കുക, ഇതുകൊണ്ട് ഞങ്ങൾക്കൊരു ആവശ്യവുമില്ല." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 175, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=94), 1, 'وَفِي رِوَايَةٍ زَادَ: "خُذْ عَنَّا مَالَكَ، لَا حَاجَةَ لَنَا بِهِ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ കൂടുതൽ വന്നിട്ടുണ്ട്: "നിനക്കു വേണ്ടത് ഞങ്ങളിൽ നിന്ന് പിടിക്കുക, ഇതുകൊണ്ട് ഞങ്ങൾക്കൊരു ആവശ്യവുമില്ല." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَجُلٌ الْمَسْجِدَ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَنْ يَطْرَحُوا ثِيَابًا، فَطَرَحُوا، فَأَمَرَ لَهُ بِثَوْبَيْنِ، ثُمَّ حَثَّ عَلَى الصَّدَقَةِ، فَجَاءَ فَطَرَحَ أَحَدَ الثَّوْبَيْنِ، فَصَاحَ بِهِ وَقَالَ: "خُذْ ثَوْبَكَ". (د,ت,ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): ഒരാൾ പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ വസ്ത്രം സംഭാവനയായി നൽകാൻ നബി(സ) അവരോട് കൽപിച്ചു. അവർ വസ്ത്രം നൽകി. ശേഷം അദ്ദേഹത്തോടു രണ്ട് വസ്ത്രം എടുക്കാൻ നബി(സ) കൽപിച്ചു. ദാനം നൽകാൻ പ്രേരിപ്പിച്ചുകൊണ്ട് സംസാരിച്ചു. അപ്പോൾ (നേരത്തെ രണ്ടു വസ്ത്രം നൽകിയ) മനുഷ്യൻ വന്ന് ഒരു വസ്ത്രം സംഭാവനയായി നൽകി. അപ്പോൾ നബി(സ) (ഗൗരവത്തോടെ) ശബ്ദമുയർത്തി പറഞ്ഞു: "നിന്റെ വസ്ത്രം എടുക്ക്." (ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ خَيْرَ الصَّدَقَةِ مَا تَرَكَ غِنًى أَوْ: تُصُدِّقَ بِهِ عَنْ ظَهْرِ غِنًى، وَابْدَأْ بِمَنْ تَعُولُ". (خ,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "നിശ്ചയം, മഹത്തായ ദാനം ഐശ്വര്യത്തിൽ നിന്നല്ലാതെ കൊടുത്തതാണ്, അല്ലെങ്കിൽ; "സമ്പൽസമൃദ്ധിയിലല്ലാത്ത സമയത്തുള്ള ദാനം എന്നാണ്. ദാനം തന്റെ കുടുംബത്തിൽ (ചെലവ്കൊടുക്കൽ നിർബന്ധമായവരിൽ നിന്ന്) തുടങ്ങുക. (ദാനം നൽകൽ ഏറ്റം പുണ്യകരം തന്റെ കുടുംബക്കാർക്കു നൽകുന്നതാണ്.) (ബു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "جُهْدُ الْمُقِلِّ، وَابْدَأْ بِمَنْ تَعُولُ". (د)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ദാനങ്ങളിൽ ശ്രേഷ്ഠമായത് ഏതാണ്? നബി(സ) പറഞ്ഞു: "പരമ ദരിദ്രന്റെ ദാനം, കുടുംബക്കാരനെക്കൊണ്ടു തുടങ്ങുകയും ചെയ്യുക." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَوْمًا أَنْ نَتَصَدَّقَ، فَوَافَقَ ذَلِكَ مَالًا عِنْدِي، فَقُلْتُ: الْيَوْمَ أَسْبِقُ أَبَا بَكْرٍ، إِنْ سَبَقْتُهُ يَوْمًا، فَجِئْتُ بِنِصْفِ مَالِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَا أَبْقَيْتَ لِأَهْلِكَ". قُلْتُ: مِثْلَهُ. قَالَ: وَأَتَى أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ بِكُلِّ مَا عِنْدَهُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَا أَبْقَيْتَ لِأَهْلِكَ؟". قَالَ: أَبْقَيْتُ لَهُمُ اللَّهَ وَرَسُولَهُ، قُلْتُ: لَا أُسَابِقُكَ إِلَى شَيْءٍ أَبَدًا. (د,ت)', 'ഉമറുബ്നുൽഖത്താബ്(റ): ഒരു ദിവസം ദാനംചെയ്യാൻ നബി(സ) ഞങ്ങളോടു കൽപിച്ചു. എന്റെയടുത്ത് സമ്പത്തുണ്ടായിരുന്ന സന്ദർഭമായിരുന്നു അത്. അന്നേരം ഞാൻ പറഞ്ഞു: വല്ല ദിവസവും അബൂബക്കർ(റ)വിനെ ഞാൻ മുൻകടക്കുകയാണെങ്കിൽ അത് ഇന്നായിരിക്കും. എന്റെ സമ്പത്തിന്റെ പകുതി ഭാഗവും ഞാൻ കൊണ്ടുവന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "താങ്കളുടെ കുടുംബത്തിനു വേണ്ടി എന്തു ബാക്കിവെച്ചു?" ഞാൻ പറഞ്ഞു: ഇതുപോലെയുള്ളതിനെ. അബൂബക്കർ(റ) തന്റെ കൈവശമുണ്ടായിരുന്ന സർവ്വ സമ്പത്തുമായി വന്നു. അദ്ദേഹത്തോടു പ്രവാചകർ(സ) ചോദിച്ചു: "താങ്കളുടെ കുടുംബത്തിന് എന്താണ് അവശേഷിപ്പിച്ചത്?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിനെയും റസൂലിനെയും അവർക്ക് ഞാൻ ബാക്കിവെച്ചിരിക്കുന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഒരിക്കലും ഒന്നിലും ഞാൻ താങ്കളെ മുൻകടക്കുകയില്ല. (ദ,തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽഖത്താബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَعُدُّ الْمَاعُونَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَارِيَةَ الدَّلْوِ وَالْقِدْرِ. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ)യുടെ കാലത്ത് ചട്ടിയും തൊട്ടിയും വായ്പ കൊടുക്കുന്നതിനെയായിരുന്നു ''മാഊൻ'' എന്നു ഞങ്ങൾ കണക്കാക്കിയിരുന്നത്. (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عُبَيْدِ بْنِ عُمَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، مَا حَقُّ الْإِبِلِ؟ فَذَكَرَ نَحْوَهُ، وَزَادَ: "وَإِعَارَةُ دَلْوِهَا". (د)', 'ഉബൈദുബ്നു ഉമൈർ(റ): ഒരാൾ ചോദിച്ചു: തിരുദൂതരേ, ഒട്ടകത്തോടുള്ള ബാദ്ധ്യതയെന്താണ്? (ശേഷം ദീർഘമായ ഹദീസ് പറഞ്ഞു). തുടർന്നു പറഞ്ഞു: "അതിന്റെ പാനപാത്രം വായ്പ കൊടുക്കലും അതിന്റെ ബാധ്യതയിൽപെട്ടതാണ്." (ദ)', 'عُبَيْدِ بْنِ عُمَيْرٍ', 'ഉബൈദുബ്നു ഉമൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَمَرَ مِنْ كُلِّ جَادٍّ عَشَرَةِ أَوْسُقٍ مِنَ التَّمْرِ بِقِنْوٍ يُعَلَّقُ فِي الْمَسْجِدِ لِلْمَسَاكِينِ. (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഓരോ പത്ത് വസ്ഖ് ഈത്തപ്പഴം പറിക്കപ്പെടുമ്പോൾ ഒരു കുല പാവപ്പെട്ടവർക്ക് വേണ്ടി പള്ളിയിൽ കെട്ടിത്തൂക്കപ്പെടണമെന്ന് നബി(സ) കൽപിച്ചു. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلْتُ - أَوْ سُئِلَ - النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَنِ الزَّكَاةِ، فَقَالَ: "إِنَّ فِي الْمَالِ لَحَقًّا سِوَى الزَّكَاةِ". ثُمَّ تَلَا هَذِهِ الْآيَةَ الَّتِي فِي الْبَقَرَةِ [١٧٧] {لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ} الْآيَةَ. (ت)', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ): സക്കാത്തിനെ കുറിച്ച് നബി(സ)യോട് ഞാൻ ചോദിച്ചു: (അല്ലെങ്കിൽ ചോദിക്കപ്പെട്ടു.) നബി(സ) പറഞ്ഞു: "സക്കാത്ത് കൂടാതെ തീർച്ചയായും സമ്പാദ്യത്തിൽ ബാധ്യതയുണ്ട്." തുടർന്ന് ബഖറയിലെ ''നിങ്ങളുടെ മുഖം കിഴക്കോട്ടോ പടിഞ്ഞാറോട്ടോ തിരിക്കുന്നതിലല്ല പുണ്യം'' (177) എന്ന സൂക്തം പാരായണം ചെയ്തു. (തു)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], '١٧٧', null, 177, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ - وَلَهُ مَا يُغْنِيهِ - جَاءَتْ مَسْأَلَتُهُ يَوْمَ الْقِيَامَةِ خُدُوشًا - أَوْ: خُمُوشًا، أَوْ: كُدُوحًا - فِي وَجْهِهِ". قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا يُغْنِيهِ؟ قَالَ: "خَمْسُونَ دِرْهَمًا، أَوْ قِيمَتُهَا مِنَ الذَّهَبِ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "മറ്റുള്ളവരിൽ നിന്ന് ഐശ്വര്യവാനാക്കുന്ന സമ്പത്തുണ്ടായിരിക്കെ ആരെങ്കിലും യാചിച്ചാൽ ആ യാചന അവന്റെ മുഖത്ത് കലയായോ, അല്ലെങ്കിൽ മാന്തിയ പോറലായോ അന്ത്യനാളിൽ വരും." അപ്പോൾ ഒരാൾ ചോദിച്ചു: നബിയേ, ഐശ്വര്യവാനാക്കുന്നത് [?]ന്നതു കൊണ്ടു അങ്ങ് ഉദ്ദേശിച്ചത്? നബി(സ) പറഞ്ഞു: "അമ്പത് വെള്ളിനാണയം, അല്ലെങ്കിൽ അത്ര [?] വരുന്ന സ്വർണ്ണം." (ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 178, 178, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أُتِيَ بِلَحْمٍ، قَالَ: "مَا هَذَا؟". قَالُوا: شَيْءٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، فَقَالَ: "هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ". (ق,د,ن)', 'അനസ്(റ): നബി(സ)യുടെയടുക്കൽ മാംസം കൊണ്ടുവരപ്പെട്ടു. നബി(സ) ചോദിച്ചു: "ഇതെന്താണ്?" അവർ പറഞ്ഞു: ബരീറക്ക് ദാനമായി ലഭിച്ചതാണ്. നബി(സ) പറഞ്ഞു: "അതവൾക്കു ദാനവും നമുക്ക് സമ്മാനവുമാണ്." (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ الْخَازِنَ الْأَمِينَ، الَّذِي يُعْطِي مَا أُمِرَ بِهِ كَامِلًا مُوَفَّرًا، طَيِّبَةً بِهِ نَفْسُهُ حَتَّى يَدْفَعَهُ إِلَى الَّذِي أُمِرَ لَهُ بِهِ، أَحَدُ الْمُتَصَدِّقَيْنِ". (ق,د,ن)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "കൽപിക്കപ്പെട്ടത് പരിപൂർണ്ണമായും, തൃപ്തിയോടെ, കൽപിക്കപ്പെട്ടവർക്ക് നൽകുന്ന വിശ്വസ്തനായ സമ്പത്ത് സൂക്ഷിപ്പുകാരൻ ദാനം ചെയ്യുന്നവരിൽ ഒരാളാണ്." (ബു,മു,ദ,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ نَاسٌ مِنَ الْأَعْرَابِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَقَالُوا: إِنَّ نَاسًا مِنَ الْمُصَدِّقِينَ يَأْتُونَنَا فَيَظْلِمُونَنَا، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَرْضُوا مُصَدِّقِيكُمْ". قَالَ جَرِيرٌ: مَا صَدَرَ عَنِّي مُصَدِّقٌ مُنْذُ سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَّا وَهُوَ عَنِّي رَاضٍ. (م,ن)', 'ജരീറുബ്നു അബ്ദുല്ല(റ): ഒരു സംഘം അപരിഷ്കൃത അറബികൾ വന്ന് നബി(സ)യോട് പറഞ്ഞു: സകാത്ത് നൽകുന്ന ഒരു സംഘമാളുകൾ ഞങ്ങളുടെയടുക്കൽ വന്ന് ഞങ്ങളെ ആക്രമിക്കുകയും ചെയ്യുന്നു. നിവേദകൻ: അപ്പോൾ നബി(സ) പറഞ്ഞു: ദാനം നൽകുന്നവരെ നിങ്ങൾ തൃപ്തിപ്പെടുത്തുക. ജരീർ(റ) പറയുന്നു: നബി(സ) ഇതു പറഞ്ഞതിനു ശേഷം ദാനം നൽകുന്നവൻ എന്റടുത്തുവന്ന് തൃപ്തിപ്പെടാതെ പോയിട്ടില്ല. (മു,ന)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَا يَزَالُ الرَّجُلُ يَسْأَلُ حَتَّى يَأْتِيَ يَوْمَ الْقِيَامَةِ لَيْسَ فِي وَجْهِهِ مُزْعَةٌ مِنْ لَحْمٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ മുഖത്ത് ഒരുതുണ്ട് ഇറച്ചി പോലുമില്ലാതെ വരുന്ന അവസ്ഥ ഉണ്ടാവുന്നതുവരെ ഒരാൾ യാചിച്ചു കൊണ്ടേയിരിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي، ثُمَّ قَالَ: "يَا حَكِيمُ، إِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةٌ، فَمَنْ أَخَذَهُ بِسَخَاوَةِ نَفْسٍ، بُورِكَ لَهُ فِيهِ، وَمَنْ أَخَذَ بِإِشْرَافِ نَفْسٍ، لَمْ يُبَارَكْ لَهُ فِيهِ كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ، الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى". قَالَ حَكِيمٌ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَا أَرْزَأُ أَحَدًا بَعْدَكَ شَيْئًا حَتَّى أُفَارِقَ الدُّنْيَا، فَكَانَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ يَدْعُو حَكِيمًا إِلَى الْعَطَاءِ، فَيَأْبَى أَنْ يَقْبَلَهُ مِنْهُ، ثُمَّ إِنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ دَعَاهُ لِيُعْطِيَهُ، فَأَبَى أَنْ يَقْبَلَ مِنْهُ شَيْئًا، فَقَالَ عُمَرُ: إِنِّي أُشْهِدُكُمْ يَا مَعْشَرَ الْمُسْلِمِينَ عَلَى حَكِيمٍ، أَنِّي أَعْرِضُ عَلَيْهِ حَقَّهُ مِنْ هَذَا الْفَيْءِ، فَيَأْبَى أَنْ يَأْخُذَهُ، فَلَمْ يَرْزَأْ حَكِيمٌ أَحَدًا مِنَ النَّاسِ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ حَتَّى تُوُفِّيَ. (خ)', 'ഹകീമുബ്നു ഹിസാം(റ): നബി(സ)യോട് ഞാൻ (ദാനം) ചോദിക്കുകയും നബി(സ) എനിക്ക് തരികയും ചെയ്തു. വീണ്ടും ചോദിച്ചപ്പോൾ വീണ്ടും തന്നു, പിന്നെ ചോദിച്ചപ്പോഴും തന്നു. പിന്നെ നബി(സ) പറഞ്ഞു: "ഹകീം, ധനം മധുരിതവും പച്ചയുമാണ്, ആരെങ്കിലുമത് ഔദാര്യപൂർവ്വം എടുത്താൽ അവനതിൽ അനുഗ്രഹം ചെയ്യപ്പെടും. ആരെങ്കിലുമത് അത്യാഗ്രഹപൂർവ്വം എടുത്താൽ അവനതിൽ അനുഗ്രഹം ചെയ്യപ്പെടുകയില്ല. ഭക്ഷിച്ചിട്ടും വയറു നിറയാത്തവനെപ്പോലെയായിരിക്കുമവന്റെ അവസ്ഥ. മീതെയുള്ള (ദാനം ചെയ്യുന്ന) കയ്യാണ് താഴെയുള്ള (ദാനം സ്വീകരിക്കുന്ന) കയ്യിനേക്കാൾ നല്ലത്." ഹകീം(റ) പറഞ്ഞു: അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: റസൂലേ, അങ്ങയെ സത്യവുമായി നിയോഗിച്ചവനാരോ അവനിൽ സത്യം, ഇനിയൊരിക്കലും ഒരാളോടും ഈ ലോകത്തുനിന്ന് വിടപറയുന്നതു വരെ ഞാൻ ഒന്നും ചോദിക്കുകയില്ല. അബൂബക്കർ(റ) ഹകീം(റ)നെ ദാനം സ്വീകരിക്കാൻ വിളിക്കാറുണ്ടായിരുന്നു. എന്നാൽ അദ്ദേഹത്തിൽ നിന്നത് സ്വീകരിക്കാനദ്ദേഹം വിസമ്മതിച്ചിരുന്നു. പിന്നെ ഉമർ(റ)വും അദ്ദേഹത്തെ ദാനം സ്വീകരിക്കാൻ വിളിച്ചു. എന്നാൽ അത് സ്വീകരിക്കാനദ്ദേഹം വിസമ്മതിച്ചു. ഉമർ(റ) പറഞ്ഞു: മുസ്‌ലിം സമൂഹമേ, ഞാൻ ഹകീമിന്റെ പേരിൽ നിങ്ങളെ സാക്ഷികളാക്കുന്നു. ഈ യുദ്ധമുതലിലുള്ള അദ്ദേഹത്തിന്റെ ഓഹരി ഞാൻ കാണിച്ചു കൊടുക്കുന്നു. അദ്ദേഹമത് സ്വീകരിക്കാൻ വിസമ്മതിക്കുന്നു. നബി(സ)ക്ക് ശേഷം തന്റെ മരണം വരെ ഹകീം(റ) ആരോടും ദാനം വാങ്ങിയിട്ടില്ല. (ബു)', 'حَكِيمِ بْنِ حِزَامٍ', 'ഹകീമുബ്നു ഹിസാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 179, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ صَدَقَةَ الْفِطْرِ: عَلَى الذَّكَرِ وَالْأُنْثَى، وَالْحُرِّ وَالْمَمْلُوكِ، صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ. قَالَ: فَعَدَلَ النَّاسُ إِلَى نِصْفِ صَاعٍ مِنْ بُرٍّ. (ن)', 'ഇബ്നുഉമർ(റ): ഫിത്വർ സകാത്ത് പുരുഷനും സ്ത്രീക്കും, സ്വതന്ത്രനും അടിമക്കും നബി(സ) നിർബന്ധമാക്കിയിരിക്കുന്നു. ഒരു സ്വാഅ് കാരക്കയോ ഒരു സ്വാഅ് ബാർലിയോ ആണത്. എന്നാൽ പിന്നീട് ജനങ്ങൾ അത് ഗോതമ്പിൽ നിന്നുള്ള അര സ്വാആക്കി ചുരുക്കി. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "أَرْبَعَةٌ يُبْغِضُهُمُ اللَّهُ عَزَّ وَجَلَّ: الْبَيَّاعُ الْحَلَّافُ، وَالْفَقِيرُ الْمُخْتَالُ، وَالشَّيْخُ الزَّانِي، وَالْإِمَامُ الْجَائِرُ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നാലാളുകളോട് അല്ലാഹു ദേഷ്യപ്പെടും; സത്യം ചെയ്യിക്കുന്ന കച്ചവടക്കാരൻ, അഹങ്കാരിയായ ദരിദ്രൻ, വ്യഭിചരിക്കുന്ന വൃദ്ധൻ, അക്രമിയായ ഭരണാധികാരി." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِذَا أُتِيَ بِشَيْءٍ سَأَلَ عَنْهُ: "أَهَدِيَّةٌ أَمْ صَدَقَةٌ؟". فَإِنْ قِيلَ: صَدَقَةٌ لَمْ يَأْكُلْ، وَإِنْ قِيلَ: هَدِيَّةٌ، بَسَطَ يَدَهُ. (ن)', 'മുആവിയ(റ): നബി(സ)ക്ക് എന്തെങ്കിലും കൊണ്ടുവരപ്പെട്ടാൽ നബി(സ) ചോദിക്കും: "സമ്മാനമാണോ അതോ ദാനമാണോ?" ദാനമാണെന്നു പറയപ്പെട്ടാൽ അതു ഭക്ഷിക്കില്ല. സമ്മാനമാണെന്നു പറയപ്പെട്ടാൽ കൈ നീട്ടും. (ന)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَدَوْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَبْدِاللَّهِ بْنِ أَبِي طَلْحَةَ لِيُحَنِّكَهُ، فَوَافَيْتُهُ فِي يَدِهِ الْمِيسَمُ يَسِمُ إِبِلَ الصَّدَقَةِ. (خ)', 'അനസുബിൻമാലിക്ക്(റ): അബൂത്വൽഹ(റ)ന്റെ മകൻ അബ്ദുല്ല(റ)വിനെ മധുരം തൊട്ടു കൊടുക്കാൻ വേണ്ടി ഒരു ദിവസം രാവിലെ തിരുമേനിയുടെ അടുക്കൽ ഞാൻ കൊണ്ട് വന്നു. അപ്പോൾ നബി(സ) ചൂടു വെക്കാനുപയോഗിക്കുന്ന ഇരുമ്പുകോലു കൊണ്ട് സകാത്തിന്റെ ഒട്ടകങ്ങൾക്കു അടയാളം വെക്കുകയായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബിൻമാലിക്ക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أَعْرَابِيًّا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْهِجْرَةِ، فَقَالَ: "وَيْحَكَ إِنَّ شَأْنَهَا شَدِيدٌ فَهَلْ لَكَ مِنْ إِبِلٍ تُؤَدِّي صَدَقَتَهَا؟". قَالَ: نَعَمْ، قَالَ: "فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ، فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا". (خ)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): ഒരു ഗ്രാമീണൻ നബി(സ)യുടെ അടുക്കൽ വന്ന് ഹിജ്റയെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ നബി(സ): "നിനക്കാണ് നാശം, അതു വളരെ വിഷമകരമായ ഒരു കാര്യമാണ്. നിനക്കു സകാത്ത് കൊടുക്കാൻ മാത്രം ഒട്ടകമുണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ, നബി(സ) അരുളി: "കടലിനപ്പുറംപോയി സൽക്കർമ്മം ചെയ്താലും നിന്റെ കർമ്മങ്ങൾക്കുള്ള പ്രതിഫലത്തിൽ ഒരു കുറവും അല്ലാഹു വരുത്തുകയില്ല." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ كَتَبَ لَهُ فَرِيضَةَ الصَّدَقَةِ، الَّتِي أَمَرَ اللَّهُ رَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَنْ بَلَغَتْ عِنْدَهُ مِنَ الْإِبِلِ صَدَقَةُ الْجَذَعَةِ، وَلَيْسَتْ عِنْدَهُ جَذَعَةٌ، وَعِنْدَهُ حِقَّةٌ، فَإِنَّهَا تُقْبَلُ مِنْهُ الْحِقَّةُ وَيَجْعَلُ مَعَهَا شَاتَيْنِ، إِنِ اسْتَيْسَرَتَا لَهُ، أَوْ عِشْرِينَ دِرْهَمًا، وَمَنْ بَلَغَتْ عِنْدَهُ صَدَقَةُ الْحِقَّةِ، وَلَيْسَتْ عِنْدَهُ الْحِقَّةُ، وَعِنْدَهُ الْجَذَعَةُ، فَإِنَّهَا تُقْبَلُ مِنْهُ الْجَذَعَةُ، وَيُعْطِيهِ الْمُصَدِّقُ عِشْرِينَ دِرْهَمًا أَوْ شَاتَيْنِ، وَمَنْ بَلَغَتْ عِنْدَهُ صَدَقَةُ الْحِقَّةِ، وَلَيْسَتْ عِنْدَهُ إِلَّا بِنْتُ لَبُونٍ، فَإِنَّهَا تُقْبَلُ مِنْهُ بِنْتُ لَبُونٍ، وَيُعْطِي شَاتَيْنِ أَوْ عِشْرِينَ دِرْهَمًا، وَمَنْ بَلَغَتْ صَدَقَتُهُ بِنْتَ لَبُونٍ، وَعِنْدَهُ حِقَّةٌ، فَإِنَّهَا تُقْبَلُ مِنْهُ الْحِقَّةُ، وَيُعْطِيهِ الْمُصَدِّقُ عِشْرِينَ دِرْهَمًا أَوْ شَاتَيْنِ، وَمَنْ بَلَغَتْ صَدَقَتُهُ بِنْتَ لَبُونٍ، وَلَيْسَتْ عِنْدَهُ وَعِنْدَهُ بِنْتُ مَخَاضٍ، فَإِنَّهَا تُقْبَلُ مِنْهُ بِنْتُ مَخَاضٍ، وَيُعْطِي مَعَهَا عِشْرِينَ دِرْهَمًا أَوْ شَاتَيْنِ. (خ)', 'അനസുബ്നുമാലിക്(റ): അല്ലാഹുവും റസൂൽ(സ)യും നിശ്ചയിച്ച സകാത്തിന്റെ വിധി അബൂബകർ(റ) എനിക്ക് എഴുതി. അതിപ്രകാരമായിരുന്നു: ഒരാളുടെ ഒട്ടകത്തിനു നാലുവയസ്സുള്ള പെണ്ണൊട്ടകത്തെ സകാത്തു കൊടുക്കേണ്ട ഘട്ടമെത്തി. എന്നാൽ അവന്റെ പക്കൽ അതുണ്ടായില്ല; മറിച്ച് മൂന്നുവയസ്സുള്ള പെണ്ണൊട്ടകം മാത്രമാണുള്ളതെങ്കിൽ അവനിൽ നിന്ന് അതു സ്വീകരിക്കാം. അതോടൊപ്പം രണ്ടാടുകൂടി അവൻ കൊടുക്കേണ്ടതുണ്ട്, അവന് സാധിച്ചാൽ. അല്ലെങ്കിൽ ഇരുപത് ദിർഹം. മൂന്നു വയസ്സുള്ള ഒരു പെണ്ണൊട്ടകം സകാത്ത് കൊടുക്കേണ്ട ഘട്ടമെത്തി, എന്നാൽ അവന്റെ പക്കൽ ആ ഒട്ടകം ഇല്ല. ഉള്ളതു നാലു വയസ്സുള്ള പെണ്ണൊട്ടകം മാത്രമാണ്. എങ്കിൽ അതു സ്വീകരിച്ച് സകാത്ത് പിരിച്ചെടുക്കുന്നവൻ ഇരുപത് ദിർഹം അങ്ങോട്ടു കൊടുക്കണം. അല്ലെങ്കിൽ രണ്ടാട്. മൂന്ന് വയസ്സുള്ള പെണ്ണൊട്ടകം സകാത്ത് കൊടുക്കേണ്ട ഘട്ടമെത്തി, അവന്റെ പക്കൽ ആ ഒട്ടകം ഇല്ല. ഉള്ളത് ഒരു വയസ്സുള്ള പെണ്ണൊട്ടകം മാത്രമാണെങ്കിൽ അത് സ്വീകരിക്കാം. അതോടൊപ്പം രണ്ടാട്, അല്ലെങ്കിൽ ഇരുപത് ദിർഹം അവന് കൊടുക്കണം. രണ്ട് വയസ്സുള്ള പെണ്ണൊട്ടകം സകാത്ത് കൊടുക്കേണ്ട ഘട്ടമെത്തി, എന്നാൽ അവന്റെ പക്കൽ മൂന്നുവയസ്സുള്ള പെണ്ണൊട്ടകം മാത്രമാണുള്ളതെങ്കിൽ അത് സ്വീകരിക്കാം. സകാത്ത് പിരിക്കുന്നവൻ ഇരുപത് ദിർഹം അല്ലെങ്കിൽ ഒരാട് ഒട്ടകത്തിന്റെ ഉടമസ്ഥന് കൊടുക്കണം. രണ്ട് വയസ്സുള്ള പെണ്ണൊട്ടകം സകാത്ത് കൊടുക്കേണ്ട ഘട്ടത്തിൽ അവന്റെ അടുക്കൽ അതില്ല. അവന്റെ അടുക്കലുള്ളത് ഒരു വയസ്സുള്ള പെണ്ണൊട്ടകക്കുട്ടി മാത്രമാണെങ്കിൽ അതു സ്വീകരിക്കാം. അതോടൊപ്പം ഇരുപത് ദിർഹം അല്ലെങ്കിൽ ഒരാടുകൂടി അവനു കൊടുക്കണം. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 181, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أَبَا بَكْرٍ كَتَبَ لَهُ كِتَابًا، وَعَلَيْهِ خَاتَمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حِينَ بَعَثَهُ مُصَدِّقًا، فَإِذَا فِيهِ: هَذِهِ فَرِيضَةُ الصَّدَقَةِ الَّتِي فَرَضَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمُسْلِمِينَ، الَّتِي أَمَرَ اللَّهُ عَزَّ وَجَلَّ بِهَا نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَنْ سُئِلَهَا مِنَ الْمُسْلِمِينَ عَلَى وَجْهِهَا فَلْيُعْطِهَا، وَمَنْ سُئِلَ فَوْقَهَا فَلَا يُعْطِهِ: فِيمَا دُونَ خَمْسٍ وَعِشْرِينَ مِنَ الْإِبِلِ الْغَنَمُ، فِي كُلِّ خَمْسِ ذَوْدٍ شَاةٌ، فَإِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ فَفِيهَا بِنْتُ مَخَاضٍ، إِلَى أَنْ تَبْلُغَ خَمْسًا وَثَلَاثِينَ، فَإِنْ لَمْ يَكُنْ فِيهَا بِنْتُ مَخَاضٍ فَابْنُ لَبُونٍ ذَكَرٌ، فَإِذَا بَلَغَتْ سِتًّا وَثَلَاثِينَ فَفِيهَا بِنْتُ لَبُونٍ، إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا بَلَغَتْ سِتًّا وَأَرْبَعِينَ فَفِيهَا حِقَّةٌ طَرُوقَةُ الْفَحْلِ إِلَى سِتِّينَ، فَإِذَا بَلَغَتْ إِحْدَى وَسِتِّينَ فَفِيهَا جَذَعَةٌ، إِلَى خَمْسٍ وَسَبْعِينَ، فَإِذَا بَلَغَتْ سِتًّا وَسَبْعِينَ فَفِيهَا ابْنَتَا لَبُونٍ، إِلَى تِسْعِينَ، فَإِذَا بَلَغَتْ إِحْدَى وَتِسْعِينَ فَفِيهَا حِقَّتَانِ طَرُوقَتَا الْفَحْلِ، إِلَى عِشْرِينَ وَمِائَةٍ، فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ فَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ وَفِي كُلِّ خَمْسِينَ حِقَّةٌ. فَإِذَا تَبَايَنَ أَسْنَانُ الْإِبِلِ فِي فَرَائِضِ الصَّدَقَاتِ: فَمَنْ بَلَغَتْ عِنْدَهُ صَدَقَةُ الْجَذَعَةِ– وَلَيْسَتْ عِنْدَهُ جَذَعَةٌ– وَعِنْدَهُ حِقَّةٌ فَإِنَّهَا تُقْبَلُ مِنْهُ، وَأَنْ يَجْعَلَ مَعَهَا شَاتَيْنِ – إِنِ اسْتَيْسَرَتَا لَهُ – أَوْ عِشْرِينَ دِرْهَمًا.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَتَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابَ الصَّدَقَةِ، فَلَمْ يُخْرِجْهُ إِلَى عُمَّالِهِ حَتَّى قُبِضَ، فَقَرَنَهُ بِسَيْفِهِ، فَعَمِلَ بِهِ أَبُو بَكْرٍ حَتَّى قُبِضَ، ثُمَّ عَمِلَ بِهِ عُمَرُ حَتَّى قُبِضَ، فَكَانَ فِيهِ:
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=116), 1, 'وَفِي رِوَايَةٍ: فَإِنْ لَمْ تَكُنْ ابْنَةُ مَخَاضٍ فَابْنُ لَبُونٍ – فَإِنْ زَادَتْ وَاحِدَةً فَفِيهَا ابْنَةُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّةٌ إِلَى سِتِّينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا جَذَعَةٌ إِلَى خَمْسٍ وَسَبْعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَتَا لَبُونٍ إِلَى تِسْعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّتَانِ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِنْ كَانَتِ الْإِبِلُ أَكْثَرَ مِنْ ذَلِكَ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ، وَفِي كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=116), 2, 'وَفِي رِوَايَةٍ قَالَ: فَإِذَا كَانَتْ إِحْدَى وَعِشْرِينَ وَمِائَةً فَفِيهَا ثَلَاثُ بَنَاتِ لَبُونٍ، حَتَّى تَبْلُغَ تِسْعًا وَعِشْرِينَ وَمِائَةً. فَإِذَا كَانَتْ ثَلَاثِينَ وَمِائَةً فَفِيهَا بِنْتَا لَبُونٍ وَحِقَّةٌ، حَتَّى تَبْلُغَ تِسْعًا وَثَلَاثِينَ وَمِائَةً. فَإِذَا كَانَتْ أَرْبَعِينَ وَمِائَةً فَفِيهَا حِقَّتَانِ وَبِنْتُ لَبُونٍ، حَتَّى تَبْلُغَ تِسْعًا وَأَرْبَعِينَ وَمِائَةً. فَإِذَا كَانَتْ خَمْسِينَ وَمِائَةً فَفِيهَا ثَلَاثُ حِقَاقٍ، حَتَّى تَبْلُغَ تِسْعًا وَخَمْسِينَ وَمِائَةً. فَإِذَا كَانَتْ سِتِّينَ وَمِائَةً فَفِيهَا أَرْبَعُ بَنَاتِ لَبُونٍ، حَتَّى تَبْلُغَ تِسْعًا وَسِتِّينَ وَمِائَةً. فَإِذَا كَانَتْ سَبْعِينَ وَمِائَةً فَفِيهَا ثَلَاثُ بَنَاتِ لَبُونٍ وَحِقَّةٌ، حَتَّى تَبْلُغَ تِسْعًا وَسَبْعِينَ وَمِائَةً. فَإِذَا كَانَتْ ثَمَانِينَ وَمِائَةً فَفِيهَا حِقَّتَانِ وَابْنَتَا لَبُونٍ، حَتَّى تَبْلُغَ تِسْعًا وَثَمَانِينَ وَمِائَةً. فَإِذَا كَانَتْ تِسْعِينَ وَمِائَةً فَفِيهَا ثَلَاثُ حِقَاقٍ وَبِنْتُ لَبُونٍ، حَتَّى تَبْلُغَ تِسْعًا وَتِسْعِينَ وَمِائَةً. فَإِذَا كَانَتْ مِائَتَيْنِ فَفِيهَا أَرْبَعُ حِقَاقٍ أَوْ خَمْسُ بَنَاتِ لَبُونٍ، أَيُّ السِّنَّيْنِ وُجِدَتْ أُخِذَتْ. وَفِي سَائِمَةِ الْغَنَمِ..... وَفِيهِ: وَلَا يُؤْخَذُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلَا ذَاتُ عَوَارٍ مِنَ الْغَنَمِ، وَلَا تَيْسُ الْغَنَمِ، إِلَّا أَنْ يَشَاءَ الْمُصَدِّقُ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "هَاتُوا رُبْعَ الْعُشُورِ: مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ، وَلَيْسَ عَلَيْكُمْ شَيْءٌ حَتَّى تَتِمَّ مِائَتَيْ دِرْهَمٍ، فَإِذَا كَانَتْ مِائَتَيْ دِرْهَمٍ فَفِيهَا خَمْسَةُ دَرَاهِمَ، فَمَا زَادَ فَعَلَى حِسَابِ ذَلِكَ. وَفِي الْغَنَمِ فِي أَرْبَعِينَ شَاةً شَاةٌ، فَإِنْ لَمْ يَكُنْ إِلَّا تِسْعٌ وَثَلَاثُونَ، فَلَيْسَ عَلَيْكَ فِيهَا شَيْءٌ". وَسَاقَ الْحَدِيثَ، صَدَقَةُ الْغَنَمِ مِثْلَ (حَدِيثِ ابْنِ عُمَرَ) قَالَ: "وَفِي الْبَقَرِ فِي كُلِّ ثَلَاثِينَ تَبِيعٌ، وَفِي الْأَرْبَعِينَ مُسِنَّةٌ، وَلَيْسَ عَلَى الْعَوَامِلِ شَيْءٌ، وَفِي الْإِبِلِ". وَسَاقَ الْحَدِيثَ فَذَكَرَ صَدَقَتَهَا كَمَا ذَكَرَ قَالَ: "وَفِي خَمْسٍ وَعِشْرِينَ خَمْسَةٌ مِنَ الْغَنَمِ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَةُ مَخَاضٍ، فَإِنْ لَمْ تَكُنْ بِنْتُ مَخَاضٍ فَابْنُ لَبُونٍ ذَكَرٌ، إِلَى خَمْسٍ وَثَلَاثِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا بِنْتُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّةٌ طَرُوقَةُ الْجَمَلِ، إِلَى سِتِّينَ". ثُمَّ سَاقَ الْحَدِيثَ مِثْلَ قَبِيلٍ قَالَ: "فَإِذَا زَادَتْ وَاحِدَةً – يَعْنِي وَاحِدَةً وَتِسْعِينَ – فَفِيهَا حِقَّتَانِ طَرُوقَتَا الْجَمَلِ، إِلَى عِشْرِينَ وَمِائَةٍ، فَإِنْ كَانَتِ الْإِبِلُ أَكْثَرَ مِنْ ذَلِكَ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ. وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، وَلَا يُجْمَعُ بَيْنَ مُفْتَرِقٍ، خَشْيَةَ الصَّدَقَةِ. وَلَا تُؤْخَذُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلَا ذَاتُ عَوَارٍ، وَلَا تَيْسٌ، إِلَّا أَنْ يَشَاءَ الْمُصَدِّقُ". وَفِي النَّبَاتِ: "مَا سَقَتْهُ الْأَنْهَارُ أَوْ سَقَتِ السَّمَاءُ الْعُشْرُ، وَمَا سَقَى الْغَرْبُ فَفِيهِ نِصْفُ الْعُشْرِ". وَفِي رِوَايَةٍ: "الصَّدَقَةُ فِي كُلِّ عَامٍ مَرَّةً". وَفِي رِوَايَةٍ: "إِذَا لَمْ يَكُنْ فِي الْإِبِلِ ابْنَةُ مَخَاضٍ وَلَا ابْنُ لَبُونٍ فَعَشَرَةُ دَرَاهِمَ أَوْ شَاتَانِ". (د)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "പത്തിലൊന്നിന്റെ നാലിലൊന്നിനെ (നാൽപ്പതിൽ ഒന്ന്) നിങ്ങൾ കൊണ്ടുവരിക. എല്ലാ നാൽപത് ദിർഹമിലും ഒരു ദിർഹം. 200 ദിർഹം പൂർത്തിയാകുന്നതുവരെ നിങ്ങളുടെ മേൽ ഒന്നും നിർബന്ധമില്ല. ഇരുനൂറ് ദിർഹമുണ്ടെങ്കിൽ അതിൽ അഞ്ച് ദിർഹം നിർബന്ധമാകും. അതിലും വർദ്ധിച്ചാൽ അതിന്റെ കണക്കനുസരിച്ച് കൊടുക്കണം. 40 ആടിൽ നിന്ന് ഒരാട് കൊടുക്കണം. 39 ആടുകളേയുള്ളുവെങ്കിൽ അതിൽ ഒന്നും കൊടുക്കേണ്ടതില്ല." (ആടിനെപ്പറ്റി ഇബ്നുഉമർ(റ)വിന്റെ ഹദീസിലുള്ളതുപോലെ പറഞ്ഞു.) ശേഷം തുടർന്നു: "ഓരോ 30 പശുവിലും ഒരു വയസ്സ് പൂർത്തിയായ പശുക്കിടാവിനെയും ഓരോ 40 ലും 2 വയസ്സ് പൂർത്തിയായ പശുക്കിടാവിനെയുമാണ് നൽകേണ്ടത്. സകാത്ത് പിരിവുകാരന്റെ മേൽ ഒന്നും നിർബന്ധവുമില്ല. ഒട്ടകത്തിൽ:" ശേഷം അതിലുള്ള സകാത്തിനെക്കുറിച്ച് മുൻപറഞ്ഞ ഹദൂസിലുള്ളത് പോലെ പറഞ്ഞു: "25ൽ 5 ആട്, ഒന്ന് അധികരിച്ചാൽ 35 വരെ ഒരു വയസ്സായ പെണ്ണൊട്ടകം, അതില്ലെങ്കിൽ രണ്ട് വയസ്സായ ആണൊട്ടകം, ഒന്നധികരിച്ചാൽ 45 വരെ രണ്ട് വയസ്സായ പെണ്ണൊട്ടകം, അതിലൊന്നധികരിച്ചാൽ 60 വരെ ഇണ ചേർക്കപ്പെടുന്ന മൂന്ന് വയസ്സായൊരു പെണ്ണൊട്ടകം." പിന്നെ മുൻ ഹദീസ് പോലെ പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അതിലൊന്നധികരിച്ചാൽ അതായത് 91 ആയാൽ 120 വരെ അതിൽ ഇണ ചേർക്കപ്പെടുന്ന 3 വയസ്സായ 2 പെണ്ണൊട്ടകം. ഒട്ടകം അതിലും കൂടുതലുണ്ടെങ്കിൽ ഓരോ അൻപതിലും മൂന്ന് വയസ്സായ പെണ്ണൊട്ടകമാണ്. സകാത്ത് ഭയന്ന് ഒരുമിച്ചു കൂട്ടപ്പെട്ടത് വിഭജിക്കപ്പെടുകയോ വിഭിന്നമായതു കൂട്ടപ്പെടുകയോ ചെയ്യരുത്. സകാതിൽ, വാർദ്ധക്യം ബാധിച്ചതിനെയോ, മോശപ്പെട്ടതിനെയോ മോട്ടു കാണിക്കുന്നതിനെയോ, സകാത്ത് പിരിക്കുന്നയാളുദ്ദേശിച്ചാലല്ലാതെ പിടിക്കപ്പെടരുത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=117), 1, 'وَفِي رِوَايَةٍ: "الصَّدَقَةُ فِي كُلِّ عَامٍ مَرَّةً".', 'മറ്റൊരു നിവേദനിൽ: "സകാത്ത് ഓരോ വർഷവും ഓരോ തവണയാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=117), 2, 'وَفِي رِوَايَةٍ: "إِذَا لَمْ يَكُنْ فِي الْإِبِلِ ابْنَةُ مَخَاضٍ وَلَا ابْنُ لَبُونٍ فَعَشَرَةُ دَرَاهِمَ أَوْ شَاتَانِ". (د)', 'മറ്റൊരു നിവേദനിൽ: "ഒട്ടകത്തിൽ ബിൻത് മഹാളോ (ഒരു വയസ്സ് പൂർത്തിയായ പെണ്ണൊട്ടകം) ഇബ്നു ലബൂനോ (രണ്ടുവയസ്സായ ആണൊട്ടകം) ഇല്ലെങ്കിൽ, പത്ത് ദിർഹം അല്ലെങ്കിൽ രണ്ടാടാണ് നൽകേണ്ടത്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبَعْضِ أَوَّلِ هَذَا الْحَدِيثِ قَالَ: "فَإِذَا كَانَتْ لَكَ مِائَتَا دِرْهَمٍ وَحَالَ عَلَيْهَا الْحَوْلُ فَفِيهَا خَمْسَةُ دَرَاهِمَ، وَلَيْسَ عَلَيْكَ شَيْءٌ – يَعْنِي فِي الذَّهَبِ – حَتَّى يَكُونَ لَكَ عِشْرُونَ دِينَارًا، فَإِذَا كَانَ لَكَ عِشْرُونَ دِينَارًا وَحَالَ عَلَيْهَا الْحَوْلُ فَفِيهَا نِصْفُ دِينَارٍ، فَمَا زَادَ فَبِحِسَابِ ذَلِكَ". قَالَ الرَّاوِي: فَلَا أَدْرِي أَعَلِيٌّ يَقُولُ: "فَبِحِسَابِ ذَلِكَ". – أَوْ رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَلَيْسَ فِي مَالٍ زَكَاةٌ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ". (د,جه)', 'അലി(റ): നബി(സ)യിൽ നിന്നും ഹദീസിന്റെ ആദ്യ ഭാഗം പറയുന്നു: "നിന്റെ പക്കൽ വർഷം പൂർത്തിയായ ഇരുനൂറ് ദിർഹമുണ്ടായാൽ അതിലെ സകാത്ത് അഞ്ച് ദിർഹമുകളാണ്. സ്വർണ്ണത്തിലാണെങ്കിൽ 20 ദീനാറെത്തുന്നത് വരെ നിനക്കൊന്നും നിർബന്ധമില്ല. അങ്ങനെ വർഷം പൂർത്തിയായ ഇരുപത് ദീനാറുണ്ടായാൽ അതിലെ സകാത്ത് അര ദീനാറാണ്, അതിലും അധികരിച്ചതിൽ അതാതിന്റെ തോതനുസരിച്ച് നൽകപ്പെടണം." നിവേദകൻ പറയുന്നു: "ബിഹിസാബി ദാലിക (അതാതിന്റെ തോതനുസരിച്ച്)" എന്ന് അലി(റ) നേരിട്ട് പറഞ്ഞതാണോ അതോ റസൂൽ(സ)യിലേക്ക് തന്നെ ചേർത്തിപ്പറഞ്ഞതാണോ എന്ന് എനിക്കറിയില്ല. "സമ്പത്തിൽ വർഷം പൂർത്തിയാകുന്നത് വരെ ഒരു സകാതുമില്ല." (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ عَفَوْتُ عَنِ الْخَيْلِ وَالرَّقِيقِ، فَهَاتُوا صَدَقَةَ الرِّقَةِ: مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمًا، وَلَيْسَ فِي تِسْعِينَ وَمِائَةٍ شَيْءٌ، فَإِذَا بَلَغَتْ مِائَتَيْنِ فَفِيهَا خَمْسَةُ دَرَاهِمَ". (د,ت,ن,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമയിലും കുതിരയിലുമുള്ള സകാത്ത് ഞാൻ ഇളവ് ചെയ്തിരിക്കുന്നു, അത് കൊണ്ട് വെള്ളിയിലെ സകാത്ത് നിങ്ങൾ കൊണ്ട് വരിക. അത് ഓരോ നാൽപ്പത് ദിർഹമിലും ഒരു ദിർഹമാണ്. 190 വരെ ഒന്നും നിർബന്ധമില്ല, 200 എത്തിയാൽ അഞ്ച് ദിർഹമാണ് സകാത്ത് നൽകേണ്ടത്." (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', 'قَالَ أَبُو دَاوُدَ رَضِيَ اللَّهُ عَنْهُ: سَمِعْتُهُ مِنَ الرِّيَاشِيِّ وَأَبِي حَاتِمٍ وَغَيْرِهِمَا، وَمِنْ كِتَابِ النَّضْرِ بْنِ شُمَيْلٍ، وَمِنْ كِتَابِ أَبِي عُبَيْدٍ. وَرُبَّمَا ذَكَرَ أَحَدُهُمُ الْكَلِمَةَ قَالُوا: يُسَمَّى الْحُوَارُ ثُمَّ الْفَصِيلُ إِذَا فَصَلَ، ثُمَّ تَكُونُ بِنْتُ مَخَاضٍ لِسَنَةٍ إِلَى تَمَامِ سَنَتَيْنِ، فَإِذَا دَخَلَتْ فِي الثَّالِثَةِ فَهِيَ ابْنَةُ لَبُونٍ، فَإِذَا تَمَّتْ لَهُ ثَلَاثُ سِنِينَ فَهُوَ حِقٌّ وَحِقَّةٌ إِلَى تَمَامِ أَرْبَعِ سِنِينَ، لِأَنَّهَا اسْتَحَقَّتْ أَنْ تُرْكَبَ وَيُحْمَلَ عَلَيْهَا الْفَحْلُ، وَهِيَ تَلْقَحُ، وَلَا يُلْقِحُ الذَّكَرُ حَتَّى يُثَنِّيَ، وَيُقَالُ لِلْحِقَّةِ طَرُوقَةُ الْفَحْلِ، لِأَنَّ الْفَحْلَ يَطْرُقُهَا إِلَى تَمَامِ أَرْبَعِ سِنِينَ، فَإِذَا طَعَنَتْ فِي الْخَامِسَةِ فَهِيَ جَذَعَةٌ، حَتَّى يَتِمَّ لَهَا خَمْسُ سِنِينَ، فَإِذَا دَخَلَتْ فِي السَّادِسَةِ وَأَلْقَى ثَنِيَّتَهُ فَهُوَ حِينَئِذٍ ثَنِيٌّ، حَتَّى يَسْتَكْمِلَ سِتًّا، فَإِذَا طَعَنَ فِي السَّابِعَةِ سُمِّيَ الذَّكَرُ رَبَاعِيًا وَالْأُنْثَى رَبَاعِيَةً إِلَى تَمَامِ السَّابِعَةِ، فَإِذَا دَخَلَ فِي الثَّامِنَةِ وَأَلْقَى السِّنَّ السَّدِيسَ الَّذِي بَعْدَ الرَّبَاعِيَةِ فَهُوَ سَدِيسٌ وَسَدَسٌ إِلَى تَمَامِ الثَّامِنَةِ، فَإِذَا دَخَلَ فِي التِّسْعِ وَطَلَعَ نَابُهُ فَهُوَ بَازِلٌ، أَيْ بَزَلَ نَابُهُ يَعْنِي طَلَعَ، حَتَّى يَدْخُلَ فِي الْعَاشِرَةِ، فَهُوَ حِينَئِذٍ مُخْلِفٌ، ثُمَّ لَيْسَ لَهُ اسْمٌ، وَلَكِنْ يُقَالُ بَازِلُ عَامٍ، وَبَازِلُ عَامَيْنِ، وَمُخْلِفُ عَامٍ، وَمُخْلِفُ عَامَيْنِ، وَمُخْلِفُ ثَلَاثَةِ أَعْوَامٍ، إِلَى خَمْسِ سِنِينَ. وَالْخَلِفَةُ الْحَامِلُ. (د)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ فِيمَا دُونَ خَمْسٍ مِنَ الْإِبِلِ صَدَقَةٌ، وَلَا فِي الْأَرْبَعِ شَيْءٌ، فَإِذَا بَلَغَتْ خَمْسًا فَفِيهَا شَاةٌ إِلَى أَنْ تَبْلُغَ تِسْعًا، فَإِذَا بَلَغَتْ عَشْرًا فَفِيهَا شَاتَانِ إِلَى أَنْ تَبْلُغَ أَرْبَعَ عَشْرَةَ، فَإِذَا بَلَغَتْ خَمْسَ عَشْرَةَ فَفِيهَا ثَلَاثُ شِيَاهٍ إِلَى أَنْ تَبْلُغَ تِسْعَ عَشْرَةَ، فَإِذَا بَلَغَتْ عِشْرِينَ فَفِيهَا أَرْبَعُ شِيَاهٍ إِلَى أَنْ تَبْلُغَ أَرْبَعًا وَعِشْرِينَ، فَإِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ فَفِيهَا بِنْتُ مَخَاضٍ إِلَى خَمْسٍ وَثَلَاثِينَ، فَإِذَا لَمْ تَكُنْ بِنْتُ مَخَاضٍ فَابْنُ لَبُونٍ ذَكَرٌ، فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا بِنْتُ لَبُونٍ إِلَى أَنْ تَبْلُغَ خَمْسًا وَأَرْبَعِينَ، فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا حِقَّةٌ إِلَى أَنْ تَبْلُغَ سِتِّينَ، فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا جَذَعَةٌ إِلَى أَنْ تَبْلُغَ خَمْسًا وَسَبْعِينَ، فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا بِنْتَا لَبُونٍ إِلَى أَنْ تَبْلُغَ تِسْعِينَ، فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا حِقَّتَانِ إِلَى أَنْ تَبْلُغَ عِشْرِينَ وَمِائَةً، ثُمَّ فِي كُلِّ خَمْسِينَ حِقَّةٌ، وَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ". (جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "ഒട്ടകങ്ങളിൽ അഞ്ചിൽ താഴെയുള്ളതിനു സകാത്ത് നിർബന്ധമില്ല. നാലെണ്ണത്തിലും സകാത്തില്ല. അഞ്ചെണ്ണമായാൽ ഒൻപതു ഒട്ടകങ്ങൾ വരെ ഒരു ആട് സകാത്ത് നൽകണം. 10 എണ്ണമായാൽ 14 വരെ രണ്ടാട് സകാത്ത് നൽകണം. 15 എണ്ണമായാൽ 19 വരെ മൂന്ന് ആടും, 20 എണ്ണമായാൽ 24 വരെയുള്ളതിന് നാല് ആടുകളും, 25 എണ്ണമായാൽ 35 വരെയുള്ളവക്ക് ''ബിൻത് മഖാളും'' (ഒരു വയസ്സ് പൂർത്തിയായ പെണ്ണൊട്ടകം) സകാത്തായി നൽകണം; ''ബിൻത് മഖാള്'' ഇല്ലെങ്കിൽ ''ഇബ്നു ലബൂനും'' (രണ്ട് വയസ്സ് പൂർത്തിയായ ആണൊട്ടകം) സകാത്തായി നൽകണം. അതിനേക്കാൾ ഒട്ടകങ്ങളുണ്ടെങ്കിൽ 45 വരെ ഒട്ടകങ്ങൾക്ക് ''ബിൻത് ലബൂനും'' (രണ്ട് വയസ്സ് പൂർത്തിയായ പെണ്ണൊട്ടകം), അതിനേക്കാൾ ഒട്ടകങ്ങളുണ്ടെങ്കിൽ 60 വരെയുള്ളതിന് ''ഹിക്ക''യും (മൂന്ന് വയസ്സ് പൂർത്തിയായ പെണ്ണൊട്ടകം), അതിനേക്കാൾ ഒട്ടകങ്ങളുണ്ടെങ്കിൽ 75 വരെ ''ജദ്അതും'' (നാലു വയസ്സു പൂർത്തിയായ പെണ്ണൊട്ടകം), അതിനേക്കാൾ ഒട്ടകങ്ങളുണ്ടെങ്കിൽ 90 വരെ രണ്ട് ''ബിൻത് ലബൂനും'' അതിനേക്കാൾ ഒട്ടകങ്ങളുണ്ടെങ്കിൽ 120 വരെയുള്ളതിന് രണ്ട് ''ഹിക്ക''കളും, പിന്നീടങ്ങോട്ട് ഓരോ അമ്പത് ഒട്ടകങ്ങൾക്കും ഓരോ ''ഹിക്ക'' വീതവും, ഓരോ 40 ഒട്ടകങ്ങൾക്ക് ഓരോ ''ബിൻത് ലബൂനും'' സകാത്തായി നൽകണം." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تُؤْخَذُ صَدَقَاتُ الْمُسْلِمِينَ عَلَى مِيَاهِهِمْ". (جه) (في سنده ضعيف)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "മുസ്‌ലിംകളുടെ സകാത്ത് അവരുടെ ജലാശയത്തിനരികെ (മൃഗങ്ങളെ വെള്ളം കുടിപ്പിക്കുന്ന സ്ഥലം) വെച്ച് പിടിക്കപ്പെടും." (പരമ്പരയിൽ ഭംഗമുള്ളവനുണ്ട്) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده ضعيف', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا وَجَّهَهُ إِلَى الْيَمَنِ أَمَرَهُ: أَنْ يَأْخُذَ مِنَ الْبَقَرِ مِنْ كُلِّ ثَلَاثِينَ تَبِيعًا أَوْ تَبِيعَةً، وَمِنْ كُلِّ أَرْبَعِينَ مُسِنَّةً. وَمِنْ كُلِّ حَالِمٍ – يَعْنِي مُحْتَلِمًا – دِينَارًا أَوْ عَدْلَهُ مِنَ الْمَعَافِرِ، ثِيَابٌ تَكُونُ بِالْيَمَنِ. وَفِي رِوَايَةٍ: لَمْ يَذْكُرْ ثِيَابًا تَكُونُ بِالْيَمَنِ، وَلَا ذَكَرَ: يَعْنِي مُحْتَلِمًا. (د,ت,ن,جه)', 'മുആദ്(റ): നബി(സ) അദ്ദേഹത്തെ യമനിലേക്കയച്ചപ്പോൾ പ്രായപൂർത്തിയായ എല്ലാവരിൽ നിന്നും വെള്ളി നാണയമോ, അതിനോട് വിലയിൽ തുല്യമായ യമനിലെ ഒരിനം വസ്ത്രത്തേയോ (സകാത്തായി) പിടിക്കാനും, പശുക്കളിൽ ഓരോ മുപ്പത് പശുവിൽ നിന്നും ഒരു വയസ്സ് പൂർത്തിയായ ആൺപശുവിനെയോ പെൺപശുവിനെയോ പിടിക്കാനും, എല്ലാ നാൽപത് പശുവിൽ നിന്നും രണ്ടുവയസ്സ് പൂർത്തിയായ ഒരു പെൺപശുവിനെ പിടിക്കാനും കൽപിച്ചു. മറ്റൊരു നിവേദനം: യമനിലുണ്ടാകുന്ന ഒരു വസ്ത്രമെന്നും, ''യഅ്നീ മുഹ്തലിമൻ'' (അതായത് പ്രായപൂർത്തിയെത്തിയവൻ) എന്നും റസൂൽ(സ) പറഞ്ഞിട്ടില്ല. (ദ,തു,ന,ജ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 188, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=122), 1, 'وَفِي رِوَايَةٍ: لَمْ يَذْكُرْ ثِيَابًا تَكُونُ بِالْيَمَنِ، وَلَا ذَكَرَ: يَعْنِي مُحْتَلِمًا. (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: യമനിലുണ്ടാകുന്ന ഒരു വസ്ത്രമെന്നും, ''യഅ്നീ മുഹ്തലിമൻ'' (അതായത് പ്രായപൂർത്തിയെത്തിയവൻ) എന്നും റസൂൽ(സ) പറഞ്ഞിട്ടില്ല. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِي ثَلَاثِينَ مِنَ الْبَقَرِ تَبِيعٌ أَوْ تَبِيعَةٌ، وَفِي كُلِّ أَرْبَعِينَ مُسِنَّةٌ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "മുപ്പത് പശുക്കളിൽ ഒരു വയസ്സു പൂർത്തിയായ മൂരിയെയോ പശുവിനേയോ സകാത്തു കൊടുക്കണം. ഓരോ നാൽപതിലും രണ്ടു വയസ്സു പൂർത്തിയായ പെൺപശുവിനെ കൊടുക്കണം." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ فِي الْخَيْلِ وَالرَّقِيقِ زَكَاةٌ، إِلَّا زَكَاةُ الْفِطْرِ فِي الرَّقِيقِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കുതിരയിലോ അടിമയിലോ നിർബന്ധദാനമില്ല. അടിമയിൽ ഫിത്വ്ർ സകാത്തൊഴികെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ عَلَى الْمُسْلِمِ فِي عَبْدِهِ وَلَا فِي فَرَسِهِ صَدَقَةٌ". وَفِي رِوَايَةٍ: "لَا زَكَاةَ عَلَى الرَّجُلِ الْمُسْلِمِ فِي عَبْدِهِ وَلَا فَرَسِهِ". وَفِي رِوَايَةٍ: "لَيْسَ عَلَى الْمَرْءِ فِي فَرَسِهِ وَلَا فِي مَمْلُوكِهِ صَدَقَةٌ". وَفِي رِوَايَةٍ: "لَيْسَ عَلَى الْمُسْلِمِ صَدَقَةٌ فِي غُلَامِهِ وَلَا فِي فَرَسِهِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിമിന് തന്റെ അടിമയിലോ കുതിരയിലോ സകാതില്ല." മറ്റൊരു നിവേദനത്തിൽ: "മുസ്‌ലിമായ പുരുഷന് തന്റെ അടിമയിലോ കുതിരയിലോ സകാതില്ല." മറ്റൊരു നിവേദനത്തിൽ: "മനുഷ്യന് തന്റെ അടിമയിലോ കുതിരയിലോ സകാതില്ല." മറ്റൊരു നിവേദനത്തിൽ: "മുസ്‌ലിമിന് തന്റെ ഭൃത്ത്യനിലോ കുതിരയിലോ സകാതില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=125), 1, 'وَفِي رِوَايَةٍ: "لَا زَكَاةَ عَلَى الرَّجُلِ الْمُسْلِمِ فِي عَبْدِهِ وَلَا فَرَسِهِ".', 'മറ്റൊരു നിവേദനത്തിൽ: "മുസ്‌ലിമായ പുരുഷന് തന്റെ അടിമയിലോ കുതിരയിലോ സകാതില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=125), 2, 'وَفِي رِوَايَةٍ: "لَيْسَ عَلَى الْمَرْءِ فِي فَرَسِهِ وَلَا فِي مَمْلُوكِهِ صَدَقَةٌ".', 'മറ്റൊരു നിവേദനത്തിൽ: "മനുഷ്യന് തന്റെ അടിമയിലോ കുതിരയിലോ സകാതില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=125), 3, 'وَفِي رِوَايَةٍ: "لَيْسَ عَلَى الْمُسْلِمِ صَدَقَةٌ فِي غُلَامِهِ وَلَا فِي فَرَسِهِ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "മുസ്‌ലിമിന് തന്റെ ഭൃത്ത്യനിലോ കുതിരയിലോ സകാതില്ല." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ كَتَبَ لَهُ الَّتِي فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَلَا يُجْمَعُ بَيْنَ مُتَفَرِّقٍ، وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، خَشْيَةَ الصَّدَقَةِ. (خ)', 'അനസ്(റ): അബൂബക്കർ സിദ്ദീഖ്(റ) റസൂൽ(സ) നിശ്ചയിച്ച കാര്യം അദ്ദേഹത്തിന് എഴുതിക്കൊടുത്തു: സകാതിനെ ഭയന്ന് വിഭജിച്ചതിനെ കൂട്ടപ്പെടുകയോ കൂട്ടത്തെ വിഭജിക്കപ്പെടുകയോ ചെയ്യപ്പെടാൻ പാടില്ല. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'قَالَ مَالِكٌ رَضِيَ اللَّهُ عَنْهُ: وَقَوْلُ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: لَا يُجْمَعُ بَيْنَ مُتَفَرِّقٍ، وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، هُوَ أَنْ يَكُونَ لِكُلِّ رَجُلٍ أَرْبَعُونَ شَاةً، فَإِذَا أَظَلَّهُمُ الْمُصَدِّقُ جَمَعُوهَا لِئَلَّا يَكُونَ فِيهَا إِلَّا شَاةٌ، وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، أَنَّ الْخَلِيطَيْنِ إِذَا كَانَ لِكُلِّ وَاحِدٍ مِنْهُمَا مِائَةُ شَاةٍ وَشَاةٌ فَيَكُونُ عَلَيْهِمَا فِيهَا ثَلَاثُ شِيَاهٍ، فَإِذَا أَظَلَّهُمَا الْمُصَدِّقُ فَرَّقَا غَنَمَهُمَا، فَلَمْ يَكُنْ عَلَى كُلِّ وَاحِدٍ مِنْهُمَا إِلَّا شَاةٌ، فَهَذَا الَّذِي سَمِعْتُ فِي ذَلِكَ. (د)', 'മാലിക്(റ) പറഞ്ഞു: ''വിഭിന്നമായതിനെ കൂട്ടപ്പെടുകയില്ല, കൂട്ടത്തെ വിഭജിക്കപ്പെടുകയുമില്ല'' എന്ന് ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞത് ഇതിനെക്കുറിച്ചാണ്: ഓരോരുത്തർക്കും 40 ആടുകൾ വീതമുണ്ടാവുക, അങ്ങനെ സകാത്ത് പിരിവുകാരൻ വരുമ്പോൾ, അതിൽ ഒരാട് മാത്രം സകാത്തുണ്ടാകാൻ വേണ്ടി അവർ എല്ലാ ആടുകളെയും ഒരുമിച്ചു കൂട്ടുന്നു. ''കൂട്ടം വിഭജിക്കപ്പെടുകയില്ല'' എന്ന് പറയുന്നത് ഇതാണ്: രണ്ട് കൂറായ ആളുകൾ, ഓരോരുത്തർക്കും 101 ആട് വീതമുണ്ട്. അപ്പോൾ രണ്ടാളും കൂടി സകാത്ത് കൊടുക്കേണ്ടത് 3 ആടുകൾ, സകാത്ത് പിരിവുകാരൻ വരുമ്പോൾ, രണ്ടു പേരുടെയും ആടുകളെ വിഭജിക്കും, അപ്പോൾ ഓരോരുത്തർക്കും സകാത്തായി ഒരാട് മാത്രമേ ഉണ്ടാകൂ. ഈ വിഷയത്തിൽ ഞാൻ(മാലിക്(റ)) കേട്ടത് ഇതാണ്. (ദ)', null, 'മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 189, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا مُصَدِّقُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُهُ فَجَلَسْتُ إِلَيْهِ، فَسَمِعْتُهُ يَقُولُ: إِنَّ فِي عَهْدِي أَنْ لَا نَأْخُذَ رَاضِعَ لَبَنٍ، وَلَا نَجْمَعَ بَيْنَ مُتَفَرِّقٍ، وَلَا نُفَرِّقَ بَيْنَ مُجْتَمِعٍ. فَأَتَاهُ رَجُلٌ بِنَاقَةٍ كَوْمَاءَ فَقَالَ: خُذْهَا، فَأَبَى. (ن)', 'സുവൈദുബ്നു ഗഫല(റ): നബി(സ)യുടെ സകാത്ത്പിരിവുകാരൻ ഞങ്ങളുടെ അടുത്തേക്ക് വന്നപ്പോൾ, ഞാനദ്ദേഹത്തിനടുത്തേക്ക് ചെന്ന് അരികിലിരുന്നു. അദ്ദേഹം പറയുന്നത് ഞാൻ കേട്ടു. നിശ്ചയമായും എന്റെ ഈ കരാർപത്രത്തിലുള്ളത്, മുലകുടിക്കുന്ന ഒട്ടകത്തെ എടുക്കരുതെന്നും, വിഭിന്നമായതിനെ ഒരുമിച്ചു കൂട്ടരുതെന്നും, കൂട്ടത്തെ വിഭജിക്കരുതെന്നുമാണ്. അപ്പോൾ അദ്ദേഹത്തിനടുത്തേക്ക്, ഉയർന്ന പൂഞ്ഞയുള്ള ഒരൊട്ടകവുമായി, ഒരാൾ വന്ന് പറഞ്ഞു: ഇതെടുക്കുക. അപ്പോൾ അദ്ദേഹം അത് നിരസിച്ചു. (ന)', 'سُوَيْدِ بْنِ غَفَلَةَ', 'സുവൈദുബ്നു ഗഫല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 190, 190, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ كَتَبَ لَهُ الَّتِي أَمَرَ اللَّهُ رَسُولَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَا يُخْرَجُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلَا ذَاتُ عَوَارٍ، وَلَا تَيْسٌ، إِلَّا مَا شَاءَ الْمُصَدِّقُ. (خ)', 'അനസ്(റ): അല്ലാഹു തന്റെ പ്രവാചകർ(സ)യോട് കൽപ്പിച്ച കാര്യം അബൂബക്കർ(റ) അദ്ദേഹത്തിന് എഴുതിക്കൊടുത്തു. അതിൽ ഇപ്രകാരമുണ്ട്: പിരിവുകാരൻ ഉദ്ദേശിച്ചാലല്ലാതെ വാർദ്ധക്യമുള്ളതിനെയോ, മോശപ്പെട്ടതിനെയോ, മോട്ടുകാണിക്കുന്നതിനെയോ, സകാത്തിൽ പിടിക്കപ്പെടരുത്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 190, 190, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنِ ابْنِ عَبَّاسٍ رَضِي اللَّهُ عَنْهُمَا حَدِيثَ بَعْثِ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ إِلَى الْيَمَنِ تَقَدَّمَ، وَفِي هَذِهِ الرِّوَايَةِ: قَالَ: "إِنَّكَ تَقْدَمُ عَلَى قَوْمٍ أَهْلِ كِتَابٍ...". وَذَكَرَ بَاقِيَ الحَدِيثِ، ثُمَّ قَالَ فِي آخِرِهِ: وَتَوَقَّ كَرَائِمَ أَمْوَالِ النَّاسِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മുആദ്(റ)വിനെ യമനിലേക്കയച്ച സംഭവം മുന്നെ പറഞ്ഞു. ഈ നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: റസൂൽ(സ) പറഞ്ഞു: "നീ വേദക്കാരിലേക്കാണ് പോകുന്നത്....." ശേഷം ബാക്കി ഭാഗം പറഞ്ഞു. അവസാനം പറഞ്ഞു: "ജനങ്ങളുടെ വിലപിടിപ്പുള്ള സമ്പത്ത് നീ സൂക്ഷിക്കുക." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 190, 190, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سِرْتُ - أَوْ قَالَ: أَخْبَرَنِي مَنْ سَارَ - مَعَ مُصَدِّقِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنْ لَا تَأْخُذَ مِنْ رَاضِعِ لَبَنٍ، وَلَا تَجْمَعَ بَيْنَ مُفْتَرِقٍ، وَلَا تُفَرِّقَ بَيْنَ مُجْتَمِعٍ". وَكَانَ إِنَّمَا يَأْتِي الْمِيَاهَ حِينَ تَرِدُ الْغَنَمُ، فَيَقُولُ: أَدُّوا صَدَقَاتِ أَمْوَالِكُمْ، قَالَ: فَعَمَدَ رَجُلٌ مِنْهُمْ إِلَى نَاقَةٍ كَوْمَاءَ، قَالَ: عَظِيمَةُ السَّنَامِ - قَالَ: فَأَبَى أَنْ يَقْبَلَهَا، قَالَ: إِنِّي أُحِبُّ أَنْ تَأْخُذَ خَيْرَ إِبِلِي، قَالَ: فَأَبَى أَنْ يَقْبَلَهَا، قَالَ: فَخَطَمَ لَهُ أُخْرَى دُونَهَا، فَأَبَى أَنْ يَقْبَلَهَا، ثُمَّ خَطَمَ لَهُ أُخْرَى دُونَهَا فَقَبِلَهَا، وَقَالَ: إِنِّي آخِذُهَا وَأَخَافُ أَنْ يَجِدَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ لِي: عَمَدْتَ إِلَى رَجُلٍ فَتَخَيَّرْتَ عَلَيْهِ إِبِلَهُ. وَفِي رِوَايَةٍ قَالَ: أَتَانَا مُصَدِّقُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذْتُ بِيَدِهِ، وَقَرَأْتُ فِي عَهْدِهِ: "لَا يُجْمَعُ بَيْنَ مُفْتَرِقٍ وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، خَشْيَةَ الصَّدَقَةِ". وَلَمْ يَذْكُرْ: "رَاضِعَ لَبَنٍ". (د,ن,جه)', 'സുവൈദ് ബിൻ ഗഫല(റ): ഞാൻ നബി(സ)യുടെ സകാത്ത് പിരിവുകാരനോടു കൂടെ സഞ്ചരിച്ചു. -അല്ലെങ്കിൽ അദ്ദേഹം പറഞ്ഞത്, പിരിവുകാരനോടു കൂടെ പോയ വ്യക്തി എന്നോട് പറഞ്ഞുവെന്നാണ് - അപ്പോൾ റസൂൽ(സ)യുടെ കരാർപത്രത്തിലുണ്ട്: "നീ മുല കുടിക്കുന്ന ഒട്ടകത്തെ എടുക്കരുത്, നീ വിഭിന്നമായതിനെ ഒരുമിച്ചു കൂട്ടരുത്, കൂട്ടത്തെ വിഭജിക്കരുത്." ജലാശയങ്ങളുടെ അടുത്തേക്ക് ആടുകൾ വരുമ്പോൾ അദ്ദേഹം അവിടെ ചെന്ന് പറയും: നിങ്ങളുടെ സമ്പത്തിലെ സകാത്ത് വീട്ടുക. അങ്ങനെ ഉയർന്ന പൂഞ്ഞയുള്ളൊരു ഒട്ടകവുമായി വന്നു. പക്ഷേ, അദ്ദേഹമത് സ്വീകരിക്കാൻ വിസമ്മതിച്ചു. ആ ഉടമസഥൻ പറഞ്ഞു: എന്റെ ഒട്ടകങ്ങളിൽ ഏറ്റവും നല്ല ഒട്ടകത്തെ നീ എടുക്കാൻ ഞാൻ താൽപര്യപ്പെടുന്നു. പക്ഷേ, അദ്ദേഹം സ്വീകരിക്കാൻ വിസമ്മതിച്ചു. പിന്നെ മറ്റൊന്നിനെ മൂക്കയർ പിടിച്ച് കൊടുത്തു. അതും സ്വീകരിക്കാൻ തയ്യാറായില്ല. പിന്നെ അതുമല്ലാത്ത വേറൊന്നിന് മൂക്കയർ പിടിച്ചു. അതിനെയദ്ദേഹം സ്വീകരിച്ചു. എന്നിട്ട് പറഞ്ഞു: നിശ്ചയമായും ഞാനിത് എടുക്കുന്നു. നീ ഒരാളുടെ അടുത്ത് ചെന്ന് അയാളുടെ ഏറ്റവും നല്ല ഒട്ടകമെടുത്തുവല്ലേ എന്ന് പറഞ്ഞ് റസൂൽ(സ) എന്നോട് ദേഷ്യപ്പെടുമോ എന്ന് ഞാൻ ഭയപ്പെടുന്നു. മറ്റൊരു നിവേദനത്തിൽ: നബി(സ)യുടെ സകാത്ത് പിരിവുകാരൻ ഞങ്ങളുടെയടുത്ത് വന്നു. അന്നേരം ഞാനദ്ദേഹത്തിന്റെ കൈ പിടിച്ചു. അദ്ദേഹത്തിന്റെ കരാറിൽ ഞാൻ വായിച്ചു. "സകാത്ത് വിഭിന്നമായത് ഒരുമിച്ച് കൂട്ടപ്പെടുകയോ, കൂട്ടം വിഭജിക്കപ്പെടുകയോ ഇല്ല." മുല കൊടുക്കുന്നത് എന്ന് പറഞ്ഞിട്ടില്ല. (ദ,ന,ജ)', 'سُوَيْدِ بْنِ غَفَلَةَ', 'സുവൈദ് ബിൻ ഗഫല(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 190, 191, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=131), 1, 'وَفِي رِوَايَةٍ قَالَ: أَتَانَا مُصَدِّقُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذْتُ بِيَدِهِ، وَقَرَأْتُ فِي عَهْدِهِ: "لَا يُجْمَعُ بَيْنَ مُفْتَرِقٍ وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، خَشْيَةَ الصَّدَقَةِ". وَلَمْ يَذْكُرْ: "رَاضِعَ لَبَنٍ". (د,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: നബി(സ)യുടെ സകാത്ത് പിരിവുകാരൻ ഞങ്ങളുടെയടുത്ത് വന്നു. അന്നേരം ഞാനദ്ദേഹത്തിന്റെ കൈ പിടിച്ചു. അദ്ദേഹത്തിന്റെ കരാറിൽ ഞാൻ വായിച്ചു. "സകാത്ത് വിഭിന്നമായത് ഒരുമിച്ച് കൂട്ടപ്പെടുകയോ, കൂട്ടം വിഭജിക്കപ്പെടുകയോ ഇല്ല." മുല കൊടുക്കുന്നത് എന്ന് പറഞ്ഞിട്ടില്ല. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنِ ابْنِ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَعْمَلَنِي عُمَرُ رَضِيَ اللهُ عَنْهُ عَلَى الصَّدَقَةِ، فَلَمَّا فَرَغْتُ مِنْهَا وَأَدَّيْتُهَا إِلَيْهِ أَمَرَ لِي بِعُمَالَةٍ، فَقُلْتُ: إِنَّمَا عَمِلْتُ لِلَّهِ، وَأَجْرِي عَلَى اللهِ. قَالَ: خُذْ مَا أُعْطِيتَ، فَإِنِّي قَدْ عَمِلْتُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَعَمَّلَنِي، فَقُلْتُ مِثْلَ قَوْلِكَ، فَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أُعْطِيتَ شَيْئًا مِنْ غَيْرِ أَنْ تَسْأَلَهُ فَكُلْ وَتَصَدَّقْ". (ق,د,ن)', 'ഇബ്നുസ്സാഇദീ(റ): ഉമർ(റ) സകാത്ത് പിരിക്കാൻ എന്നെ ഏൽപ്പിച്ചു. അങ്ങനെ പിരിച്ച് കഴിഞ്ഞ് എല്ലാം ഉമർ(റ)വിനെ ഏൽപ്പിച്ചപ്പോൾ അതിനുള്ള കൂലി എടുക്കാനെന്നോട് പറഞ്ഞു. ഞാൻ പറഞ്ഞു: ഞാൻ അല്ലാഹുവിന് വേണ്ടിയാണ് പണിയെടുത്തത്. എന്റെ കൂലി അല്ലാഹുവിന്റെ അടുത്താണ്. ഉമർ(റ) പറഞ്ഞു: നിനക്ക് നൽകപ്പെട്ടത് നീ എടുക്കുക, കാരണം റസൂൽ(സ)യുടെ കാലത്ത് ഞാൻ പിരിവുകാരനായി പ്രവർത്തിച്ചു. എന്നോട് കൂലിയെടുക്കാൻ പറഞ്ഞപ്പോൾ നീ പറഞ്ഞ പോലെ ഞാൻ പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ ചോദിക്കാതെ വല്ലതും നിനക്ക് ലഭിച്ചാൽ അതിൽ നിന്ന് നീ തിന്നുകയും സദഖ ചെയ്യുകയും ചെയ്യുക." (ബു,മു,ദ,ന)', 'ابْنِ السَّاعِدِيِّ', 'ഇബ്നുസ്സാഇദീ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 191, 191, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ مُسْلِمِ بْنِ ثَفِنَةَ الْيَشْكُرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَعْمَلَ نَافِعُ بْنُ عَلْقَمَةَ أَبِي عَلَى عِرَافَةِ قَوْمِهِ، فَأَمَرَهُ أَنْ يُصَدِّقَهُمْ، قَالَ: فَبَعَثَنِي أَبِي فِي طَائِفَةٍ مِنْهُمْ فَأَتَيْتُ شَيْخًا كَبِيرًا يُقَالُ لَهُ سِعْرُ بْنُ دَيْسَمَ، فَقُلْتُ: إِنَّ أَبِي بَعَثَنِي إِلَيْكَ، يَعْنِي لِأُصَدِّقَكَ. قَالَ: ابْنَ أَخِي، وَأَيَّ نَحْوٍ تَأْخُذُونَ؟ قُلْتُ: نَخْتَارُ حَتَّى إِنَّا نَتَبَيَّنُ ضُرُوعَ الْغَنَمِ، قَالَ: ابْنَ أَخِي، فَإِنِّي أُحَدِّثُكَ: أَنِّي كُنْتُ فِي شِعْبٍ مِنْ هَذِهِ الشِّعَابِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَنَمٍ لِي، فَجَاءَنِي رَجُلَانِ عَلَى بَعِيرٍ، فَقَالَا لِي: إِنَّا رَسُولَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْكَ لِتُؤَدِّيَ صَدَقَةَ غَنَمِكَ. فَقُلْتُ: مَا عَلَيَّ فِيهَا؟ فَقَالَا: شَاةٌ. فَأَعْمَدُ إِلَى شَاةٍ قَدْ عَرَفْتُ مَكَانَهَا، مُمْتَلِئَةٍ مَحْضًا وَشَحْمًا، فَأَخْرَجْتُهَا إِلَيْهِمَا، فَقَالَا: هَذِهِ شَاةُ الشَّافِعِ، وَقَدْ نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَأْخُذَ شَافِعًا – وَفِي رِوَايَةٍ: وَالشَّافِعُ الَّتِي فِي بَطْنِهَا الْوَلَدُ – قُلْتُ: فَأَيَّ شَيْءٍ تَأْخُذَانِ؟ قَالَا: عَنَاقًا جَذَعَةً أَوْ ثَنِيَّةً، قَالَ: فَأَعْمَدُ إِلَى عَنَاقٍ مُعْتَاطٍ – وَالْمُعْتَاطُ: الَّتِي لَمْ تَلِدْ وَلَدًا، وَقَدْ حَانَ وِلَادُهَا – فَأَخْرَجْتُهَا إِلَيْهِمَا، فَقَالَا: نَاوِلْنَاهَا، فَجَعَلَاهَا مَعَهُمَا عَلَى بَعِيرِهِمَا، ثُمَّ انْطَلَقَا. (د,ن)', 'മുസ്‌ലിമുബ്നു സഫ്നതിൽ യശ്കുരീ(റ): നാഫിഉബ്നു അൽഖമ(റ) എന്റെ പിതാവിനെ തന്റെ നാട്ടുകാരുടെ കാര്യങ്ങൾ നോക്കി നടത്താനേൽപ്പിച്ചു. അങ്ങനെ എന്റെ പിതാവിനോട് സകാത്ത് പിരിക്കാനേൽപ്പിച്ചു. മുസ്‌ലിം(റ) പറയുന്നു: എന്റെ പിതാവ് എന്നെ കുറച്ചാളുകളോട് കൂടെ അയച്ചു. അങ്ങനെ ഞാൻ വയസ്സായ ഒരു മനുഷ്യന്റെ അടുത്ത് ചെന്നു. ''സിഅ്റുബ്നു ദൈസം'' എന്നാണയാളുടെ പേര്. ഞാൻ പറഞ്ഞു: എന്റെ പിതാവാണ് എന്നെ നിങ്ങളുടെ അടുത്തേക്ക് അയച്ചത്. അതായത് നിങ്ങളിൽ നിന്നും സകാത്ത് പിരിക്കാൻ വേണ്ടി. അയാൾ ചോദിച്ചു: സഹോദര പുത്രാ, ഏത് തരത്തിലുള്ളതാണ് നിങ്ങളെടുക്കുക? ഞാൻ പറഞ്ഞു: ആടിന്റെ അകിടുകൾ കണക്കാക്കി ഞങ്ങൾ തെരഞ്ഞെടുക്കും. അയാൾ പറഞ്ഞു: സഹോദര പുത്രാ, ഞാൻ നിന്നോട് പറഞ്ഞ് തരാം. റസൂൽ(സ)യുടെ കാലത്ത് എന്റെ ആടുകളുമായി ഈ താഴ്വരകളിലൊരു താഴ്വരയിലായിരുന്നു ഞാനുണ്ടായിരുന്നത്. അങ്ങനെ ഒരു ഒട്ടകത്തിന്മേൽ രണ്ടാളുകൾ എന്റെ അടുത്ത് വന്ന് പറഞ്ഞു: നിങ്ങളുടെ ആടുകളിലുള്ള സകാത്ത് ഏൽപിക്കാൻ റസൂൽ(സ) നിങ്ങളിലേക്ക് നിയോഗിച്ച രണ്ട് ദൂതൻമാരാണ് ഞങ്ങൾ. ഞാൻ ചോദിച്ചു: എനിക്ക് നിർബന്ധമായ തോത് എത്രയാണ്? അവർ പറഞ്ഞു: ഒരാട്. അങ്ങനെ പാലും നെയ്യും നിറഞ്ഞ ഒരാടിനെ എടുക്കാൻ ഞാൻ പോയി. അതെവിടെയാണെന്ന് എനിക്ക് അറിയാമായിരുന്നു. അതിനെയെടുത്ത് ഞാനവർക്ക് കൊടുത്തു. അവർ പറഞ്ഞു: ഇത് ഗർഭമുള്ള ആടാണ്. റസൂൽ(സ) ഗർഭമുള്ളതിനെ എടുക്കൽ നിരോധിച്ചിട്ടുണ്ട്. ഒരു നിവേദനം: ശാഫിഅ് എന്നാൽ വയറ്റിൽ കുട്ടിയുള്ളതാണ്. ഞാൻ ചോദിച്ചു: പിന്നെ ഏതിനെയാണ് നിങ്ങളെടുക്കുക? അവർ പറഞ്ഞു: രണ്ടോ മൂന്നോ വയസ്സുള്ള പെണ്ണാട്. അങ്ങനെ പ്രസവിക്കാനടുത്ത ഒരു പെണ്ണാടിനെയെടുത്ത് അവർക്ക് കൊടുത്തു. മുഅ്താഥ് എന്നാൽ പ്രസവിച്ചിട്ടില്ലാത്തതും എന്നാൽ പ്രസവമടുത്തതുമാണ്. അവർ പറഞ്ഞു: അതിനെ ഞങ്ങൾക്ക് നൽകുക. അങ്ങനെ അവരതിനെ അവരുടെ ഒട്ടകത്തിൽ വെച്ച് പോവുകയും ചെയ്തു. (ദ,ന)', 'مُسْلِمِ بْنِ ثَفِنَةَ الْيَشْكُرِيِّ', 'മുസ്‌ലിമുബ്നു സഫ്നതിൽ യശ്കുരീ(റ)', 'قَالَ أَبُو دَاود: أَنَّهُ قَرَأَ فِي كِتَاب: عَنْ عَبْدِ اللَّهِ بْنِ مُعَاوِيَةَ الْغَاضِرِيِّ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ مَنْ فَعَلَهُنَّ فَقَدْ طَعِمَ طَعْمَ الْإِيمَانِ: مَنْ عَبَدَ اللَّهَ وَحْدَهُ، وَأَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ، وَأَعْطَى زَكَاةَ مَالِهِ طَيِّبَةً بِهَا نَفْسُهُ رَافِدَةً عَلَيْهِ كُلَّ عَامٍ، وَلَا يُعْطِي الْهَرِمَةَ، وَلَا الدَّرِنَةَ، وَلَا الْمَرِيضَةَ، وَلَا الشَّرَطَ اللَّئِيمَةَ، وَلَكِنْ مِنْ وَسَطِ أَمْوَالِكُمْ، فَإِنَّ اللَّهَ لَمْ يَسْأَلْكُمْ خَيْرَهُ، وَلَمْ يَأْمُرْكُمْ بِشَرِّهِ". (د)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=133), 1, 'وَفِي رِوَايَةٍ: وَالشَّافِعُ الَّتِي فِي بَطْنِهَا الْوَلَدُ – قُلْتُ: فَأَيَّ شَيْءٍ تَأْخُذَانِ؟ قَالَا: عَنَاقًا جَذَعَةً أَوْ ثَنِيَّةً، قَالَ: فَأَعْمَدُ إِلَى عَنَاقٍ مُعْتَاطٍ – وَالْمُعْتَاطُ: الَّتِي لَمْ تَلِدْ وَلَدًا، وَقَدْ حَانَ وِلَادُهَا – فَأَخْرَجْتُهَا إِلَيْهِمَا، فَقَالَا: نَاوِلْنَاهَا، فَجَعَلَاهَا مَعَهُمَا عَلَى بَعِيرِهِمَا، ثُمَّ انْطَلَقَا. (د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُصَدِّقًا، فَمَرَرْتُ بِرَجُلٍ، فَلَمَّا جَمَعَ لِي مَالَهُ لَمْ أَجِدْ عَلَيْهِ فِيهِ إِلَّا ابْنَةَ مَخَاضٍ، فَقُلْتُ لَهُ: أَدِّ ابْنَةَ مَخَاضٍ فَإِنَّهَا صَدَقَتُكَ. فَقَالَ: ذَاكَ مَا لَا لَبَنَ فِيهِ وَلَا ظَهْرَ، وَلَكِنْ هَذِهِ نَاقَةٌ فَتِيَّةٌ عَظِيمَةٌ سَمِينَةٌ فَخُذْهَا. فَقُلْتُ لَهُ: مَا أَنَا بِآخِذٍ مَا لَمْ أُومَرْ بِهِ، وَهَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْكَ قَرِيبٌ، فَإِنْ أَحْبَبْتَ أَنْ تَأْتِيَهُ فَتَعْرِضَ عَلَيْهِ مَا عَرَضْتَ عَلَيَّ فَافْعَلْ، فَإِنْ قَبِلَهُ مِنْكَ قَبِلْتُهُ، وَإِنْ رَدَّهُ عَلَيْكَ رَدَدْتُهُ. قَالَ: فَإِنِّي فَاعِلٌ، فَخَرَجَ مَعِي، وَخَرَجَ بِالنَّاقَةِ الَّتِي عَرَضَ عَلَيَّ حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: يَا نَبِيَّ اللَّهِ، أَتَانِي رَسُولُكَ لِيَأْخُذَ مِنِّي صَدَقَةَ مَالِي وَايْمُ اللَّهِ، مَا قَامَ فِي مَالِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا رَسُولُهُ قَطُّ قَبْلَهُ، فَجَمَعْتُ لَهُ مَالِي فَزَعَمَ أَنَّ مَا عَلَيَّ فِيهِ ابْنَةُ مَخَاضٍ، وَذَلِكَ مَا لَا لَبَنَ فِيهِ وَلَا ظَهْرَ، وَقَدْ عَرَضْتُ عَلَيْهِ نَاقَةً فَتِيَّةً عَظِيمَةً لِيَأْخُذَهَا فَأَبَى عَلَيَّ، وَهَا هِيَ ذِهْ، قَدْ جِئْتُكَ بِهَا يَا رَسُولَ اللَّهِ، خُذْهَا. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَاكَ الَّذِي عَلَيْكَ، فَإِنْ تَطَوَّعْتَ بِخَيْرٍ آجَرَكَ اللَّهُ فِيهِ، وَقَبِلْنَاهُ مِنْكَ". قَالَ: فَهَا هِيَ ذِهْ يَا رَسُولَ اللَّهِ، قَدْ جِئْتُكَ بِهَا فَخُذْهَا. قَالَ: فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَبْضِهَا وَدَعَا لَهُ فِي مَالِهِ بِالْبَرَكَةِ. (د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) എന്നെ സകാത്ത് പിരിവുകാരനായി അയച്ചു. അങ്ങനെ ഞാനൊരാളുടെ അടുത്ത് ചെന്നു. അദ്ദേഹം തന്റെ സമ്പത്ത് ഒരുമിച്ചുകൂട്ടിയപ്പോൾ അതിൽ അയാൾക്ക് സകാതായിട്ടുള്ളത് ''ബിൻതു മഖാളി''നെയല്ലാതെ ഞാൻ കണ്ടില്ല. (സകാത്ത് നൽകേണ്ടത് ബിൻത് മഖാളിനെയാണ്.) ഞാനയാളോട് പറഞ്ഞു: നീ ബിൻത് മഖാളി(ഒരു വയസ്സായ പെണ്ണൊട്ടകം)നെ നൽകുക, കാരണം അതാണ് നിന്റെ സകാത്ത്. അയാൾ പറഞ്ഞു: അത് പാലും തടിയുമില്ലാത്തതാണ്. പക്ഷേ, ഇത് യുവപ്രായമായ നല്ല തടിയുള്ള വലിയ ഒട്ടകമാണ്, ഇതെടുക്കുക. അപ്പോൾ ഞാൻ പറഞ്ഞു: കൽപ്പിക്കപ്പെടാത്തത് ഞാനെടുക്കില്ല. റസൂൽ(സ) നിന്നോടടുത്ത് തന്നെയാണുള്ളത്. റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് എന്നോട് പറഞ്ഞതൊക്കെ അവിടത്തോട് പറയാൻ നീ ഇഷ്ടപ്പെടുന്നുവെങ്കിൽ നീ അത് ചെയ്യുക. അങ്ങനെ റസൂൽ(സ) സ്വീകരിക്കുകയാണെങ്കിൽ ഞാൻ സ്വീകരിക്കാം, നിനക്ക് തിരിച്ചു നൽകുകയാണെങ്കിൽ, ഞാൻ തിരിച്ചു തരും. അയാൾ പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്യാം. അങ്ങനെ, അദ്ദേഹം എന്റെ കൂടെ വന്നു. എനിക്ക് കാണിച്ച് തന്ന ഒട്ടകവുമായി റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. അയാൾ നബി(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, എന്റെ സമ്പത്തിലെ സകാത്ത് എടുക്കാൻ വേണ്ടി അങ്ങയുടെ ദൂതൻ എന്റെ അടുത്തേക്ക് വന്നു. അല്ലാഹുവിനെ തന്നെയാണ് സത്യം! എന്റെ സമ്പത്തിന്റെ വിഷയത്തിൽ അദ്ദേഹത്തിന് മുമ്പ് ഇന്ന് വരെ, അല്ലാഹുവിന്റെ റസൂൽ(സ)യോ അവിടത്തെ ദൂതനോ നിന്നിട്ടില്ല. അദ്ദേഹം എന്റെ സമ്പത്ത് ഒരുമിച്ച് കൂട്ടി അതിൽ എന്റെ മേൽ നിർബന്ധമായത് ബിൻത് മഖാള് ആണെന്ന് എന്നോട് പറഞ്ഞു. അതാണെങ്കിൽ തടി കുറഞ്ഞതും പാലില്ലാത്തതുമാണ്. അങ്ങനെ യുവ പ്രായമായ നല്ല തടിച്ച വലിയ ഒട്ടകത്തെ ഞാൻ അദ്ദേഹത്തിന് കാണിച്ച് കൊടുത്ത് അതെടുക്കാൻ പറഞ്ഞു. പക്ഷേ, അദ്ദേഹം വിസമ്മതിച്ചു. ആ ഒട്ടകമിതാ. റസൂലേ, ഞാനതിനെ കൊണ്ടു വന്നിരിക്കുന്നു. അങ്ങ് അതെടുക്കുക. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "അതാണ് നിനക്ക് നിർബന്ധമായത്. നീ ഏറ്റവും നല്ലതിനെ കൊടുക്കുന്നുവെങ്കിൽ അല്ലാഹു അതു കാരണം നിനക്ക് പ്രതിഫലം നൽകും. നിന്നിൽ നിന്ന് നാം അത് സ്വീകരിച്ചിരിക്കുന്നു." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അത് ഇതാ ഇവിടെ, അങ്ങേക്ക് വേണ്ടി ഞാൻ കൊണ്ട് വന്നിരിക്കുന്നു, അങ്ങ് അതെടുക്കുക. അങ്ങനെ റസൂൽ(സ) അതിനെ എടുക്കാൻ കൽപിക്കുകയും, അദ്ദേഹത്തിന്റെ സമ്പത്തിൽ ബർക്കത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്തു. (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 193, 193, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَاعِيًا، فَأَتَى رَجُلًا فَآتَاهُ فَصِيلًا مَخْلُولًا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَعَثْنَا مُصَدِّقَ اللَّهِ وَرَسُولِهِ، وَإِنَّ فُلَانًا أَعْطَاهُ فَصِيلًا مَخْلُولًا. اللَّهُمَّ لَا تُبَارِكْ فِيهِ وَلَا فِي إِبِلِهِ". فَبَلَغَ ذَلِكَ الرَّجُلَ فَجَاءَ بِنَاقَةٍ حَسْنَاءَ، فَقَالَ: أَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ وَإِلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ بَارِكْ فِيهِ وَفِي إِبِلِهِ". (ن)', 'വാഇലുബ്നു ഹുജ്ർ(റ): നബി(സ) തങ്ങൾ സകാത്ത് പിരിവുകാരനെ നിയോഗിച്ചു. അങ്ങനെ ഒരാളുടെ അടുത്ത് ചെന്നപ്പോൾ അയാൾ കൊടുത്തത് മെലിഞ്ഞ ഒരു വയസ്സനായ ഒട്ടകക്കുട്ടിയെയാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നാം അല്ലാഹുവിന്റെയും അവന്റെ തിരുദൂതരുടെയും പിരിവുകാരനെ അയച്ചപ്പോൾ ഇന്ന വ്യക്തി, പിരിവുകാരന് നൽകിയത് മെലിഞ്ഞൊട്ടിയ ഒട്ടകക്കുട്ടിയെയാണ്. അല്ലാഹുവേ, അവനിലും അവന്റെ ഒട്ടകത്തിലും നീ ബർകത്ത് ചെയ്യരുത്." ഈ വാർത്ത അയാളുടെ അടുത്തെത്തി, അയാൾ നല്ലൊരൊട്ടകവുമായി വന്ന് പറഞ്ഞു: അല്ലാഹുവിനോടും അവന്റെ തിരദൂതരോടും ഞാൻ തൗബ ചെയ്യുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അവനിലും അവന്റെ ഒട്ടകത്തിലും നീ ബർക്കത്ത് ചെയ്യേണമേ." (ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَرْجِعُ الْمُصَدِّقُ إِلَّا عَنْ رِضًا". (م,ت,ن,جه)', 'ജരീറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "പിരിവുകാരൻ സംതൃപ്തിയോടെയല്ലാതെ മടങ്ങരുത്." (മു,തു,ന,ജ)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَبْدِ اللَّهِ بْنِ هِلَالٍ الثَّقَفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كِدْتُ أُقْتَلُ بَعْدَكَ فِي عَنَاقٍ – أَوْ شَاةٍ – مِنَ الصَّدَقَةِ. فَقَالَ: "لَوْلَا أَنَّهَا تُعْطَى فُقَرَاءَ الْمُهَاجِرِينَ مَا أَخَذْتُهَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഹിലാലിസ്സഖഫീ(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അങ്ങേക്ക് ശേഷം സകാത്തിൽ നിന്നുള്ള ഒരു ഒട്ടകത്തിന്റെ – അല്ലെങ്കിൽ ആടിന്റെ– വിഷയത്തിൽ ഞാൻ കൊല്ലപ്പെടാനടുത്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മുഹാജിരീങ്ങളിലെ പാവപ്പെട്ടവർക്കത് നൽകപ്പെടുന്നില്ലെങ്കിൽ ഞാനത് സ്വീകരിക്കുകയില്ല." (ന)', 'عَبْدِ اللَّهِ بْنِ هِلَالٍ الثَّقَفِيِّ', 'അബ്ദുല്ലാഹിബ്നു ഹിലാലിസ്സഖഫീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَعْمَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مِنَ الْأَسْدِ عَلَى صَدَقَاتِ بَنِي سُلَيْمٍ يُدْعَى ابْنُ اللُّتْبِيَّةِ، فَلَمَّا جَاءَ حَاسَبَهُ. (خ)', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ): റസൂൽ(സ) ബനൂസുലൈമുകാരിൽ നിന്ന് സകാത്ത് പിരിക്കാൻ ഇബ്നുലത്ബിയ്യ എന്ന് വിളിക്കപ്പെടുന്ന ഒരു അസദ് ഗോത്രക്കാരനെ ഏൽപിച്ചു. അങ്ങനെ അയാൾ വന്നപ്പോൾ റസൂൽ(സ) അയാളെ വിചാരണ ചെയ്തു. (ബു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ بَشِيرِ بْنِ الْخَصَاصِيَّةِ رَضِيَ اللَّهُ عَنْهُ – وَمَا كَانَ اسْمُهُ بَشِيرًا، وَلَكِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمَّاهُ بَشِيرًا – قَالَ: قُلْنَا: إِنَّ أَهْلَ الصَّدَقَةِ يَعْتَدُونَ عَلَيْنَا، أَفَنَكْتُمُ مِنْ أَمْوَالِنَا بِقَدْرِ مَا يَعْتَدُونَ عَلَيْنَا؟ فَقَالَ: "لَا". وَفِي رِوَايَةٍ: قُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ أَصْحَابَ الصَّدَقَةِ يَعْتَدُونَ. (د)', 'ബശീറുബ്നു ഖസ്വാസിയ്യ(റ): അദ്ദേഹത്തിന്റെ പേര് ''ബശീർ'' എന്നായിരുന്നില്ല. പക്ഷേ, റസൂൽ(സ) അദ്ദേഹത്തെ ബശീർ എന്ന് വിളിച്ചു. നിവേദകൻ: ഞങ്ങൾ (റസൂൽ(സ)യോട്) പറഞ്ഞു: പിരിവുകാർ ഞങ്ങളോട് അതിക്രമം കാണിക്കുന്നു. അവർ അതിക്രമം കാണിക്കുന്നതിന്റെ തോത് ഞങ്ങളുടെ സമ്പത്തിൽ നിന്നും ഞങ്ങൾ മറച്ചു വെക്കണോ? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട" മറ്റൊരു നിവേദനം: ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സകാത്തിന്റെ ആളുകൾ അതിക്രമം പ്രവർത്തിക്കുന്നു. (ദ)', 'بَشِيرِ بْنِ الْخَصَاصِيَّةِ', 'ബശീറുബ്നു ഖസ്വാസിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 194, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=139), 1, 'وَفِي رِوَايَةٍ: قُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ أَصْحَابَ الصَّدَقَةِ يَعْتَدُونَ. (د)', 'മറ്റൊരു നിവേദനം: ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സകാത്തിന്റെ ആളുകൾ അതിക്രമം പ്രവർത്തിക്കുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ جَابِرِ بْنِ عَتِيكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَيَأْتِيكُمْ رُكَيْبٌ مُبْغَضُونَ، فَإِنْ جَاءُوكُمْ فَرَحِّبُوا بِهِمْ، وَخَلُّوا بَيْنَهُمْ وَبَيْنَ مَا يَبْتَغُونَ، فَإِنْ عَدَلُوا فَلِأَنْفُسِهِمْ، وَإِنْ ظَلَمُوا فَعَلَيْهَا، وَأَرْضُوهُمْ، فَإِنَّ تَمَامَ زَكَاتِكُمْ رِضَاهُمْ، وَلْيَدْعُوا لَكُمْ". (د)', 'ജാബിറുബ്നു അതീക്(റ): റസൂൽ(സ) പറഞ്ഞു: "പെട്ടെന്ന് ദേഷ്യപ്പെടുന്ന (പ്രകൃതമുള്ള) ചെറിയ സംഘം നിങ്ങളുടെ അടുത്തേക്ക് വരും. അവർ നിങ്ങളുടെ അടുത്തേക്ക് വരുമ്പോൾ അവരെ നിങ്ങൾ സ്വാഗതം ചെയ്യുക. അവരെയും അവർ ആഗ്രഹിക്കുന്നതിനെയും നിങ്ങൾ വിട്ടേക്കുക. അവർ നീതി പാലിച്ചാൽ അതിന്റെ നന്മ അവർക്ക് തന്നെയാണ്, അവർ അതിക്രമം പ്രവർത്തിച്ചുവെങ്കിൽ, അതിന്റെ തിക്ത ഫലവും അവർക്ക് തന്നെ. നിങ്ങളവരെ തൃപ്തിപ്പെടുത്തുക. അവരുടെ തൃപ്തിയാണ് നിങ്ങളുടെ സകാത്തിന്റെ പൂർണ്ണത, നിങ്ങളവർക്കുവേണ്ടി പ്രാർത്ഥിക്കുക." (ദ)', 'جَابِرِ بْنِ عَتِيكٍ', 'ജാബിറുബ്നു അതീക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 195, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ نَاسٌ – يَعْنِي مِنَ الْأَعْرَابِ – إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: إِنَّ نَاسًا مِنَ الْمُصَدِّقِينَ يَأْتُونَا فَيَظْلِمُونَا، قَالَ: فَقَالَ: "أَرْضُوا مُصَدِّقِيكُمْ". قَالُوا: يَا رَسُولَ اللَّهِ، وَإِنْ ظَلَمُونَا؟ قَالَ: "أَرْضُوا مُصَدِّقِيكُمْ وَإِنْ ظُلِمْتُمْ". قَالَ جَرِيرٌ: مَا صَدَرَ عَنِّي مُصَدِّقٌ بَعْدَ مَا سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا وَهُوَ عَنِّي رَاضٍ. (م,د,ن)', 'ജരീറുബ്നു അബ്ദില്ല(റ): കുറച്ചാളുകൾ – അതായത് അഅ്റാബികളിൽ നിന്ന് ചിലർ – റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: പിരിവുകാരിൽ ചിലയാളുകൾ ഞങ്ങളുടെ അടുത്ത് വന്ന് ഞങ്ങളോട് അതിക്രമം കാണിക്കുന്നു. നിവേദകൻ: അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ സകാത്ത് പിരിവുകാരെ നിങ്ങൾ സംതൃപ്തരാക്കുക." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവർ ഞങ്ങളെ അക്രമിച്ചാലോ? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ പിരിവുകാരെ നിങ്ങൾ സംതൃപ്തിപ്പെടുത്തുക, നിങ്ങൾ അക്രമിക്കപ്പെട്ടാലും ശരി." ജരീർ(റ) പറഞ്ഞു: റസൂൽ(സ)യടുടെ പക്കൽ നിന്നും ഇത് കേട്ട ശേഷം ഒരു പിരിവുകാരനും എന്നിൽ നിന്ന് സംതൃപ്തനായിട്ടല്ലാതെ പിരിഞ്ഞ് പോയിട്ടില്ല. (മു,ദ,ന)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 195, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْعَامِلُ عَلَى الصَّدَقَةِ بِالْحَقِّ كَالْغَازِي فِي سَبِيلِ اللَّهِ، حَتَّى يَرْجِعَ إِلَى بَيْتِهِ". (د,ت,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: സത്യസന്ധതയോടെ സകാതിന് വേണ്ടി പ്രവർത്തിക്കുന്നവൻ, അവന്റെ വീട്ടിലേക്ക് മടങ്ങുന്നത് വരെ, അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്യുന്നവനെപ്പോലെയാണ്." (ദ,തു,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 195, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَاكُمُ الْمُصَدِّقُ فَلَا يُفَارِقَنَّكُمْ إِلَّا عَنْ رِضًا". (م,ت)', 'ജരീർ(റ): നബി(സ) പറഞ്ഞു: "പിരിവുകാരൻ നിങ്ങളുടെ അടുത്തേക്ക് വന്നാൽ സംതൃപ്തിയോടെയല്ലാതെ അവൻ നിങ്ങളെ പിരിഞ്ഞുപോകരുത്." (മു,തു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 195, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَاكُمُ الْمُصَدِّقُ فَلْيَصْدُرْ وَهُوَ عَنْكُمْ رَاضٍ". (ن)', 'ജരീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "പിരിവുകാരൻ നിങ്ങളുടെ അടുത്തേക്ക് വന്നാൽ സംതൃപ്തിയോടെ അവൻ നിങ്ങളിൽ നിന്ന് പിരിഞ്ഞ് പോകട്ടെ." (ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 195, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمُعْتَدِي فِي الصَّدَقَةِ كَمَانِعِهَا". (د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "സകാതിൽ അതിക്രമം കാണിക്കുന്നവൻ അത് നൽകാത്തവനെപ്പോലെയാണ്." (ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ تَذَاكَرَ هُوَ وَعُمَرُ بْنُ الْخَطَّابِ يَوْمًا الصَّدَقَةَ، فَقَالَ عُمَرُ: أَلَمْ تَسْمَعْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ يَذْكُرُ غُلُولَ الصَّدَقَةِ؟: "أَنَّهُ مَنْ غَلَّ مِنْهَا بَعِيرًا أَوْ شَاةً أُتِيَ بِهِ يَوْمَ الْقِيَامَةِ يَحْمِلُهُ". قَالَ: فَقَالَ عَبْدُ اللَّهِ بْنُ أُنَيْسٍ: بَلَى. (جه)', 'അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ): അദ്ദേഹവും ഉമറുബ്നുൽ ഖത്താബ്(റ)വും ചേർന്ന് ഒരു ദിവസം സകാതിനെ സംബന്ധിച്ച് പരസ്പരം ചർച്ച ചെയ്തു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: സകാതിനെ ഒളിപ്പിച്ച് വെക്കുന്നതിനെ സംബന്ധിച്ച് റസൂൽ(സ) പറയുന്നത് നീ കേട്ടിട്ടില്ലേ. "അതിൽ നിന്നാരെങ്കിലും ഒരൊട്ടകത്തെയോ ആടിനെയോ ഒളിപ്പിച്ച് വെച്ചാൽ, അന്ത്യനാളിൽ അതിനെ ചുമന്നവനായി അവൻ കൊണ്ടുവരപ്പെടുന്നതാണ്." നിവേദകൻ: അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ) പറഞ്ഞു: അതെ, (ഞാൻ കേട്ടിട്ടുണ്ട്) (ജ)', 'عَبْدِ اللَّهِ بْنِ أُنَيْسٍ', 'അബ്ദുല്ലാഹിബ്നു ഉനൈസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللَّهُ عَنْهُ: اسْتُعْمِلَ عَلَى الصَّدَقَةِ، فَلَمَّا رَجَعَ قِيلَ لَهُ: أَيْنَ الْمَالُ؟ قَالَ: وَلِلْمَالِ أَرْسَلْتَنِي؟ أَخَذْنَاهُ مِنْ حَيْثُ كُنَّا نَأْخُذُهُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَوَضَعْنَاهُ حَيْثُ كُنَّا نَضَعُهُ. (د,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): താൻ സകാത്ത് പിരിക്കാൻ ഏൽപിക്കപ്പെട്ടു. അദ്ദേഹം തിരിച്ച് വന്നപ്പോൾ ചോദിക്കപ്പെട്ടു: എവിടെയാണ് സമ്പത്ത്? അദ്ദേഹം ചോദിച്ചു: സമ്പത്തിന് വേണ്ടിയാണോ നീ എന്നെ അയച്ചത്? റസൂൽ(സ)യുടെ കാലത്ത് എടുക്കാറുണ്ടായിരുന്നതു പോലെ ഞങ്ങൾ എടുക്കുകയും വെക്കേണ്ടിടത്ത് വെക്കുകയും ചെയ്തിട്ടുണ്ട്. (ദ,ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ صَاحِبِ إِبِلٍ وَلَا بَقَرٍ وَلَا غَنَمٍ لَا يُؤَدِّي حَقَّهَا إِلَّا وُقِفَ لَهَا يَوْمَ الْقِيَامَةِ بِقَاعٍ قَرْقَرٍ، تَطَؤُهُ ذَاتُ الْأَظْلَافِ بِأَظْلَافِهَا وَتَنْطَحُهُ ذَاتُ الْقُرُونِ بِقُرُونِهَا، لَيْسَ فِيهَا يَوْمَئِذٍ جَمَّاءُ وَلَا مَكْسُورَةُ الْقَرْنِ". قُلْنَا: يَا رَسُولَ اللَّهِ، وَمَاذَا حَقُّهَا؟ قَالَ: "إِطْرَاقُ فَحْلِهَا وَإِعَارَةُ دَلْوِهَا وَحَمْلٌ عَلَيْهَا فِي سَبِيلِ اللَّهِ. وَلَا صَاحِبِ مَالٍ لَا يُؤَدِّي حَقَّهُ إِلَّا يُخَيَّلُ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعٌ أَقْرَعُ، يَفِرُّ مِنْهُ صَاحِبُهُ وَهُوَ يَتْبَعُهُ، يَقُولُ لَهُ: هَذَا كَنْزُكَ الَّذِي كُنْتَ تَبْخَلُ بِهِ، فَإِذَا رَأَى أَنَّهُ لَا بُدَّ لَهُ مِنْهُ أَدْخَلَ يَدَهُ فِي فِيهِ، فَجَعَلَ يَقْضَمُهَا كَمَا يَقْضَمُ الْفَحْلُ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ആടിന്റെയോ പശുവിന്റെയോ ഒട്ടകത്തിന്റെയോ ബാധ്യത തീർക്കാത്ത ഉടമസ്ഥൻ, അന്ത്യനാളിൽ വളരെ വിശാലമായ മൈതാനത്ത് അവക്ക് മുന്നിൽ നിറുത്തപ്പെടും. കുളമ്പുള്ളവ, അവയുടെ കുളമ്പുകൾ കൊണ്ട് അവനെ ചവിട്ടും. കൊമ്പുള്ളവ, അവനെ കൊമ്പുകൾ കൊണ്ട് കുത്തും, ആ ദിവസം ആ കൂട്ടത്തിൽ കൊമ്പില്ലാത്തതോ കൊമ്പ് പൊട്ടിയതോ ഉണ്ടാവുകയില്ല." ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണ് അവയുടെ ബാധ്യത? റസൂൽ(സ) പറഞ്ഞു: "അവയിലെ കൂറ്റനെ (ആണിനെ) ഇണചേരാൻ വേണ്ടി വായ്പ നൽകലും അവയുടെ വെള്ളം കുടിപ്പിക്കുന്ന തൊട്ടികൾ വായ്പ കൊടുക്കലും അല്ലാഹുവിന്റെ മാർഗത്തിൽ അതിന്മേൽ ചുമക്കലുമാണ്. സമ്പത്തിലെ ബാധ്യത തീർക്കാത്തവന് ഖിയാമത് നാളിൽ നല്ല വിഷമുള്ള വെളുത്ത തലയുള്ള പാമ്പിനെ ഏൽപിക്കപ്പെടുന്നതാണ്. അയാൾ അതിൽ നിന്നോടുമെങ്കിലും അത് അവനെ തുടർന്ന് കൊണ്ടിരിക്കും. അവനോട് പറയും: നീ പിശുക്ക് കാണിച്ചിരുന്ന ഖനിയാണിത്, ഒരു നിലക്കും രക്ഷപ്പെടില്ലെന്ന് മനസ്സിലായാൽ അതിന്റെ വായിൽ അവന്റെ കൈയിടും. അങ്ങനെ അത് അവന്റെ കൈ, നല്ല ശക്തിയുള്ളവൻ കടിച്ചു മുറിക്കും പോലെ കടിച്ചു മുറിച്ച് കൊണ്ടിരിക്കും." (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 196, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَأْتِي الْإِبِلُ عَلَى رَبِّهَا عَلَى خَيْرِ مَا كَانَتْ، إِذَا هِيَ لَمْ يُعْطِ فِيهَا حَقَّهَا، تَطَؤُهُ بِأَخْفَافِهَا. وَتَأْتِي الْغَنَمُ عَلَى رَبِّهَا عَلَى خَيْرِ مَا كَانَتْ، إِذَا لَمْ يُعْطِ فِيهَا حَقَّهَا، تَطَؤُهُ بِأَظْلَافِهَا وَتَنْطَحُهُ بِقُرُونِهَا، قَالَ: وَمِنْ حَقِّهَا أَنْ تُحْلَبَ عَلَى الْمَاءِ. أَلَا لَا يَأْتِيَنَّ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ بِبَعِيرٍ يَحْمِلُهُ عَلَى رَقَبَتِهِ لَهُ رُغَاءٌ، فَيَقُولُ: يَا مُحَمَّدُ، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ بَلَّغْتُ. أَلَا لَا يَأْتِيَنَّ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ بِشَاةٍ يَحْمِلُهَا عَلَى رَقَبَتِهِ لَهَا يُعَارٌ، فَيَقُولُ: يَا مُحَمَّدُ، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ بَلَّغْتُ. قَالَ: وَيَكُونُ كَنْزُ أَحَدِهِمْ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ، يَفِرُّ مِنْهُ صَاحِبُهُ وَيَطْلُبُهُ: أَنَا كَنْزُكَ، فَلَا يَزَالُ حَتَّى يُلْقِمَهُ أُصْبُعَهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബാധ്യത തീർക്കപ്പെടാത്ത ഒട്ടകം അതുണ്ടായിരുന്നതിലേറെ നല്ല രൂപത്തിൽ അതിന്റെ ഉടമസ്ഥനടുത്ത് വരും. അവനെ അവയുടെ കുളമ്പുകൾ കൊണ്ട് ചവിട്ടും. ബാധ്യത തീർക്കപ്പെടാത്ത ആട്, അതുണ്ടായിരുന്നതിലേറെ നല്ല രൂപത്തിൽ അതിന്റെ ഉടമസ്ഥനടുത്ത് വരും. കുളമ്പുകൾ കൊണ്ട് അവനെ ചവിട്ടുകയും കൊമ്പുകൾ കൊണ്ട് കുത്തുകയും ചെയ്യും." റസൂൽ(സ) പറഞ്ഞു: "വെള്ളത്തിനരികെ വെച്ച് പാൽ കറന്നെടുക്കപ്പെടൽ അതിന്റെ ബാധ്യതയിൽ പെട്ടതാണ്. അറിയുക, നിങ്ങളിൽ നിന്നൊരാളും ഖിയാമത്ത് നാളിൽ അവന്റെ ചുമലിൽ ഒച്ച വെക്കുന്ന ഒട്ടകവുമായി വരരുത്. എന്നിട്ടവൻ പറയും: മുഹമ്മദേ! അപ്പോൾ ഞാൻ പറയും: നിനക്ക് വേണ്ടി ഒന്നും എന്റെ കൈവശമില്ല, എല്ലാം ഞാനെത്തിച്ചു തന്നിട്ടുണ്ട്. അറിയുക, നിങ്ങളിൽ നിന്നൊരാളും ഖിയാമത്ത് നാളിൽ അവന്റെ ചുമലിൽ കരയുന്ന ആടുമായി വരരുത്. അവൻ വിളിക്കും: മുഹമ്മദേ! ഞാൻ പറയും: നിനക്ക് വേണ്ടി ഒന്നും എന്റെ കൈവശമില്ല, എല്ലാം ഞാനെത്തിച്ച് തന്നിട്ടുണ്ട്." റസൂൽ(സ) പറഞ്ഞു: "അവരിലൊരാളുടെ നിധി നല്ല വിഷമുള്ള വെള്ളത്തലയുള്ള പാമ്പായിരിക്കും, അതിന്റെ ഇരയാക്കപ്പെട്ടവൻ അതിൽ നിന്നും ഓടിക്കൊണ്ടിരിക്കും. പക്ഷേ, അത് അവനെ ഞാൻ നിന്റെ നിധിയാണെന്ന് പറഞ്ഞ് തേടിക്കൊണ്ടിരിക്കും, അവന്റെ വിരൽ വിഴുങ്ങുന്നത് വരെ അത് അവനെ പിന്തുടരും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 197, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "فِي كُلِّ إِبِلٍ سَائِمَةٍ فِي كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ، لَا يُفَرَّقُ إِبِلٌ عَنْ حِسَابِهَا. مَنْ أَعْطَاهَا مُؤْتَجِرًا فَلَهُ أَجْرُهَا، وَمَنْ أَبَى فَإِنَّا آخِذُوهَا وَشَطْرَ إِبِلِهِ، عَزْمَةٌ مِنْ عَزَمَاتِ رَبِّنَا، لَا يَحِلُّ لِآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا شَيْءٌ". (ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "മേയുന്ന ഒട്ടകത്തിൽ ഓരോ നാൽപ്പതിലും ഒരു ബിൻത് ലബൂൻ ആണ് (സകാത്ത്). ഒരു ഒട്ടകവും അതിന്റെ തോതിനെ തൊട്ട് വേർപെടുത്തപ്പെടുകയില്ല. ആരെങ്കിലും അതിനെ കൂലി പ്രതീക്ഷിച്ചവനായി നൽകിയാൽ അവന് അതിന്റെ കൂലിയുണ്ട്. ആരെങ്കിലും വിസമ്മതിച്ചാൽ, അതിനെയും അവന്റെ ഒട്ടകത്തിന്റെ പകുതിയും നാം എടുക്കുന്നതാണ്. അത് നമ്മുടെ റബ്ബിന്റെ കടമകളിൽ പെട്ടൊരു കടമയാണ്. മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന് അതിൽ നിന്ന് ഒന്നും തന്നെ ഹലാലാവുകയില്ല." (ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 197, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ عَفَوْتُ عَنْ صَدَقَةِ الْخَيْلِ وَالرَّقِيقِ. فَهَاتُوا صَدَقَةَ الرِّقَةِ: مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمًا، وَلَيْسَ فِي تِسْعِينَ وَمِائَةٍ شَيْءٌ، فَإِذَا بَلَغَتْ مِائَتَيْنِ فَفِيهَا خَمْسَةُ دَرَاهِمَ". (د,ت,ن,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "കുതിരയുടെയും അടിമയുടെയും സകാതിൽ ഞാൻ ഇളവ് ചെയ്തിരിക്കുന്നു. അത് കൊണ്ട് വെള്ളിയിലെ സകാത്ത് കൊണ്ട് വരിക. ഓരോ നാൽപ്പത് ദിർഹമിലും ഒരു ദിർഹം, 190 ൽ ഒന്നുമില്ല, 200 എത്തിയാൽ അഞ്ച് ദിർഹമാണ്." (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوَاقٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسَةِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ". (ن)', 'അബൂസഈദുൽ ഖുദ്‌രീ(റ): റസൂൽ(സ) പറഞ്ഞു: "അഞ്ച് ഊഖിയക്ക് താഴെയുള്ളതിൽ (സ്വർണ്ണം, വെള്ളി) സകാതില്ല, അഞ്ചെണ്ണത്തിൽ താഴെയുള്ള ഒട്ടകത്തിൽ സകാതില്ല, അഞ്ച് ഔസുഖിന് താഴെയുള്ളതിൽ (ധാന്യങ്ങളിൽ) സകാതില്ല." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ: أَنَّ امْرَأَةً أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهَا ابْنَةٌ لَهَا، وَفِي يَدِ ابْنَتِهَا مَسَكَتَانِ غَلِيظَتَانِ مِنْ ذَهَبٍ، فَقَالَ لَهَا: "أَتُعْطِينَ زَكَاةَ هَذَا". قَالَتْ: لَا، قَالَ: "أَيَسُرُّكِ أَنْ يُسَوِّرَكِ اللَّهُ بِهِمَا يَوْمَ الْقِيَامَةِ سِوَارَيْنِ مِنْ نَارٍ". قَالَ: فَخَلَعَتْهُمَا فَأَلْقَتْهُمَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَتْ: هُمَا لِلَّهِ عَزَّ وَجَلَّ وَلِرَسُولِهِ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരു സ്ത്രീ തിരുദൂതർ(സ)യുടെ സന്നിധിയിലെത്തി. അവർക്കൊപ്പം അവളുടെ മകളുമുണ്ട്. മകളുടെ കയ്യിൽ കട്ടിയുള്ള രണ്ടു സ്വർണവളകളുണ്ടായിരുന്നു. അവിടുന്നവളോടു ചോദിച്ചു: "നീ ഇതിന്റെ സകാതു കൊടുത്തുവീട്ടിയോ?" അവൾ പറഞ്ഞു: ഇല്ല. അവിടന്ന് ചോദിച്ചു: "അന്ത്യദിനത്തിൽ രണ്ട് അഗ്നിവളകൾ അല്ലാഹു നിന്നെ ധരിപ്പിക്കുന്നതിൽ നിനക്കു സന്തോഷമുണ്ടോ?" അപ്പോൾ അവളത് ഊരി തിരുനബി(സ)ക്ക് കൊടുത്തുകൊണ്ട് പറഞ്ഞു: ഇതു രണ്ടും അല്ലാഹുവിനും അവന്റെ ദൂതർക്കുമാണ്. (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ أَلْبَسُ أَوْضَاحًا مِنْ ذَهَبٍ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَكَنْزٌ هُوَ؟ فَقَالَ: "مَا بَلَغَ أَنْ تُؤَدَّى زَكَاتُهُ فَزُكِّيَ فَلَيْسَ بِكَنْزٍ". (د)', 'ഉമ്മുസലമ(റ) പറയുന്നു: ഞാൻ സ്വർണ്ണാഭരണങ്ങൾ ധരിക്കാറുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇതു നിധിയാണോ? അവിടന്ന് പറഞ്ഞു: "സകാത്ത് വീട്ടേണ്ട. കണക്കെത്തിയാൽ സകാത്ത് വീട്ടുക. അതു നിധിയല്ല." (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: دَخَلْنَا عَلَى عَائِشَةَ – زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – فَقَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَأَى فِي يَدَيَّ فَتَخَاتٍ مِنْ وَرِقٍ، فَقَالَ: "مَا هَذَا يَا عَائِشَةُ؟". فَقُلْتُ: صَنَعْتُهُنَّ أَتَزَيَّنُ لَكَ يَا رَسُولَ اللَّهِ، قَالَ: "أَتُؤَدِّينَ زَكَاتَهُنَّ". قُلْتُ: لَا، أَوْ: مَا شَاءَ اللَّهُ، قَالَ: "هُوَ حَسْبُكِ مِنَ النَّارِ". (د)', 'അബ്ദുല്ലാഹിബ്നു ശദ്ദാദുബ്നുൽ ഹാദി(റ): ആഇശ(റ)യുടെ സന്നിധിയിൽ ഞങ്ങൾ ചെന്നു. അവർ പറഞ്ഞു: ഒരിക്കൽ റസൂൽ(സ) എന്റെയടുത്തു വന്നപ്പോൾ എന്റെ കൈയിൽ രണ്ടു വെള്ളിമോതിരങ്ങൾ കണ്ട് അവിടന്ന് ചോദിച്ചു: "എന്താണിത് ആഇശാ?" ഞാൻ പറഞ്ഞു: ധരിക്കുമ്പോൾ അങ്ങേക്ക് ഭംഗിതോന്നാൻ വേണ്ടി ഞാൻ ഉണ്ടാക്കിയതാണിത്. അവിടന്ന് ചോദിച്ചു: "അവയുടെ സകാത്ത് കൊടുത്തുവീട്ടിയോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അല്ലെങ്കിൽ പറഞ്ഞത്: ما شاء الله എന്നാണ്. അവിടുന്നരുളി: "നരകം കിട്ടുന്നതിനു നിനക്കതു മതി." (ദ)', 'عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ', 'അബ്ദുല്ലാഹിബ്നു ശദ്ദാദുബ്നുൽ ഹാദി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا مَعْشَرَ النِّسَاءِ، تَصَدَّقْنَ وَلَوْ مِنْ حُلِيِّكُنَّ، فَإِنَّكُنَّ أَكْثَرُ أَهْلِ جَهَنَّمَ يَوْمَ الْقِيَامَةِ". (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ ഭാര്യ സൈനബ്(റ): റസൂൽ(സ) ഞങ്ങളോടു പ്രസംഗിച്ചു: "സ്ത്രീസമൂഹമേ, നിങ്ങൾ സ്വദഖ ചെയ്യുക. അതു നിങ്ങളുടെ ആഭരണത്തിൽനിന്നാണെങ്കിലും ശരി. അന്ത്യദിനത്തിൽ നരകാവകാശികളിൽ അധികവും നിങ്ങളാണ്." (ബു,മു,തു,ന)', 'زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ امْرَأَتَيْنِ أَتَتَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي أَيْدِيهِمَا سُوَارَانِ مِنْ ذَهَبٍ، فَقَالَ لَهُمَا: "أَتُؤَدِّيَانِ زَكَاتَهُ؟". قَالَتَا: لَا، فَقَالَ لَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَتُحِبَّانِ أَنْ يُسَوِّرَكُمَا اللَّهُ بِسُوَارَيْنِ مِنْ نَارٍ". قَالَتَا: لَا، قَالَ: "فَأَدِّيَا زَكَاتَهُ". [ضَعَّفَهُ التِّرْمِذِيُّ وَقَالَ: لَا يَصِحُّ فِي هَذَا الْبَابِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْءٌ.] (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): രണ്ടു സ്ത്രീകൾ തിരുദൂതർ(സ)യുടെ സന്നിധിയിൽ വന്നു. അവരുടെ കരങ്ങളിൽ രണ്ടു സ്വർണവളകളുണ്ടായിരുന്നു. അവിടന്ന് ചോദിച്ചു: "നിങ്ങൾ ഇതിന്റെ സകാത്ത് വീട്ടിയോ?" അവർ പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു അഗ്നിവളകൾ നിങ്ങളെ അല്ലാഹു ധരിപ്പിക്കുന്നത് നിങ്ങൾ ഇഷ്ടപ്പെടുന്നുണ്ടോ? അവർ പറഞ്ഞു: ഇല്ല. അവിടുന്നരുളി: "എങ്കിൽ നിങ്ങൾ അതിന്റെ സകാത്ത് വീട്ടുക." ഈ അദ്ധ്യായത്തിൽ നബിതങ്ങൾ ഇക്കാര്യത്തെക്കുറിച്ച് വല്ലതും പറഞ്ഞെന്ന അഭിപ്രായം ശരിയല്ലെന്ന് നിലക്ക് തുർമുദി ഈ ഹദീസിനെ ബലഹീനമാക്കിയിട്ടുണ്ട്. (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], 'ضَعَّفَهُ التِّرْمِذِيُّ وَقَالَ: لَا يَصِحُّ فِي هَذَا الْبَابِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْءٌ.', null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عُمَرَ وَعَائِشَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْخُذُ مِنْ كُلِّ عِشْرِينَ دِينَارًا فَصَاعِدًا نِصْفَ دِينَارٍ، وَمِنَ الْأَرْبَعِينَ دِينَارًا دِينَارًا. (جه)', 'ഇബ്നുഉമർ(റ), ആഇശ(റ): "റസൂൽ(സ) ഓരോ ഇരുപതുദീനാറിൽനിന്നും അതിൽ കൂടിയതിൽനിന്നും അര ദീനാർ (സകാത്) എടുക്കാറുണ്ടായിരുന്നു. നാൽപതു ദീനാറിൽനിന്നും ഒരു ദീനാറും എടുക്കാറുണ്ടായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ وَعَائِشَةَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِيمَا سَقَتِ الْأَنْهَارُ وَالْغَيْمُ الْعُشُورُ، وَفِيمَا سُقِيَ بِالسَّانِيَةِ نِصْفُ الْعُشْرِ". (م,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹം റസൂൽ(സ) പറയുന്നത് കേട്ടു: "നദിയോ മേഘമോ നനച്ചുണ്ടാക്കിയതിൽ പത്തിലൊന്നും ഒട്ടകത്തെക്കൊണ്ടു നനച്ചുണ്ടാക്കിയതാണെങ്കിൽ പത്തിലൊന്നിന്റെ പകുതിയുമാണ്." (മു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 199, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ فِي حَبٍّ وَلَا تَمْرٍ صَدَقَةٌ حَتَّى يَبْلُغَ خَمْسَةَ أَوْسُقٍ، وَلَا فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسِ أَوَاقِيَّ صَدَقَةٌ". (م)', 'അബൂസഈദുൽ ഖുദ്‌രീ(റ): നിശ്ചയം, റസൂൽ(സ) പറഞ്ഞു: "അഞ്ചുവസഖ് (ഒരു വസഖ് എന്നാൽ അറുബത് സ്വാഅ്) എത്തിയാലല്ലാതെ കാരക്കയിലോ ധാന്യത്തിലോ സകാതു നൽകേണ്ടതില്ല. അഞ്ചിൽ കുറഞ്ഞ എണ്ണം ഒട്ടകത്തിലും അഞ്ചിൽ കുറഞ്ഞ ഔഖിയ്യയിലും (ഒരു ഔഖ് എന്നാൽ വെള്ളിയുടെ 40 ദിർഹം) സകാതില്ല." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فِيمَا سَقَتِ السَّمَاءُ وَالْأَنْهَارُ وَالْعُيُونُ، أَوْ كَانَ بَعْلًا الْعُشْرُ، وَفِيمَا سُقِيَ بِالسَّوَانِي أَوِ النَّضْحِ نِصْفُ الْعُشْرِ". (خ,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മേഘം, നദി, അരുവി എന്നിവ നനച്ചുണ്ടാക്കിയതിൽ അല്ലെങ്കിൽ വേര് കുഴിച്ചെടുത്തുണ്ടാക്കിയതിൽ പത്തിലൊന്നും, ഒട്ടകത്തെ ഉപയോഗിച്ചോ തേകിയോ നനച്ചുണ്ടാക്കിയതിൽ പത്തിലൊന്നിന്റെ പകുതിയുമാണ്." (ബു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، فَأَمَرَنِي أَنْ آخُذَ مِمَّا سَقَتِ السَّمَاءُ الْعُشْرَ، وَفِيمَا سُقِيَ بِالدَّوَالِي نِصْفَ الْعُشْرِ. (ن,جه)', 'മുആദ്(റ): റസൂൽ(സ) എന്നെ യമനിലേക്കയച്ചു. മഴ നനച്ചതിൽ പത്തിൽ ഒന്നും തൊട്ടികളുപയോഗിച്ച് നനക്കപ്പെട്ടതിൽ പത്തിലൊന്നിന്റെ പകുതിയും (സകാത്ത്) വാങ്ങാൻ അവിടന്ന് എന്നോട് കൽപ്പിച്ചു. (ന,ജ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَتَبَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُهُ عَنِ الْخَضْرَاوَاتِ، وَهِيَ الْبُقُولُ فَقَالَ: "لَيْسَ فِيهَا شَيْءٌ". (ت)', 'മുആദ്(റ): റസൂൽ(സ)യോട് അദ്ദേഹം പച്ചക്കറിയെക്കുറിച്ച് (ചീര) ചോദിച്ച് എഴുതി. അവിടുന്നരുളി "അതിൽ ഒന്നുമില്ല." (തു)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسَاقٍ مِنْ حَبٍّ أَوْ تَمْرٍ صَدَقَةٌ". (ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ധാന്യം, കാരക്ക എന്നിവയിൽനിന്ന് അഞ്ചിൽ കുറഞ്ഞ വസഖുകൾക്കു സകാതില്ല." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُ فِي الْبُرِّ وَالتَّمْرِ زَكَاةٌ حَتَّى تَبْلُغَ خَمْسَةَ أَوْسُقٍ، وَلَا يَحِلُّ فِي الْوَرِقِ زَكَاةٌ حَتَّى تَبْلُغَ خَمْسَةَ أَوَاقٍ، وَلَا يَحِلُّ فِي إِبِلٍ زَكَاةٌ حَتَّى تَبْلُغَ خَمْسَ ذَوْدٍ". (ن)', 'അബുസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "കാരക്കയിലും ഗോതമ്പിലും അഞ്ചു വസഖ് എത്തുന്നതുവരെയും വെള്ളിയിൽ അഞ്ചു ഊഖിയ എത്തുന്നതുവരെയും ഒട്ടകത്തിൽ അഞ്ചു ''ദൗദ്'' എത്തുന്നതുവരെയും സകാതിന്റെ പരിധിയെത്തുകയില്ല." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 201, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ غَزْوَةَ تَبُوكَ، فَلَمَّا جَاءَ وَادِيَ الْقُرَى إِذَا امْرَأَةٌ فِي حَدِيقَةٍ لَهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "اُخْرُصُوا". وَخَرَصَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَشَرَةَ أَوْسُقٍ فَقَالَ لَهَا: "أَحْصِي مَا يَخْرُجُ مِنْهَا". فَلَمَّا أَتَيْنَا تَبُوكَ قَالَ: أَمَا إِنَّهَا سَتَهُبُّ اللَّيْلَةَ رِيحٌ شَدِيدَةٌ، فَلَا يَقُومَنَّ أَحَدٌ، وَمَنْ كَانَ مَعَهُ بَعِيرٌ فَلْيَعْقِلْهُ فَعَقَلْنَاهَا، وَهَبَّتْ رِيحٌ شَدِيدَةٌ فَقَامَ رَجُلٌ فَأَلْقَتْهُ بِجَبَلِ طَيِّءٍ، وَأَهْدَى مَلِكُ أَيْلَةَ لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بَغْلَةً بَيْضَاءَ، وَكَسَاهُ بُرْدًا، وَكَتَبَ لَهُ بِبَحْرِهِمْ، فَلَمَّا أَتَى وَادِيَ الْقُرَى، قَالَ لِلْمَرْأَةِ: "كَمْ جَاءَ حَدِيقَتُكِ؟". قَالَتْ: عَشَرَةَ أَوْسُقٍ خَرْصَ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنِّي مُتَعَجِّلٌ إِلَى الْمَدِينَةِ، فَمَنْ أَرَادَ مِنْكُمْ أَنْ يَتَعَجَّلَ مَعِي فَلْيَتَعَجَّلْ". فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ: "هَذِهِ طَابَةُ". فَلَمَّا رَأَى أُحُدًا، قَالَ: "هَذَا جُبَيْلٌ يُحِبُّنَا وَنُحِبُّهُ، أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ الْأَنْصَارِ؟". قَالُوا: بَلَى، قَالَ: "دُورُ بَنِي النَّجَّارِ، ثُمَّ دُورُ بَنِي عَبْدِالْأَشْهَلِ، ثُمَّ دُورُ بَنِي سَاعِدَةَ أَوْ دُورُ بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ، وَفِي كُلِّ دُورِ الْأَنْصَارِ". يَعْنِي خَيْرًا. (خ)', 'അബൂ ഹുമൈദുസ്സാഇദീ(റ) പറയുന്നു: ഞങ്ങൾ നബി(സ)യോടൊപ്പം തബൂക് യുദ്ധത്തിനു പോയി. വാദിൽഖുറയിലെത്തിയപ്പോൾ അതാ ഒരു സ്ത്രീ അവരുടെ തോട്ടത്തിൽ. റസൂൽ(സ) അനുചരരോടരുളി: ഈ തോട്ടത്തിലെ ഉൽപന്നത്തിന്റെ മതിപ്പു കണക്കാക്കുക. അവസാനം റസൂൽ(സ) തന്നെ പത്തു വസ്ഖുണ്ടാകുമെന്ന് മതിച്ചു. "ഈ തോട്ടത്തിൽനിന്നു കിട്ടുന്ന ഉൽപന്നത്തിന് കണക്കുവെക്കുക." എന്ന് അവളോടും അവിടന്നരുളി. തബൂക്കിലെത്തിയപ്പോൾ അവിടന്ന് ഞങ്ങൾക്കു മുന്നറിയിപ്പ് തന്നു: "ഇന്നു രാത്രി ഒരു കൊടുങ്കാറ്റടിക്കും. ആരും ഇരിക്കുന്നിടത്തുനിന്ന് എഴുന്നേൽക്കരുത്. വല്ലവന്റെയും കൂടെ ഒട്ടകമുണ്ടെങ്കിൽ അവനതിനെ കെട്ടിയിടട്ടെ." ഞങ്ങൾ ഒട്ടകങ്ങളെയെല്ലാം കെട്ടിയിട്ടു. ശക്തിയായി കൊടുങ്കാറ്റടിച്ചു. അതിനിടക്ക് ഒരാൾ എഴുന്നേറ്റുനിന്നു. ഉടനെ ആ കാറ്റ് അയാളെ കൊണ്ടുപോയി, ''ത്വയ്യിഅ്'' ഗോത്രത്തിന്റെ രണ്ടു മലകൾക്കിടയിൽ എറിഞ്ഞു. ''ഐല'' രാജ്യത്തെ രാജാവ് തിരുമേനി(സ)ക്ക് ഒരു വെളുത്ത കോവർ കഴുതയെ സമ്മാനിച്ചു; ധരിക്കാൻ ഒരു വസ്ത്രവും. തിരുമേനി(സ) ആ രാജാവിനെ അദ്ദേഹത്തിന്റെ ദേശത്തിലെ ഭരണാധികാരിയായി അംഗീകരിച്ചുകൊണ്ട് ഒരു പത്രമെഴുതി കൊടുത്തു. തിരുമേനി(സ) തിരിച്ചു ''വാതിൽ ഖുറാ''യിലെത്തിയപ്പോൾ തോട്ടക്കാരിയോടു ചോദിച്ചു: "നിന്റെ തോട്ടത്തിലെ ഉൽപന്നം എത്രയുണ്ടായിരുന്നു?" തിരുമേനി(സ) മതിച്ചപോലെ പത്തു വസ്ഖ് എന്ന് അവർ പറഞ്ഞു: അവിടന്ന് പറഞ്ഞു: "എനിക്ക് മദീനത്തേക്കു വേഗം പോകേണ്ടതുണ്ട്. എന്റെ കൂടെ ധൃതിപ്പെട്ടുപോരാൻ ആരെങ്കിലും ഒരുക്കമെങ്കിൽ അവർ വന്നുകൊള്ളട്ടെ." ഒടുവിൽ തിരുമേനി(സ) മദീന ദർശിക്കാൻ തുടങ്ങിയപ്പോൾ ഇങ്ങനെ അരുളി: "ഇതാ ''താബ'' (മദീന)യിലെത്തിക്കഴിഞ്ഞു." ഉഹ്ദ് കണ്ടപ്പോൾ അവിടുന്നരുളി: "ഈ മല നമ്മെ സ്നേഹിക്കുന്നു, നാം ഇതിനെയും. അൻസാരികളുടെ ഭവനങ്ങളിൽവെച്ച് ഏറ്റവും ഉത്തമമായത് ഏതെന്നു ഞാൻ പറഞ്ഞുതരട്ടെയോ?" അനുചരന്മാർ പറഞ്ഞു: അരുളിയാലും. അവിടന്നരുളി: "ബനൂനജ്ജാർ ഗോത്രത്തിന്റെ ഭവനങ്ങൾ; പിന്നെ ബനൂ അബ്ദുൽ അശ്ഹൽ ഗോത്രത്തിന്റെ ഭവനങ്ങൾ; പിന്നെ ബനൂ സാഇദാ ഗോത്രത്തിന്റെ ഭവനങ്ങൾ. (അല്ലെങ്കിൽ, ബനുൽ ഹാരിസ് ഗോത്രത്തിന്റെ ഭവനങ്ങൾ) ചുരുക്കത്തിൽ അൻസാറുകളുടെ എല്ലാ ഭവനങ്ങളിലും നന്മയുണ്ട്." (ബു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂ ഹുമൈദുസ്സാഇദീ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 201, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَصْتُمْ فَجُذُّوا وَدَعُوا الثُّلُثَ، فَإِنْ لَمْ تَدَعُوا – أَوْ تَجُذُّوا – الثُّلُثَ فَدَعُوا الرُّبُعَ". (د,ت,ن)', 'സഹ്ലുബ്നു അബീഹത്മ(റ): റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചു: "നിങ്ങൾ മതിപ്പു കണക്കാക്കുകയാണെങ്കിൽ (ഫലങ്ങൾ) നിങ്ങൾ വെട്ടിയെടുക്കുകയും മൂന്നിലൊന്ന് ഒഴിവാക്കുകയും ചെയ്യുക; നിങ്ങൾ (മൂന്നിലൊന്നിനെ) ഒഴിവാക്കുകയോ വെട്ടിയെടുക്കുകയോ ചെയ്യുന്നില്ലെങ്കിൽ നാലിലൊന്നിനെ ഒഴിവാക്കുക." (ദ,തു,ന)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹത്മ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 202, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَتَّاب بْنِ أَسِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ كَانَ يَبْعَثُ عَلَى النَّاسِ مَنْ يَخْرُصُ عَلَيْهِمْ كُرُومَهُمْ وَثِمَارَهُمْ. أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ فِي زَكَاةِ الْكُرُومِ: "إِنَّهَا تُخْرَصُ كَمَا يُخْرَصُ النَّخْلُ، ثُمَّ تُؤَدَّى زَكَاتُهُ زَبِيبًا كَمَا تُؤَدَّى زَكَاةُ النَّخْلِ تَمْرًا". (د,ت,ن,جه)', 'അത്താബുബ്നു അസീദ്(റ): റസൂൽ(സ) ജനങ്ങളിലേക്ക് അവരുടെ മുന്തിരികളും ഫലങ്ങളും മതിപ്പു കണക്കാക്കുന്നതിന് ആളെ അയക്കാറുണ്ടായിരുന്നു. പ്രവാചകർ(സ) മുന്തിരിയുടെ സകാതിൽ പറഞ്ഞു: "അതിന്റെ മതിപ്പു കണക്കാക്കുന്നതു കാരക്ക കണക്കാക്കുംപോലെ തന്നെയാണ്. എന്നിട്ട് ഈത്തപ്പനയുടെ സകാത്ത് കാരക്കയായി നൽകുംപ്രകാരം മുന്തിരിയുടെ സകാത്ത് ഉണക്കമുന്തിരിയായി നൽകണം." (ദ,തു,ന,ജ)', 'عَتَّاب بْنِ أَسِيدٍ', 'അത്താബുബ്നു അസീദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 202, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ – حِينَ افْتَتَحَ خَيْبَرَ – وَاشْتَرَطَ أَنَّ لَهُ الْأَرْضَ، وَكُلَّ صَفْرَاءَ وَبَيْضَاءَ. يَعْنِي الذَّهَبَ وَالْفِضَّةَ. وَقَالَ لَهُ أَهْلُ خَيْبَرَ: نَحْنُ أَعْلَمُ بِالْأَرْضِ، فَأَعْطِنَاهَا عَلَى أَنْ نَعْمَلَهَا، وَيَكُونَ لَنَا نِصْفُ الثَّمَرَةِ وَلَكُمْ نِصْفُهَا. فَزَعَمَ أَنَّهُ أَعْطَاهُمْ عَلَى ذَلِكَ، فَلَمَّا كَانَ حِينَ يُصْرَمُ النَّخْلُ، بَعَثَ إِلَيْهِمُ ابْنَ رَوَاحَةَ فَحَزَرَ النَّخْلَ، وَهُوَ الَّذِي يَدْعُونَهُ – أَهْلُ الْمَدِينَةِ – الْخَرْصَ. فَقَالَ: فِي ذَا كَذَا وَكَذَا. فَقَالُوا: أَكْثَرْتَ عَلَيْنَا يَا ابْنَ رَوَاحَةَ، فَقَالَ: فَأَنَا أَحْزِرُ النَّخْلَ وَأُعْطِيكُمْ نِصْفَ الَّذِي قُلْتُ. قَالَ: فَقَالُوا: هَذَا الْحَقُّ، وَبِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ. فَقَالُوا: قَدْ رَضِينَا أَنْ نَأْخُذَ بِالَّذِي قُلْتَ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഖൈബർ വിജയം നേടിയ സമയത്ത് റസൂൽ(സ) ശത്രുക്കളുടെമേൽ ഇപ്രകാരം നിബന്ധനവെച്ചു: ഭൂമിയും, മഞ്ഞയായതും, വെളുത്തതുമായ അഥവാ സ്വർണവും വെള്ളിയും മുഴുവനും അവിടുത്തേക്ക് വേണം. അവിടുത്തോടു ഖൈബറുകാർ പറഞ്ഞു: ഞങ്ങളാണു ഭൂമിയെക്കുറിച്ചു നല്ലവണ്ണം അറിയുന്നവർ. അതിനാൽ, ഞങ്ങൾ അതിൽ ജോലി ചെയ്യാമെന്നതിന്റെ മേൽ ഞങ്ങൾക്കതു നൽകിയാലും. ഉൽപന്നത്തിന്റെ പകുതി നിങ്ങൾക്കും പകുതി ഞങ്ങൾക്കുമായിരിക്കും. അവിടന്ന് അവർക്ക് ആ നിബന്ധനയുടെ മേൽ നൽകി. കാരക്കയുടെ വിളവെടുപ്പിന്റെ സമയമായപ്പോൾ കാരക്കയുടെ മതിപ്പു കണക്കാക്കാൻ ഇബ്നുറവാഹ(റ)വിനെ അവിടന്ന് അവരിലേക്ക് അയച്ചു. ഇപ്രകാരം ചെയ്യുന്നതിനെയാണ് ഖർസ് എന്ന് മദീനക്കാർ വിളിക്കുന്നത്. അദ്ദേഹം മതിപ്പു കണക്കാക്കി. ശേഷം പറഞ്ഞു: ഇതിൽ ഇത്രയും ഇത്രയുംവേണം. അവർ പറഞ്ഞു: താങ്കൾ ഞങ്ങളുടെ മേൽ കൂടുതലാക്കിയല്ലോ ഇബ്നു റവാഹാ. അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഈത്തപ്പനയിൽ മതിപ്പു കണക്കാക്കുക മാത്രമാണ്; ഞാൻ പറഞ്ഞതിന്റെ പകുതി നിങ്ങൾക്കു തരികയും ചെയ്യും. അപ്പോൾ അവർ പറഞ്ഞു: ഇതുതന്നെയാണു സത്യം, അതിന്മേലാണ് ആകാശഭൂമിയുടെ നിലനിൽപ്. താങ്കൾ പറഞ്ഞത് എടുക്കുന്നതിൽ ഞങ്ങൾ സംതൃപ്തരുമാണ്. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 202, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: وَهِيَ تَذْكُرُ شَأْنَ خَيْبَرَ: كَانَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَبْعَثُ عَبْدَ اللَّهِ بْنَ رَوَاحَةَ إِلَى يَهُودَ، فَيَخْرُصُ النَّخْلَ حِينَ يَطِيبُ، قَبْلَ أَنْ يُؤْكَلَ مِنْهُ. (د)', 'ആഇശ(റ): ഖൈബർ യുദ്ധത്തെ സൂചിപ്പിച്ച് അവർ പറയുന്നു: തിരുനബി(സ) അബ്ദുല്ലാഹിബ്നു റവാഹ(റ)വിനെ ജൂതരുടെ സമീപത്തേക്കയക്കാറുണ്ടായിരുന്നു. ഈത്തപ്പഴം ഭക്ഷിക്കപ്പെടുംമുമ്പ് അത് പാകമായാൽ മതിച്ചു കണക്കാക്കാൻവേണ്ടിയായിരുന്നു ഇത്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ سَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَنِ الْجُعْرُورِ وَلَوْنِ الْحُبَيْقِ أَنْ يُؤْخَذَا فِي الصَّدَقَةِ. (د,ن)', 'സഹ്ൽ(റ): അദ്ദേഹം പറഞ്ഞു: ''ജുഅ്റൂറ്'', ''ഹുബൈഖ്'' (താഴ്ന്ന ഇനം കാരക്കകൾ) എന്നിവയിൽനിന്നു സകാത്ത് വാങ്ങൽ റസൂൽ(സ) വിലക്കി. (ദ,ന)', 'سَهْلٍ', 'സഹ്ൽ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ هِلَالٌ – أَحَدُ بَنِي مُتْعَانَ – إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِعُشُورِ نَحْلٍ لَهُ، وَكَانَ سَأَلَهُ أَنْ يَحْمِيَ لَهُ وَادِيًا يُقَالُ لَهُ سَلَبَةُ، فَحَمَى لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ ذَلِكَ الْوَادِي، فَلَمَّا وُلِّيَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ كَتَبَ سُفْيَانُ بْنُ وَهْبٍ إِلَى عُمَرَ بْنِ الْخَطَّابِ يَسْأَلُهُ عَنْ ذَلِكَ، فَكَتَبَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: إِنْ أَدَّى إِلَيْكَ مَا كَانَ يُؤَدِّي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنْ عُشُورِ نَحْلِهِ فَاحْمِ لَهُ سَلَبَةَ، وَإِلَّا فَإِنَّمَا هُوَ ذُبَابُ غَيْثٍ يَأْكُلُهُ مَنْ يَشَاءُ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അദ്ദേഹം പറഞ്ഞു: ബനൂമുത്ആൻ ഗോത്രത്തിൽപ്പെട്ട ''ഹിലാൽ'' ഒരിക്കൽ തന്റെ തേനീച്ചയിൽ (തേനിൽ) നിന്നു പത്തിലൊന്നുമായി പ്രവാചകസന്നിധിയിലെത്തി. സലബ എന്നു പറയപ്പെടുന്ന താഴ്വര തന്റെ സംരക്ഷണമേഖലയാക്കാൻ അദ്ദേഹം ചോദിച്ചിരുന്നു. റസൂൽ(സ) അദ്ദേഹത്തിന് അതു സംരക്ഷിത മേഖലയാക്കുകയും ചെയ്തു. ഉമറുബ്നു ഖത്താബ്(റ) ഭരണത്തിലെത്തിയപ്പോൾ സുഫ്യാനുബ്നു വഹബ്(റ) ഉമർ(റ)നോട് ഇതിനെക്കുറിച്ചു ചോദിച്ചുകൊണ്ട് എഴുതി. ഉമർ(റ) മറുപടി എഴുതി. തിരുദൂതർ(സ)ക്ക് അദ്ദേഹം നൽകിയിരുന്ന തേനീച്ചയിൽനിന്നുള്ള പത്തിലൊന്ന് നിങ്ങൾക്കും നൽകുകയാണെങ്കിൽ അദ്ദേഹത്തിനു സലബയെ സംരക്ഷിച്ചുകൊടുക്കുക. ഇനി അദ്ദേഹം വീട്ടുന്നില്ലെങ്കിൽ അത് മേഘത്തിൽനിന്നുള്ള ഈച്ചയാണ്, അത് ഇഷ്ടമുള്ളവർക്കു ഭക്ഷിക്കാം. (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 203, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "فِي الْعَسَلِ: فِي كُلِّ عَشَرَةِ أَزُقٌ زِقٌّ". (ت)', 'ഇബ്നുഉമർ(റ): തേനിന്റെ കാര്യത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "ഓരോ പത്ത് സിഖുകളിലും (സിഖ് എന്നാൽ ഒരു അളവാണ്) ഒരു സിഖ് ആണ് (കൊടുക്കേണ്ടത്)." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ نَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلَنِي عُمَرُ بْنِ عَبْدِ الْعَزِيزِ عَنْ صَدَقَةِ الْعَسَلِ، قَالَ: قُلْتُ: مَا عِنْدَنَا عَسَلٌ نَتَصَدَّقُ مِنْهُ، وَلَكِنْ أَخْبَرَنَا الْمُغِيرَةُ بْنِ حَكِيمٍ أَنَّهُ قَالَ: لَيْسَ فِي الْعَسَلِ صَدَقَةٌ. فَقَالَ عُمَرُ: عَدْلٌ مَرْضِيٌّ. فَكَتَبَ إِلَى النَّاسِ أَنْ تُوضَعَ، يَعْنِي عَنْهُمْ. (ت)', 'നാഫിഅ്(റ): എന്നോട് ഉമർബ്നു അബ്ദുൽ അസീസ് തേനിന്റെ സകാതു സംബന്ധിച്ചു വിവരമാരാഞ്ഞു. ഞാൻ പറഞ്ഞു: സകാതു കൊടുക്കാനുള്ള തേൻ ഞങ്ങളുടെ അടുത്തില്ല. എങ്കിലും അൽ മുഗീറതുബ്നു ഹകീം(റ) എന്നയാൾ ഞങ്ങളോട് പറഞ്ഞതു തേനിൽ സകാതില്ല എന്നാണ്. ഇതുകേട്ട് ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹം അംഗീകൃതനായ നീതിമാനാണ്. അങ്ങനെയദ്ദേഹം ജനങ്ങളിൽനിന്നു തേനിന്റെ സകാത്ത് ഒഴിവാക്കാൻ നിർദ്ദേശമയച്ചു. (തു)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَبِي سَيَّارَةَ الْمُتَّقِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ لِي نَحْلًا. قَالَ: "أَدِّ الْعُشْرَ". قُلْتُ: يَا رَسُولَ اللَّهِ، احْمِهَا لِي، فَحَمَاهَا لِي. (جه)', 'അബൂസയ്യാറതുൽ മുത്തഖി(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ എനിക്കു തേനീച്ചയുണ്ട്. അവിടുന്നരുളി: പത്തിലൊന്ന് നീ കൊടുത്തുവിടുക. ഞാൻ ആവശ്യപ്പെട്ടു. എനിക്കതിനെ സംരക്ഷിച്ചുതരണം. അവിടുന്നതെനിക്കു സംരക്ഷിച്ചു തരികയും ചെയ്തു. (ജ)', 'أَبِي سَيَّارَةَ الْمُتَّقِيِّ', 'അബൂസയ്യാറതുൽ മുത്തഖി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: أَنَّهُ أَخَذَ مِنَ الْعَسَلِ الْعُشْرَ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നിശ്ചയം നബി(സ) തേനിൽനിന്നു പത്തിലൊന്ന് (സകാതായി) എടുത്തു. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَنَّ رَجُلًا مِنْ بَنِي إِسْرَائِيلَ سَأَلَ بَعْضَ بَنِي إِسْرَائِيلَ أَنْ يُسْلِفَهُ أَلْفَ دِينَارٍ، فَدَفَعَهَا إِلَيْهِ، فَخَرَجَ فِي الْبَحْرِ، فَلَمْ يَجِدْ مَرْكَبًا، فَأَخَذَ خَشَبَةً فَنَقَرَهَا، فَأَدْخَلَ فِيهَا أَلْفَ دِينَارٍ، فَرَمَى بِهَا فِي الْبَحْرِ، فَخَرَجَ الرَّجُلُ الَّذِي كَانَ أَسْلَفَهُ، فَإِذَا بِالْخَشَبَةِ، فَأَخَذَهَا لِأَهْلِهِ حَطَبًا، فَذَكَرَ الْحَدِيثَ، فَلَمَّا نَشَرَهَا وَجَدَ الْمَالَ". (خ)', 'അബുഹുറൈറ(റ) പ്രവാചകരിൽനിന്ന് ഉദ്ധരിക്കുന്നു: അവിടന്ന് പറഞ്ഞു: "ഒരിക്കൽ ഒരു ബനൂ ഇസ്രായിൽകാരൻ ഇസ്രായീല്യരിൽ ഒരാളോട് ആയിരം ദീനാർ കടം ആവശ്യപ്പെട്ടു. അയാൾ അതവനു കൊടുത്തു. അവൻ സമുദ്രതീരത്തേക്ക് പുറപ്പെട്ടു. അവിടെ വാഹനമൊന്നും കിട്ടിയില്ല. അപ്പോൾ ഒരു മരക്കഷണമെടുത്ത് അതു തുരന്ന് ആയിരം ദീനാർ അതിലിട്ടു സമുദ്രത്തിലേക്കെറിഞ്ഞു. കടംകൊടുത്തവൻ കടൽതീരത്തേക്കു വന്നു. അതാ ഒരു മരക്കഷ്ണം. തന്റെ കുടുംബത്തിനു കത്തിക്കാൻ അതെടുത്തു കൊണ്ടുവന്നു. ഈ ഹദീസിന്റെ (ബാക്കി ഭാഗങ്ങൾ) അബൂഹുറൈറ തുടർന്നു പറഞ്ഞു. എന്നിട്ടതു കീറിയപ്പോൾ ആ തുക അദ്ദേഹത്തിനു ലഭിച്ചു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 204, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ؟ فَقَالَ: "مَا كَانَ فِي طَرِيقٍ مَأْتِيٍّ أَوْ فِي قَرْيَةٍ عَامِرَةٍ فَعَرِّفْهَا سَنَةً، فَإِنْ جَاءَ صَاحِبُهَا وَإِلَّا فَلَكَ. وَمَا لَمْ يَكُنْ فِي طَرِيقٍ مَأْتِيٍّ وَلَا فِي قَرْيَةٍ عَامِرَةٍ، فَفِيهِ وَفِي الرِّكَازِ الْخُمْسُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ)യോട് വീണുകിട്ടിയ വസ്തുവിനെക്കുറിച്ചു ചോദിക്കപ്പെട്ടു: അവിടുന്നരുളി: "അത് ആൾത്താമസമുള്ള ഗ്രാമത്തിലോ, സഞ്ചാരമുള്ള വഴിയിൽനിന്നോ ആണെങ്കിൽ ഒരു വർഷം അതു പരസ്യം ചെയ്യുക. തുടർന്ന് അതിന്റെയുടമ വന്നില്ലായെങ്കിൽ നിനക്കുള്ളതാണത്. ഇനി അത് ആൾസഞ്ചാരമുള്ള വഴിയിലോ, ആൾതാമസമുള്ള ഗ്രാമത്തിലോ അല്ലെങ്കിൽ അതിൽനിന്നും (അതുപോലെ) നിധിയിൽനിന്നും അഞ്ചിലൊന്നു സകാതു കൊടുക്കുക." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "الْعَجْمَاءُ جُرْحُهَا جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ". (ق,ت,ن)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുറിവുള്ള മൃഗത്തിൽ ഉത്തരവാദിത്തമില്ല. ഖനിയപകടത്താലോ കിണറ്റിൽവീണോ നശിച്ചതിനും ഉത്തരവാദിത്തമില്ല. നിധിക്ക് അഞ്ചിലൊന്നാണ് സകാത്ത്." (ബു,മു,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا رَسُولَ اللَّهِ، إِنَّ أُمِّيَ افْتُلِتَتْ نَفْسَهَا وَلَمْ تُوصِ، وَأَظُنُّهَا لَوْ تَكَلَّمَتْ تَصَدَّقَتْ، أَفَلَهَا أَجْرٌ إِنْ تَصَدَّقْتُ عَنْهَا؟ قَالَ: "نَعَمْ". (م)', 'ആഇശ(റ): ഒരാൾ പ്രവാചകർ(സ)യുടെ സന്നിധിയിൽ വന്നുപറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മാതാവു മരണപ്പെട്ടുപോയി. അവർ ഒന്നും വസ്വിയത്തു ചെയ്തിട്ടില്ല. ഞാൻ ഊഹിക്കുന്നത്, അവർക്കു സംസാരിക്കാൻ കഴിഞ്ഞിരുന്നെങ്കിൽ സ്വദഖ ചെയ്യുമായിരുന്നു എന്നാണ്. അപ്പോൾ ഞാനവർക്കു വേണ്ടി സ്വദഖ ചെയ്താൽ അവർക്കു പ്രതിഫലം ലഭിക്കുമോ? അവിടുന്നരുളി: "അതെ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أُمِّي تُوُفِّيَتْ، أَفَيَنْفَعُهَا إِنْ تَصَدَّقْتُ عَنْهَا؟ قَالَ: "نَعَمْ". قَالَ: فَإِنَّ لِي مَخْرَفًا، فَأُشْهِدُكَ أَنِّي قَدْ تَصَدَّقْتُ بِهِ عَنْهَا. (د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ മാതാവു മരിച്ചുപോയി. അവർക്കുവേണ്ടി ഞാൻ സ്വദഖ ചെയ്താൽ അവർക്ക് ഉപകരിക്കുമോ? അവിടന്നരുളി: "അതെ" അയാൾ പറഞ്ഞു: എനിക്കൊരു ഈത്തപ്പന (മുന്തിരി)ത്തോട്ടമുണ്ട്. അങ്ങയെ സക്ഷിയാക്കി ഞാനത് അവർക്കു വേണ്ടി സ്വദഖ ചെയ്യുന്നു. (ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ فَقَالَ: "أَلَا مَنْ وَلِيَ يَتِيمًا لَهُ مَالٌ فَلْيَتَّجِرْ فِيهِ، وَلَا يَتْرُكْهُ حَتَّى تَأْكُلَهُ الصَّدَقَةُ". [قَالَ الترمذي: في إسناده مقالٌ.] (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): "നിശ്ചയം റസൂൽ(സ) ജനങ്ങളോടു പ്രസംഗിച്ചു. അറിയണം, ആരെങ്കിലും സമ്പത്തുള്ള അനാഥയുടെ കൈകാര്യകർതൃത്വം ഏറ്റെടുത്താൽ അവന്റെ സമ്പത്തിൽ വ്യാപാരം നടത്തിക്കൊള്ളട്ടെ. സകാത്ത് അതിനെ തിന്നുതീർക്കും വരെ അവൻ അതിനെ ഉപേക്ഷിച്ചിടരുത്. (ഇതിന്റെ സനദിൽ അഭിപ്രായമുണ്ടെന്ന് തുർമുദി(റ) പറയുന്നു.) (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], 'قَالَ الترمذي: في إسناده مقالٌ.', null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ، وَلَا لِذِي مِرَّةٍ سَوِيٍّ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സമ്പന്നൻ, പ്രതാപവാൻ എന്നിവർക്ക് സകാതു നൽകൽ അനുവദനീയമല്ല." (ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ عَطَاءِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ إِلَّا لِخَمْسَةٍ: لِغَازٍ فِي سَبِيلِ اللَّهِ، أَوْ لِعَامِلٍ عَلَيْهَا، أَوْ لِغَارِمٍ، أَوْ لِرَجُلٍ اشْتَرَاهَا بِمَالِهِ، أَوْ لِرَجُلٍ كَانَ لَهُ جَارٌ مِسْكِينٌ فَتُصُدِّقَ عَلَى الْمِسْكِينِ، فَأَهْدَاهَا الْمِسْكِينُ لِلْغَنِيِّ". وَفِي رِوَايَةٍ: عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ. (د,جه)', 'അതാഉബ്നു യസാർ(റ): റസൂൽ(സ) അരുളി: "അഞ്ചു കാര്യത്തിന് വേണ്ടിയല്ലാതെ സമ്പന്നന് സകാത്ത് അനുവദനീയമല്ല. അല്ലാഹുവിന്റെ മാർഗത്തിൽ ധർമസമരത്തിലേർപ്പെട്ടവൻ, സകാതിന്റെ ജോലിക്കാരൻ, കടത്തിൽ അകപ്പെട്ടവൻ, തന്റെ ധനംകൊണ്ട് സ്വദഖ വാങ്ങിയവൻ, ഒരാളുടെ ദരിദ്രനായ അയൽക്കാരന് സ്വദഖ നൽകപ്പെടുകയും എന്നിട്ടത് ആ ദരിദ്രൻ സമ്പന്നന് ഹദ്യ നൽകുകയും ചെയ്തു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=184), 1, 'وَفِي رِوَايَةٍ: عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، بِمَعْنَاهُ. (د,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: അതാഅ്ബ്നു യസാർ(റ) അബൂസഈദിൽ ഖുദ്രീ(റ)വിൽ നിന്ന് നിവേദനം: റസൂൽ(സ) മേൽ പറഞ്ഞതിന്റെ ആശയം പറഞ്ഞു. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ، إِلَّا فِي سَبِيلِ اللَّهِ، أَوِ ابْنِ السَّبِيلِ، أَوْ جَارٍ فَقِيرٍ يُتَصَدَّقُ عَلَيْهِ، فَيُهْدِي لَكَ أَوْ يَدْعُوكَ". (د)', 'അബൂസഈദ്(റ): റസൂൽ(സ) അരുളി: "സമ്പന്നന്, അവൻ അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധംചെയ്യുന്നവനോ, വഴിയാത്രക്കാരനോ ആവുകയും അല്ലെങ്കിൽ ഒരു ദരിദ്രനായ അയൽവാസിക്ക് സകാത്ത് ലഭിക്കുകയും എന്നിട്ട് നിനക്കയാൾ അതിൽനിന്ന് സമ്മാനിക്കുകയോ നിന്നെ സൽക്കരിക്കുകയോ ചെയ്താലുമല്ലാതെ സകാത്ത് അനുവദനീയമല്ല." (ദ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَدَاهُ بِمِائَةٍ مِنْ إِبِلِ الصَّدَقَةِ. يَعْنِي دِيَةَ الْأَنْصَارِيِّ الَّذِي قُتِلَ بِخَيْبَرَ. (ق,د,ت,ن,جه)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ): റസൂൽ(സ) സകാതിൽനിന്നുള്ള നൂറ് ഒട്ടകത്തെ അദ്ദേഹത്തിന് രക്തമൂലമായി നൽകി – ഖൈബറിൽ കൊല്ലപ്പെട്ട അൻസാരിയുടെ രക്തമൂലം. (ബു,മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 206, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ حُبْشِيِّ بْنِ جُنَادَةَ السَّلُولِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ فِي حَجَّةِ الْوَدَاعِ، وَهُوَ وَاقِفٌ بِعَرَفَةَ، أَتَاهُ أَعْرَابِيٌّ فَأَخَذَ بِطَرَفِ رِدَائِهِ، فَسَأَلَهُ إِيَّاهُ، فَأَعْطَاهُ وَذَهَبَ، فَعِنْدَ ذَلِكَ حَرُمَتِ الْمَسْأَلَةُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ لِغَنِيٍّ، وَلَا لِذِي مِرَّةٍ سَوِيٍّ، إِلَّا لِذِي فَقْرٍ مُدْقِعٍ، أَوْ غُرْمٍ مُفْظِعٍ، وَمَنْ سَأَلَ النَّاسَ لِيُثْرِيَ بِهِ مَالَهُ كَانَ خُمُوشًا فِي وَجْهِهِ يَوْمَ الْقِيَامَةِ، وَرَضْفًا يَأْكُلُهُ مِنْ جَهَنَّمَ، وَمَنْ شَاءَ فَلْيُقِلَّ، وَمَنْ شَاءَ فَلْيُكْثِرْ". (ت)', 'ഹുബ്ശിയ്യുബ്നു ജുനാദതുസ്സലൂലി(റ): ഹജ്ജതുൽവിദാഇൽ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു, അവിടന്ന് അറഫയിൽ നിൽക്കവെ ഒരു ഗ്രാമീണൻ വന്നു അവിടുത്തെ തട്ടത്തിന്റെ അറ്റംപിടിച്ച് അത് ആവശ്യപ്പെട്ടു. അവിടുന്നത് അയാൾക്കു കൊടുത്തു. അയാൾ സ്ഥലംവിട്ടു. ഈയവസരത്തിലാണു യാചന നിഷിദ്ധമായത്. എന്നിട്ട് റസൂൽ(സ) അരുളി: "നിശ്ചയം, സമ്പന്നൻ, ശാരീരികക്ഷമതയും ശക്തിയുമുള്ളവൻ എന്നിവർക്ക് യാചന അനുവദനീയമല്ല. കൊടും ദാരിദ്ര്യമോ അമിതമായ കടമോ ഉള്ളവനൊഴികെ. ഒരാൾ തന്റെ സമ്പത്ത് അധികരിപ്പിക്കാൻ വേണ്ടി പണം യാചിച്ചാൽ, അതവന് അന്ത്യനാളിൽ മുഖത്തു മാന്തിയ അടയാളമായും നരകത്തിൽനിന്നും അവനു ഭക്ഷിക്കാനുള്ള തീക്കട്ടയായും ആയിരിക്കും ഉണ്ടാവുക. ആരെങ്കിലും ചുരുക്കാൻ ഉദ്ദേശിച്ചാൽ ചുരുക്കിക്കൊള്ളട്ടെ; വികസിപ്പിക്കാൻ ഉദ്ദേശിച്ചെങ്കിൽ വികസിപ്പിച്ചുകൊള്ളട്ടെ." (തു)', 'حُبْشِيِّ بْنِ جُنَادَةَ السَّلُولِيِّ', 'ഹുബ്ശിയ്യുബ്നു ജുനാദതുസ്സലൂലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ وَلَهُ قِيمَةُ أُوقِيَّةٍ فَقَدْ أَلْحَفَ". فَقُلْتُ: نَاقَتِي الْيَاقُوتَةُ هِيَ خَيْرٌ مِنْ أُوقِيَّةٍ، أَوْ: خَيْرٌ مِنْ أَرْبَعِينَ دِرْهَمًا، فَرَجَعْتُ، فَلَمْ أَسْأَلْهُ شَيْئًا، قَالَ: وَكَانَتِ الْأُوقِيَّةُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ دِرْهَمًا. (د,ن)', 'അബുസഈദുൽ ഖുദ്രി(റ): റസൂൽ(സ) അരുളി: "ഒരു ഊഖിയയുടെ മൂല്യം കൈവശമുള്ള ഒരാൾ യാചന നടത്തിയാൽ അവൻ അമിതം ചോദിച്ചു." അപ്പോൾ ഞാൻ സ്വയം പറഞ്ഞു: യാഖൂതത് എന്ന എന്റെ ഒട്ടകം ഒരു ഊഖിയയെക്കാൾ മികച്ചതാണ്. അപ്പോൾ ഞാൻ മടങ്ങി. പിന്നെ ഞാനൊന്നും ചോദിച്ചിട്ടില്ല. നിവേദകൻ പറയുന്നു: റസൂൽ(സ)യുടെ കാലത്ത് ഒരു ഊഖിയ നാൽപതു ദിർഹമായിരുന്നു. (ദ,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദുൽ ഖുദ്രി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ سَهْلِ بْنِ الْحَنْظَلِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عُيَيْنَةُ بْنُ حِصْنٍ وَالْأَقْرَعُ بْنُ حَابِسٍ، فَسَأَلَاهُ، فَأَمَرَ لَهُمَا بِمَا سَأَلَا، وَأَمَرَ مُعَاوِيَةَ فَكَتَبَ لَهُمَا بِمَا سَأَلَا، فَأَمَّا الْأَقْرَعُ فَأَخَذَ كِتَابَهُ، فَلَفَّهُ فِي عِمَامَتِهِ وَانْطَلَقَ، وَأَمَّا عُيَيْنَةُ فَأَخَذَ كِتَابَهُ وَأَتَى النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مَكَانَهُ، فَقَالَ: يَا مُحَمَّدُ، أَتُرَانِي حَامِلًا إِلَى قَوْمِي كِتَابًا لَا أَدْرِي، مَا فِيهِ كَصَحِيفَةِ الْمُتَلَمِّسِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ وَعِنْدَهُ مَا يُغْنِيهِ فَإِنَّمَا يَسْتَكْثِرُ مِنَ النَّارِ". وَفِي رِوَايَةٍ: "مِنْ جَمْرِ جَهَنَّمَ". فَقَالُوا: يَا رَسُولَ اللَّهِ، وَمَا يُغْنِيهِ؟ وَفِي رِوَايَةٍ: وَمَا الْغِنَى الَّذِي لَا تَنْبَغِي مَعَهُ الْمَسْأَلَةُ؟ قَالَ: "قَدْرُ مَا يُغَدِّيهِ وَيُعَشِّيهِ". وَفِي رِوَايَةٍ: "أَنْ يَكُونَ لَهُ شِبْعُ يَوْمٍ وَلَيْلَةٍ، أَوْ لَيْلَةٍ وَيَوْمٍ". (د)', 'സഹ്ലുബ്നുൽ ഹൻളലിയ്യ(റ): റസൂൽ(സ)യുടെ സന്നിധിയിൽ ഉയൈനത്ബ്നു ഹുസ്നും അഖ്റഉബ്നു ഹാബിസും വന്ന് ആവശ്യപ്പെട്ടു. അവർക്കു ചോദിച്ചതു നൽകാൻ അവിടന്ന് ഉത്തരവിടുകയും ചെയ്തു. മുആവിയ(റ)നോട് കൽപിച്ചപ്പോൾ അവർക്കു വേണ്ടി അവർ ചോദിച്ചത് അദ്ദേഹം രേഖപ്പെടുത്തി. അഖ്റഅ് ആ രേഖയെടുത്തു തന്റെ തലപ്പാവിൽ തിരുകി സ്ഥലംവിട്ടു. എന്നാൽ ഉയൈന തന്റെ രേഖയുമെടുത്ത് തിരുസന്നിധിയിലെത്തി പറഞ്ഞു: "ഹേ മുഹമ്മദ്, എന്താണെന്നറിയാതെ യാചകന്റെ ഏടുപോലുള്ള ഒരു രേഖയുമായി എന്റെ സമൂഹത്തിലേക്കു ഞാനിതു വഹിച്ചുകൊണ്ട് പോകണമെന്നാണോ താങ്കൾ കരുതുന്നത്. അവിടന്നരുളി: "ആരെങ്കിലും അവന് മതിയാകുന്നതു കൈവശമുണ്ടായിരിക്കെ യാചന നടത്തിയാൽ അവൻ നരകത്തിൽനിന്നുള്ളതിനെ കൂടുതലാക്കുകയാണ്." മറ്റൊരു നിവേദനത്തിൽ: "നരകത്തിലെ കല്ലിനെ." അവർ ചോദിച്ചു: മതിയാകുന്നതിന്റെ പരിധി എന്താണ് അല്ലാഹുവിന്റെ റസൂലേ? മറ്റൊരു നിവേദനത്തിൽ: ഒരാൾക്കു യാചന പാടില്ലാത്ത സമ്പത്ത് എത്രയാണ്? അവിടന്നരുളി: "അവന് ഭക്ഷിക്കാനും ജീവിക്കാനും മതിയായത്രയാണ്." മറ്റൊരു നിവേദനത്തിൽ: "ഒരു പകലിലും രാത്രിയിലും വിശപ്പടക്കാനുള്ളത് അവനുണ്ടായിരിക്കുക." (ദ)', 'سَهْلِ بْنِ الْحَنْظَلِيَّةِ', 'സഹ്ലുബ്നുൽ ഹൻളലിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 207, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=189), 1, 'وَفِي رِوَايَةٍ: "مِنْ جَمْرِ جَهَنَّمَ". فَقَالُوا: يَا رَسُولَ اللَّهِ، وَمَا يُغْنِيهِ؟', 'മറ്റൊരു നിവേദനത്തിൽ: "നരകത്തിലെ കല്ലിനെ." അവർ ചോദിച്ചു: മതിയാകുന്നതിന്റെ പരിധി എന്താണ് അല്ലാഹുവിന്റെ റസൂലേ?');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=189), 2, 'وَفِي رِوَايَةٍ: وَمَا الْغِنَى الَّذِي لَا تَنْبَغِي مَعَهُ الْمَسْأَلَةُ؟ قَالَ: "قَدْرُ مَا يُغَدِّيهِ وَيُعَشِّيهِ".', 'മറ്റൊരു നിവേദനത്തിൽ: ഒരാൾക്കു യാചന പാടില്ലാത്ത സമ്പത്ത് എത്രയാണ്? അവിടന്നരുളി: "അവന് ഭക്ഷിക്കാനും ജീവിക്കാനും മതിയായത്രയാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=189), 3, 'وَفِي رِوَايَةٍ: "أَنْ يَكُونَ لَهُ شِبْعُ يَوْمٍ وَلَيْلَةٍ، أَوْ لَيْلَةٍ وَيَوْمٍ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഒരു പകലിലും രാത്രിയിലും വിശപ്പടക്കാനുള്ളത് അവനുണ്ടായിരിക്കുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ زِيَادِ بْنِ الْحَارِثِ الصُّدَائِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَبَايَعْتُهُ، فَذَكَرَ حَدِيثًا طَوِيلًا، قَالَ: فَأَتَاهُ رَجُلٌ، فَقَالَ: أَعْطِنِي مِنَ الصَّدَقَةِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ تَعَالَى لَمْ يَرْضَ بِحُكْمِ نَبِيٍّ وَلَا غَيْرِهِ فِي الصَّدَقَاتِ حَتَّى حَكَمَ فِيهَا هُوَ، فَجَزَّأَهَا ثَمَانِيَةَ، فَإِنْ كُنْتَ مِنْ تِلْكَ الْأَجْزَاءِ أَعْطَيْتُكَ حَقَّكَ". (د)', 'സിയാദുബ്നുൽ ഹാരിസുസ്സുദാഈ(റ): റസൂൽ(സ)യുടെ സന്നിധിയിൽ ഞാൻ ചെന്നു, അവിടുത്തോട് ഉടമ്പടി ചെയ്തു. അവിടന്ന് സുദീർഘമായ ഭാഷണം നടത്തി. അന്നേരം ഒരാൾ അവിടുത്തേക്കു വന്നുപറഞ്ഞു: സകാതിൽനിന്ന് എനിക്കു തരണം. റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു – അവൻ ഉന്നതനത്രെ – സകാതിന്റെ കാര്യത്തിൽ ഒരു നബിയുടെയോ മറ്റാരുടെയോ വിധിയിൽ തൃപ്തനാവുകയില്ല. അവൻതന്നെ അതിൽ വിധി കൽപിച്ചിട്ടുണ്ട്. അവനതിനെ എട്ടു വകുപ്പാക്കി തിരിച്ചു. നീ ആ വകുപ്പിൽ പെട്ടിട്ടുണ്ടെങ്കിൽ നിനക്കതിന്റെ അവകാശം ഞാൻ തരുന്നതാണ്." (ദ)', 'زِيَادِ بْنِ الْحَارِثِ الصُّدَائِيِّ', 'സിയാദുബ്നുൽ ഹാരിസുസ്സുദാഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ رَضِيَ اللهُ عَنْهُ قَالَ: أَخْبَرَنِي رَجُلَانِ أَنَّهُمَا أَتَيَا رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ وَهُوَ يُقَسِّمُ الصَّدَقَةَ، فَسَأَلَاهُ مِنْهَا، فَرَفَعَ فِينَا الْبَصَرَ وَخَفَضَهُ، فَرَآنَا جَلْدَيْنِ، فَقَالَ: "إِنْ شِئْتُمَا أَعْطَيْتُكُمَا، وَلَا حَظَّ فِيهَا لِغَنِيٍّ وَلَا لِقَوِيٍّ مُكْتَسِبٍ". (د,ن)', 'ഉബൈദുല്ലാഹിബ്നു അദിയ്യിബ്നുഖിയാർ(റ): ഹജ്ജതുൽ വദാഇൽ സകാതു വീതിച്ചുകൊണ്ടിരുന്ന റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നതായി രണ്ടാളുകൾ എനിക്കു പറഞ്ഞുതന്നു. എന്നിട്ട് അവർ അവിടുത്തോടു സകാത്ത് ആവശ്യപ്പെട്ടു. അവിടന്ന് ഞങ്ങളെ തുറിച്ചുനോക്കി. തുടർന്നു ദൃഷ്ടി താഴ്ത്തി. ഞങ്ങൾ യുവാക്കളാ(ആരോഗ്യമുള്ളവരാ)ണെന്ന് അഭിപ്രായപ്പെട്ടു. എന്നിട്ടു പറഞ്ഞു: "നിങ്ങൾക്കുദ്ദേശ്യമുണ്ടെങ്കിൽ ഞാൻ തരാം. (എന്നാൽ) അതിൽ സമ്പന്നനോ, തൊഴിലെടുക്കുവാൻ ശക്തനായവനോ വിഹിതമില്ല." (ദ,ന)', 'عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ', 'ഉബൈദുല്ലാഹിബ്നു അദിയ്യിബ്നുഖിയാർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ النَّاسَ – وَلَهُ مَا يُغْنِيهِ – جَاءَ يَوْمَ الْقِيَامَةِ وَمَسْأَلَتُهُ فِي وَجْهِهِ خُمُوشٌ، أَوْكَخُدُوشٍ، أَوْ: كُدُوحٌ". قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا يُغْنِيهِ؟ قَالَ: "خَمْسُونَ دِرْهَمًا، أَوْ قِيمَتُهَا مِنَ الذَّهَبِ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) അരുളി: "തനിക്കു മതിയായതുണ്ടായിരിക്കെ ഒരുത്തൻ ജനങ്ങളോടു യാചിച്ചാൽ അവൻ അന്ത്യനാളിൽ വരുന്നതു യാചന അവന്റെ മുഖത്തു പതിഞ്ഞ അടയാളവുമായാവും. തിരുനബി(സ)യോട് ചോദിച്ചു: മതിയാകുന്നതിന്റെ പരിധിയെത്രയാണ്, അല്ലാഹുവിന്റെ റസൂലേ! അവിടുന്നരുളി: "അമ്പതു ദിർഹമോ, അല്ലെങ്കിൽ സ്വർണത്തിൽനിന്നുള്ള അതിന്റെ മൂല്യമോ ആണ്." (ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فِي ثِمَارٍ ابْتَاعَهَا، فَكَثُرَ دَيْنُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "تَصَدَّقُوا عَلَيْهِ". فَتَصَدَّقَ النَّاسُ عَلَيْهِ فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لِغُرَمَائِهِ: "خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ". (م,ت)', 'അബുസഈദുൽ ഖുദ്രി(റ): തിരുദൂതർ(സ)യുടെ കാലത്ത് ഒരാൾക്ക് അയാൾ വാങ്ങിയ ഫലങ്ങളിൽ ആപത്ത് നേരിട്ടു. അയാളുടെ കടം അധികമായി. അപ്പോൾ റസൂൽ(സ) അരുളി: "അയാൾക്ക് നിങ്ങൾ സകാത്ത് നൽകുക." ജനങ്ങൾ അയാൾക്ക് സകാത്ത് നൽകിയെങ്കിലും തന്റെ കടം വീട്ടിത്തീർക്കാൻ കഴിഞ്ഞില്ല. അപ്പോൾ റസൂൽ(സ) കടബാധിതരോടായി പറഞ്ഞു: "നിങ്ങൾക്കു കിട്ടിയത് എടുത്തുകൊള്ളുക. നിങ്ങൾക്ക് അതല്ലാതെ മറ്റൊന്നുമില്ല." (മു,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ الْمِسْكِينُ الَّذِي يَطُوفُ عَلَى النَّاسِ تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ وَالتَّمْرَةُ وَالتَّمْرَتَانِ، وَلَكِنِ الْمِسْكِينُ، الَّذِي لَا يَجِدُ غِنًى يُغْنِيهِ، وَلَا يُفْطَنُ بِهِ فَيُتَصَدَّقُ عَلَيْهِ، وَلَا يَقُومُ فَيَسْأَلُ النَّاسَ". (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "ഒന്നോ രണ്ടോ പിടി ആഹാരമോ, ഒന്നോ രണ്ടോ ഈത്തപ്പഴമോ കിട്ടാൻ വേണ്ടി ആളുകൾക്കിടയിൽ ചുറ്റിത്തിരിയുന്നവനല്ല ''മിസ്കീൻ''. പിന്നെയോ, അവനു മതിയാകുന്ന സമ്പത്തില്ല, അവന്റെ യഥാർത്ഥ നിലപാടു അറിയപ്പെടാത്തത് കാരണം ആരും അവന് ദാനം ചെയ്യുന്നുമില്ല, അവൻ ജനങ്ങളുടെ മുമ്പിൽ ചെന്നു യാചിക്കുന്നുമില്ല; അങ്ങനെയുള്ളവനാണ് മിസ്കീൻ.*" (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '* ഒരു യഥാർത്ഥ മിസ്കീൻ തന്റെ യഥാർത്ഥ അവസ്ഥ ഒരിക്കലും പുറത്ത് അറിയിക്കുകയില്ല. അത് കൊണ്ടാണ് ജനങ്ങൾ അയാൾക്ക് ഒന്നും നൽകാത്തത്. അങ്ങനെയുള്ളവനാണ് യഥാർത്ഥ മിസ്കീൻ എന്നാണ് തിരുവചനങ്ങളിൽ വ്യക്തമാകുന്നത്.', null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ، وَالْأَكْلَةُ وَالْأَكْلَتَانِ، وَلَكِنَّ الْمِسْكِينَ – وَفِي رِوَايَةٍ: الْمُتَعَفِّفُ – الَّذِي لَا يَسْأَلُ النَّاسَ شَيْئًا، وَلَا يَفْطِنُونَ بِهِ فَيُعْطُونَهُ". وَفِي رِوَايَةٍ: "لَيْسَ لَهُ مَا يَسْتَغْنِي بِهِ الَّذِي لَا يَسْأَلُ، وَلَا يُعْلَمُ بِحَاجَتِهِ فَيُتَصَدَّقَ عَلَيْهِ، فَذَاكَ الْمَحْرُومُ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "ഒന്നോ രണ്ടോ പിടി ആഹാരംകൊണ്ടോ ഒന്നോ രണ്ടോ ഈത്തപ്പഴംകൊണ്ടോ മടങ്ങുന്നവനല്ല മിസ്കീൻ; സച്ചരിതത്ത്വം പാലിക്കുന്ന, ജനങ്ങളോട് ഒന്നും ചോദിക്കുകയോ ജനങ്ങൾ അവന്റെ നിലപാടു ഗ്രഹിച്ച് നൽകുകയോ ചെയ്യാത്ത വ്യക്തിയാണ് മിസ്കീൻ." മറ്റൊരു നിവേദനത്തിൽ: "ചോദിക്കാതിരിക്കാൻ മാത്രമുള്ള സമ്പത്ത് അവനില്ല. അവന്റെ ദാരിദ്ര്യം അറിയപ്പെടാത്തത് കൊണ്ട് അവന് സകാത്ത് നൽകപ്പെടുകയുമില്ല. അവനാണ് മഹ്റൂം (നിർധനൻ)." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=195), 1, 'وَفِي رِوَايَةٍ: الْمُتَعَفِّفُ – الَّذِي لَا يَسْأَلُ النَّاسَ شَيْئًا، وَلَا يَفْطِنُونَ بِهِ فَيُعْطُونَهُ".', 'മറ്റൊരു നിവേദനത്തിൽ: "ചോദിക്കാതിരിക്കാൻ മാത്രമുള്ള സമ്പത്ത് അവനില്ല. അവന്റെ ദാരിദ്ര്യം അറിയപ്പെടാത്തത് കൊണ്ട് അവന് സകാത്ത് നൽകപ്പെടുകയുമില്ല. അവനാണ് മഹ്റൂം (നിർധനൻ)." (ബു,മു,ദ,ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=195), 2, 'وَفِي رِوَايَةٍ: "لَيْسَ لَهُ مَا يَسْتَغْنِي بِهِ الَّذِي لَا يَسْأَلُ، وَلَا يُعْلَمُ بِحَاجَتِهِ فَيُتَصَدَّقَ عَلَيْهِ، فَذَاكَ الْمَحْرُومُ". (ق,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ، وَاللُّقْمَةُ وَاللُّقْمَتَانِ، إِنَّ الْمِسْكِينَ الْمُتَعَفِّفُ، اقْرَءُوا إِنْ شِئْتُمْ: {لَا يَسْأَلُونَ النَّاسَ إِلْحَافًا}". [البقرة: ٢٧٣] وَفِي رِوَايَةٍ: "لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ وَالتَّمْرَةُ وَالتَّمْرَتَانِ". قَالُوا: فَمَا الْمِسْكِينُ يَا رَسُولَ اللَّهِ؟ قَالَ: "الَّذِي لَا يَجِدُ غِنًى، وَلَا يَعْلَمُ النَّاسُ حَاجَتَهُ فَيُتَصَدَّقَ عَلَيْهِ". (ن)', 'അബൂഹുറൈറ(റ): "നിശ്ചയം റസൂൽ(സ) അരുളി: "ഒന്നോ രണ്ടോ പിടി ആഹാരം കൊണ്ടോ ഒന്നോ രണ്ടോ ഈത്തപ്പഴംകൊണ്ടോ മടങ്ങുന്നവനല്ല മിസ്കീൻ. വിശുദ്ധി കാണിക്കുന്നവനാണ് യഥാർത്ഥ മിസ്കീൻ. എന്നാൽ നിങ്ങൾക്ക് വേണമെങ്കിൽ പാരായണംചെയ്യുക: ''അവർ ജനങ്ങളോട് വിഷമിപ്പിക്കും വിധം ചോദിക്കുകയില്ല.'' (അൽബഖറ: 273)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=196), 1, 'وَفِي رِوَايَةٍ: "لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ وَالتَّمْرَةُ وَالتَّمْرَتَانِ". قَالُوا: فَمَا الْمِسْكِينُ يَا رَسُولَ اللَّهِ؟ قَالَ: "الَّذِي لَا يَجِدُ غِنًى، وَلَا يَعْلَمُ النَّاسُ حَاجَتَهُ فَيُتَصَدَّقَ عَلَيْهِ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: നിശ്ചയം റസൂൽ(സ) അരുളി: "ഒന്നോ രണ്ടോ പിടി ആഹാരം കൊണ്ടോ, ഒന്നോ രണ്ടോ കാരക്ക കൊണ്ടോ മടങ്ങുന്നവനല്ല മിസ്കീൻ." അവർ ചോദിച്ചു: ആരാണു മിസ്കീൻ അല്ലാഹുവിന്റെ റസൂലേ? അവിടന്നരുളി: "സമ്പത്തില്ലാത്ത്വൻ; അവന്റെ അവസ്ഥ അറിയാത്തത് കാരണം ജനങ്ങൾ അവന് സ്വദഖ നൽകുകയുമില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أُمِّ بُجَيْدٍ رَضِيَ اللهُ عَنْهَا – وَكَانَتْ مِمَّنْ بَايَعَتْ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ– أَنَّهَا قَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: إِنَّ الْمِسْكِينَ لَيَقُومُ عَلَى بَابِي، فَمَا أَجِدُ لَهُ شَيْئًا أُعْطِيهِ إِيَّاهُ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنْ لَمْ تَجِدِي شَيْئًا تُعْطِينَهُ إِيَّاهُ إِلَّا ظِلْفًا مُحْرَقًا فَادْفَعِيهِ إِلَيْهِ". (د,ت,ن)', 'ഉമ്മുബുജൈദ്(റ) (മഹതി റസൂൽ(സ)യോട് ഉടമ്പടി ചെയ്തവരിൽപ്പെട്ടവരായിരുന്നു.): അവർ ഒരിക്കൽ റസൂൽ(സ)യോട് ചോദിച്ചു: എന്റെ വീട്ടുപടിക്കൽ ഒരു മിസ്കീൻ വന്നു നിൽക്കുകയും എന്നാൽ, അയാൾക്കു കൊടുക്കാൻ എന്റെയടുത്ത് ഒന്നും ഇല്ലാതിരിക്കുകയും ചെയ്താൽ എന്ത് ചെയ്യണം? അപ്പോൾ അവിടുന്നരുളി: "വേവിച്ച ആട്ടിൻകുളമ്പൊഴികെ ഒന്നും നിനക്കു കിട്ടിയില്ല എങ്കിൽ അതെങ്കിലും നീ അയാൾക്ക് കൊടുത്തേക്കണം." (ദ,തു,ന)', 'أُمِّ بُجَيْدٍ', 'ഉമ്മുബുജൈദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أَبُو طَلْحَةَ أَكْثَرَ الْأَنْصَارِ بِالْمَدِينَةِ مَالًا مِنْ نَخْلٍ، وَكَانَ أَحَبُّ أَمْوَالِهِ إِلَيْهِ بَيْرُحَاءَ، وَكَانَتْ مُسْتَقْبِلَةَ الْمَسْجِدِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَدْخُلُهَا وَيَشْرَبُ مِنْ مَاءٍ فِيهَا طَيِّبٍ، قَالَ أَنَسٌ: فَلَمَّا أُنْزِلَتْ هَذِهِ الْآيَةُ: {لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ}، قَامَ أَبُو طَلْحَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ: {لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ} وَإِنَّ أَحَبَّ أَمْوَالِي إِلَيَّ بَيْرُحَاءَ، وَإِنَّهَا صَدَقَةٌ لِلَّهِ أَرْجُو بِرَّهَا وَذُخْرَهَا عِنْدَ اللَّهِ، فَضَعْهَا يَا رَسُولَ اللَّهِ حَيْثُ أَرَاكَ اللَّهُ، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "بَخٍ ذَلِكَ مَالٌ رَابِحٌ، ذَلِكَ مَالٌ رَابِحٌ، وَقَدْ سَمِعْتُ مَا قُلْتَ، وَإِنِّي أَرَى أَنْ تَجْعَلَهَا فِي الْأَقْرَبِينَ". فَقَالَ أَبُو طَلْحَةَ: أَفْعَلُ يَا رَسُولَ اللَّهِ، فَقَسَمَهَا أَبُو طَلْحَةَ فِي أَقَارِبِهِ وَبَنِي عَمِّهِ. (ق)', 'അനസുബ്നു മാലിക്(റ): അബൂത്വൽഹ അൻസാരികളുടെ കൂട്ടത്തിൽ ഏറ്റവും കൂടുതൽ ഈത്തപ്പന സമ്പത്തുള്ള വ്യക്തിയായിരുന്നു. തന്റെ ധനത്തിൽവെച്ചേറ്റവും അദ്ദേഹത്തിന് പ്രിയപ്പെട്ടത് ബൈറുഹാഅ് തോട്ടമായിരുന്നു. അതു പള്ളിയുടെ മുൻവശത്താണു സ്ഥിതിചെയ്തിരുന്നത്. റസൂൽ(സ) അതിൽ ചിലപ്പോൾ കടന്നു ശുദ്ധജലം കുടിക്കാറുണ്ടായിരുന്നു. ''നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതിൽനിന്നു നിങ്ങൾ ചെലവഴിക്കുംവരേക്കും നിങ്ങൾ പുണ്യം കൈവരിക്കുകയില്ല'' എന്ന ഖുർആൻ വാക്യം അവതരിച്ചപ്പോൾ അബൂത്വൽഹ(റ) തിരുദൂതർ(സ)യോട് പറഞ്ഞു: എന്റെ സമ്പത്തിൽ ഏറ്റവും പ്രിയപ്പെട്ടതു ബൈറുഹാ തോട്ടമാണ്. അത് അല്ലാഹുവിന്റെ മാർഗത്തിൽ ഞാനിതാ ദാനം ചെയ്യുന്നു. അതിന്റെ പുണ്യം അല്ലാഹുവിങ്കൽ സൂക്ഷിക്കപ്പെടുമെന്നു ഞാനാശിക്കുന്നു. അല്ലാഹു അങ്ങേക്കു തോന്നിപ്പിച്ചുതരുന്ന വിധത്തിൽ അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങത് വെക്കുക. അവിടന്നരുളി: "വളരെ നല്ലത്, അത് നിങ്ങൾക്കു ലാഭമുണ്ടാക്കിത്തരുന്ന സ്വത്താണ്, തീർച്ചയായും അത് നിങ്ങൾക്കു ലാഭമുണ്ടാക്കിത്തരുന്ന സ്വത്താണ്. താങ്കൾ പറഞ്ഞത് ഞാൻ ഗ്രഹിച്ചിരിക്കുന്നു. നിങ്ങൾ അതു നിങ്ങളുടെ അടുത്ത കുടുംബങ്ങൾക്കായി നീക്കിവെക്കണമെന്നാണെന്റെ അഭിപ്രായം." അബൂത്വൽഹ(റ) പറഞ്ഞു: ഞാനങ്ങനെ ചെയ്യാം അല്ലാഹുവിന്റെ ദൂതരേ. ശേഷം അദ്ദേഹം അതു തന്റെ അടുത്ത കുടുംബങ്ങൾക്കും പിതൃവ്യപുത്രന്മാർക്കും വീതിച്ചുകൊടുത്തു. (ബു,മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 210, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: حَدِيثُهُ فِي خُرُوجِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ إِلَى الْمُصَلَّى، تَقَدَّمَ، وَفِي هذه الرواية قَالَ: فَلَمَّا صَارَ إِلَى مَنْزِلِهِ جَاءَتْ زَيْنَبُ امْرَأَةُ ابْنِ مَسْعُودٍ تَسْتَأْذِنُ عَلَيْهِ، فَقِيلَ: يَا رَسُولَ اللَّهِ: هَذِهِ زَيْنَبُ فَقَالَ: أَيُّ الزَّيَانِبِ؟ فَقِيلَ امْرَأَةُ ابْنِ مَسْعُودٍ، قَالَ: نَعَمْ ائْذَنُوا لَهَا فَأُذِنَ لَهَا قَالَتْ: يَا نَبِيَّ اللَّهِ إِنَّكَ أَمَرْتَ الْيَوْمَ بِالصَّدَقَةِ، وَكَانَ عِنْدِي حُلِيٌّ لِي، فَأَرَدْتُ أَنْ أَتَصَدَّقَ بِهِ فَزَعَمَ ابْنُ مَسْعُودٍ، أَنَّهُ وَوَلَدَهُ أَحَقُّ مَنْ تَصَدَّقْتُ بِهِ عَلَيْهِمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "صَدَقَ ابْنُ مَسْعُودٍ زَوْجُكِ وَوَلَدُكِ أَحَقُّ مَنْ تَصَدَّقْتِ بِهِ عَلَيْهِمْ". (خ)', 'അബുസഈദുൽ ഖുദ്രി(റ): നമസ്കാരസ്ഥലത്തേക്കു റസൂൽ(സ) പോയതിനെപ്പറ്റിയുള്ള ഹദീസ് മുമ്പ് പറഞ്ഞു. ഈ നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്. റസൂൽ(സ) വീട്ടിലെത്തിയപ്പോൾ ഇബ്നുമസ്ഊദ്(റ)വിന്റെ ഭാര്യ സൈനബ്(റ) തിരുമേനി(സ)യുടെ സന്നിധിയിൽ വരാൻ സമ്മതം ചോദിച്ചു. ചിലർ പറഞ്ഞു: ഇതാ സൈനബ്. അവിടന്ന് ചോദിച്ചു: "ഏതു സൈനബ്?" ഇബ്നു മസ്ഊദ്(റ)വിന്റെ ഭാര്യ എന്നൊരാൾ പറഞ്ഞു: "ശരി അവൾക്കനുവാദം നൽകൂ" എന്നവിടുന്നരുളി. അപ്പോഴവർക്ക് അനുവാദം ലഭിച്ചു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അങ്ങ് ഇന്നു ദാനംചെയ്യാൻ കൽപിച്ചല്ലോ. എന്റെയടുത്ത് ഒരാഭരണമുണ്ടായിരുന്നു. ഞാനത് ദാനംചെയ്യാൻ ഉദ്ദേശിച്ചു. ഞാൻ നൽകുന്ന ദാനം വാങ്ങാൻ കൂടുതൽ അവകാശപ്പെട്ടവൻ ഇബ്നുമസ്ഊദ്(റ)വും അദ്ദേഹത്തിന്റെ പുത്രനുമാണെന്ന് ഇബ്നുമസ്ഊദ്(റ) വാദിക്കുന്നു. അവിടുന്നരുളി: "ഇബ്നുമസ്ഊദ് പറഞ്ഞത് ശരിയാണ്. നിന്റെ ദാനം വാങ്ങാൻ ഏറ്റവും അവകാശപ്പെട്ടതു നിന്റെ ഭർത്താവും മകനും തന്നെയാണ്." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ زَيْنَبَ امْرَأَةِ عَبْدِاللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا حَدِيثُهَا الْمُتَقَدِّمُ قَرِيبًا وَقَالَتْ فِي هَذِهِ الرِّوَايَةِ: انْطَلَقْتُ إِلَى النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَوَجَدْتُ امْرَأَةً مِنَ الْأَنْصَارِ عَلَى الْبَابِ حَاجَتُهَا مِثْلُ حَاجَتِي، فَمَرَّ عَلَيْنَا بِلَالٌ، فَقُلْنَا: سَلِ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَيَجْزِي عَنِّي أَنْ أُنْفِقَ عَلَى زَوْجِي وَأَيْتَامٍ لِي فِي حَجْرِي، قَالَ: "نَعَمْ، لَهَا أَجْرَانِ أَجْرُ الْقَرَابَةِ وَأَجْرُ الصَّدَقَةِ". (خ,جه)', 'ഇബ്നുമസ്ഊദ്(റ)വിന്റെ ഭാര്യ സൈനബ്(റ): അവരുടെ ഹദീസ് തൊട്ടുമുമ്പു കഴിഞ്ഞുപോയി. ഈ നിവേദനത്തിൽ അവർ പറഞ്ഞു: തിരുനബി(സ)യുടെ സന്നിധിയിലേക്കു ഞാൻ ചെന്നു. അപ്പോൾ ഒരു അൻസ്വാരി സ്ത്രീ എന്റെ അതേ ആവശ്യവുമായി കവാടത്തിൽ നിൽക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞങ്ങൾക്കരികിലൂടെ ബിലാൽ(റ) കടന്നുപോയി. ഞങ്ങൾ ആവശ്യപ്പെട്ടു. നിങ്ങൾ തിരുനബി(സ)യോടു ചോദിക്കുക. എന്റെ ഭർത്താവിനും എന്റെ അധീനത്തിലുള്ള അനാഥക്കുട്ടികൾക്കും ഞാൻ ചെലവഴിച്ചാൽ എനിക്കതു മതിയാവുമോ എന്ന്. അവിടന്ന് പറഞ്ഞു: "അതെ, അവൾക്കു രണ്ടു പ്രതിഫലമുണ്ട്. കുടുംബബന്ധം ചേർത്തതിന്റെ പ്രതിഫലവും സ്വദഖയുടെ പ്രതിഫലവും." (ബു,ജ)', 'زَيْنَبَ امْرَأَةِ عَبْدِاللَّهِ بْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَلِيَ أَجْرٌ أَنْ أُنْفِقَ عَلَى بَنِي أَبِي سَلَمَةَ؟ إِنَّمَا هُمْ بَنِيَّ، فَقَالَ: "أَنْفِقِي عَلَيْهِمْ، فَلَكِ أَجْرُ مَا أَنْفَقْتِ عَلَيْهِمْ". (خ)', 'ഉമ്മുസലമ(റ): അല്ലാഹുവിന്റെ റസൂലേ, ബനുസലമയുടെ മക്കൾക്കു ഞാൻ ദാനം ചെയ്താൽ എനിക്കു പ്രതിഫലം കിട്ടുമോ? അവർ എന്റെ മക്കൾതന്നെയാണ്. അവിടന്നരുളി: "അവർക്കു നീ ചെലവഴിച്ചുകൊള്ളുക. അവർക്കു ചെലവഴിച്ചതിന്റെ പ്രതിഫലം നിനക്കുണ്ട്." (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ". (خ)', 'ഹകീമുബ്നു ഹിസാം(റ): തിരുമേനി(സ) അരുളി: "താഴെയുള്ള കൈയെക്കാൾ മേലെയുള്ള കൈയാണ് ഉത്തമം. നീ പരിപാലിക്കേണ്ടവർക്ക് ആദ്യം കൊടുക്കുക. പരാശ്രയരഹിതമായ നിലയിൽ നൽകുന്ന ദാനമാണ് ഏറ്റവും ഉത്തമം. വല്ലവനും അന്യരോട് ധനസഹായം ആവശ്യപ്പെടാതെ അകന്നുനിന്നാൽ അല്ലാഹു അവനെ ഈ ദുരവസ്ഥകളിൽ നിന്ന് അകറ്റിനിർത്തും. വല്ലവനും പരാശ്രിതനല്ലാതെ ജീവിക്കാൻ ഉദ്ദേശിച്ചാൽ അല്ലാഹു അവനെ പരാശ്രയനല്ലാതാക്കും." (ബു)', 'حَكِيمِ بْنِ حِزَامٍ', 'ഹകീമുബ്നു ഹിസാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ وَلَوْ مِنْ حُلِيِّكُنَّ". قَالَتْ: فَرَجَعْتُ إِلَى عَبْدِ اللَّهِ فَقُلْتُ: إِنَّكَ رَجُلٌ خَفِيفُ ذَاتِ الْيَدِ، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَنَا بِالصَّدَقَةِ، فَأْتِهِ فَاسْأَلْهُ، فَإِنْ كَانَ ذَلِكَ يَجْزِي عَنِّي، وَإِلَّا صَرَفْتُهَا إِلَى غَيْرِكُمْ. قَالَتْ: فَقَالَ لِي عَبْدُ اللَّهِ: بَلِ ائْتِيهِ أَنْتِ. قَالَتْ: فَانْطَلَقْتُ فَإِذَا امْرَأَةٌ مِنَ الْأَنْصَارِ بِبَابِ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ حَاجَتِي حَاجَتُهَا، قَالَتْ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَدْ أُلْقِيَتْ عَلَيْهِ الْمَهَابَةُ، قَالَتْ: فَخَرَجَ عَلَيْنَا بِلَالٌ، فَقُلْنَا لَهُ: ائْتِ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَأَخْبِرْهُ أَنَّ امْرَأَتَيْنِ بِالْبَابِ تَسْأَلَانِكَ: أَتُجْزِئُ الصَّدَقَةُ عَنْهُمَا عَلَى أَزْوَاجِهِمَا وَعَلَى أَيْتَامٍ فِي حُجُورِهِمَا؟ وَلَا تُخْبِرْهُ مَنْ نَحْنُ. قَالَتْ: فَدَخَلَ بِلَالٌ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ هُمَا؟". فَقَالَ: امْرَأَةٌ مِنَ الْأَنْصَارِ وَزَيْنَبُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "أَيُّ الزَّيَانِبِ". قَالَ: امْرَأَةُ عَبْدِ اللَّهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَهُمَا أَجْرَانِ: أَجْرُ الْقَرَابَةِ، وَأَجْرُ الصَّدَقَةِ". (ق,ن)', 'അബ്ദുല്ല(റ)വിന്റെ ഭാര്യ സൈനബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓ സ്ത്രീകളേ, നിങ്ങൾ ധർമ്മം ചെയ്യുക. അത് നിങ്ങളുടെ ആഭരണങ്ങളിൽ നിന്നാണെങ്കിലും." സൈനബ്(റ) പറയുന്നു: ഞാൻ അബ്ദുല്ല(റ)വിന്റെ അടുക്കൽ മടങ്ങിച്ചെന്ന് ചോദിച്ചു: നിങ്ങൾ ദരിദ്രനാണ്. റസൂൽ(സ) ഞങ്ങളോട് ധർമ്മം ചെയ്യാൻ കൽപിച്ചിരിക്കുന്നു. നിങ്ങൾ തിരുനബി(സ)യോട് ചെന്ന് ചോദിക്കുക. അത് ഞാൻ താങ്കൾക്ക് തന്നാൽ മതിയാകുമോയെന്ന്. അത് മതിയാകില്ലെങ്കിൽ ഞാനത് മറ്റുള്ളവർക്ക് ചെലവഴിക്കും. സൈനബ്(റ) പറഞ്ഞു: അപ്പോൾ എന്നോട് അബ്ദുല്ല(റ) പറഞ്ഞു: നബി(സ)യുടെ അടുത്ത് നീ പോകുക. ഞാൻ ചെന്നപ്പോൾ അൻസാറുകളിൽ പെട്ട ഒരു സ്ത്രീ എന്റെ അതേ ആവശ്യവുമായി റസൂൽ(സ)യുടെ വാതിൽക്കൽ നിൽക്കുന്നു. റസൂൽ(സ)യിൽ ഗാംഭീര്യം തോന്നിക്കുന്നു. ബിലാൽ(റ) ഞങ്ങളുടെ അടുത്ത് വന്നു. ഞങ്ങൾ അദ്ദേഹത്തോട് പറഞ്ഞു: നിങ്ങൾ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് അവിടത്തോട് പറയുക. സ്വന്തം ഭർത്താക്കൻമാർക്കും തങ്ങൾ വളർത്തുന്ന അനാഥകൾക്കും തങ്ങളുടെ സ്വദഖ നൽകിയാൽ വീടുമോയെന്ന് ചോദിക്കുന്ന രണ്ട് സ്ത്രീകൾ വാതിൽക്കൽ നിൽക്കുന്നുണ്ട്. ഞങ്ങൾ ആരാണെന്ന് തിരുനബി(സ)യോട് പറയരുത്. ബിലാൽ(റ) റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആ രണ്ടു പേർ ആരാണ്?" ബിലാൽ(റ) പറഞ്ഞു: അൻസാറുകളിൽ പെട്ട ഒരു സ്ത്രീയും, സൈനബും. റസൂൽ(സ) ചോദിച്ചു: "ഏത് സൈനബ്?" ബിലാൽ(റ) പറഞ്ഞു: അബ്ദുല്ലായുടെ ഭാര്യ. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അവർക്ക് രണ്ട് പ്രതിഫലമുണ്ട്. കുടുംബത്തിന്റെ പ്രതിഫലവും ധർമ്മത്തിന്റെ പ്രതിഫലവും." (ബു,മു,ന)', 'زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ', 'അബ്ദുല്ല(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ – قَالَتْ: كَانَتْ لِي جَارِيَةٌ فَأَعْتَقْتُهَا، فَدَخَلَ عَلَيَّ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَقَالَ: "آجَرَكِ اللَّهُ، أَمَا إِنَّكِ لَوْ كُنْتِ أَعْطَيْتِهَا أَخْوَالَكِ كَانَ أَعْظَمَ لِأَجْرِكِ". (ق,د,ن)', 'നബി(സ)യുടെ പത്നി മൈമൂന(റ): എനിക്കൊരു അടിമസ്ത്രീയുണ്ടായിരുന്നു. ഞാനവളെ മോചിപ്പിച്ചു: എന്റെയടുത്ത് നബി(സ) വന്നപ്പോൾ ഞാൻ അവിടത്തോട് വിവരം പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കല്ലാഹു പ്രതിഫലം നൽകട്ടെ. അത് നിങ്ങളുടെ അമ്മാവൻമാർക്ക് നൽകിയിരുന്നെങ്കിൽ, അത് നിങ്ങളുടെ പ്രതിഫലം വലുതാക്കുമായിരുന്നു." (ബു,മു,ദ,ന)', 'مَيْمُونَةَ', 'നബി(സ)യുടെ പത്നി മൈമൂന(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 212, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: قُلْتُ يَا رَسُولَ اللهِ، إِنَّ أُمِّي قَدِمَتْ عَلَيَّ، وَهِيَ رَاغِبَةٌ أَوْ رَاهِبَةٌ أَفَأَصِلُهَا؟ قَالَ: "نَعَمْ". (ق,د)', 'അബുബക്കർ(റ)ന്റെ മകൾ അസ്മാഅ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ മാതാവ് പ്രതീക്ഷയർപ്പിച്ച് എന്റെ അടുത്തേക്ക് വന്നിരിക്കുന്നു. ഞാനവരെ ബന്ധം ചേർക്കട്ടെയോ? അവിടുന്നരുളി: "അതെ." (ബു,മു,ദ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അബുബക്കർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ: {لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ} [آل عمران:٩٢] قَالَ أَبُو طَلْحَةَ: يَا رَسُولَ اللَّهِ، أَرَى رَبَّنَا يَسْأَلُنَا مِنْ أَمْوَالِنَا، فَإِنِّي أُشْهِدُكَ أَنِّي قَدْ جَعَلْتُ أَرْضِي بِأَرِيحَاءَ لَهُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "اجْعَلْهَا فِي قَرَابَتِكَ". فَقَسَمَهَا بَيْنَ حَسَّانَ بْنِ ثَابِتٍ وَأُبَيِّ بْنِ كَعْبٍ. (ق,د,ن)', 'അനസ്(റ): ''നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതിൽനിന്നു ചെലവഴിക്കുംവരെ നിങ്ങൾ നന്മ കൈവരിക്കുകയില്ല'' (ആലുഇംറാൻ: 92) എന്ന ആയത് അവതരിച്ചപ്പോൾ അബൂത്വൽഹ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! നമ്മുടെ സ്വത്തിൽ നിന്നാണ് ചോദിക്കുന്നത് എന്ന് എനിക്കു മനസിലാകുന്നു. ഞാൻ എന്റെ ബൈറുഹാഅ് ഭൂമി അല്ലാഹുവിനു സമർപ്പിച്ചതായി അങ്ങയെ സാക്ഷിനിർത്തുന്നു. "നിങ്ങൾ അത് നിങ്ങളുടെ അടുത്ത ബന്ധുക്കൾക്ക് നീക്കിവക്കുക." എന്ന് അവിടന്നരുളി. അപ്പോൾ അദ്ദേഹമതു ഹസ്സാനുബ്നുസാബിത്(റ)വിനും ഉബയ്യിബ്നു കഅ്ബ്(റ)വിനും ഭാഗിച്ചുകൊടുത്തു. (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], 'آل عمران:٩٢', null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِالصَّدَقَةِ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، عِنْدِي دِينَارٌ. فَقَالَ: "تَصَدَّقْ بِهِ عَلَى نَفْسِكَ". قَالَ: عِنْدِي آخَرُ، قَالَ: "تَصَدَّقْ بِهِ عَلَى وَلَدِكَ". قَالَ: عِنْدِي آخَرُ، قَالَ: "تَصَدَّقْ بِهِ عَلَى زَوْجَتِكَ". أَوْ قَالَ: "زَوْجِكَ". قَالَ: عِنْدِي آخَرُ، قَالَ: "تَصَدَّقْ بِهِ عَلَى خَادِمِكَ". قَالَ: عِنْدِي آخَرُ، قَالَ: "أَنْتَ أَبْصَرُ". (د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ധർമം ചെയ്യാൻ കൽപിച്ചു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പക്കൽ ഒരു ദീനാറുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "നീ അത് നിനക്കുതന്നെ ധർമം ചെയ്യുക." അയാൾ പറഞ്ഞു: മറ്റൊന്നുകൂടിയുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "നിന്റെ മകന് ധർമ്മം ചെയ്യുക." അയാൾ പറഞ്ഞു: ഇനിയും ഉണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "അതു നിന്റെ ഭാര്യക്കു ധർമം ചെയ്യുക." അയാൾ പറഞ്ഞു: എന്റടുത്തു മറ്റൊന്ന് കൂടിയുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "നീ അതു നിന്റെ സേവകന് ധർമം ചെയ്യുക." അയാൾ പറഞ്ഞു: എന്റെ പക്കൽ വേറെയുമുണ്ട്. തിരുമേനി(സ): "നീ നല്ല ഉൾകാഴ്ചയുള്ളവനാണ്." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُضَيِّعَ مَنْ يَقُوتُ". (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) അരുളി: "തന്നെ ആശ്രയിച്ച് കഴിയുന്നവരെ വെടിയുകയെന്നതു തന്നെ അവൻ ചെയ്യുന്ന വലിയൊരു കുറ്റമാണ്." (മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ سَرَّهُ أَنْ يُبْسَطَ عَلَيْهِ فِي رِزْقِهِ، وَيُنْسَأَ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ". (ق,د,ن)', 'അനസ്(റ): റസൂൽ(സ) അരുളി: "ഒരാൾ തന്റെ ആഹാരം വിശാലമാകുന്നതിലും ആയുസ്സു വർദ്ധിക്കുന്നതിലും സന്തോഷിക്കുന്നെങ്കിൽ അവൻ കുടുംബബന്ധം ചേർത്തുകൊള്ളട്ടെ." (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 213, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللَّهُ: أَنَا الرَّحْمَنُ، وَهِيَ الرَّحِمُ، شَقَقْتُ لَهَا اسْمًا مِنْ اِسْمِي، مَنْ وَصَلَهَا وَصَلْتُهُ، وَمَنْ قَطَعَهَا بَتَتُّهُ". (د,ت)', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹു പറഞ്ഞു: ഞാൻ റഹ്മാനാ(കാരുണ്യവാൻ)ണ്. അത് റഹ്മ് (കുടുംബബന്ധം) ആണ്. അതിന് ഞാൻ എന്റെ നാമത്തിൽനിന്ന് ഒരു നാമം മുറിച്ചുനൽകിയതാണ്. ആരെങ്കിലുമതിനെ ചേർത്താൽ ഞാനവനെ ചേർത്തു. ആരെങ്കിലും അതിനെ വേർപെടുത്തിയാൽ ഞാനവനെ വേർപെടുത്തി." (ദ,തു)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ قَاطِعُ رَحِمٍ". (ق,د,ت)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) അരുളി: "കുടുംബബന്ധം മുറിക്കുന്നവൻ സ്വർഗത്തിൽ പ്രവേശിക്കുകയില്ല." (ബു,മു,ദ,തു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنْ هُوَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا". (خ,د,ت)', 'അബ്ദുല്ലാഹുബ്നു അംറ്(റ): റസൂൽ(സ) അരുളി: "കുടുംബബന്ധം ചേർക്കുന്നവനെന്നാൽ ചെയ്തതിന് പകരം ചെയ്യുന്നവനല്ല. വേർപെട്ട ബന്ധം കൂട്ടിയിണക്കുന്നവനാണു (യഥാർത്ഥ) കുടുംബം ചേർക്കുന്നവൻ." (ബു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹുബ്നു അംറ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ سَلْمَانَ ابْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ، فَإِنَّهُ بَرَكَةٌ. فَإِنْ لَمْ يَجِدْ تَمْرًا فَالْمَاءُ، فَإِنَّهُ طَهُورٌ". وَقَالَ: "الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ، وَهِيَ عَلَى ذِي الرَّحِمِ ثِنْتَانِ: صَدَقَةٌ وَصِلَةٌ". (د,ت,ن,جه)', 'സൽമാനുബ്നു ആമിർ(റ): നബി(സ) അരുളി: "ആരെങ്കിലും നോമ്പ് തുറക്കുന്നെങ്കിൽ കാരക്കകൊണ്ടു തുറന്നുകൊള്ളട്ടെ. നിശ്ചയം, അതു പുണ്യമുള്ളതാണ്. കാരക്ക കിട്ടിയില്ലെങ്കിൽ വെള്ളംകൊണ്ടാവട്ടെ; അതു ശുദ്ധിയുള്ളതാണ്. ധർമം മിസ്കീനിനാണെങ്കിൽ അതു ധർമമാണ്. അതുതന്നെ കുടുംബത്തിനാണെങ്കിൽ രണ്ടു പ്രതിഫലമുണ്ട്; ധർമവും കുടുംബം ചേർക്കലും." (ദ,തു,ന,ജ)', 'سَلْمَانَ ابْنِ عَامِرٍ', 'സൽമാനുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى، وَالْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏറ്റവും നല്ല ധർമ്മം ഐശ്വര്യ സമയത്തുള്ളതാണ്. മേലെയുള്ള കൈ താഴെയുള്ള കയ്യിനേക്കാൾ ഉത്തമമാണ്. നിന്റെ കുടുംബത്തിൽ നിന്ന് നീ തുടങ്ങുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ وَهُوَ يَحْتَسِبُهَا كَانَتْ لَهُ صَدَقَةً". (ن)', 'അബൂ മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ പ്രതിഫലേച്ഛയോടുകൂടി തന്റെ കുടുംബത്തിനു വേണ്ടി ചെലവഴിച്ചാൽ അത് അവന് ധർമ്മമാണ്." (ന)', 'أَبِي مَسْعُودٍ', 'അബൂ മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَعْتَقَ رَجُلٌ مِنْ بَنِي عُذْرَةَ عَبْدًا لَهُ عَنْ دُبُرٍ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَكَ مَالٌ غَيْرُهُ". قَالَ: لَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "مَنْ يَشْتَرِيهِ مِنِّي". فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللَّهِ الْعَدَوِيُّ بِثَمَانِ مِائَةِ دِرْهَمٍ، فَجَاءَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَدَفَعَهَا إِلَيْهِ، ثُمَّ قَالَ: "ابْدَأْ بِنَفْسِكَ فَتَصَدَّقْ عَلَيْهَا، فَإِنْ فَضَلَ شَيْءٌ فَلِأَهْلِكَ، فَإِنْ فَضَلَ شَيْءٌ عَنْ أَهْلِكَ فَلِذِي قَرَابَتِكَ، فَإِنْ فَضَلَ عَنْ ذِي قَرَابَتِكَ شَيْءٌ فَهَكَذَا وَهَكَذَا". يَقُولُ: بَيْنَ يَدَيْكَ وَعَنْ يَمِينِكَ وَعَنْ شِمَالِكَ. (ن)', 'ജാബിർ(റ): ബനൂഉദ്റത് ഗോത്രത്തിലെ ഒരാൾ തന്റെ മരണശേഷം തന്റെ അടിമയെ മോചിതനായി പ്രഖ്യാപിച്ചു. വിവരം റസൂൽ(സ)യുടെ അടുക്കലെത്തി. അവിടന്ന് ചോദിച്ചു: "നിനക്കു വേറെ മുതലുണ്ടോ". അയാൾ പറഞ്ഞാു: ഇല്ല. അറിടന്ന് ചോദിച്ചു: "ആരാണിവനെ എന്നിൽനിന്ന് വിലക്കുവാങ്ങുന്നത്." എണ്ണൂറ് ദിർഹമിന് നഈമുബ്നു അബ്ദുല്ലാഹിൽ അദവി(റ) എന്നയാൾ അടിമയെ വാങ്ങി. റസൂൽ(സ) വന്ന് അത് അദ്ദേഹത്തിന് കൊടുത്ത് പറഞ്ഞു: "നീ നിന്നെക്കൊണ്ടു തുടങ്ങുക. നിന്റെ ശരീരത്തിനു ധർമം ചെയ്യുക. എന്തെങ്കിലും ശേഷിച്ചാൽ നിന്റെ കുടുംബത്തിനാണ്. കുടുംബത്തെയും കഴിച്ച് വല്ലതും ശേഷിച്ചാൽ നിന്റെ അടുത്ത ബന്ധത്തിൽപെട്ടവർക്കാണ്. നിന്റെ അടുത്ത ബന്ധുക്കളിൽനിന്നും ശേഷിച്ചാൽ ഇപ്രകാരവും ഇപ്രകാരവുമാണ്." അവിടന്ന് പറഞ്ഞു: "നിന്റെ മുന്നിലുള്ളവർ, ഇടഭാഗത്തും, വലഭാഗത്തുമുള്ളവർ എന്നിങ്ങനെയാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 214, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُمِّ سَلَمَةَ قَالَتْ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بِالصَّدَقَةِ، فَقَالَتْ زَيْنَبُ امْرَأَةُ عَبْدِ اللَّهِ: أَيُجْزِينِي مِنَ الصَّدَقَةِ أَنْ أَتَصَدَّقَ عَلَى زَوْجِي وَهُوَ فَقِيرٌ، وَبَنِي أَخٍ لِي أَيْتَامٍ، وَأَنَا أُنْفِقُ عَلَيْهِمْ هَكَذَا وَهَكَذَا، وَعَلَى كُلِّ حَالٍ؟ قَالَ: "نَعَمْ". قَالَ: وَكَانَتْ صَنَاعَ الْيَدَيْنِ. (جه)', 'ഉമ്മുസലമ(റ)യുടെ മകൾ സൈനബ്(റ) ഉമ്മു സലമ(റ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു: റസൂൽ(സ) ഞങ്ങളോടു ധർമം ചെയ്യാൻ നിർദേശിച്ചു. അപ്പോൾ അബ്ദുല്ല(റ)വിന്റെ ഭാര്യ സൈനബ്(റ) ചോദിച്ചു: എന്റെ ദരിദ്രനായ ഭർത്താവിനും അനാഥരായ സഹോദരമക്കൾക്കും എപ്പോഴും എങ്ങനെയും ഞാൻ ചിലവഴിക്കാറുണ്ട്. ഞാൻ അപ്രകാരം ധർമം ചെയ്താൽ എനിക്കതു ധർമ്മമാകുമോ? അവിടുന്ന് "അതെ" എന്ന് പറഞ്ഞു. ആ സ്വദഖ സ്വന്തം അദ്ധ്വാനിച്ചുണ്ടാക്കിയതായിരുന്നു. (ജ)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ حُنَيْنٍ أَقْبَلَتْ هَوَازِنُ وَغَطَفَانُ وَغَيْرُهُمْ بِذَرَارِيِّهِمْ وَنَعَمِهِمْ، وَمَعَ النَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ عَشَرَةُ آلَافٍ وَمَعَهُ الطُّلَقَاءُ، فَأَدْبَرُوا عَنْهُ حَتَّى بَقِيَ وَحْدَهُ، قَالَ: فَنَادَى يَوْمَئِذٍ نِدَاءَيْنِ لَمْ يَخْلِطْ بَيْنَهُمَا شَيْئًا، قَالَ: فَالْتَفَتَ عَنْ يَمِينِهِ فَقَالَ: "يَا مَعْشَرَ الْأَنْصَارِ". فَقَالُوا: لَبَّيْكَ يَا رَسُولَ اللَّهِ، أَبْشِرْ نَحْنُ مَعَكَ. قَالَ: ثُمَّ الْتَفَتَ عَنْ يَسَارِهِ فَقَالَ: "يَا مَعْشَرَ الْأَنْصَارِ". قَالُوا: لَبَّيْكَ يَا رَسُولَ اللَّهِ أَبْشِرْ نَحْنُ مَعَكَ، قَالَ: وَهُوَ عَلَى بَغْلَةٍ بَيْضَاءَ، فَنَزَلَ فَقَالَ: "أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ". فَانْهَزَمَ الْمُشْرِكُونَ، وَأَصَابَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ غَنَائِمَ كَثِيرَةً، فَقَسَمَ فِي الْمُهَاجِرِينَ وَالطُّلَقَاءِ، وَلَمْ يُعْطِ الْأَنْصَارَ شَيْئًا، فَقَالَتِ الْأَنْصَارُ: إِذَا كَانَتِ الشِّدَّةُ فَنَحْنُ نُدْعَى، وَتُعْطَى الْغَنَائِمُ غَيْرَنَا فَبَلَغَهُ ذَلِكَ فَجَمَعَهُمْ فِي قُبَّةٍ، فَقَالَ: "يَا مَعْشَرَ الْأَنْصَارِ، مَا حَدِيثٌ بَلَغَنِي عَنْكُمْ". فَسَكَتُوا، فَقَالَ: "يَا مَعْشَرَ الْأَنْصَارِ، أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا، وَتَذْهَبُونَ بِمُحَمَّدٍ تَحُوزُونَهُ إِلَى بُيُوتِكُمْ". قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، رَضِينَا، قَالَ: فَقَالَ: "لَوْ سَلَكَ النَّاسُ وَادِيًا، وَسَلَكَتِ الْأَنْصَارُ شِعْبًا، لَأَخَذْتُ شِعْبَ الْأَنْصَارِ". قَالَ هِشَامٌ – ابْنُ زَيْدِ بْنِ أَنَسِ بْنِ مَالِكٍ – فَقُلْتُ: يَا أَبَا حَمْزَةَ، أَنْتَ شَاهِدٌ ذَاكَ؟ قَالَ: وَأَيْنَ أَغِيبُ عَنْهُ. (م)', 'അനസുബ്നു മാലിക്(റ): ഹുനൈൻ യുദ്ധദിവസം ഹവാസിൻ, ഗത്ഫാൻ എന്നീ ഗോത്രക്കാരും മറ്റും അവരുടെ സന്താനങ്ങളേയും ഒട്ടകങ്ങളേയും കൊണ്ട് (യുദ്ധത്തിന്നായി) മുന്നോട്ടുവന്നു, തിരുമേനി(സ)യോടൊപ്പം അന്നു പതിനായിരം ഭടന്മാരും, കൂടാതെ, മക്കാ വിജയദിവസം തിരുമേനി(സ) മാപ്പുകൊടുത്തു വിട്ടയക്കുകയും ശേഷം ഇസ്ലാം സ്വീകരിക്കുകയും ചെയ്തവരും ഉണ്ടായിരുന്നു. പക്ഷേ, അവരെല്ലാം പിന്തിരിഞ്ഞോടി, തിരുമേനി(സ) മാത്രമവശേഷിച്ചു. തദവസരത്തിൽ തിരുമേനി(സ) രണ്ടു വിളി വിളിച്ചു. ആ രണ്ടു വിളിയല്ലാതെ വേറെ യാതൊന്നും അവിടുന്നുരുവിട്ടില്ല. അതായത്, അവിടന്ന് വലഭാഗത്തേക്കു തിരിഞ്ഞു "ഹേ! അൻസാരി സമൂഹമേ!" എന്ന് ഒരു വിളി വിളിച്ചു. ഉടനെ അവർ (അൻസാരികൾ) അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങൾ അങ്ങയോടൊപ്പമുണ്ട്. അങ്ങ് സന്തോഷിക്കുക, എന്നു പറഞ്ഞു. അനന്തരം ഇടഭാഗത്തേക്കു തിരിഞ്ഞുകൊണ്ടും അവിടന്ന് "ഹേ, അൻസാരി സമൂഹമേ" എന്നു വിളിച്ചു. അപ്പോഴും അവർ അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങളിതാ അങ്ങയുടെ കൂടെ, അങ്ങ് സന്തോഷിക്കുക, എന്നു പറഞ്ഞു. നബി(സ) അവിടുത്തെ വെളുത്ത കോവർ കഴുതയുടെ പുറത്തിരിക്കുകയായിരുന്നു. അനന്തരം അവിടുന്ന് അതിൽനിന്ന് ഇറങ്ങുകയും തുടർന്ന് "ഞാൻ അല്ലാഹുവിന്റെ ദാസനും ദൂതനുമാണ്" എന്നു പറയുകയും ചെയ്തു. ഉടനെ മുശ്രിക്കുകൾ തോറ്റോടുകയും തിരുമേനി(സ)ക്ക് അവർ ഉപേക്ഷിച്ചോടിയ ധാരാളം സമ്പത്തു ലഭിക്കുകയും ചെയ്തു. അനന്തരം നബി(സ) അതു മുഹാജിറുകൾക്കിടയിലും (കൂടെയുണ്ടായിരുന്ന) മക്കാ വിജയദിവസം നബി(സ)യുടെ മാപ്പുലഭിക്കുകയും അനന്തരം ഇസ്ലാം മതം സ്വീകരിക്കുകയും ചെയ്തവരിലും വിതരണം ചെയ്തു. അൻസാരികൾക്കു യാതൊന്നും കൊടുത്തില്ല. തന്നിമിത്തം അൻസാരികൾ പറഞ്ഞു: വിഷമാവസ്ഥകൾ ഉണ്ടാകുമ്പോൾ നമ്മൾ വിളിക്കപ്പെടുകയും ഗനീമത്ത് നബി(സ) മറ്റുള്ളവർക്കു കൊടുക്കുകയും ചെയ്യുന്നു. ഈ വിവരം അറിഞ്ഞപ്പോൾ തിരുമേനി(സ) അവരെ ഒരു കൂടാരത്തിൽ ഒരുമിച്ചുകൂട്ടി ചോദിച്ചു: "അൻസാരി സമൂഹമേ! എന്തൊരു വിവരമാണ് നിങ്ങളെക്കുറിച്ച് ഞാൻ കേട്ടത്?" അപ്പോൾ അവർ മൗനികളായി. ശേഷം നബി(സ) ചോദിച്ചു: "അൻസാരി സമൂഹമേ! ജനങ്ങൾ ദുൻയാവുമായി (ഗനീമത്ത് അഥവാ യുദ്ധമുതൽ) മടങ്ങുന്നതും നിങ്ങൾ മുഹമ്മദിനേയും കൊണ്ടു നിങ്ങളുടെ ഭവനങ്ങളിലേക്കു മടങ്ങുന്നതും നിങ്ങൾ ഇഷ്ടപ്പെടുന്നില്ലേ?" അപ്പോൾ അവർ പറഞ്ഞു: അതേ, റസൂലേ ഞങ്ങൾ ഇഷ്ടപ്പെടുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ജനങ്ങൾ ഒരു വഴിയിലും അൻസാരികൾ മറ്റൊരു വഴിയിലും പ്രവേശിച്ചാൽ ഞാൻ അൻസാറുകളുടെ വഴിയിലാണു പ്രവേശിക്കുക." ഹിശാം – അനസ്(റ)വിന്റെ മകൻ ഇബ്നു സൈദ് – പറയുന്നു: ഞാൻ ചോദിച്ചു: അബൂ ഹംസ, നിങ്ങൾ അതിനു സാക്ഷിയായിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതുവിട്ടു ഞാൻ എവിടെ മറയാനാണ്? (മറഞ്ഞിട്ടില്ല). (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 215, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَعْطَى رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ أَبَا سُفْيَانَ بْنَ حَرْبٍ وَصَفْوَانَ بْنَ أُمَيَّةَ وَعُيَيْنَةَ بْنَ حِصْنٍ وَالْأَقْرَعَ بْنَ حَابِسٍ، كُلَّ إِنْسَانٍ مِنْهُمْ مِائَةً مِنَ الْإِبِلِ، وَأَعْطَى عَبَّاسَ بْنَ مِرْدَاسٍ دُونَ ذَلِكَ، فَقَالَ عَبَّاسُ بْنُ مِرْدَاسٍ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَ عَلِيُّ بْنُ أَبِي طَالِبٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنَ الْيَمَنِ بِذَهَبَةٍ فِي أَدِيمٍ مَقْرُوظٍ، لَمْ تُحَصَّلْ مِنْ تُرَابِهَا، قَالَ: فَقَسَمَهَا بَيْنَ أَرْبَعَةِ نَفَرٍ: بَيْنَ عُيَيْنَةَ بْنِ حِصْنٍ وَالْأَقْرَعِ بْنِ حَابِسٍ وَزَيْدِ الْخَيْلِ، وَالرَّابِعُ: إِمَّا عَلْقَمَةُ بْنُ عُلَاثَةَ، وَإِمَّا عَامِرُ بْنُ الطُّفَيْلِ، فَقَالَ رَجُلٌ مِنْ أَصْحَابِهِ: كُنَّا نَحْنُ أَحَقَّ بِهَذَا مِنْ هَؤُلَاءِ، قَالَ: فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَا تَأْمَنُونِي وَأَنَا أَمِينُ مَنْ فِي السَّمَاءِ يَأْتِينِي خَبَرُ السَّمَاءِ صَبَاحًا وَمَسَاءً". قَالَ: فَقَامَ رَجُلٌ غَائِرُ الْعَيْنَيْنِ، مُشْرِفُ الْوَجْنَتَيْنِ، نَاشِزُ الْجَبْهَةِ، كَثُّ اللِّحْيَةِ، مَحْلُوقُ الرَّأْسِ، مُشَمَّرُ الْإِزَارِ، فَقَالَ: يَا رَسُولَ اللَّهِ اتَّقِ اللَّهَ. فَقَالَ: "وَيْلَكَ، أَوَلَسْتُ أَحَقَّ أَهْلِ الْأَرْضِ أَنْ يَتَّقِيَ اللَّهَ". قَالَ: ثُمَّ وَلَّى الرَّجُلُ، فَقَالَ خَالِدُ بْنُ الْوَلِيدِ: يَا رَسُولَ اللَّهِ، أَلَا أَضْرِبُ عُنُقَهُ؟ فَقَالَ: "لَا،لَعَلَّهُ أَنْ يَكُونَ يُصَلِّي". قَالَ خَالِدٌ: وَكَمْ مِنْ مُصَلٍّ يَقُولُ بِلِسَانِهِ مَا لَيْسَ فِي قَلْبِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنِّي لَمْ أُومَرْ أَنْ أَنْقُبَ عَنْ قُلُوبِ النَّاسِ، وَلَا أَشُقَّ بُطُونَهُمْ". قَالَ: ثُمَّ نَظَرَ إِلَيْهِ وَهُوَ مُقَفٍّ، فَقَالَ: "إِنَّهُ يَخْرُجُ مِنْ ضِئْضِئِ هَذَا قَوْمٌ يَتْلُونَ كِتَابَ اللَّهِ رَطْبًا، لَا يُجَاوِزُ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ". قَالَ: أَظُنُّ قَالَ: "لَئِنْ أَدْرَكْتُهُمْ لَأَقْتُلَنَّهُمْ قَتْلَ ثَمُودَ". (م)', 'അബുസഈദിൽ ഖുദ്രി(റ): ഒരിക്കൽ അലിയ്യുബ്നു അബീത്വാലിബ്(റ) യമനിൽനിന്നു കുറച്ചു അസംസ്കൃത സ്വർണ്ണം ഊറക്കിട്ട തോലിൽ പൊതിഞ്ഞ് നബി(സ)യുടെ അടുക്കലേക്കു കൊടുത്തയച്ചു. തിരുമേനി(സ) അത് ഉയയ്നത്ബ്നു ഹിസ്ൻ(റ), അഖ്റഅ്ബ്നു ഹാബിസ്(റ), സൈദുൽ ഖൈൽ(റ), അൽഖമത്ബ്നു ഉലാസ(റ) അല്ലെങ്കിൽ, ആമിറുബ്നു തുഫൈൽ(റ) എന്നീ നാലുപേർക്കിടയിൽ വിതരണം ചെയ്തു. അന്നേരം സഹാബാക്കളിൽ നിന്നൊരാൾ പറഞ്ഞു: ഇതിന് ഇവരേക്കാൾ അർഹർ നമ്മളായിരുന്നു. ആ വിവരം നബി(സ) അറിഞ്ഞു. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "എന്നെ നിങ്ങൾ എന്തിന് ഭയപ്പെടണം? ഞാൻ ആകാശാധിപന്റെ വിശ്വസ്തസേവകനാണ്. രാവിലെയും വൈകുന്നേരവും എനിക്ക് ആകാശത്തെ വിവരം ലഭിക്കുന്നു." അപ്പോൾ കണ്ണ് കുണ്ടിൽ ചാടിയ, കവിൾതടം തടിച്ച, നെറ്റിത്തടം ഉയർന്നുനിൽക്കുന്ന, തിങ്ങിയ, താടിയുള്ള, മുടി വരണ്ടുണങ്ങിയ, തുണി മടക്കികുത്തിയ ഒരു മനുഷ്യൻ എഴുന്നേറ്റു നിന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. ഉടനെ നബി(സ) പറഞ്ഞു: "നിനക്കു നാശം ഭവിക്കട്ടെ! അല്ലാഹുവിനെ സൂക്ഷിക്കുവാൻ ഭൂമുഖത്തു വെച്ച് ഏറ്റവും അർഹൻ ഞാൻ അല്ലാതെ മറ്റാരുണ്ട്?" അനന്തരം ആ മനുഷ്യൻ തിരിച്ചുപോയി. ഉടനെ ഖാലിദുബ്നു വലീദ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! അവന്റെ കഴുത്തു ഞാൻ വെട്ടിക്കളയട്ടെയോ?. നബി(സ) അരുളി: "പാടില്ല, ഒരു പക്ഷേ അവൻ നമസ്കരിക്കുന്ന മനുഷ്യനായിരിക്കാം." ഖാലിദ്(റ) പറഞ്ഞു: ഹൃദയത്തിലില്ലാത്തതു നാവുകൊണ്ടു പറയുന്ന എത്രയെത്ര നിസ്ക്കാരക്കാരുണ്ട്. അന്നേരം തിരുമേനി(സ) പറഞ്ഞു: "ജനങ്ങളുടെ ഹൃദയം തുറന്നു നോക്കുവാനും വയറുകൾ കീറിനോക്കുവാനും ഞാൻ കൽപിക്കപ്പെട്ടിട്ടില്ല." അനന്തരം അവൻ തിരിച്ചുപോകുമ്പോൾ അവിടന്ന് അവനെ ഒന്നു നോക്കുകയും ഇങ്ങനെ പറയുകയും ചെയ്തു: "ഇവന്റെ വംശത്തിൽനിന്ന് ഒരു ജനവിഭാഗമുണ്ടാകും. അവർ അല്ലാഹുവിന്റെ ഗ്രന്ഥം വളരെ എളുപ്പം പാരായണം ചെയ്യും. പക്ഷേ, അത് അവരുടെ കണ്ഠനാളത്തിനപ്പുറം എത്തുകയില്ല. കുറിക്കുകൊള്ളാത്ത അമ്പു തെറിക്കുന്നതുപോലെ അവർ ദീനിൽനിന്നു തെറിച്ചുപോകും." നബി(സ) ഇതുകൂടി പറഞ്ഞെന്ന് നിവേദകൻ വിചാരിക്കുന്നു: "അവരെ കണ്ടു കിട്ടുകയാണെങ്കിൽ സമൂദ് ഗോത്രക്കാരെ വധിച്ചതുപോലെ നിശ്ചയമായും ഞാൻ അവരെ വധിക്കുമായിരുന്നു." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 217, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ، وَإِنَّهُ لَأَبْغَضُ الْخَلْقِ إِلَيَّ، فَمَا زَالَ يُعْطِينِي حَتَّى إِنَّهُ لَأَحَبُّ الْخَلْقِ إِلَيَّ. (ت)', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ): റസൂൽ(സ) ഹുനൈൻ ദിവസത്തിൽ എനിക്ക് ദാനം നൽകി. അന്ന് നബി(സ) എനിക്ക് സൃഷ്ടികളിൽ വെച്ചേറ്റവും വെറുപ്പുള്ള ആളായിരുന്നു. അങ്ങനെ മനുഷ്യരിൽ വെച്ച് എനിക്കേറ്റവും പ്രിയപ്പെട്ടവർ അവിടന്ന് ആകുന്നതുവരെ അവിടന്ന് എനിക്ക് ദാനം നൽകിക്കൊണ്ടിരുന്നു. (തു)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 218, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ عَلِيٌّ وَهُوَ بِالْيَمَنِ بِذُهَيْبَةٍ بِتُرْبَتِهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ، فَقَسَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بَيْنَ أَرْبَعَةِ نَفَرٍ: الْأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ، وَعُيَيْنَةَ بْنِ بَدْرٍ الْفَزَارِيِّ، وَعَلْقَمَةَ بْنِ عُلَاثَةَ الْعَامِرِيِّ، وَزَيْدٍ الطَّائِيِّ، فَغَضِبَتْ – وَفِي رِوَايَةٍ: صَنَادِيدُ – قُرَيْشٌ، فَقَالُوا: تُعْطِي صَنَادِيدَ نَجْدٍ وَتَدَعُنَا؟ قَالَ: "إِنَّمَا فَعَلْتُ ذَلِكَ لِأَتَأَلَّفَهُمْ". فَجَاءَ رَجُلٌ كَثُّ اللِّحْيَةِ مُشْرِفُ الْوَجْنَتَيْنِ غَائِرُ الْعَيْنَيْنِ نَاتِئُ الْجَبِينِ مَحْلُوقُ الرَّأْسِ، فَقَالَ: اتَّقِ اللَّهَ يَا مُحَمَّدُ، قَالَ: "فَمَنْ يُطِيعُ اللَّهَ عَزَّ وَجَلَّ إِنْ عَصَيْتُهُ؟ أَيَأْمَنُنِي عَلَى أَهْلِ الْأَرْضِ وَلَا تَأْمَنُونِي". ثُمَّ أَدْبَرَ الرَّجُلُ، فَاسْتَأْذَنَ رَجُلٌ مِنَ الْقَوْمِ فِي قَتْلِهِ، يَرَوْنَ أَنَّهُ خَالِدُ بْنُ الْوَلِيدِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ ضِئْضِئِ هَذَا قَوْمًا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ، يَقْتُلُونَ أَهْلَ الْإِسْلَامِ وَيَدَعُونَ أَهْلَ الْأَوْثَانِ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَئِنْ أَدْرَكْتُهُمْ لَأَقْتُلَنَّهُمْ قَتْلَ عَادٍ". (ن)', 'അബുസഈദിൽ ഖുദ്രി(റ): യമനിലായിരിക്കെ അലി(റ) അൽപ്പം അസംസ്കൃത സ്വർണ്ണനാണയങ്ങൾ നബി(സ)യുടെ അടുക്കലേക്ക് അയച്ചു. അപ്പോൾ റസൂൽ(സ) അവയെ അഖ്റഉബിൻ ഹാബിസ് അൽഹൻളലി(റ), ഉയയ്നത്തുബിൻ ബദ്ർ അൽഫസാരി(റ), അൽഖമത്തുബിൻ ഉലാസത്തുൽ ആമിറി(റ), സൈദുത്ത്വാഈ(റ) എന്നീ നാലു പേർക്ക് വീതിച്ചു നൽകി. അപ്പോൾ ഖുറൈശി യോദ്ധാക്കാൾ കോപാകുലരായി. അവർ പറഞ്ഞു: നജ്ദിലെ യോദ്ധാക്കൾക്ക് താങ്കൾ നൽകുകയും ഞങ്ങളെ ഉപേക്ഷിക്കുകയും ചെയ്യുന്നവല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "അവരുമായി ഇണക്കം ഉണ്ടാക്കാൻ വേണ്ടിയാണ് ഞാൻ അങ്ങിനെ ചെയ്തത്." അപ്പോൾ തിങ്ങിയ താടിയും ഉയർന്ന് നിൽക്കുന്ന ചുണ്ടുകളും, കുഴിഞ്ഞ കണ്ണകുളും, ഉന്തിനിൽക്കുന്ന നെറ്റിത്തടവും ഉള്ള തല മുടി മുണ്ഡനം ചെയ്ത ഒരാൾ വന്നു. അദ്ദേഹം പറഞ്ഞു: മുഹമ്മദേ! നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക! അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ മഹത്വമുള്ളവനും പ്രതാപവാനുമായ അല്ലാഹുവിനെ ധിക്കരിച്ചുവെങ്കിൽ പിന്നെ ആരാണ് അവനെ അനുസരിക്കുക. ഭൂനിവാസികളുടെ കാര്യത്തിൽ അവൻ എന്നെ വിശ്വസിക്കുകയും, നിങ്ങൾക്ക് എന്നിൽ വിശ്വാസമില്ലാതിരിക്കുകയും ചെയ്യുന്നുവോ?" ശേഷം അയാൾ പിറകോട്ട് തിരിഞ്ഞു പോയി. അപ്പോൾ കൂട്ടത്തിലൊരാൾ അയാളെ കൊല്ലുവാൻ പ്രവാചകർ(സ)യോട് അനുവാദം തേടി. – അത് ഖാലിദുബിൻ വലീദാണെന്നാണ് അഭിപ്രായം – അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇദ്ദേഹത്തിന്റെ പരമ്പരയിൽ ഖുർആൻ പാരായണം ചെയ്യുകയും, എന്നാലത് തൊണ്ടകൾക്ക് താഴേക്ക് ഇറങ്ങാതിരിക്കുകയും ചെയ്യുന്ന ചില ആളുകളുണ്ടാകും. അവർ മുസ്ലികളെ കൊലപ്പെടുത്തുകയും ബിംബാരാധകരെ വെറുതെ വിടുകയും ചെയ്യും. അമ്പുകൾ വില്ലുകളിൽനിന്ന് തെറിച്ച് പോകുന്നത് പോലെ അവർ ഇസ്ലാമിൽനിന്നും പുറത്ത് പോകുന്നതാണ്. ഞാൻ അവരെ കണ്ട് മുട്ടുകയാണെങ്കിൽ ആദ് സമൂഹത്തെ കൊന്ന പോലെ കൊന്നുകളയും." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 218, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=222), 1, 'وَفِي رِوَايَةٍ: صَنَادِيدُ – قُرَيْشٌ، فَقَالُوا: تُعْطِي صَنَادِيدَ نَجْدٍ وَتَدَعُنَا؟ قَالَ: "إِنَّمَا فَعَلْتُ ذَلِكَ لِأَتَأَلَّفَهُمْ". فَجَاءَ رَجُلٌ كَثُّ اللِّحْيَةِ مُشْرِفُ الْوَجْنَتَيْنِ غَائِرُ الْعَيْنَيْنِ نَاتِئُ الْجَبِينِ مَحْلُوقُ الرَّأْسِ، فَقَالَ: اتَّقِ اللَّهَ يَا مُحَمَّدُ، قَالَ: "فَمَنْ يُطِيعُ اللَّهَ عَزَّ وَجَلَّ إِنْ عَصَيْتُهُ؟ أَيَأْمَنُنِي عَلَى أَهْلِ الْأَرْضِ وَلَا تَأْمَنُونِي". ثُمَّ أَدْبَرَ الرَّجُلُ، فَاسْتَأْذَنَ رَجُلٌ مِنَ الْقَوْمِ فِي قَتْلِهِ، يَرَوْنَ أَنَّهُ خَالِدُ بْنُ الْوَلِيدِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ ضِئْضِئِ هَذَا قَوْمًا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ، يَقْتُلُونَ أَهْلَ الْإِسْلَامِ وَيَدَعُونَ أَهْلَ الْأَوْثَانِ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَئِنْ أَدْرَكْتُهُمْ لَأَقْتُلَنَّهُمْ قَتْلَ عَادٍ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاص رَضِيَ اللهُ عَنْهُ قَالَ: قَسَمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَسْمًا، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَعْطِ فُلَانًا فَإِنَّهُ مُؤْمِنٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوْ مُسْلِمٌ". أَقُولُهَا ثَلَاثًا وَيُرَدِّدُهَا عَلَيَّ ثَلَاثًا: "أَوْ مُسْلِمٌ". ثُمَّ قَالَ: "إِنِّي لَأُعْطِي الرَّجُلَ وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ، مَخَافَةَ أَنْ يَكُبَّهُ اللَّهُ فِي النَّارِ". (م)', 'സഅദ്ബിൻ അബീവഖാസ്(റ): റസുൽ(സ) (യുദ്ധാർജ്ജിത സ്വത്ത്) വിഹിതം വെച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ! ഇന്നയാൾക്ക് നൽകു! അയാൾ സത്യവിശ്വാസിയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതോ അയാൾ മുസ്‌ലിമാണോ?" ഞാൻ ഇക്കാര്യം മൂന്നു പ്രാവശ്യം ആവർത്തിച്ചു പറയുകയും റസൂൽ(സ) എന്നോട് "അതോ അയാൾ മുസ്‌ലിമാണോ?" എന്ന് മൂന്നു തവണ പ്രതികരിക്കുകയും ചെയ്തു. ശേഷം തിരുമേനി(സ) പറഞ്ഞു: "വേറെയൊരാൾ എനിക്ക് കുടുതൽ ഇഷ്ടപ്പെട്ടവനായിട്ടും ഞാനൊരുത്തന് നൽകുന്നത് അവനെ അല്ലാഹു നരകത്തിൽ വീഴ്ത്തുമെന്ന് ഭയന്നത് കൊണ്ടാണ്." (മു)', 'سَعْدِ بْنِ أَبِي وَقَّاص', 'സഅദ്ബിൻ അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 219, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَا رَجُلٌ بِفَلَاةٍ مِنَ الْأَرْضِ، فَسَمِعَ صَوْتًا فِي سَحَابَةٍ: اسْقِ حَدِيقَةَ فُلَانٍ، فَتَنَحَّى ذَلِكَ السَّحَابُ فَأَفْرَغَ مَاءَهُ فِي حَرَّةٍ، فَإِذَا شَرْجَةٌ مِنْ تِلْكَ الشِّرَاجِ قَد اسْتَوْعَبَتْ ذَلِكَ الْمَاءَ كُلَّهُ، فَتَتَبَّعَ الْمَاءَ، فَإِذَا رَجُلٌ قَائِمٌ فِي حَدِيقَتِهِ يُحَوِّلُ الْمَاءَ بِمِسْحَاتِهِ، فَقَالَ لَهُ: يَا عَبْدَ اللَّهِ، مَا اسْمُكَ؟ قَالَ: فُلَانٌ لِلِاسْمِ الَّذِي سَمِعَ فِي السَّحَابَةِ، فَقَالَ لَهُ: يَا عَبْدَ اللَّهِ، لِمَ تَسْأَلُنِي عَنِ اسْمِي؟ فَقَالَ: إِنِّي سَمِعْتُ صَوْتًا فِي السَّحَابِ الَّذِي هَذَا مَاؤُهُ يَقُولُ: اسْقِ حَدِيقَةَ فُلَانٍ، لِاسْمِكَ، فَمَا تَصْنَعُ فِيهَا؟ قَالَ: أَمَّا إِذْ قُلْتَ هَذَا: فَإِنِّي أَنْظُرُ إِلَى مَا يَخْرُجُ مِنْهَا فَأَتَصَدَّقُ بِثُلُثِهِ، وَآكُلُ أَنَا وَعِيَالِي ثُلُثًا، وَأَرُدُّ فِيهَا ثُلُثَهُ". وَفِي رِوَايَةٍ: "وَأَجْعَلُ ثُلُثَهُ فِي الْمَسَاكِينِ وَالسَّائِلِينَ وَابْنِ السَّبِيلِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ വിശാലമായ ഒരു മരുഭൂമിയിലൂടെ സഞ്ചിരിക്കുകയായിരുന്നു. അപ്പോൾ കാർമേഘത്തിൽനിന്ന് ഒരു അശരീരി കേട്ടു: ''ഇന്നാലിന്ന വ്യക്തിയുടെ തോട്ടം നനക്കുക.'' ഉടനെ കാർമേഘങ്ങൾ നീങ്ങുകയും ഒരു നിരപ്പായ ഭൂപ്രതലത്തിൽ വെള്ളം ചൊരിയുകയും ചെയ്തു. അപ്പോൾ അവിടെ ഉണ്ടായിരുന്ന വെള്ളക്കുഴികളിൽ നിന്നുള്ള ഒരു വെള്ളക്കുഴിയിൽ ആ വെള്ളം മുഴുവൻ നിറഞ്ഞു നിന്നു. അദ്ദേഹം ആ വെള്ളത്തെ തന്നെ സശ്രദ്ധം വിക്ഷിച്ചു. അപ്പോഴതാ ഒരാൾ മൺവെട്ടി കൊണ്ട് വെള്ളം തന്റെ തോട്ടത്തിലേക്ക് തിരിച്ചു വിടുന്നു. അപ്പോൾ ഈ മനുഷ്യൻ ആ (വെള്ളം തിരിക്കുന്ന) വ്യക്തിയോട് ചോദിച്ചു: ഏ, അല്ലാഹുവിന്റെ ദാസാ! താങ്കളുടെ പേരെന്താണ്? കാർമേഘത്തിൽനിന്ന് കേട്ട അതേ പേര് അദ്ദേഹം പറഞ്ഞു. ശേഷം അയാൾ ചോദിച്ചു: ഏ! അല്ലാഹുവിന്റെ ദാസാ! താങ്കൾ എന്തിനാണ് എന്റെ പേര് ചോദിച്ചറിയുന്നത്? അദ്ദേഹം പറഞ്ഞു: ഈ വെള്ളം നിങ്ങൾക്ക് ചൊരിഞ്ഞുതന്ന കാർമേഘത്തിൽനിന്ന് ഇപ്രകാരം വിളിച്ചു പറയുന്നത് ഞാൻ കേട്ടു: താങ്കളുടെ പേരെടുത്ത് പറഞ്ഞു കൊണ്ട് ഇന്നയാളുടെ തോട്ടത്തിൽ വെള്ളം ചെരിയുക എന്ന്. അതിനു മാത്രം താങ്കൾ ഈ തോട്ടത്തിൽ എന്ത് ചെയ്യുന്നു? ഉടനെ അയാൾ പറഞ്ഞു: താങ്കൾ ചോദിച്ച സ്ഥിക്ക് ഞാൻ പറയാം: ഞാൻ അതിൽ നിന്ന് ലഭിക്കുന്ന വിളയിലെ മൂന്നിൽ ഒന്ന് സ്വദഖ നൽകുകയും മുന്നിൽ ഒന്ന് ഞാനും എന്റെ കുടുംബവും ഭക്ഷിക്കുകയും മൂന്നിൽ ഒന്ന് (അടുത്ത വിളക്ക് വേണ്ടി) അതിലേക്ക് തന്നെ മടക്കുകയും ചെയ്യും." മറ്റൊരു റിപ്പോർട്ടിൽ: "ഞാൻ അതിലെ മൂന്നിലൊന്ന് മിസ്കീനുകൾക്കും ചോദിച്ചു വരുന്നവർക്കും വഴിപോക്കർക്കും വേണ്ടി നീക്കിവെക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 219, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=224), 1, 'وَفِي رِوَايَةٍ: "وَأَجْعَلُ ثُلُثَهُ فِي الْمَسَاكِينِ وَالسَّائِلِينَ وَابْنِ السَّبِيلِ". (م)', 'മറ്റൊരു നിവേദനിൽ: "ഞാൻ അതിലെ മൂന്നിലൊന്ന് മിസ്കീനുകൾക്കും ചോദിച്ചു വരുന്നവർക്കും വഴിപോക്കർക്കും വേണ്ടി നീക്കിവെക്കും." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ حُسَيْنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِلسَّائِلِ حَقٌّ وَإِنْ جَاءَ عَلَى فَرَسٍ". (د)', 'ഹുസൈനുബ്നു അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ചോദിച്ച് വരുന്നവൻ കുതിരപ്പുറത്ത് വന്നാലും അവന് അവകാശമുണ്ട്." (ദ)', 'حُسَيْنِ بْنِ عَلِيٍّ', 'ഹുസൈനുബ്നു അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مِنْكُمْ أَحَدٌ أَطْعَمَ الْيَوْمَ مِسْكِينًا؟". فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: دَخَلْتُ الْمَسْجِدَ، فَإِذَا أَنَا بِسَائِلٍ يَسْأَلُ، فَوَجَدْتُ كِسْرَةَ خُبْزٍ فِي يَدِ عَبْدِ الرَّحْمَنِ، فَأَخَذْتُهَا مِنْهُ فَدَفَعْتُهَا إِلَيْهِ. (م,د,ن)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്കർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇന്ന് ഒരു മിസ്കീന് ഭക്ഷണം നൽകിയ ആരെങ്കിലും നിങ്ങളിലുണ്ടോ?" അപ്പോൾ അബുബക്കർ(റ) പറഞ്ഞു: ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ ഒരാൾ അവിടെ യാചിക്കുന്നതായി കണ്ടു. അപ്പോൾ ഞാൻ അബ്ദുർറഹ്മാന്റെ കയ്യിൽ ഒരു റൊട്ടിക്കഷ്ണം കാണുകയും അതെടുത്ത് ആ യാചകന് നൽകുകയും ചെയ്തു. (മു,ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്കർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَمْشِي مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعَلَيْهِ بُرْدٌ نَجْرَانِيٌّ غَلِيظُ الْحَاشِيَةِ، فَأَدْرَكَهُ أَعْرَابِيٌّ، فَجَبَذَهُ بِرِدَائِهِ جَبْذَةً شَدِيدَةً، نَظَرْتُ إِلَى صَفْحَةِ عُنُقِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ أَثَّرَتْ بِهَا حَاشِيَةُ الرِّدَاءِ مِنْ شِدَّةِ جَبْذَتِهِ، ثُمَّ قَالَ: يَا مُحَمَّدُ، مُرْ لِي مِنْ مَالِ اللَّهِ الَّذِي عِنْدَكَ، فَالْتَفَتَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضَحِكَ، ثُمَّ أَمَرَ لَهُ بِعَطَاءٍ. (ق)', 'അനസുബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യുടെ കൂടെ നടക്കുകയായിരുന്നു. അപ്പോൾ പ്രവാചകൻ(സ) പരുത്ത കരയുള്ള ഒരു നജ്റാനീ പുതപ്പ് തന്റെ പൂമേനിയിൽ ഇട്ടിരുന്നു. ഒരു ഗ്രാമീണനായ അറബി അത് കണ്ടു. അയാൾ ആ തട്ടം ശക്തിയായി പിടിച്ചു വലിച്ചു. അപ്പോൾ ഞാൻ തിരുദൂതരുടെ പിരടിയുടെ അടിഭാഗത്തേക്ക് നോക്കി, അയാൾ ആ തട്ടം ശക്തിയായി വലിച്ചതുകാരണത്താൽ (അവിടുത്തെ പിരടിയിൽ) പാടുകൾ വീണിട്ടുണ്ട്. അയാൾ പറഞ്ഞു: മുഹമ്മദ്! നിന്റെ അടുക്കലുള്ള അല്ലാഹുവിന്റെ സ്വത്തിൽനിന്നും എനിക്ക് നൽകാൻ കൽപ്പിക്കുക! റസൂൽ(സ) അദ്ദേഹത്തിലേക്ക് തിരിഞ്ഞുനോക്കി ചിരിച്ചു. ശേഷം അദ്ദേഹത്തിന് ദാനം നൽകാൻ കൽപിച്ചു. (ബു,മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 220, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قَسَمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقْبِيَةً، وَلَمْ يُعْطِ مَخْرَمَةَ شَيْئًا، فَقَالَ مَخْرَمَةُ: يَا بُنَيَّ انْطَلِقْ بِنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقْتُ مَعَهُ، قَالَ: ادْخُلْ فَادْعُهُ لِي قَالَ: فَدَعَوْتُهُ لَهُ فَخَرَجَ إِلَيْهِ وَعَلَيْهِ قَبَاءٌ مِنْهَا، فَقَالَ: "خَبَأْتُ هَذَا لَكَ". قَالَ: فَنَظَرَ إِلَيْهِ. فَقَالَ: "رَضِيَ مَخْرَمَةُ". (م)', 'മിസ്‌വറുബ്നു മഖ്റമ(റ): റസൂൽ(സ) ഉടുപ്പുകൾ വിഹിതം വെച്ചു. മഖ്റമ(റ)വിന് ഒന്നും നൽകിയില്ല. അപ്പോൾ മഖ്റമ(റ) പറഞ്ഞു: എന്റെ പൊന്നുമോനേ, നീ എന്നെയും കൊണ്ട് റസൂൽ(സ) അടുക്കലേക്ക് പോകൂ. അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന്റെ കൂടെ പോയി. അദ്ദേഹം (മഖ്റമ) പറഞ്ഞു: നീ ഉള്ളിൽ ചെന്ന് എനിക്ക് വേണ്ടി തിരുമേനി(സ)യെ വിളിക്കുക. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന് വേണ്ടി റസൂൽ(സ)യെ വിളിച്ചു. നബി(സ) അദ്ദേഹത്തിന്റെ അടുത്ത് വന്നു. അവിടുത്തെ ശരീരത്തിൽ അതിൽ പെട്ട ഒരു ഉടുപ്പുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "ഇത് നിങ്ങൾക്ക് വേണ്ടി ഞാൻ സുക്ഷിച്ചു വെച്ചതാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ തിരുമേനി(സ) അദ്ദേഹത്തെ നേക്കി. എന്നിട്ടവിടന്ന് പറഞ്ഞു: "ഇപ്പോൾ മഖ്റമക്ക് തൃപ്തിയായിരിക്കുന്നു." (മു)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്‌വറുബ്നു മഖ്റമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ بُجَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُدُّوا السَّائِلَ وَلَوْ بِظِلْفٍ مُحْرَقٍ". (ن)', 'അബ്ദുർറഹ്മാനുബ്നു ബുജൈദിൽ അൻസാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ യാചകന് കരിക്കപ്പെട്ട ഒരു കുളമ്പെങ്കിലും നൽകി വിട്ടയക്കുക. (വെറുതെ മടക്കരുത് എന്നർത്ഥം)." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ بُجَيْدٍ الْأَنْصَارِيِّ', 'അബ്ദുർറഹ്മാനുബ്നു ബുജൈദിൽ അൻസാരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَأْتِي رَجُلٌ مَوْلَاهُ يَسْأَلُهُ مِنْ فَضْلٍ عِنْدَهُ، فَيَمْنَعُهُ إِيَّاهُ، إِلَّا دُعِيَ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعٌ أَقْرَعُ، يَتَلَمَّظُ فَضْلَهُ الَّذِي مَنَعَ". (ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാൾ തന്റെ യജമാനന്റെ അടുക്കൽ വന്ന് അദ്ദേഹത്തിന്റെ ധനത്തിൽനിന്ന് വല്ലതും ചോദിച്ചിട്ട് അത് തടഞ്ഞാൽ, അന്ത്യദിനത്തിൽ അവന്റെ അടുക്കലേക്ക്, കൊത്തുന്ന ഒരു പാമ്പിനെ കൊണ്ടുവരപ്പെടുകയും അത് അവൻ തടഞ്ഞു വെച്ച ആ ധനത്തിന് നേരെ നാവ് നീട്ടിനിൽക്കുകയും ചെയ്യാതിരിക്കില്ല." (ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُسْأَلُ بِوَجْهِ اللَّهِ إِلَّا الْجَنَّةُ". (د)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ വജ്ഹ്(തിരുമുഖം) കൊണ്ട് സ്വർഗമല്ലാതെ മറ്റൊന്നും ചോദിക്കപ്പെടരുത്." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 221, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَا نَبِيَّ اللَّهِ، مَا أَتَيْتُكَ حَتَّى حَلَفْتُ أَكْثَرَ مِنْ عَدَدِهِنَّ – لِأَصَابِعِ يَدَيْهِ – أَلَّا آتِيكَ وَلَا آتِيَ دِينَكَ، وَإِنِّي كُنْتُ امْرَأً لَا أَعْقِلُ شَيْئًا إِلَّا مَا عَلَّمَنِي اللَّهُ وَرَسُولُهُ، وَإِنِّي أَسْأَلُكَ بِوَجْهِ اللَّهِ عَزَّ وَجَلَّ، بِمَا بَعَثَكَ رَبُّكَ إِلَيْنَا؟ قَالَ: "بِالْإِسْلَامِ". قَالَ: قُلْتُ: وَمَا آيَاتُ الْإِسْلَامِ؟ قَالَ: "أَنْ تَقُولَ: أَسْلَمْتُ وَجْهِي إِلَى اللَّهِ عَزَّ وَجَلَّ، وَتَخَلَّيْتُ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ. كُلُّ مُسْلِمٍ عَلَى مُسْلِمٍ مُحَرَّمٌ، أَخَوَانِ نَصِيرَانِ. لَا يَقْبَلُ اللَّهُ عَزَّ وَجَلَّ مِنْ مُشْرِكٍ بَعْدَمَا أَسْلَمَ عَمَلًا أَوْ يُفَارِقَ الْمُشْرِكِينَ إِلَى الْمُسْلِمِينَ". (ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, താങ്കളുടെ അടുക്കലേക്കും താങ്കളുടെ മതത്തിലേക്കും വരില്ല എന്ന് എന്റെ കൈവിരലുകളുടെ എണ്ണത്തിലധികം പ്രാവശ്യം ശപഥം ചെയ്തതിന് ശേഷം മാത്രമാണ് ഞാൻ താങ്കളുടെ അടുക്കൽ വന്നിരിക്കുന്നത്. ഞാൻ അല്ലാഹുവും റസൂലും പറയുന്നതിലപ്പുറം ഒന്നും ചിന്തിച്ചുമനസ്സിലാക്കാത്ത ഒരാളായിരുന്നു. മഹത്വമുള്ളവനും പ്രതാപവാനുമായ അല്ലാഹുവിന്റെ വജ്ഹ് കൊണ്ട് ഞാൻ താങ്കളോട് ചോദിക്കുന്നു. താങ്കളുടെ രക്ഷിതാവ് താങ്കളെ എന്തുമായാണ് ഞങ്ങളിലേക്ക് നിയോഗിച്ചിട്ടുള്ളത്? റസൂൽ(സ) പറഞ്ഞു: "ഇസ്ലാം കൊണ്ട്." അദ്ദേഹം ചോദിച്ചു: എന്തെല്ലാമാണ് ഇസ്ലാം നൽകുന്ന അധ്യായങ്ങൾ? നബി(സ) പറഞ്ഞു: "മഹത്വമുള്ളവനും പ്രതാപവാനുമായ അല്ലാഹുവിന് ഞാൻ കീഴൊതുങ്ങുകയും ആരാധന അവന് മാത്രമാക്കുകയും ചെയ്തിരിക്കുന്നു എന്ന് പ്രഖ്യാപിക്കുകയും, നിസ്കാരം നിലനിർത്തുകയും, സകാത്ത് നൽകുകയും ചെയ്യലാണ്. ഓരോ മുസ്ലിമും മറ്റൊരു മുസ്ലിമിനെ പവിത്രമായി കണക്കാക്കേണ്ടതാകുന്നു. അവർ പരസ്പരം സഹായിക്കുന്ന സഹേദരങ്ങളാണ്. മുസ്ലിമായതിനു ശേഷം മുശ്രിക്കായവനിൽ നിന്ന് മുശ്രിക്കുകളെ പൂർണ്ണമായും.ഒഴിവാക്കി മുസ്ലിംകളിലേക്ക് വരുന്നത് വരെ അല്ലാഹു ഒരു കർമ്മവും സ്വീകരിക്കുകയില്ല." (ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَعَاذَ بِاللَّهِ فَأَعِيذُوهُ، وَمَنْ سَأَلَ بِاللَّهِ فَأَعْطُوهُ، وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ، وَمَنْ صَنَعَ إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ، فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُونَهُ فَادْعُوا لَهُ حَتَّى تَرَوْا أَنَّكُمْ قَدْ كَافَأْتُمُوهُ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനെക്കൊണ്ട് അഭയം തേടിയാൽ നിങ്ങൾ അവന് അഭയം നൽകുക. വല്ലവനും അല്ലാഹുവിനെക്കൊണ്ട് യാചിച്ചാൽ നിങ്ങൾ അവന് നൽകുക. ആരെങ്കിലും നിങ്ങളെ ക്ഷണിച്ചാൽ നിങ്ങൾ അവന്റെ ക്ഷണം സ്വീകരിക്കുക, നിങ്ങൾക്ക് ഒരുത്തൻ നൻമ ചെയ്താൽ നിങ്ങൾ അവന് പ്രത്യുപകാരം ചെയ്യുക. പ്രത്യുപകാരം ചെയ്യാൻ ഒന്നും നിങ്ങളുടെ പക്കൽ ഇല്ലെങ്കിൽ, അവന് നിങ്ങൾ പ്രത്യുപകാരം ചെയ്തു എന്ന് നിങ്ങൾക്ക് ബോദ്ധ്യമാകും വിധം നിങ്ങൾ അവന് വേണ്ടി പ്രാർത്ഥിക്കുക." (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ مَنْزِلًا". قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: "رَجُلٌ آخِذٌ بِرَأْسِ فَرَسِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ حَتَّى يَمُوتَ أَوْ يُقْتَلَ. وَأُخْبِرُكُمْ بِالَّذِي يَلِيهِ". قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: "رَجُلٌ مُعْتَزِلٌ فِي شِعْبٍ، يُقِيمُ الصَّلَاةَ وَيُؤْتِي الزَّكَاةَ، وَيَعْتَزِلُ شُرُورَ النَّاسِ. وَأُخْبِرُكُمْ بِشَرِّ النَّاسِ". قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: "الَّذِي يُسْأَلُ بِاللَّهِ عَزَّ وَجَلَّ وَلَا يُعْطِي بِهِ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിൽ ഏറ്റവും ഉന്നതപദവിയിലുള്ളത് ആരാണെന്ന് ഞാൻ അറിയിച്ചു തരട്ടെയോ?" ഞങ്ങൾ പറഞ്ഞു: അതെ അല്ലാഹുവിന്റെ റസൂലെ. അവിടന്ന് പറഞ്ഞു: "തന്റെ കുതിരയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ മുന്നോട്ട് നയിക്കുകയും അങ്ങിനെ മരിക്കുകയോ കൊല്ലപ്പെടുകയോ ചെയ്തവനാണവൻ." പ്രവാചകർ(സ) ചോദിച്ചു: "അതിന്റെ തൊട്ടു താഴെയുള്ള പദവിയിലുള്ളവനെ സംബന്ധിച്ച് ഞാൻ അറിയിച്ചു തരട്ടെയോ?" ഞങ്ങൾ പ്രതിവചിച്ചു: അതെ, റസുലേ. അവിടന്ന് പറഞ്ഞു: "ജനങ്ങളുടെ ഉപദ്രവങ്ങളിൽനിന്ന് ഒഴിഞ്ഞ് മാറി ഒരു കുന്നിലേക്ക് പോവുകയും നമസ്കാരം മുറപ്രകാരം നിർവ്വഹിക്കുകയും സകാത്ത് നൽകുകയും ചെയ്യുന്നവനാണവൻ." പ്രവാചകർ(സ) വീണ്ടും ചോദിച്ചു: "എന്നാൽ ആളുകളിൽ മോശമായവർ ആരെന്ന് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചു തരട്ടെയോ?" ഞങ്ങൾ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലെ. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിനെ മുൻനിറുത്തി ചോദിക്കപ്പെടുകയും അത് നൽകാതിരിക്കുകയം ചെയ്തവൻ." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 222, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةٌ يُحِبُّهُمُ اللَّهُ عَزَّ وَجَلَّ، وَثَلَاثَةٌ يَبْغُضُهُمُ اللَّهُ عَزَّ وَجَلَّ. أَمَّا الَّذِينَ يُحِبُّهُمُ اللَّهُ عَزَّ وَجَلَّ: فَرَجُلٌ أَتَى قَوْمًا فَسَأَلَهُمْ بِاللَّهِ عَزَّ وَجَلَّ، وَلَمْ يَسْأَلْهُمْ بِقَرَابَةٍ بَيْنَهُ وَبَيْنَهُمْ، فَمَنَعُوهُ، فَتَخَلَّفَهُ رَجُلٌ بِأَعْقَابِهِمْ فَأَعْطَاهُ سِرًّا، لَا يَعْلَمُ بِعَطِيَّتِهِ إِلَّا اللَّهُ عَزَّ وَجَلَّ وَالَّذِي أَعْطَاهُ، وَقَوْمٌ سَارُوا لَيْلَتَهُمْ، حَتَّى إِذَا كَانَ النَّوْمُ أَحَبَّ إِلَيْهِمْ مِمَّا يُعْدَلُ بِهِ نَزَلُوا فَوَضَعُوا رُءُوسَهُمْ، فَقَامَ يَتَمَلَّقُنِي وَيَتْلُو آيَاتِي، وَرَجُلٌ كَانَ فِي سَرِيَّةٍ، فَلَقُوا الْعَدُوَّ فَهُزِمُوا، فَأَقْبَلَ بِصَدْرِهِ حَتَّى يُقْتَلَ أَوْ يَفْتَحَ اللَّهُ لَهُ. وَالثَّلَاثَةُ الَّذِينَ يَبْغُضُهُمُ اللَّهُ عَزَّ وَجَلَّ: الشَّيْخُ الزَّانِي، وَالْفَقِيرُ الْمُخْتَالُ، وَالْغَنِيُّ الظَّلُومُ". (ن)', 'അബുദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് തരം ആളുകളെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നു. മൂന്ന് തരം ആളുകളെ അല്ലാഹു വെറുക്കുകയും ചെയ്യുന്നു. അല്ലാഹു ഇഷ്ടപ്പെടുന്നവർ ഇവരാണ്; ഒരാൾ ഒരു കൂട്ടം ആളുകളോട് അദ്ദേഹവും അവരും തമ്മിലുള്ള അടുപ്പത്തിന്റെ പേരിൽ ചോദിക്കാതെ അല്ലാഹുവിനെക്കൊണ്ട് ചോദിച്ചപ്പോൾ അവർ അയാൾക്ക് നൽകിയില്ല. ഉടനെ ആ കൂട്ടത്തിൽ പെട്ട ഒരാൾ ചോദിച്ചയാളുടെ പിറകെ പോവുകയും അദ്ദേഹത്തിന്, അല്ലാഹുവും അദ്ദേഹവും ഒഴികെ ആരും അറിയാത്ത വിധം നൽകുകയും ചെയ്തു (ഇദ്ദേഹമാണ് ഒരാൾ), ഒരു വിഭാഗം ആളുകൾ രാത്രി പുറപ്പെടുകയും ഉറങ്ങാൻ തോന്നിയപ്പോൾ വഴിയിലിറങ്ങി ഉറങ്ങുകയും ചെയ്തു. അപ്പോൾ ഒരാൾ എഴുന്നേറ്റ് എന്നെ വാഴ്ത്തുകയും എന്റെ ആയത്തുകൾ പാരായണം ചെയ്യുകയും ചെയ്തു (ഇതാണ് മറ്റൊരാൾ). മറ്റൊരാൾ ഒരു നിയുക്ത സംഘത്തിൽ പുറപ്പെടുകയും ശത്രുസംഘത്തോടേറ്റുമുട്ടുകയും സംഘം പരാജയപ്പെടുകയും ചെയ്തു. അപ്പോൾ അയാൾ തന്റെ നെഞ്ച്‌വിരിച്ച് മുന്നോട്ട് ചെല്ലുകയും കൊല്ലപ്പെടുകയോ, അല്ലെങ്കിൽ അയാൾക്ക് അല്ലാഹു വിജയം നൽകുകയോ ചെയ്തവൻ. അല്ലാഹു വെറുക്കുന്ന മൂന്നു പേർ ഇവരാണ്: വൃദ്ധനായ വ്യഭിചാരി, ദുരഭിമാനിയായ ദരിദ്രൻ, അക്രമിയായ ധനികൻ." (ന)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 223, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَحْتَطِبَ عَلَى ظَهْرِهِ خَيْرٌ لَهُ، مِنْ أَنْ يَأْتِيَ رَجُلًا فَيَسْأَلَهُ أَعْطَاهُ أَوْ مَنَعَهُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ഏതൊരുവന്റെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, നിങ്ങളിൽ ഒരാൾ മറ്റൊരാളുടെ അടുക്കൽ ചെന്ന് യാചിക്കുകയും അയാൾ നൽകുകയോ നൽകാതിരിക്കുകയോ ചെയ്യുന്നതിനേക്കാൾ ഉത്തമമായത് അയാൾ ഒരു കയറെടുക്കുകയും തന്റെ ചുമലിൽ വിറക് ചുമക്കുകയും ചെയ്യുന്നതാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ، فَيَأْتِيَ بِحُزْمَةِ الْحَطَبِ عَلَى ظَهْرِهِ فَيَبِيعَهَا فَيَكُفَّ اللَّهُ بِهَا وَجْهَهُ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ مَنَعُوهُ". (خ)', 'സുബൈറുബ്നുൽ അവ്വാം(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളുടെ അടുക്കൽ ചെന്ന് യാചിക്കുകയും അവർ നൽകുകയോ തടയുകയോ ചെയ്യുകയും ചെയ്യുന്നതിനേക്കാൾ നിങ്ങളിലോരോരുത്തർക്കും ഉത്തമം കയറെടുത്ത് വിറകുകെട്ട് തന്റെ ചുമലിൽ ചുമന്നുകൊണ്ടുവന്ന് അത് വിൽക്കുകയും അതു മുഖേന അല്ലാഹു അയാളുടെ മുഖം രക്ഷിക്കുകയും ചെയ്യലാണ്." (ബു)', 'الزُّبَيْرِ بْنِ الْعَوَّامِ', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا يَزَالُ الرَّجُلُ يَسْأَلُ النَّاسَ حَتَّى يَأْتِيَ يَوْمَ الْقِيَامَةِ لَيْسَ فِي وَجْهِهِ مُزْعَةُ لَحْمٍ". وَقَالَ: "إِنَّ الشَّمْسَ تَدْنُو يَوْمَ الْقِيَامَةِ حَتَّى يَبْلُغَ الْعَرَقُ نِصْفَ الْأُذُنِ، فَبَيْنَا هُمْ كَذَلِكَ اسْتَغَاثُوا بِآدَمَ، ثُمَّ بِمُوسَى، ثُمَّ بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ". (ق,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ആളുകളോട് യാചിച്ചു കൊണ്ടേയിരിക്കും, അങ്ങനെ അവൻ അന്ത്യനാളിൽ മുഖത്ത് ഒരു മാംസക്കഷ്ണം പോലും ഇല്ലാത്ത അവസ്ഥയിലായിരിക്കും വരിക." പ്രവാചകർ(സ) തുടർന്ന് പറഞ്ഞു: "ഒരാളുടെ ചെവിയുടെ പകുതിവരെ വിയർപ്പിൽ മുങ്ങാൻ മാത്രം അന്ത്യനാളിൽ സൂര്യൻ അടുത്തുവരും. ആ സന്ദർഭത്തിൽ അവർ ആദം(അ)നോടും ശേഷം മൂസാ(അ)നോടും, അനന്തരം മുഹമ്മദ്(സ)യോടും സഹായത്തിനായി അഭ്യർത്ഥിക്കും." (ബു,മു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَأَنْ يَغْدُوَ أَحَدُكُمْ فَيَحْطِبَ عَلَى ظَهْرِهِ، فَيَتَصَدَّقَ بِهِ وَيَسْتَغْنِيَ بِهِ مِنَ النَّاسِ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ رَجُلًا، أَعْطَاهُ أَوْ مَنَعَهُ ذَلِكَ، فَإِنَّ الْيَدَ الْعُلْيَا أَفْضَلُ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ". (ق,ت)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങളിൽ ഒരാൾ പ്രഭാതത്തിൽ പുറപ്പെട്ട് തന്റെ മുതുകിൽ വിറക് ചുമക്കുകയും അതിൽ നിന്ന് ദാനം ചെയ്യുകയും ജനങ്ങളിൽ നിന്ന് സ്വയം പര്യാപ്തനാവുകയും ചെയ്യുന്നതാണ് അയാൾ മറ്റൊരാളോട് ചോദിക്കുകയും എന്നിട്ട് അതവന് നൽകുകയോ നൽകാതിരിക്കുകയോ ചെയ്യുന്നതിനേക്കാൾ ഉത്തമമായത്. ഉയർന്ന (നൽകുന്ന) കൈ താഴ്ന്ന (വാങ്ങുന്ന) കയ്യിനേക്കാൾ ഉത്തമമാണ്. നീ നിന്റെ കുടുംബക്കാരിൽ നിന്നാണ് തുടങ്ങേണ്ടത്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ وَهُوَ عَلَى الْمِنْبَرِ، وَهُوَ يَذْكُرُ الصَّدَقَةَ وَالتَّعَفُّفَ عَنِ الْمَسْأَلَةِ: "الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَالْيَدُ الْعُلْيَا الْمُنْفِقَةُ وَالسُّفْلَى السَّائِلَةُ". (ق,د,ن)', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ): റസൂൽ(സ) സ്വദഖയെയും യാചനയിൽനിന്ന് വിട്ടുനിൽക്കുന്നതിനെയും സംബന്ധിച്ച് മിംബറിൽ വെച്ച് ഉത്ബോധനം ചെയ്യവെ ഇങ്ങനെ പറയുകയുണ്ടായി: "താഴ്ന്നു നിൽക്കുന്ന കൈയ്യിനേക്കാൾ ഉയർന്നു നിൽക്കുന്ന കയ്യാണ് ഉത്തമം. ഉയർന്ന കൈ ചെലവഴിക്കുന്നതും താഴ്ന്ന കൈ യാചിക്കുന്നതുമാണ്." (ബു,മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 224, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ مَالِكِ بْنِ نَضْلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْأَيْدِي ثَلَاثَةٌ: فَيَدُ اللَّهِ الْعُلْيَا، وَيَدُ الْمُعْطِي الَّتِي تَلِيهَا، وَيَدُ السَّائِلِ السُّفْلَى، فَأَعْطِ الْفَضْلَ، وَلَا تَعْجِزْ عَنْ نَفْسِكَ". (د)', 'മാലിക് ബിൻ നള്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "കൈകൾ മൂന്നു വിധമാണ്. അല്ലാഹുവിന്റെ കരമാണ് ഏറ്റവും മുകളിൽ. നൽകുന്നവന്റെ കൈ തൊട്ടു താഴെയാണ്. യാചകന്റെ കൈ ഏറ്റവും അടിയിലാണ്. അതിനാൽ (ഉപജീവനം കഴിച്ച്) മിച്ചമുള്ളത് നീ നൽകുക. നീ സ്വന്തം കാര്യത്തിൽ കഴിവുകെട്ടവനാകരുത്." (ദ)', 'مَالِكِ بْنِ نَضْلَةَ', 'മാലിക് ബിൻ നള്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ أَبِي مُسْلِمٍ الْخَوْلَانِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي الْحَبِيبُ الْأَمِينُ، أَمَّا هُوَ فَحَبِيبٌ إِلَيَّ، وَأَمَّا هُوَ عِنْدِي فَأَمِينٌ: عَوْفُ بْنُ مَالِكٍ الْأَشْجَعِيُّ قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبْعَةً أَوْ ثَمَانِيَةً، أَوْ تِسْعَةً، فَقَالَ: "أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ". وَكُنَّا حَدِيثَ عَهْدٍ بِبَيْعَةٍ، قُلْنَا: قَدْ بَايَعْنَاكَ، حَتَّى قَالَهَا ثَلَاثًا، فَبَسَطْنَا أَيْدِيَنَا فَبَايَعْنَاهُ، فَقَالَ قَائِلٌ: يَا رَسُولَ اللَّهِ، إِنَّا قَدْ بَايَعْنَاكَ فَعَلَامَ نُبَايِعُكَ؟ قَالَ: "أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَتُصَلُّوا الصَّلَوَاتِ الْخَمْسَ، وَتَسْمَعُوا وَتُطِيعُوا". وَأَسَرَّ كَلِمَةً خَفِيَّةً، قَالَ: "وَلَا تَسْأَلُوا النَّاسَ شَيْئًا". قَالَ: فَلَقَدْ كَانَ بَعْضُ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُهُ، فَمَا يَسْأَلُ أَحَدًا أَنْ يُنَاوِلَهُ إِيَّاهُ. (م,د,ن,جه)', 'അബുമുസ്ലിമിൽ ഖൗലാനീ(റ): വിശ്വസ്തനും പ്രിയപ്പെട്ടവനുമായ ആൾ എന്നോട് പറഞ്ഞു: അദ്ദേഹം എനിക്ക് പ്രിയപ്പെട്ടവനാണ്. അദ്ദേഹം എന്റെ അടുക്കൽ വിശ്വസ്തനാണ്. അത് ഔഫുബ്നു മാലികിൽ അശ്ജഈ(റ) ആണ്. അദ്ദേഹം പറയുന്നു: നബി(സ)യുടെ അടുക്കൽ ഞങ്ങൾ ഏഴോ, എട്ടോ, ഒമ്പതോ പേരുണ്ടായിരുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിന്റെ ദൂതനുമായി ബൈഅത്ത് ചെയ്യുന്നില്ലേയോ?" ഞങ്ങളാണെങ്കിൽ ബൈഅത്ത് ചെയ്തിട്ട് അൽപം കാലം മാത്രമേ കഴിഞ്ഞിട്ടുണ്ടായിരുന്നുള്ളൂ. ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ ബൈഅത്ത് ചെയ്തുവല്ലോ. തിരുമേനി(സ) ചോദ്യം മൂന്നു പ്രാവശ്യം ആവർത്തിച്ചു. അപ്പോൾ ഞങ്ങൾ കൈനീട്ടി ബൈഅത്ത് ചെയ്തു. ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലെ! ഞങ്ങൾ ബൈഅത്ത് ചെയ്തുവല്ലോ, ഇനി എന്ത് വിഷയത്തിലാണ് ഞങ്ങൾ ബൈഅത്ത് ചെയ്യേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനെയാണ് ആരാധിക്കുക എന്നും, അവനിൽ ഒരാളെയും പങ്ക് ചേർക്കില്ല എന്നും, അഞ്ചുനേരം നമസ്കരിക്കുമെന്നും (അല്ലാഹുവിൽനിന്നും എന്നിൽനിന്നും) നിങ്ങൾ കേൾക്കുകയും അനുസരിക്കുകയും ചെയ്യുമെന്നും (നിങ്ങൾ ബൈഅത്ത് ചെയ്യുക)". ശേഷം തിരുമേനി(സ) പതുക്കെപ്പറഞ്ഞു: "ജനങ്ങളോട് ഒന്നും തന്നെ യാചിക്കുകയില്ലെന്നും (നിങ്ങൾ ബൈഅത്ത് ചെയ്യുക)." നിവേദകൻ പറയുന്നു: അവരിൽ ചിലർ തന്റെ ചാട്ടവാർ താഴെ വീണാൽ അതെടുക്കാൻ പോലും മറ്റുള്ളവരോട് ആവശ്യപ്പെടാറില്ലായിരുന്നു. (മു,ദ,ന,ജ)', 'أَبِي مُسْلِمٍ الْخَوْلَانِيِّ', 'അബുമുസ്ലിമിൽ ഖൗലാനീ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ وَكَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَكْفُلُ لِي أَنْ لَا يَسْأَلَ النَّاسَ شَيْئًا وَأَتَكَفَّلُ لَهُ بِالْجَنَّةِ". فَقَالَ ثَوْبَانُ: أَنَا. فَكَانَ لَا يَسْأَلُ أَحَدًا شَيْئًا. (د)', 'നബി(സ) യുടെ അടിമയായിരുന്ന സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളോടും യാചിക്കില്ലെന്ന് ആർ എന്നോട് ഏറ്റ് പറയുന്നുവോ അവന് സ്വർഗ്ഗം നൽകുന്ന കാര്യം ഞാൻ ഏറ്റെടുത്തിരിക്കുന്നു." സൗബാൻ(റ) പറഞ്ഞു: ഞാൻ(അതിന് തയ്യാറാണ്)! പിന്നീട് അദ്ദേഹം ആരോടും ഒന്നും ചോദിച്ചിരുന്നില്ല.. (ദ)', 'ثَوْبَانَ', 'നബി(സ) യുടെ അടിമയായിരുന്ന സൗബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنَ الْأَنْصَارِ سَأَلُوا رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَعْطَاهُمْ، ثُمَّ سَأَلُوهُ فَأَعْطَاهُمْ، حَتَّى إِذَا نَفَدَ مَا عِنْدَهُ قَالَ: "مَا يَكُونُ عِنْدِي مِنْ خَيْرٍ فَلَنْ أَدَّخِرَهُ عَنْكُمْ، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ، وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ، وَمَا أَعْطَى اللَّهُ أَحَدًا مِنْ عَطَاءٍ أَوْسَعَ مِنَ الصَّبْرِ". (ق,د,ت,ن)', 'അബുസഈദിൽ ഖുദ്രീ(റ): അൻസ്വാരികളിൽ ചിലർ പ്രവാചകർ(സ)യോട് ദാനം ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) അവർക്ക് നൽകി. വീണ്ടും ചോദിച്ചപ്പോൾ വീണ്ടും നൽകി. അങ്ങനെ തിരുമേനി(സ)യുടെ അടുക്കലുള്ളത് കഴിഞ്ഞപ്പോൾ അവിടന്ന് പറഞ്ഞു: "എന്റെ അടുക്കൽ വല്ലതുമുണ്ടെങ്കിൽ ഞാൻ അത് നിങ്ങൾക്ക് തരാതെ സൂക്ഷിച്ചു വെക്കുകയില്ല. എന്നാൽ ആരെങ്കിലും അന്യരോട് യാചിക്കാതെ അഭിമാനം കാത്ത് ജീവിച്ചാൽ അപ്രകാരം ജീവിക്കാൻ അല്ലാഹു അവനെ സഹായിക്കും. അന്യരിൽ നിന്ന് ഐശ്വര്യവാനായി ജീവിച്ചാൽ അല്ലാഹു അതിനും അവന് സൗകര്യം ചെയ്ത് കൊടുക്കും. ആരെങ്കിലും ക്ഷമ കൈക്കൊണ്ട് ജീവിച്ചാൽ അല്ലാഹു അതിനുള്ള കഴിവ് നൽകും. ക്ഷമയേക്കാൾ വിശാലവും ഉത്തമവുമായ ഒരു ദാനവും അല്ലാഹു ഒരാൾക്കും നൽകിയിട്ടില്ല." (ബു,മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്രീ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَصَابَتْهُ فَاقَةٌ فَأَنْزَلَهَا بِالنَّاسِ لَمْ تُسَدَّ فَاقَتُهُ، وَمَنْ أَنْزَلَهَا بِاللَّهِ أَوْشَكَ اللَّهُ لَهُ بِالْغِنَى: إِمَّا بِمَوْتٍ عَاجِلٍ، أَوْ غِنًى عَاجِلٍ". (د,ت)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവന്നും ദാരിദ്ര്യം പിടിപെട്ടു. എന്നിട്ട് അതുമായി ജനങ്ങളിലേക്ക് ഇറങ്ങിയാൽ അവന്റെ ദാരിദ്ര്യം ഒരിക്കലും പരിഹരിക്കപ്പെടുകയില്ല. അതുമായി ഒരുത്തൻ അല്ലാഹുവിനെ സമീപിച്ചാൽ അല്ലാഹു അവന് ഐശ്വര്യം നൽകിയേക്കാം: ഒന്നുകിൽ പെട്ടെന്നുള്ള മരണം അല്ലെങ്കിൽ ഉടനെയുള്ള ഐശ്വര്യം." (ദ,തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ قَبِيصَةَ بْنِ مُخَارِقٍ الْهِلَالِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: تَحَمَّلْتُ حَمَالَةً، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَقِمْ يَا قَبِيصَةُ حَتَّى تَأْتِيَنَا الصَّدَقَةُ، فَنَأْمُرَ لَكَ بِهَا". ثُمَّ قَالَ: "يَا قَبِيصَةُ، إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثَةٍ: رَجُلٍ تَحَمَّلَ حَمَالَةً، فَحَلَّتْ لَهُ الْمَسْأَلَةُ، فَسَأَلَ حَتَّى يُصِيبَهَا، ثُمَّ يُمْسِكُ. وَرَجُلٍ أَصَابَتْهُ جَائِحَةٌ فَاجْتَاحَتْ مَالَهُ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ فَسَأَلَ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ. أَوْ قَالَ: سِدَادًا مِنْ عَيْشٍ. وَرَجُلٍ أَصَابَتْهُ فَاقَةٌ، حَتَّى يَقُولَ ثَلَاثَةٌ مِنْ ذَوِي الْحِجَى مِنْ قَوْمِهِ: قَدْ أَصَابَتْ فُلَانًا الْفَاقَةُ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ، فَسَأَلَ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ – أَوْ: سِدَادًا مِنْ عَيْشٍ – ثُمَّ يُمْسِكُ. وَمَا سِوَاهُنَّ مِنَ الْمَسْأَلَةِ يَا قَبِيصَةُ سُحْتٌ، يَأْكُلُهَا صَاحِبُهَا سُحْتًا". (م,د,ن)', 'ഖബീസത്തുബ്നു മുഖാരിഖിൽ ഹിലാലീ(റ): ഞാൻ കൂലിക്ക് ചുമടെടുത്തു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പേൾ അവിടന്ന് എന്നോട് പറഞ്ഞു: "നിൽക്കൂ ഖബീസ! സകാത്തിന്റെ ധനം എത്തട്ടെ നിനക്ക് നൽകാൻ വേണ്ടി കൽപ്പിക്കാം. ഖബിസാ, മൂന്നു കുട്ടർക്കേ യാചന പാടുള്ളൂ: ഒരാൾ കൂലിക്ക് മറ്റൊരാൾക്ക് ചുമടെടുത്തു. അയാൾക്ക് (കൂലികിട്ടാൻ) ചോദിക്കേണ്ടതായി വന്നു. അങ്ങനെ അയാൾ കൂലികിട്ടും വരെ ചോദിക്കുകയും കിട്ടിയപ്പോൾ നിർത്തുകയും ചെയ്തു. മറ്റൊരാൾ, അയാൾക്ക് കാലവിപത്ത് കാരണം ധനം നഷ്ടപ്പെടുന്നു. അങ്ങനെ അയാൾക്ക് ആളുകളോട് ചോദിക്കേണ്ടതായി വരുന്നു. അങ്ങനെ അയാളുടെ ജീവന്റെ നിലനിൽപിന് അനിവാര്യമായ സമ്പത്ത് ഉണ്ടാവുന്നത് വരെ യാചിക്കാം. മറ്റൊരാൾക്ക് ദാരിദ്ര്യം വന്നുപെടുന്നു. തന്റെ സമുദായത്തിൽപെട്ട ബുദ്ധിയുള്ള മൂന്നു പേർ അയാൾക്ക് ദാരിദ്ര്യം പിടിപെട്ടുവെന്ന് പറയുന്നു. അങ്ങനെ അയാൾക്ക് ചോദിക്കേണ്ടതായി വരുന്നു. അയാൾക്ക് ജീവിതത്തിന്റെ നിലനിൽപ്പിന്നുള്ളതോ പട്ടിണി അകറ്റാനുള്ളതോ ആവുന്നത് വരെ ചോദിക്കാം. പിന്നീട് അവൻ നിർത്തുകയും ചെയ്യുന്നു. ഖബീസേ, അതിനപ്പുറമുള്ള യാചന നിഷിദ്ധമാണ്. അങ്ങിനെ യാചിച്ചു നടക്കുന്നവൻ ഭക്ഷിക്കുന്നത്, നിഷിദ്ധമായതാണ്." (മു,ദ,ന)', 'قَبِيصَةَ بْنِ مُخَارِقٍ الْهِلَالِيِّ', 'ഖബീസത്തുബ്നു മുഖാരിഖിൽ ഹിലാലീ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُهُ، فَقَالَ: "أَمَا فِي بَيْتِكَ شَيْءٌ". قَالَ: بَلَى، حِلْسٌ: نَلْبَسُ بَعْضَهُ وَنَبْسُطُ بَعْضَهُ، وَقَعْبٌ نَشْرَبُ فِيهِ مِنَ الْمَاءِ. قَالَ: "ائْتِنِي بِهِمَا". قَالَ: فَأَتَاهُ بِهِمَا، فَأَخَذَهُمَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ وَقَالَ: "مَنْ يَشْتَرِي هَذَيْنِ". قَالَ رَجُلٌ: أَنَا آخُذُهُمَا بِدِرْهَمٍ، قَالَ: "مَنْ يَزِيدُ عَلَى دِرْهَمٍ". مَرَّتَيْنِ أَوْ ثَلَاثًا، قَالَ رَجُلٌ: أَنَا آخُذُهُمَا بِدِرْهَمَيْنِ، فَأَعْطَاهُمَا إِيَّاهُ، وَأَخَذَ الدِّرْهَمَيْنِ وَأَعْطَاهُمَا الْأَنْصَارِيَّ، وَقَالَ: "اشْتَرِ بِأَحَدِهِمَا طَعَامًا، فَانْبِذْهُ إِلَى أَهْلِكَ. وَاشْتَرِ بِالْآخَرِ قَدُومًا فَأْتِنِي بِهِ". فَأَتَاهُ بِهِ، فَشَدَّ فِيهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عُودًا بِيَدِهِ، ثُمَّ قَالَ لَهُ: "اذْهَبْ فَاحْتَطِبْ وَبِعْ، وَلَا أَرَيَنَّكَ خَمْسَةَ عَشَرَ يَوْمًا". فَذَهَبَ الرَّجُلُ يَحْتَطِبُ وَيَبِيعُ، فَجَاءَ وَقَدْ أَصَابَ عَشْرَةَ دَرَاهِمَ، فَاشْتَرَى بِبَعْضِهَا ثَوْبًا، وَبِبَعْضِهَا طَعَامًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَذَا خَيْرٌ لَكَ مِنْ أَنْ تَجِيءَ الْمَسْأَلَةُ نُكْتَةً فِي وَجْهِكَ يَوْمَ الْقِيَامَةِ، إِنَّ الْمَسْأَلَةَ لَا تَصْلُحُ إِلَّا لِثَلَاثَةٍ: لِذِي فَقْرٍ مُدْقِعٍ، أَوْ لِذِي غُرْمٍ مُفْظِعٍ، أَوْ لِذِي دَمٍ مُوجِعٍ". (د,ت,جه)', 'അനസുബിൻ മാലിക്(റ): അൻസാരികളിൽപ്പെട്ട ഒരാൾവന്ന് നബി(സ)യോട് യാചിച്ചു: അപ്പോൾ പ്രവാചകർ(സ)ചോദിച്ചു: "നിന്റെ വീട്ടിൽ വല്ലതും ഉണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, കുതിരപ്പടമുണ്ട്, അതിന്റെ ഒരു ഭാഗം ധരിക്കാനും മറ്റൊരു ഭാഗം വിരിക്കാനും ഞങ്ങൾ ഉപയോഗിക്കുന്നു. ഞങ്ങൾ കുടിക്കാൻ ഉപയോഗിക്കുന്ന ഒരു പാത്രവുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവ എന്റെ അടുക്കൽ കൊണ്ടുവരിക." അനസ്(റ) പറയുന്നു: അങ്ങനെ അയാൾ അവ രണ്ടും കൊണ്ട്‌വന്നു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "ഇവരണ്ടും ആരാണ് വിലക്ക് വാങ്ങുക?" ഒരാൾ പറഞ്ഞു: ഞാൻ അത് ഒരു ദിർഹമിന്ന് വാങ്ങാം. റസൂൽ(സ) പറഞ്ഞു: "ആരാണ് ഒരു ദിർഹമിനേക്കാൾ അധികം നൽകുക". പ്രവാചകർ(സ) ഇങ്ങനെ രണ്ടോ മൂന്നോ പ്രാവശ്യം ആവർത്തിച്ചു പറഞ്ഞു. ഒരാൾ പറഞ്ഞു: ഞാൻ അത് രണ്ട് ദിർഹമിന്നെടുക്കാം. അപ്പോൾ അത് അദ്ദേഹത്തിന്ന് രണ്ട് ദിർഹമിന് നൽകി. അവ രണ്ടും പ്രവാചകർ(സ) അൻസാരിക്ക് നൽകുകയും ചെയ്തു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "ഒരു ദിർഹമിന് ഭക്ഷണം വാങ്ങിച്ച് അത് വീട്ടുകാർക്ക് എത്തിക്കുക. ബാക്കി ഒരു ദിർഹമിന് നീ ഒരു മഴു വാങ്ങി അതുമായി എന്റെ അടുത്ത് വരികയും ചെയ്യുക." അങ്ങനെ അതുമായി തിരുമേനി(സ)യുടെ അടുക്കൽ അദ്ദേഹം ചെന്നു. അപ്പോൾ റസൂൽ(സ) അതിൽ ഒരു (മരക്കൊമ്പ്) പിടി ഉറപ്പിച്ചുകൊടുത്തു. എന്നിട്ട് അദ്ദേഹത്തോട് പറഞ്ഞു: "ഇതുമായി ചെന്ന് വിറക് വെട്ടി വിൽക്കുക. പതിനഞ്ച് ദിവസത്തേക്ക് ഇവിടെ കാണരുത്." അങ്ങനെ അയാൾ വിറകു വെട്ടി വിൽക്കാൻ പോയി. അങ്ങനെ അദ്ദേഹത്തിന് പത്ത് ദിർഹം ലഭിച്ചു. കുറച്ച് ദിർഹമിന്ന് വസ്ത്രവും കുറച്ച് ദിർഹമിന് ഭക്ഷണവും വാങ്ങി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യദിനത്തിൽ നിന്റെ മുഖത്ത് യാചനയുടെ അടയാളം ഉണ്ടാകുന്നതിനേക്കാൾ നിനക്ക് നല്ലത് ഇതാണ്. യാചന മൂന്നു വിഭാഗക്കാർക്കേ പാടുള്ളൂ. കടുത്ത ദാരിദ്ര്യമുള്ളവർക്ക്, ഭാരിച്ച കടമുള്ളവർക്ക്, തന്റെ കൊല്ലപ്പെട്ടവന്റെ കുടുംബത്തിന് കനത്ത ദണ്ഡം കൊടുക്കാനുള്ളവർക്ക്." (ദ,ത,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബിൻ മാലിക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','ത','ജ']::text[], null, null, 227, 227, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ عَطَاءِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ عَنْ رَجُلٍ مِنْ بَنِي أَسَدٍ أَنَّهُ قَالَ: نَزَلْتُ أَنَا وَأَهْلِي بِبَقِيعِ الْغَرْقَدِ، فَقَالَ لِي أَهْلِي: اذْهَبْ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَلْهُ لَنَا شَيْئًا نَأْكُلُهُ، فَجَعَلُوا يَذْكُرُونَ مِنْ حَاجَتِهِمْ، فَذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَوَجَدْتُ عِنْدَهُ رَجُلًا يَسْأَلُهُ، وَرَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا أَجِدُ مَا أُعْطِيكَ". فَتَوَلَّى الرَّجُلُ عَنْهُ وَهُوَ مُغْضَبٌ، وَهُوَ يَقُولُ: لَعَمْرِي إِنَّكَ لَتُعْطِي مَنْ شِئْتَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَغْضَبُ عَلَيَّ أَنْ لَا أَجِدَ مَا أُعْطِيهِ؟ مَنْ سَأَلَ مِنْكُمْ وَلَهُ أُوقِيَّةٌ أَوْ عِدْلُهَا فَقَدْ سَأَلَ إِلْحَافًا". قَالَ الْأَسَدِيُّ: فَقُلْتُ: لَلِقْحَةٌ لَنَا خَيْرٌ مِنْ أُوقِيَّةٍ، وَالْأُوقِيَّةُ أَرْبَعُونَ دِرْهَمًا، قَالَ: فَرَجَعْتُ وَلَمْ أَسْأَلْهُ، فَقَدِمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ شَعِيرٌ وَزَبِيبٌ، فَقَسَمَ لَنَا مِنْهُ أَوْ كَمَا قَالَ حَتَّى أَغْنَانَا اللَّهُ عَزَّ وَجَلَّ. (د,ن)', 'അത്വാഉബ്നു യസാർ(റ) ബനൂഅസദിലെ ഒരാളിൽ നിന്ന് ഉദ്ധരിക്കുന്നു: അദ്ദേഹം പറഞ്ഞു: ഞാനും കുടുംബവും ബഖീഉൽ ഗർഖദിൽ ഇറങ്ങി. അപ്പോൾ എന്റെ വീട്ടുകാർ എന്നോട് പറഞ്ഞു: നിങ്ങൾ നബി(സ)യുടെ അടുക്കൽ പോയി ഞങ്ങൾക്ക് വേണ്ടി ഭക്ഷിക്കാൻ വല്ലതും ചോദിക്കുക. അങ്ങനെ അവർ ആവശ്യം ആവർത്തിച്ചു പറയാൻ തുടങ്ങി. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് പോയി. അപ്പോൾ ഒരാൾ അവിടത്തോട് യാചിക്കുന്നതും തിരുമേനി(സ) അയാളോട് "എന്റെ അടുക്കൽ നിനക്ക് നൽകാൻ ഒന്നും കാണുന്നില്ല" എന്ന് പറയുന്നതും ഞാൻ കണ്ടു. അങ്ങനെ അയാൾ ''എന്റെ ജീവൻ തന്നെ സത്യം, താങ്കൾ ഇഷ്ടമുള്ളവർക്ക് മാത്രം നൽകുന്നു'' എന്ന് പറഞ്ഞുകൊണ്ട് കോപിഷ്ഠനായ നിലയിൽ തിരിച്ചുപോകുന്നതും ഞാൻ കണ്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്റെ അടുക്കൽ ഒന്നും നൽകാൻ ഇല്ലാത്തതിന് കോപിഷ്ഠനായി പോകുന്നു. നിങ്ങളിൽ ഒരു ഊഖിയയോ അതിനു തുല്യമായതോ ഉള്ളവൻ യാചിക്കുന്നുവെങ്കിൽ അവൻ യാചിക്കുന്നത് ആളുകളെ ബുദ്ധിമുട്ടിക്കുന്ന രൂപത്തിലാണ്." അസദ് ഗോത്രക്കാരൻ പറഞ്ഞു: ഞാൻ പറഞ്ഞു: ഞങ്ങളുടെ പ്രസവിക്കാറായ കറവഒട്ടകം ഒരു ഊഖിയയോക്കാൾ വലുതാണ്. ഊഖിയ എന്നാൽ നാൽപത് ദിർഹമാണ്. അദ്ദേഹം തുടർന്ന് പറയുന്നു: ഞാൻ തിരുമേനി(സ)യോട് ചോദിക്കാതെ മടങ്ങിപ്പോന്നു. അങ്ങനെയിരിക്കെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് ബാർലിയും ഉണക്കമുന്തിരിയും കൊണ്ടുവരപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾക്ക് അതിൽ നിന്ന് നബി(സ) വിഹിതം നൽകി. പ്രതാപശാലിയും ഇന്നതനുമായ അല്ലാഹു ഞങ്ങൾക്ക് അങ്ങനെ ഐശ്വര്യം നൽകി. (ദ,ന)', 'عَطَاءِ بْنِ يَسَارٍ', 'അത്വാഉബ്നു യസാർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 227, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْمَسْأَلَةَ كَدٌّ يَكُدُّ – وَفِي رِوَايَةٍ: كُدُوحٌ يَكْدَحُ بِهَا – بِهَا الرَّجُلُ وَجْهَهُ، إِلَّا أَنْ يَسْأَلَ الرَّجُلُ سُلْطَانًا أَوْ فِي أَمْرٍ لَا بُدَّ مِنْهُ". (د,ت,ن)', 'സമറത്തുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "യാചന ഒരാൾ തന്റെ മുഖത്തെ വളെരെയധികം ക്ഷീണിപ്പിക്കുന്ന – മറ്റൊരു റിപ്പോർട്ടിൽ: അത്യദ്ധ്വാനം ചെയ്യിക്കുന്ന – പ്രവർത്തിയാണ്. ഒരാൾ നാടിന്റെ അധികാരിയോട് ചോദിക്കുന്നതും അനിവാര്യമായ ഒരു കാര്യത്തിന് വേണ്ടി ചോദിക്കുന്നതും ഇപ്രകാരമല്ല." (ദ,തു,ന)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമറത്തുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=249), 1, 'وَفِي رِوَايَةٍ: كُدُوحٌ يَكْدَحُ بِهَا – بِهَا الرَّجُلُ وَجْهَهُ، إِلَّا أَنْ يَسْأَلَ الرَّجُلُ سُلْطَانًا أَوْ فِي أَمْرٍ لَا بُدَّ مِنْهُ". (د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: അത്യദ്ധ്വാനം ചെയ്യിക്കുന്ന – പ്രവർത്തിയാണ്. ഒരാൾ നാടിന്റെ അധികാരിയോട് ചോദിക്കുന്നതും അനിവാര്യമായ ഒരു കാര്യത്തിന് വേണ്ടി ചോദിക്കുന്നതും ഇപ്രകാരമല്ല." (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ يَحْتَزِمَ أَحَدُكُمْ حُزْمَةَ حَطَبٍ عَلَى ظَهْرِهِ، فَيَبِيعَهَا، خَيْرٌ مِنْ أَنْ يَسْأَلَ رَجُلًا، فَيُعْطِيَهُ أَوْ يَمْنَعَهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ മുതുകിൽ വിറകു കെട്ടുണ്ടാക്കി ചുമക്കുകയും അത് വിൽക്കുകയും ചെയ്യുന്നതാണ് ഒരാളോട് യാചിക്കുകയും അയാൾക്ക് നൽകുകയോ നൽകാതിരിക്കുകയോ ചെയ്യുന്നതിനേക്കാൾ ഉത്തമം." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ عَائِذِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ فَأَعْطَاهُ، فَلَمَّا وَضَعَ رِجْلَهُ عَلَى أُسْكُفَّةِ الْبَابِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَعْلَمُونَ مَا فِي الْمَسْأَلَةِ مَا مَشَى أَحَدٌ إِلَى أَحَدٍ يَسْأَلُهُ شَيْئًا". (ن)', 'ആഇദുബിൻ അംറ്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന് യാചിച്ചു. അവിടന്ന് നൽകി. അദ്ദേഹം തന്റെ കാൽ വാതിലിന്റെ ഉമ്മറപ്പടിയിൽ വെച്ചപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "യാചനയിലുള്ളത് എന്താണെന്ന് നിങ്ങൾ അറിഞ്ഞിരുന്നെങ്കിൽ ഒരാളും യാചിക്കാൻ മറ്റൊരാളുടെ അടുക്കലേക്ക് നടന്നു ചെല്ലുകയില്ലായിരുന്നു." (ന)', 'عَائِذِ بْنِ عَمْرٍو', 'ആഇദുബിൻ അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَضْمَنْ لِي وَاحِدَةً وَلَهُ الْجَنَّةُ". قَالَ يَحْيَى هَاهُنَا كَلِمَةٌ مَعْنَاهَا: "أَنْ لَا يَسْأَلَ النَّاسَ شَيْئًا". (م,ن)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവനും എനിക്ക് ഒരു കാര്യത്തിൽ ഉറപ്പ് നൽകുന്നുവോ അവന് സ്വർഗ്ഗമുണ്ട്." യഹ്യാ(റ) പറയുന്നു. ഇവിടെ ഒരു പദമുണ്ട് അതിന്റെ ആശയം ഇപ്രകാരമാണ്. "ജനങ്ങളോട് ഒന്നും ചോദിക്കാതിരിക്കുക." (മു,ന)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 228, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُلْحِفُوا فِي الْمَسْأَلَةِ، فَوَاللَّهِ لَا يَسْأَلُنِي أَحَدٌ مِنْكُمْ شَيْئًا فَتُخْرِجَ لَهُ مَسْأَلَتُهُ مِنِّي شَيْئًا وَأَنَا لَهُ كَارِهٌ فَيُبَارَكَ لَهُ فِيمَا أَعْطَيْتُهُ". (م,ن)', 'മുആവിയ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ യാചനയിൽ ആളുകളെ ബുദ്ധിമുട്ടിക്കരുത്. അല്ലാഹു തന്നെ സത്യം, എന്നോട് നിങ്ങളിലൊരാൾ എന്തെങ്കിലും ചോദിക്കുകയും ഞാൻ മനഃപ്രയാസത്തോടെ എന്തെങ്കിലും നൽകുകയും ചെയ്താൽ ഞാൻ നൽകിയതിൽ അവന് ബർകത് ചെയ്യപ്പെടുകയില്ല." (മു,ന)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ وَلَهُ أَرْبَعُونَ دِرْهَمًا فَهُوَ الْمُلْحِفُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ വശം നാൽപത് ദിർഹം ഉണ്ടായിട്ടും ഒരാൾ യാചിക്കുകയാണെങ്കിൽ അവൻ ജനങ്ങളെ ബുദ്ധിമുട്ടിച്ചുകൊണ്ട് യാചിക്കുന്നവനാണ്." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَرَّحَتْنِي أُمِّي إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ وَقَعَدْتُ، فَاسْتَقْبَلَنِي وَقَالَ: "مَنِ اسْتَغْنَى أَغْنَاهُ اللَّهُ عَزَّ وَجَلَّ، وَمَنِ اسْتَعَفَّ أَعَفَّهُ اللَّهُ عَزَّ وَجَلَّ، وَمَنِ اسْتَكْفَى كَفَاهُ اللَّهُ عَزَّ وَجَلَّ، وَمَنْ سَأَلَ وَلَهُ قِيمَةُ أُوقِيَّةٍ فَقَدْ أَلْحَفَ". فَقُلْتُ: نَاقَتِي الْيَاقُوتَةُ خَيْرٌ مِنْ أُوقِيَّةٍ، فَرَجَعْتُ وَلَمْ أَسْأَلْهُ. (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): എന്റെ മാതാവ് എന്നെ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് (ദാനം ചോദിക്കാൻ) പറഞ്ഞയച്ചു. അങ്ങനെ ഞാൻ ചെന്ന് റസൂൽ(സ) യുടെ അടുത്ത് ഇരുന്നു. തിരുമേനി(സ) എന്നിലേക്ക് തിരഞ്ഞ് കൊണ്ട് പറഞ്ഞു: "ഒരാൾ മറ്റാളുകളെ അവലംബിക്കാതെ ധന്യനായി ജീവിക്കാൻ ആഗ്രഹിച്ചാൽ അല്ലാഹു അവന് ഐശ്വര്യം നൽകും. വല്ലവനും മറ്റുള്ളവരോട് യാചിക്കാതെ സ്വയം പ്രയത്നഫലം കൊണ്ട് ജീവിക്കാൻ ഉദ്ദേശിച്ചാൽ അല്ലാഹു അതിനുള്ള കഴിവ് അവന് നൽകും. ആരെങ്കിലും ഉള്ളതു കൊണ്ട് തൃപ്തിയടഞ്ഞ് ജീവിതം നയിക്കാൻ യത്നിച്ചാൽ അല്ലാഹു അവന് അതിനുള്ള പ്രാപ്തി നൽകും. ഒരാളുടെ പക്കൽ ഒരു ഊഖിയ(നാൽപത് വെള്ളി ദിർഹം)ക്ക് തുല്യമായ സമ്പത്ത് ഉണ്ടായിട്ടും അയാൾ യാചിച്ചാൽ അവൻ ആളുകളെ ബുദ്ധിമുട്ടിച്ചുകൊണ്ടാണ് യാചിക്കുന്നത്." ഞാൻ പറഞ്ഞു: എന്റെ കറവ ഒട്ടകം ഒരു ഊഖിയയേക്കാൾ ഉത്തമമായതാണ് (വിലമതിക്കുന്നതാണ്). അങ്ങനെ ഞാൻ പ്രവാചകർ(സ)യോട് ചോദിക്കാതെ തിരിച്ചു പോന്നു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ طَارِقٍ الْمُحَارِبِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْنَا الْمَدِينَةَ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ عَلَى الْمِنْبَرِ يَخْطُبُ النَّاسَ، وَهُوَ يَقُولُ: "يَدُ الْمُعْطِي الْعُلْيَا، وَابْدَأْ بِمَنْ تَعُولُ: أُمَّكَ وَأَبَاكَ وَأُخْتَكَ وَأَخَاكَ، ثُمَّ أَدْنَاكَ أَدْنَاكَ". (ن)', 'ത്വാരിഖിൽ മുഹാരിബീ(റ): ഞങ്ങൾ മദീനയിൽ വന്നു. അപ്പോൾ റസൂൽ(സ) തന്റെ പ്രസംഗത്തിനിടെ ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു: "നൽകുന്ന കൈയാണ് ഉൽകൃഷ്ഠമായത്. നീ നിന്റെ കുടുംബത്തിൽനിന്നും ദാനം ആരംഭിക്കുക. നിന്റെ മാതാവിന്, നിന്റെ പിതാവിന്, നിന്റെ സഹോദരിക്ക്, നിന്റെ സഹോദരന്, പിന്നെ അതിനടുത്ത ബന്ധമുള്ളവർക്ക്, ശേഷം അതിനടുത്ത ബന്ധമുള്ളവർക്ക്." (ന)', 'طَارِقٍ الْمُحَارِبِيِّ', 'ത്വാരിഖിൽ മുഹാരിബീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعْطِي عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ الْعَطَاءَ، فَيَقُولُ لَهُ عُمَرُ: أَعْطِهِ يَا رَسُولَ اللَّهِ أَفْقَرَ إِلَيْهِ مِنِّي، فَقَالَ [لَهُ] رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خُذْهُ فَتَمَوَّلْهُ أَوْ تَصَدَّقْ بِهِ، وَمَا جَاءَكَ مِنْ هَذَا الْمَالِ وَأَنْتَ غَيْرُ مُشْرِفٍ وَلَا سَائِلٍ فَخُذْهُ، وَمَا لَا فَلَا تُتْبِعْهُ نَفْسَكَ". قَالَ سَالِمٌ: فَمِنْ أَجْلِ ذَلِكَ كَانَ ابْنُ عُمَرَ لَا يَسْأَلُ أَحَدًا شَيْئًا، وَلَا يَرُدُّ شَيْئًا أُعْطِيَهُ. (خ,ن)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ)വിന് റസൂൽ(സ) ദാനം നൽകുമായിരുന്നു. അപ്പോൾ ഉമർ(റ) പറയും: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെക്കാൾ ദരിദ്രരായവർക്ക് നൽകിയാലും. അപ്പോൾ റസൂൽ(സ) (ഉമർ(റ)വിനോട്) പറഞ്ഞു: "താങ്കൾ ഇതു വാങ്ങുക, എന്നിട്ട് സൂക്ഷിച്ചു വെക്കുകയോ ദാനം കൊടുക്കുകയോ ചെയ്യുക. താങ്കൾ അതിലേക്ക് ആർത്തി കാണിക്കാതിരിക്കുകയും ചോദിച്ചു വാങ്ങാതിരിക്കുകയും ചെയ്ത സ്ഥിതിക്ക് താങ്കൾക്ക് വന്നുകിട്ടിയത് സ്വീകരിച്ചുകൊള്ളുക. അങ്ങനെയല്ലാത്തതിന്റെ പിറകെ പോവുകയും അരുത്." സാലിം(റ) പറയുന്നു: അതു കാരണത്താൽ ഇബ്നുഉമർ(റ) ഒരാളോടും ഒന്നും ചോദിച്ചുവാങ്ങുകയോ ഒരാൾ ദാനമായി നൽകിയത് മടക്കുകയോ ചെയ്യുകയില്ലായിരുന്നു. (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], 'لَهُ', null, 229, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ يَأْخُذَ أَحَدُكُمْ أَحْبُلَهُ، فَيَأْتِيَ الْجَبَلَ، فَيَجِيءَ بِحُزْمَةِ حَطَبٍ عَلَى ظَهْرِهِ، فَيَبِيعَهَا فَيَسْتَغْنِيَ بِثَمَنِهَا، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ، أَعْطَوْهُ أَوْ مَنَعُوهُ". (خ,جه)', 'സുബൈറുബ്നുൽ അവ്വാം(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ യാചിച്ച്, അതവന് നൽകുകയോ നൽകാതിരിക്കുകയോ ചെയ്യുന്നതിനേക്കാൾ ഉൽകൃഷ്ടമായത്, അവൻ കയറുകൾ എടുത്ത് പർവ്വതത്തിൽ ചെന്ന് തന്റെ മുതുകിൽ വിറക് ചുമന്ന് കൊണ്ടുവരികയും അത് വിറ്റ് അതിന്റെ വിലയ്ക്ക് സ്വയം ഐശ്വര്യം നേടുകയും ചെയ്യുന്നതാണ്." (ബു,ജ)', 'الزُّبَيْرِ بْنِ الْعَوَّامِ', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَتَقَبَّلُ لِي بِوَاحِدَةٍ وَأَتَقَبَّلُ لَهُ بِالْجَنَّةِ". قُلْتُ: أَنَا. قَالَ: "لَا تَسْأَلِ النَّاسَ شَيْئًا". قَالَ: فَكَانَ ثَوْبَانُ يَقَعُ سَوْطُهُ وَهُوَ رَاكِبٌ، فَلَا يَقُولُ لِأَحَدٍ: نَاوِلْنِيهِ، حَتَّى يَنْزِلَ فَيَأْخُذَهُ. (ن,جه)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവനും എന്നോട് ഒരു കാര്യം ഏൽക്കുകയാണെങ്കിൽ ഞാൻ അവന് സ്വർഗ്ഗം നൽകുന്ന കാര്യം ഏറ്റെടുക്കുന്നതാണ്." ഞാൻ പറഞ്ഞു: ഞാൻ ഏറ്റെടുക്കാം തിരുമേനി(സ) പറഞ്ഞു: "ജനങ്ങളോട് ഒന്നും തന്നെ ചോദിക്കരുത്." നിവേദകൻ പറയുന്നു: സൗബാൻ(റ) തന്റെ വാഹനപ്പുറത്ത് യാത്ര ചെയ്യുമ്പോൾ അദ്ദേഹത്തിന്റെ ചാട്ടവാർ താഴെ വീഴാറുണ്ടായിരുന്നു. ഒരാളോടും അതൊന്ന് എടുത്ത് തരൂ എന്ന് ആവശ്യപ്പെടാറില്ല. അദ്ദേഹം ഇറങ്ങി അതെടുക്കുകയാണ് ചെയ്യുക. (ന,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ النَّاسَ أَمْوَالَهُمْ تَكَثُّرًا فَإِنَّمَا يَسْأَلُ جَمْرَ جَهَنَّمَ، فَلْيَسْتَقِلَّ مِنْهُ أَوْ لِيُكْثِرْ". (م,جه)', 'അബൂഹുറൈറ(റ): റസുൽ(സ) പറഞ്ഞു: "വല്ലവനും തന്റെ സ്വത്ത് അധികരിപ്പിക്കാൻ വേണ്ടി ജനങ്ങളോട് യാചിക്കുകയാണെങ്കിൽ അവൻ യാചിക്കുന്നത് നരകത്തിലെ തീക്കനലിനെയാണ്. അതിനാൽ അവൻ യാചന ചുരുക്കുകയോ അധികരിപ്പിക്കുകയോ ചെയ്തുകൊള്ളട്ടെ." (രണ്ടിന്റെയും ഫലം അവന് തന്നെ എന്നർത്ഥം) (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ الْفِرَاسِيِّ رَضِيَ اللهُ عَنْهُ: قَالَ لِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَسْأَلُ يَا رَسُولَ اللَّهِ؟ قَالَ: "لَا، وَإِنْ كُنْتَ سَائِلًا لَا بُدَّ فَاسْأَلِ الصَّالِحِينَ". (د,ن)', 'ഫിറാസി(റ): റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ യാചിക്കട്ടെയോ? അവിടന്ന് പറഞ്ഞു: "വേണ്ട, ഇനി നിനക്ക് യാചിക്കുകയല്ലാതെ മാർഗ്ഗമില്ലെങ്കിൽ നീ സദ്‌വൃത്തരായവരോട് ചോദിക്കുക." (ദ,ന)', 'الْفِرَاسِيِّ', 'ഫിറാസി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 230, 231, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّ حُوَيْطِبَ بْنَ عَبْدِ الْعُزَّى أَخْبَرَهُ: أَنَّ عَبْدَ اللَّهِ بْنَ السَّعْدِيِّ أَخْبَرَهُ: أَنَّهُ قَدِمَ عَلَى عُمَرَ بْنِ الْخَطَّابِ فِي خِلَافَتِهِ، فَقَالَ لَهُ عُمَرُ: أَلَمْ أُحَدَّثْ أَنَّكَ تَلِي مِنْ أَعْمَالِ النَّاسِ أَعْمَالًا، فَإِذَا أُعْطِيتَ الْعُمَالَةَ رَدَدْتَهَا؟ فَقُلْتُ: بَلَى، فَقَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: فَمَا تُرِيدُ إِلَى ذَلِكَ؟ فَقُلْتُ: لِي أَفْرَاسٌ وَأَعْبُدٌ، وَأَنَا بِخَيْرٍ، وَأُرِيدُ أَنْ يَكُونَ عَمَلِي صَدَقَةً عَلَى الْمُسْلِمِينَ. فَقَالَ لَهُ عُمَرُ: فَلَا تَفْعَلْ، فَإِنِّي كُنْتُ أَرَدْتُ مِثْلَ الَّذِي أَرَدْتَ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْطِينِي الْعَطَاءَ فَأَقُولُ: أَعْطِهِ أَفْقَرَ إِلَيْهِ مِنِّي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خُذْهُ فَتَمَوَّلْهُ أَوْ تَصَدَّقْ بِهِ، مَا جَاءَكَ مِنْ هَذَا الْمَالِ وَأَنْتَ غَيْرُ مُشْرِفٍ وَلَا سَائِلٍ فَخُذْهُ، وَمَا لَا فَلَا تُتْبِعْهُ نَفْسَكَ". (ن)', 'സാഇബുബ്നു യസീദ്(റ): ഹുവൈത്വിബുബ്നു അബ്ദിൽഉസ്സാ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു സഅ്ദീ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: അദ്ദേഹം ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെ അടുത്തേക്ക് അദ്ദേഹത്തിന്റെ ഭരണകാലത്ത് ചെന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: നീ ജോലി എടുക്കുന്നത് ജനങ്ങളുടെ പൊതു സ്വത്തിൻമേലാണെന്ന് ഞാൻ നിന്നോട് പറഞ്ഞിട്ടില്ലേ? എന്നിട്ടും നിനക്ക് ദാനം നൽകപ്പെട്ടാൽ അത് മടക്കുകയാണോ? അപ്പോൾ ഞാൻ പറഞ്ഞു: അതെ. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: താങ്കളെന്താണ് അങ്ങനെ തീരുമാനിക്കുന്നത്? ഞാൻ പറഞ്ഞു: എനിക്ക് അടിമകളും കുതിരകളും ഉണ്ട്. ഞാൻ സൗഖ്യത്തിലുമാണ്. എന്റെ ജോലി മുസ്ലിംകൾക്കുള്ള സ്വദഖയായിരിക്കട്ടെ എന്നാണ് ഞാൻ ആഗ്രഹിക്കുന്നത്. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അങ്ങനെ ചെയ്യരുത്, നീ ഉദ്ദേശിച്ചത് പോലെത്തന്നെ ഞാനും (പ്രവാചകർ(സ)യുടെ കാലത്ത്) ഉദ്ദേശിച്ചിരുന്നു. റസൂൽ(സ) എനിക്ക് ദാനം നൽകും. അപ്പോൾ ഞാൻ പറയും: എന്നേക്കാൾ ദാരിദ്ര്യമുള്ളവർക്ക് നൽകിയാലും. അപ്പോൾ റസുൽ(സ) പ്രതിവചിച്ചു: "താങ്കൾ ഇത് സ്വീകരിക്കുക. താങ്കൾ ഇത് എടുത്തു വെക്കുകയോ ദാനം ചെയ്യുകയോ ചെയ്തുകൊള്ളുക. യാചിക്കുകയോ ലഭിക്കാൻ വേണ്ടി ആർത്തിയോടെ എത്തിനോക്കുകയോ ചെയ്യാതെ താങ്കൾക്ക് വന്നെത്തിയ ധനം താങ്കൾ സ്വീകരിച്ചുകൊള്ളുക. അങ്ങനെയല്ലാത്തതിന്റെ പിറകെ നിന്റെ മനസ്സിനെ താങ്കൾ വിടരുത്." (ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 231, 231, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُؤْتَى بِالتَّمْرِ عِنْدَ صِرَامِ النَّخْلِ، فَيَجِيءُ هَذَا بِتَمْرِهِ وَهَذَا مِنْ تَمْرِهِ، حَتَّى يَصِيرَ عِنْدَهُ كَوْمًا مِنْ تَمْرٍ، فَجَعَلَ الْحَسَنُ وَالْحُسَيْنُ رَضِيَ اللَّهُ عَنْهُمَا يَلْعَبَانِ بِذَلِكَ التَّمْرِ، فَأَخَذَ أَحَدُهُمَا تَمْرَةً فَجَعَلَهَا فِي فِيهِ، فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْرَجَهَا مِنْ فِيهِ، فَقَالَ: "أَمَا عَلِمْتَ أَنَّ آلَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَأْكُلُونَ الصَّدَقَةَ". (خ)', 'അബുഹുറൈറ(റ): കാരക്ക പറിച്ചെടുക്കുന്ന സമയത്ത് റസൂൽ(സ)യുടെ അടുക്കൽ കാരക്ക(അതിന്റെ സകാത്ത്) കൊണ്ടുവരുമായിരുന്നു. ഓരോരുത്തരും അവനവന്റെ കാരക്കയിൽനിന്ന് കൊണ്ട്‌വരും. അങ്ങനെ അവിടെ കാരക്ക കുട്ടിയിട്ട കുമ്പാരമുണ്ടാകും. ഒരിക്കൽ ഹസൻ(റ)വും ഹുസൈൻ(റ)വും ആ കാരക്കക്കൂനക്കരികിലൂടെ കളിക്കുകയായിരുന്നു. അവരിലൊരാൾ ഒരു കാരക്ക എടുത്ത് തന്റെ വായിലിട്ടു. അപ്പോൾ റസൂൽ(സ) അവനിലേക്ക് നോക്കി. എന്നിട്ട് അവിടുന്ന് അത് അവന്റെ വായിൽനിന്ന് പുറത്തെടുത്തു. എന്നിട്ട് പറഞ്ഞു: "മുഹമ്മദ്(സ)യുടെ കുടുംബം സകാത്തിന്റെ ധനം ഭക്ഷിക്കുകയില്ലെന്ന് നിനക്കറിയില്ലേ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 231, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: وَجَدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةً مَيِّتَةً، أُعْطِيَتْهَا مَوْلَاةٌ لِمَيْمُونَةَ مِنَ الصَّدَقَةِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلَّا انْتَفَعْتُمْ بِجِلْدِهَا؟". قَالُوا: إِنَّهَا مَيْتَةٌ، قَالَ: "إِنَّمَا حَرُمَ أَكْلُهَا". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരു ആടിനെ ചത്തതായി കാണുകയുണ്ടായി. മൈമൂന(റ)യുടെ അടിമക്ക് സദഖയായി നൽകപ്പെട്ടതായിരുന്നു അത്. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് അതിന്റെ തോൽ ഉപയോഗപ്പെടുത്തിക്കൂടെ" അവർ പറഞ്ഞു: അത് ചത്തതാണ്, അപ്പോൾ റസുൽ(സ) പറഞ്ഞു: "അത് ഭക്ഷിക്കുന്നത് മാത്രമാണ് വിലക്കപ്പെട്ടിട്ടുള്ളത്." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذَ الْحَسَنُ بْنُ عَلِيٍّ تَمْرَةً مِنْ تَمْرِ الصَّدَقَةِ، فَجَعَلَهَا فِي فِيهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كِخْ كِخْ، ارْمِ بِهَا، أَمَا عَلِمْتَ أَنَّا لَا نَأْكُلُ الصَّدَقَةَ". (م)', 'അബുഹുറൈറ(റ) ഹസനുബ്നു അലി(റ) സകാത്തിന്റെ കാരക്കയിൽ നിന്നും ഒരു കാരക്ക എടുത്ത് തന്റെ വായിലിട്ടു. അപ്പോൾ പ്രവാചകർ(സ) പറഞ്ഞു: "തുപ്പൂ!, തുപ്പൂ! അത് ഇട്ടേക്കുക, നാം സദഖഃ ഭക്ഷിക്കാറില്ലെന്ന് നിനക്ക് അറിയില്ലേ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ بْنِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اجْتَمَعَ رَبِيعَةُ بْنُ الْحَارِثِ وَالْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ فَقَالَا: وَاللَّهِ، لَوْ بَعَثْنَا هَذَيْنِ الْغُلَامَيْنِ – قَالَ: لِي وَلِلْفَضْلِ بْنِ عَبَّاسٍ – إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَلَّمَاهُ، فَأَمَّرَهُمَا عَلَى هَذِهِ الصَّدَقَاتِ، فَأَدَّيَا مَا يُؤَدِّي النَّاسُ وَأَصَابَا مِمَّا يُصِيبُ النَّاسُ. قَالَ: فَبَيْنَمَا هُمَا فِي ذَلِكَ جَاءَ عَلِيُّ بْنُ أَبِي طَالِبٍ فَوَقَفَ عَلَيْهِمَا، فَذَكَرَا لَهُ ذَلِكَ، فَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ: لَا تَفْعَلَا، فَوَاللَّهِ مَا هُوَ بِفَاعِلٍ فَانْتَحَاهُ رَبِيعَةُ بْنُ الْحَارِثِ، فَقَالَ: وَاللَّهِ مَا تَصْنَعُ هَذَا إِلَّا نَفَاسَةً مِنْكَ عَلَيْنَا، فَوَاللَّهِ لَقَدْ نِلْتَ صِهْرَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَا نَفِسْنَاهُ عَلَيْكَ. قَالَ عَلِيٌّ: أَرْسِلُوهُمَا. فَانْطَلَقَا، وَاضْطَجَعَ عَلِيٌّ، قَالَ: فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ سَبَقْنَاهُ إِلَى الْحُجْرَةِ، فَقُمْنَا عِنْدَهَا حَتَّى جَاءَ، فَأَخَذَ بِآذَانِنَا، ثُمَّ قَالَ: "أَخْرِجَا مَا تُصَرِّرَانِ". ثُمَّ دَخَلَ وَدَخَلْنَا عَلَيْهِ، وَهُوَ يَوْمَئِذٍ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، قَالَ: فَتَوَاكَلْنَا الْكَلَامَ، ثُمَّ تَكَلَّمَ أَحَدُنَا فَقَالَ: يَا رَسُولَ اللَّهِ، أَنْتَ أَبَرُّ النَّاسِ وَأَوْصَلُ النَّاسِ، وَقَدْ بَلَغْنَا النِّكَاحَ، فَجِئْنَا لِتُؤَمِّرَنَا عَلَى بَعْضِ هَذِهِ الصَّدَقَاتِ، فَنُؤَدِّيَ إِلَيْكَ كَمَا يُؤَدِّي النَّاسُ، وَنُصِيبَ كَمَا يُصِيبُونَ، قَالَ: فَسَكَتَ طَوِيلًا حَتَّى أَرَدْنَا أَنْ نُكَلِّمَهُ، قَالَ: وَجَعَلَتْ زَيْنَبُ تُلْمِعُ عَلَيْنَا مِنْ وَرَاءِ الْحِجَابِ: أَنْ لَا تُكَلِّمَاهُ، قَالَ: ثُمَّ قَالَ: "إِنَّ الصَّدَقَةَ لَا تَنْبَغِي لِآلِ مُحَمَّدٍ، إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ، ادْعُوَا لِي مَحْمِيَةَ – وَكَانَ عَلَى الْخُمُسِ – وَنَوْفَلَ بْنَ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ". قَالَ: فَجَاءَاهُ، فَقَالَ لِمَحْمِيَةَ: "أَنْكِحْ هَذَا الْغُلَامَ ابْنَتَكَ" – لِلْفَضْلِ بْنِ عَبَّاسٍ – فَأَنْكَحَهُ، وَقَالَ لِنَوْفَلِ بْنِ الْحَارِثِ: "أَنْكِحْ هَذَا الْغُلَامَ ابْنَتَكَ" – لِي – فَأَنْكَحَنِي، وَقَالَ لِمَحْمِيَةَ: "أَصْدِقْ عَنْهُمَا مِنَ الْخُمُسِ كَذَا وَكَذَا". (م)', 'അബ്ദുൽ മുത്വലിബുബ്നു റബീഅതബ്നിൽ ഹാരിസ്(റ): റബീഅത്തുബിൻ ഹാരിസ്(റ)വും അബ്ബാസുബിൻ അബ്ദിൽ മുത്വലിബ്(റ)വും ഒരിക്കൽ ഒത്തുചേർന്നു. അപ്പോൾ അവരിരുവരും പറഞ്ഞു: ഈ രണ്ടു ബാലൻമാരെ – എന്നെ(നിവേദകൻ)യും ഫള്ലുബ്നു അബ്ബാസ്(റ)വിനെയും – റസൂൽ(സ)യുടെ അടുത്തേക്ക് അയക്കുകയും തിരുമേനി(സ)യോട് അവർ സംസാരിച്ച് (അവിടന്ന് സമ്മതിക്കുകയാണെങ്കിൽ) ഇരുവരെയും സകാത്ത് പിരിവുകാരാക്കുകയും ജനങ്ങൾ നൽകുന്നപോലെ ഇവരും നൽകുകയും ജനങ്ങൾക്ക് ലഭിക്കുന്ന പോലെ ഇവർക്കും ലഭിക്കുകയാണെങ്കിൽ (അത് കൊള്ളാമായിരുന്നു). നിവേദകൻ തുടർന്ന് പറയുന്നു. ഇങ്ങനെ സംസാരിക്കുന്നതിനിടയിൽ അലി(റ) അവരിരുവർക്കുമിടയിലേക്ക് കടന്നുവന്ന് അവർക്കടുത്ത് നിന്നു. അവരിരുവരും സംഭവം അലി(റ)വിനെ അറിയിച്ചു. അപ്പോൾ അലി(റ) പറഞ്ഞു: ഇങ്ങനെ ചെയ്യരുത്. അല്ലാഹു സത്യം! അവിടുന്ന് ഒരിക്കലും ഇങ്ങനെ ചെയ്യുകയില്ല. അപ്പോൾ റബീഅത്(റ) അലി(റ)വിന് നേരെ തിരിഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹു സത്യം, താങ്കൾക്ക് ഞങ്ങളോടുള്ള അസൂയ കാരണത്താലാണ് താങ്കൾ ഇപ്രകാരം പറയുന്നത്. താങ്കൾക്ക് റസൂൽ(സ)യുടെ മരുമകനാണെന്നുള്ള സ്ഥാനമുണ്ട്. ഞങ്ങൾ താങ്കളേക്കാളും ഉന്നതരല്ല. അപ്പോൾ അലി(റ) പറഞ്ഞു: എന്നാൽ നിങ്ങൾ പോകുക. അലി(റ) അവിടെ കിടന്നു. നിവേദകൻ തുടർന്ന് പറയുന്നു. അങ്ങനെ റസൂൽ(സ) ളുഹർ നമസ്കരിച്ച ശേഷം തിരുമേനി(സ)യെ മുൻകടന്ന് ഞങ്ങൾ അവിടുത്തെ മുറിയിലേക്ക് നീങ്ങി. അങ്ങനെ ഞങ്ങൾ അതിന്നടുത്ത് നിന്നപ്പോൾ തിരുമേനി(സ) വന്നു. എന്നിട്ട് ഞങ്ങളുടെ ഇരുവരുടെയും ചെവിക്ക് പിടിച്ചു. ശേഷം പറഞ്ഞു: "നിങ്ങളുടെ മനസ്സിലുള്ളത് തുറന്ന് പറയുക". അങ്ങിനെ തിരുമേനി(സ) റൂമിൽ പ്രവേശിച്ചു. ഞങ്ങളും കൂടെ കടന്നു ചെന്നു. അവിടന്ന് അന്ന് സൈനബ് ബിൻതു ജഹ്ശ്(റ)യുടെ അടുത്തായിരുന്നു. നിവേദകൻ പറയുന്നു. അങ്ങനെ ഞങ്ങളിരുവരും ''നീ പറയൂ'' ''നീ പറയൂ'' എന്നിങ്ങനെ റസൂൽ(സ)യോട് പറയുന്ന കാര്യത്തിൽ പരസ്പരം ഏൽപിച്ചു. അങ്ങനെ ഞങ്ങളിലൊരാൾ ഇപ്രകരം പറഞ്ഞു: അല്ലാഹിവന്റെ ദൂതരേ, താങ്കൾ ആളുകളിൽ ഏറ്റവും പുണ്യവാനും അവരിൽ ഏറ്റവും കുടുംബബന്ധം പുലർത്തുന്നവനുമാണ്. ഞങ്ങൾക്ക് വിവാഹ പ്രായം എത്തിയിട്ടുണ്ട്. അതിനാൽ ഞങ്ങൾ വന്നത് ഞങ്ങളെ അങ്ങ് സകാത്തിന്റെ കാര്യത്തിൽ നേതൃത്വം ഏൽപിക്കുന്ന വിഷയം സംസാരിക്കാനാണ്. ശേഷം ഞങ്ങൾ ആളുകൾ നൽകുന്നത് പോലെ അങ്ങേക്ക് നൽകുകയും ആളുകൾക്ക് ലഭിക്കുന്നത് പോലെ ഞങ്ങൾക്ക് ലഭിക്കുകയും ചെയ്യും. നിവേദകൻ പറയുന്നു: അപ്പോൾ തിരുമേനി(സ) ദീർഘമായി മൗനമവലംബിച്ചു. ഞങ്ങൾ അവിടുത്തോട് സംസാരിച്ചെങ്കിലോ എന്ന് വിചാരിച്ചു പോയി. ഉടനെ സൈനബ്(റ) മറക്കു പിന്നിൽ നിന്നും ഞങ്ങൾ തിരുമേനി(സ)യോട് ''ഒന്നും മിണ്ടരുത്'' എന്ന് ആംഗ്യം കാണിച്ചു. അദ്ദേഹം പറയുന്നു: ശേഷം റസൂൽ(സ) പറഞ്ഞു: "സകാത്തിന്റ ധനം മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന് എടുക്കാൻ പാടില്ല. അത് ജനങ്ങളുടെ ഉച്ചിഷ്ടമാണ്. മഹ്മിയ – അദ്ദേഹത്തിന് അഞ്ചിൽ ഒന്ന് ഉണ്ടായിരുന്നു.– യെയും നൗഫൽ ബിൻ ഹാരിസിബ്നി അബ്ദിൽ മുത്വലിബിനെയും എന്റെ അടുത്തേക്ക് വിളിക്കുക." അങ്ങനെ അവവിരിരുവരും തിരുമേനി(സ)യുടെ അടുത്തേക്ക് വന്നു. അപ്പോൾ മഹ്മിയ(റ)വിനോട് തിരുമേനി(സ) പറഞ്ഞു: "നീ ഈ കുട്ടിക്ക് (ഫള്ലുബ്നു അബ്ബാസ്) നിന്റെ മകളെ വിവാഹം ചെയ്ത് കൊടുക്കുക" അപ്പോൾ അദ്ദേഹം വിവാഹം ചെയ്ത് കൊടുത്തു. പിന്നീട് തിരുമേനി(സ) നൗഫലുബ്നു ഹാരിസ്(റ)വിനോട് പറഞ്ഞു: "നീ ഇവന് –എനിക്ക് (അബ്ദുൽ മുത്വലിബ്)– നിന്റെ മകളെ വിവാഹം ചെയ്ത് കൊടുക്കുക." അങ്ങനെ എനിക്കദ്ദേഹം വിവാഹം കഴിപ്പിച്ചുതന്നു. അപ്പോൾ തിരുമേനി(സ) മഹ്മിയ(റ)വിനോട് പറഞ്ഞു: "അഞ്ചിൽ ഒന്ന് വിഹിതത്തിൽനിന്ന് ഇവരുടെ പേരിൽ ഇത്ര അളവ് സദഖ നൽകുക." (മു)', 'عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ بْنِ الْحَارِثِ', 'അബ്ദുൽ മുത്വലിബുബ്നു റബീഅതബ്നിൽ ഹാരിസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 232, 233, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمُرُّ بِالتَّمْرَةِ الْعَائِرَةِ، فَمَا يَمْنَعُهُ مِنْ أَخْذِهَا إِلَّا مَخَافَةَ أَنْ تَكُونَ صَدَقَةً. (د)', 'അനസ്(റ): റസൂൽ(സ) വീണുകിടക്കുന്ന ഒരു കാരക്കയുടെ അടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ അതെടുക്കുന്നതിൽ നിന്ന് തിരുമേനി(സ)യെ തടഞ്ഞത് അത് സകാത്തിന്റെ ധനമായോക്കാം എന്ന ഭയം മാത്രമായിരുന്നു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 233, 233, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَجَدَ تَمْرَةً، فَقَالَ: "لَوْلَا أَنِّي أَخَافُ أَنْ تَكُونَ صَدَقَةً لَأَكَلْتُهَا". (م,د)', 'അനസ്(റ) റസുൽ(സ) ഒരു കാരക്ക കണ്ടു. അവിടന്ന് പറഞ്ഞു: "ഇത് സകാത്തിന്റെ ധനമാണെന്ന് ഞാൻ ഭയപ്പെട്ടിട്ടില്ലായിരുന്നെങ്കിൽ ഞാനിത് ഭക്ഷിക്കുമായിരുന്നു." (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 233, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَنِي أَبِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلٍ، أَعْطَاهَا إِيَّاهُ مِنَ الصَّدَقَةِ. وَفِي رِوَايَةٍ: آتِي بِبَدَلِهَا. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): എന്റെ പിതാവ് എന്നെ, അദ്ദേഹം തന്നെ സകാത്തായി നൽകിയ, ഒരു ഒട്ടകം വാങ്ങാൻ നബി(സ)യുടെ അടുക്കലേക്ക് പറഞ്ഞയച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ, അതിനു പകരമായി മറ്റൊന്ന് കൊണ്ടുവരാൻ എന്നാണുള്ളത്. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=269), 1, 'وَفِي رِوَايَةٍ: آتِي بِبَدَلِهَا. (د,ن)', 'മറ്റൊരു നിവേദനിൽ, അതിനു പകരമായി മറ്റൊന്ന് കൊണ്ടുവരാൻ എന്നാണുള്ളത്. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُتِيَ بِشَيْءٍ سَأَلَ: "أَصَدَقَةٌ هِيَ أَمْ هَدِيَّةٌ؟". فَإِنْ قَالُوا: صَدَقَةٌ، لَمْ يَأْكُلْ، وَإِنْ قَالُوا: هَدِيَّةٌ، أَكَلَ. (ت,ن)', 'മുആവിയതുബ്നു ഹൈദ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ)ക്ക് വല്ലതും നൽകപ്പെട്ടാൽ തിരുമേനി(സ) "അതു സ്വദഖയാണോ ഹദ്‌യയാണോ?" എന്നു ചോദിക്കുമായിരുന്നു. അവർ സ്വദഖയാണെന്ന് പറഞ്ഞാൽ അവിടുന്ന് ഭക്ഷിക്കില്ല. അവർ ഹദ്‌യ (സമ്മാനം) ആണെന്ന് പറഞ്ഞാൽ റസൂൽ(സ) ഭക്ഷിക്കും. (തു,ന)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا مِنْ بَنِي مَخْزُومٍ عَلَى الصَّدَقَةِ، فَقَالَ لِأَبِي رَافِعٍ: اصْحَبْنِي كَيْمَا تُصِيبَ مِنْهَا. فَقَالَ: لَا، حَتَّى آتِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْأَلَهُ، فَانْطَلَقَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ، فَقَالَ: "إِنَّ الصَّدَقَةَ لَا تَحِلُّ لَنَا، وَإِنَّ مَوَالِيَ الْقَوْمِ مِنْ أَنْفُسِهِمْ". (د,ت,ن)', 'അബൂറാഫിഅ്(റ): ബനൂമഖ്സൂം ഗോത്രത്തിലെ ഒരാളെ തിരുമേനി(സ) സ്വദഖ പിരിച്ചെടുക്കാനായി നിയോഗിച്ചു. അയാൾ അബൂറാഫിഅ്(റ)നോട് (പ്രവാചകന്റെ വിമോചിത അടിമ) പറഞ്ഞു: താങ്കളും എന്നോടൊപ്പം വരൂ, താങ്കൾക്കും ഇതിൽ നിന്നെടുക്കാമല്ലോ. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ)യെ സമീപിച്ച് ഇതേക്കുറിച്ചു ചോദിക്കുന്നതുവരെ ഞാനൊന്നും എടുക്കുകയില്ല. അദ്ദേഹം പ്രവാചകർ(സ)യെ സമീപിച്ചു ചോദിച്ചപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "സ്വദഖഃ നമുക്ക് അനുവദനീയമാവുകയില്ല. ഒരു വിഭാഗത്തിന്റെ മോചിതരായ അടിമകൾ അവരിൽപെട്ടവർതന്നെയാണ്." (ദ,തു,ന)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ الْهَاشِمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عَبْدَ الْمُطَّلِبِ بْنَ رَبِيعَةَ بْنِ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ أَخْبَرَهُ: أَنَّ أَبَاهُ رَبِيعَةَ بْنَ الْحَارِثِ قَالَ لِعَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ بْنِ الْحَارِثِ وَالْفَضْلِ بْنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، ائْتِيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُولَا لَهُ: اسْتَعْمِلْنَا يَا رَسُولَ اللَّهِ عَلَى الصَّدَقَاتِ. فَأَتَى عَلِيُّ بْنُ أَبِي طَالِبٍ وَنَحْنُ عَلَى تِلْكَ الْحَالِ، فَقَالَ لَهُمَا: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَسْتَعْمِلُ مِنْكُمْ أَحَدًا عَلَى الصَّدَقَةِ. قَالَ عَبْدُ الْمُطَّلِبِ: فَانْطَلَقْتُ أَنَا وَالْفَضْلُ حَتَّى أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَنَا: "إِنَّ هَذِهِ الصَّدَقَةَ إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ، وَإِنَّهَا لَا تَحِلُّ لِمُحَمَّدٍ، وَلَا لِآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ". (ن)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി നൗഫലിൽ ഹാശിമീ(റ): അബ്ദുൽ മുത്വലിബുബ്നു റബീഅ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: തന്റെ പിതാവായ റബീഅത്തുബിൻ ഹാരിസ് അബ്ദുൽ മുത്വലിബ്ബിൻ റബീഅ(റ)വിനോടും ഫള്ലുബ്നു അബ്ബാസ്(റ)വിനോടും പറഞ്ഞു: നിങ്ങൾ രണ്ടു പേരും റസുൽ(സ)യുടെ അടുക്കലേക്ക് ചെന്ന് ഇപ്രകാരം പറയുക: അല്ലാഹുവിന്റെ റസൂലേ ഞങ്ങളെ സകാത്ത് പിരിക്കുന്ന ജോലിക്ക് നിയമിച്ചാലും! ആ സന്ദർഭത്തിൽ അലി(റ) അവിടേക്ക് കടന്നു വന്നു. അപ്പോൾ അദ്ദേഹം അവരിരുവരോടുമായി പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളിൽ ഒരാളെയും സകാത്ത് പിരിക്കുന്ന ജോലിക്ക് ഏൽപിക്കില്ല. അബ്ദുൽ മുത്വലിബ്(റ) തുടർന്നു പറയുന്നു: അങ്ങനെ ഞാനും ഫള്ൽ(റ)വും പ്രവാചകർ(സ)യുടെ അടുത്തേക്ക് പോയി. അവിടന്ന് പറഞ്ഞു: "ഈ സകാത്തിന്റെ ധനം ആളുകളുടെ ഉച്ചിഷ്ടമാണ്. അത് മുഹമ്മദ്(സ)ക്കും കുടുംബത്തിനും അനുവദനീയമല്ല." (ന)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ الْهَاشِمِيِّ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി നൗഫലിൽ ഹാശിമീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ". وَفِي رِوَايَةٍ: "مِنْ أَنْفُسِهِمْ". (ن)', 'അനസ്ബിൻ മാലിക്(റ) റസൂൽ(സ) പറഞ്ഞു: "ഒരു സമൂഹത്തിലെ സഹോദരിയുടെ മകൻ ആ സമൂഹത്തിൽ പെട്ടവനാണ്." മറ്റൊരു നിവേദനം: "അവരുടെ കൂട്ടത്തിൽ പെട്ടവനാണ്." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബിൻ മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=273), 1, 'وَفِي رِوَايَةٍ: "مِنْ أَنْفُسِهِمْ". (ن)', 'മറ്റൊരു നിവേദനം: "അവരുടെ കൂട്ടത്തിൽ പെട്ടവനാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَهْدَتْ بَرِيرَةُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَحْمًا تُصُدِّقَ بِهِ عَلَيْهَا، فَقَالَ: "هُوَ لَهَا صَدَقَةٌ، وَلَنَا هَدِيَّةٌ". (ق)', 'അനസ്(റ)ൽനിന്നു നിവേദനം: സകാതായി നൽകപ്പെട്ട അൽപം മാംസം ബരീറ(റ) റസൂൽ(സ)ക്ക് സമ്മാനമായി നൽകി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അവൾക്കിതു സ്വദഖയും നമുക്ക് ഹദ്‌യയുമാണ്." (ബു,മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: بَعَثَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ مِنَ الصَّدَقَةِ، فَبَعَثْتُ إِلَى عَائِشَةَ مِنْهَا بِشَيْءٍ، فَلَمَّا جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَائِشَةَ قَالَ: "هَلْ عِنْدَكُمْ شَيْءٌ؟". قَالَتْ: لَا، إِلَّا أَنَّ نُسَيْبَةَ بَعَثَتْ إِلَيْنَا مِنَ الشَّاةِ الَّتِي بَعَثْتُمْ بِهَا إِلَيْهَا. قَالَ: "إِنَّهَا قَدْ بَلَغَتْ مَحِلَّهَا". (م)', 'ഉമ്മു അത്വിയ്യ(റ): റസൂൽ(സ) എന്റെ അടുത്തേക്ക് സകാത്തിന്റെ സ്വത്തിൽ പെട്ട ഒരു ആടിനെ കൊടുത്തയച്ചു. അങ്ങനെ ഞാൻ അതിൽ നിന്നൽപം ആഇശ(റ)ക്ക് കൊടുത്തയച്ചു. അങ്ങനെ റസൂൽ(സ) ആയിശ(റ)യുടെ അടുക്കൽ വന്നപ്പോൾ അവിടന്ന് ചോദിച്ചു: "നിങ്ങളുടെയടുത്ത് വല്ലതും ഇരുപ്പുണ്ടോ?" അപ്പോൾ ആഇശ(റ) പറഞ്ഞു; ഇല്ല. താങ്കൾ നുസൈബത്ത്(റ)ക്ക് കൊടുത്തയച്ച മാംസത്തിൽ നിന്നൽപ്പം ഇവിടെയുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "അത് അതിന്റെ സ്ഥാനത്ത് തന്നെ എത്തിയിരിക്കുന്നു." (മു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മു അത്വിയ്യ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أُتِيَ بِطَعَامٍ سَأَلَ عَنْهُ، فَإِنْ قِيلَ: هَدِيَّةٌ، أَكَلَ مِنْهَا، وَإِنْ قِيلَ: صَدَقَةٌ، لَمْ يَأْكُلْ مِنْهَا. (م)', 'അബുഹുറൈറ(റ) പ്രവാചകൻ(സ)യുടെ അടുക്കലേക്ക് വല്ല ആഹാരവും കൊണ്ടുവരപ്പെട്ടാൽ അവിടന്ന് അതിനെക്കുറിച്ച് ചോദിക്കുമായിരുന്നു. അത് ദാനമാണെന്ന് പറയപ്പെട്ടാൽ അവിടന്ന് ഭക്ഷിക്കും. സകാത്തിന്റെ വകയാണെന്ന് പറയപ്പെട്ടാൽ അതിൽനിന്ന് അവിടന്ന് തിന്നുകയില്ല. (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَرَادَتْ أَنْ تَشْتَرِيَ بَرِيرَةَ فَتُعْتِقَهَا، وَإِنَّهُمُ اشْتَرَطُوا وَلَاءَهَا، فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "اشْتَرِيهَا وَأَعْتِقِيهَا، فَإِنَّ الْوَلَاءَ لِمَنْ أَعْتَقَ". وَخُيِّرَتْ حِينَ أُعْتِقَتْ، وَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَحْمٍ، فَقِيلَ: هَذَا مِمَّا تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، فَقَالَ: "هُوَ لَهَا صَدَقَةٌ، وَلَنَا هَدِيَّةٌ". وَكَانَ زَوْجُهَا حُرًّا. (ن)', 'ആഇശ(റ): ആഇശ(റ) ബരീറ(റ)യെ വിലക്ക് വാങ്ങി മോചിപ്പിക്കാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ ബരീറ(റ)യുടെ സ്വത്തിന്റെ അനന്തരാവകാശം അവർക്ക് വേണമെന്ന് അവർ നിബന്ധന ¹ പറഞ്ഞു. അക്കാര്യം പ്രവാചകർ(സ)യോട് മഹതി അറിയിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ ബരീറയെ വിലക്ക് വാങ്ങി മോചിപ്പിച്ചു കൊള്ളുക. നിശ്ചയം മോചിപ്പിച്ച ആൾക്കാണ് അടിമയുടെ സ്വത്തിന്റെ അവകാശം." ബരീറ(റ) മോചിതയായപ്പോൾ ഭർത്താവിനെ തിരഞ്ഞെടുക്കുവാനുള്ള സ്വാതന്ത്ര്യം നൽകപ്പെട്ടു. അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് മാംസം കൊണ്ടു വരപ്പെട്ടു. എന്നിട്ട് തിരുമേനി(സ)യോട് പറയപ്പെട്ടു: ഇത് ബരീറ(റ)ക്ക് സകാതായി ലഭിച്ച സ്വത്തിൽ നിന്നുള്ളതാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അത് ബരീറക്ക് സ്വദഖയും, നമുക്ക് ഹദ്‌യയുമാണ്." ബരീറ(റ)യുടെ ഭർത്താവ് സ്വതന്ത്രനായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', '¹ യഥാർത്ഥത്തിൽ അടിമയുടെ സ്വത്തിന്റെ അവകാശം മോചിപ്പിച്ച വ്യക്തിക്കായിരിക്കും. പക്ഷെ, ബരീറയുടെ വിഷയത്തിൽ അത് മുമ്പുള്ള യജമാനന് നൽകണമെന്ന് ശർത് വെക്കപ്പെട്ടു.', null, array['ن']::text[], array['ന']::text[], null, null, 235, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَصْلُحُ قِبْلَتَانِ فِي أَرْضٍ وَاحِدَةٍ، وَلَيْسَ عَلَى الْمُسْلِمِينَ جِزْيَةٌ". (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ഥലത്തു രണ്ടു ഖിബ്‌ല ശരിയാവുകയില്ല. മുസ്‌ലിംകൾക്കു ജിസ്‌യയും ഉണ്ടാവുകയില്ല." (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْخَازِنَ الْمُسْلِمَ الْأَمِينَ، الَّذِي يُنْفِذُ – وَرُبَّمَا – قَالَ: يُعْطِي مَا أُمِرَ بِهِ، فَيُعْطِيهِ كَامِلًا مُوَفَّرًا طَيِّبَةً بِهِ نَفْسُهُ، فَيَدْفَعُهُ إِلَى الَّذِي أُمِرَ لَهُ بِهِ، أَحَدُ الْمُتَصَدِّقِينَ". (ق,د,ن)', 'അബൂമുസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിമും വിശ്വസ്തനുമായ സകാത്തിന്റെ സൂക്ഷിപ്പുകാരൻ, അതായത് തന്നോട് കൽപ്പിക്കപ്പെട്ടത് പ്രകാരം കാര്യങ്ങൾ നടപ്പിലാക്കുന്നവൻ –നൽകുന്നവൻ എന്നും ചില സന്ദർഭങ്ങളിൽ പറഞ്ഞിട്ടുണ്ട്– സൻമനസ്സോടു കൂടി അർഹമായത് പൂർണ്ണമായും കുറവ് വരുത്താതെയും സംതൃപ്തിയോടെയും നൽകുന്നവൻ, അത് ആർക്ക് നൽകാനാണോ കൽപ്പിക്കപ്പെട്ടത് അവർക്ക് തന്നെ നൽകുന്നവൻ, സകാത്ത് നൽകുന്ന രണ്ട് പേരിൽ ഒരുവനാണ്." (ബു,മു,ദ,ന)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമുസൽ അശ്അരി(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا، وَقَالَ: الْخَازِنُ الْأَمِينُ الَّذِي يُعْطِي مَا أُمِرَ بِهِ – طَيِّبًا بِهَا نَفْسُهُ – أَحَدُ الْمُتَصَدِّقِينَ". (ن)', 'അബുമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യവിശ്വാസികൾ പരസ്പരം ഒരു കെട്ടിടത്തെപ്പോലെയാണ്. അവ (കെട്ടിടത്തിന്റെ കല്ലുകൾ) പരസ്പരം താങ്ങായി വർത്തിക്കുന്നു." തിരുമേനി(സ) പറഞ്ഞു: "സൻമനസ്സോടെ തന്നോട് കൽപ്പിക്കപ്പെട്ടതു പ്രകാരം നൽകുന്ന വിശ്വസ്തനായ സകാത്തിന്റെ സൂക്ഷിപ്പുകാരൻ സകാത്ത് നൽകുന്ന രണ്ട് പേരിൽ ഒരുവനാണ്." (ന)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَيُّ الصَّدَقَةِ أَعْجَبُ إِلَيْكَ؟ قَالَ: "الْمَاءُ". وفي روايةٍ: أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أُمَّ سَعْدٍ مَاتَتْ، فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "الْمَاءُ". قَالَ: فَحَفَرَ بِئْرًا، وَقَالَ: هَذِهِ لِأُمِّ سَعْدٍ. (د,ن,جه)', 'സഅ്ദ് ബിൻഉബാദ(റ): അദ്ദേഹം പ്രവാചകർ(സ)യുടെ അടുത്ത് ചെന്ന് ചോദിച്ചു: താങ്കൾക്ക് ഏറ്റവും പ്രിയങ്കരമായ ദാനം ഏതാണ്? തിരുമേനി(സ) പ്രതിവചിച്ചു: "വെള്ളം" മറ്റൊരു റിപ്പോർട്ടിൽ: പ്രവാചകർ(സ)യോട് അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഉമ്മു സഅ്ദ് മരണപ്പെട്ടു. അപ്പോൾ ഏത് ധർമ്മമാണ് ഏറ്റവും ഉത്തമമായത്? തിരുമേനി(സ) പറഞ്ഞു: "വെള്ളം" അദ്ദേഹം പറയുന്നു: ശേഷം അദ്ദേഹം ഒരു കിണർ കുഴിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഇത് ഉമ്മു സഅദിനു വേണ്ടിയാണ്. (ദ,ന,ജ)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദ് ബിൻഉബാദ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=281), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أُمَّ سَعْدٍ مَاتَتْ، فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "الْمَاءُ". قَالَ: فَحَفَرَ بِئْرًا، وَقَالَ: هَذِهِ لِأُمِّ سَعْدٍ. (د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: പ്രവാചകർ(സ)യോട് അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഉമ്മു സഅ്ദ് മരണപ്പെട്ടു. അപ്പോൾ ഏത് ധർമ്മമാണ് ഏറ്റവും ഉത്തമമായത്? തിരുമേനി(സ) പറഞ്ഞു: "വെള്ളം" അദ്ദേഹം പറയുന്നു: ശേഷം അദ്ദേഹം ഒരു കിണർ കുഴിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഇത് ഉമ്മു സഅദിനു വേണ്ടിയാണ്. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا مُسْلِمٍ كَسَا مُسْلِمًا ثَوْبًا عَلَى عُرْيٍ كَسَاهُ اللَّهُ مِنْ خُضْرِ الْجَنَّةِ، وَأَيُّمَا مُسْلِمٍ أَطْعَمَ مُسْلِمًا عَلَى جُوعٍ أَطْعَمَهُ اللَّهُ مِنْ ثِمَارِ الْجَنَّةِ، وَأَيُّمَا مُسْلِمٍ سَقَى مُسْلِمًا عَلَى ظَمَإٍ سَقَاهُ اللَّهُ مِنَ الرَّحِيقِ الْمَخْتُومِ". (د)', 'അബു സഈദിൽ ഖുദ്‌രി(റ) റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്‌ലിം മറ്റൊരു മുസ്‌ലിം നഗ്നനായിരിക്കെ (വസ്ത്രത്തിലേക്ക് ആവശ്യമുള്ളവനായിരിക്കെ) അവനെ വസ്ത്രം ധരിപ്പിച്ചാൽ അല്ലാഹു പച്ചനിറമുള്ള സ്വർഗ്ഗീയ വസ്ത്രം അവനെ അണിയിക്കും. ഒരു മുസ്‌ലിം മറ്റൊരു മുസ്‌ലിമിനെ വിശപ്പുള്ളപ്പോൾ ഭക്ഷിപ്പിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗത്തിലെ കായ്ക്കനികളിൽനിന്ന് ഭക്ഷണം നൽകും. ഒരു മുസ്‌ലിം മറ്റൊരു മുസ്‌ലിമിന് ദാഹമുള്ളപ്പോൾ വെള്ളം നൽകിയാൽ അല്ലാഹു അവനെ സ്വർഗ്ഗത്തിലെ മുദ്രവെക്കപ്പെട്ട പാനീയത്തിൽ നിന്നും കുടിപ്പിക്കും." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബു സഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنْفَقَتِ الْمَرْأَةُ مِنْ بَيْتِ زَوْجِهَا، غَيْرَ مُفْسِدَةٍ، كَانَ لَهَا أَجْرُ مَا أَنْفَقَتْ، وَلِزَوْجِهَا أَجْرُ مَا اكْتَسَبَ، وَلِخَازِنِهِ مِثْلُ ذَلِكَ، لَا يَنْقُصُ بَعْضُهُمْ أَجْرَ بَعْضٍ". (ق,د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ഭാര്യ തന്റെ ഭർത്താവിന്റെ വീട്ടിൽ കുഴപ്പം സൃഷ്ടിക്കാത്ത വിധം ചെലവ് നടത്തിയാൽ അവൾക്ക് അവൾ ചെലവഴിച്ചതിന്റെ പ്രതിഫലമുണ്ട്. അവളുടെ ഭർത്താവിന്ന് അയാൾ സമ്പാദിച്ചതിന്റെ പ്രതിഫലമുണ്ട്. അതിന്റെ സൂക്ഷിപ്പുകാരന്നും തത്തുല്യമായ പ്രതിഫലമുണ്ട്. ഒരാളുടെയും പ്രതിഫലം മറ്റൊരാളുടെ പ്രതിഫലം കാരണത്താൽ കുറയുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا بَايَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النِّسَاءَ قَامَتِ امْرَأَةٌ جَلِيلَةٌ، كَأَنَّهَا مِنْ نِسَاءِ مُضَرَ، فَقَالَتْ: يَا نَبِيَّ اللَّهِ، إِنَّا كَلٌّ عَلَى آبَائِنَا وَأَبْنَائِنَا، فَمَا يَحِلُّ لَنَا مِنْ أَمْوَالِهِمْ؟ فَقَالَ: "الرَّطْبُ تَأْكُلْنَهُ وَتُهْدِينَهُ". قَالَ أَبُو دَاود: الرَّطْبُ: الْخُبْزُ وَالْبَقْلُ وَالرُّطَبُ. (د)', 'സഅ്ദ്(റ): റസൂൽ(സ)യോടു സ്ത്രീകൾ ബൈഅത്ത് ചെയ്തപ്പോൾ മുളർ ഗോത്രക്കാരിയാണെന്ന് തോന്നിക്കും വിധം ആകാര ഗാംഭീര്യമുള്ള ഒരു സ്ത്രീ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ! ഞങ്ങൾ ഞങ്ങളുടെ മാതാപിതാക്കൾക്കും മക്കൾക്കും ഒരു ഭാരമായി തീർന്നിരിക്കുന്നു. അതിനാൽ അവരുടെ സ്വത്തിൽനിന്നും ഞങ്ങൾക്ക് അനുവദനീയമായവ എന്തെല്ലാമാണ്. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിക്കുകയോ ദാനം ചെയ്യുകയോ ചെയ്യുന്ന റത്ബ്." അബൂദാവൂദ്(റ) പറയുന്നു: റത്ബ് എന്നത് കൊണ്ട് ഉദ്ദേശിച്ചത് റൊട്ടിയും ചീരയും പഴുത്ത കാരക്കയുമാണ്. (ദ)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 237, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنْفَقَتِ الْمَرْأَةُ مِنْ كَسْبِ زَوْجِهَا مِنْ غَيْرِ أَمْرِهِ، فَلَهَا نِصْفُ أَجْرِهِ". (ق,د)', 'അബൂഹുറൈറ(റ): "ഭർത്താവിന്റെ കൽപ്പന പ്രകാരമല്ലാതെ ഭാര്യ തന്റെ ഭർത്താവിന്റെ ധനം കൊണ്ട് ചെലവ് നടത്തിയാൽ അവൾക്ക് പകുതി പ്രതിഫലമുണ്ട്." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خُطْبَتِهِ عَامَ حَجَّةِ الْوَدَاعِ يَقُولُ: "لَا تُنْفِقُ امْرَأَةٌ شَيْئًا مِنْ بَيْتِ زَوْجِهَا إِلَّا بِإِذْنِ زَوْجِهَا". قِيلَ: يَا رَسُولَ اللَّهِ، وَلَا الطَّعَامَ؟ قَالَ: "ذَاكَ أَفْضَلُ أَمْوَالِنَا". (د,ت,جه)', 'അബൂഉമാമത്തുൽ ബാഹിലീ(റ): റസൂൽ(സ) തന്റെ ''ഹജ്ജത്തുൽ വദാഇ''ലെ പ്രസംഗത്തിലൂടെ പറയുന്നതായി ഞാൻ കേട്ടു. "തന്റെ ഭർത്താവിന്റെ അനുമതികൂടാതെ ഒരു ഭാര്യ ഭർതൃഗൃഹത്തിൽനിന്ന് ഒന്നും തന്നെ ചെലവ് ചെയ്യാൻ പാടില്ല." അപ്പോൾ തിരുമേനി(സ)യോട് പറയപ്പെട്ടു: ഭക്ഷണവും നൽകിക്കൂടെ? തിരുമേനി(സ) പറഞ്ഞു: "അതാകുന്നു നമ്മുടെ സമ്പത്തുകളിൽ വെച്ചേറ്റവും ശ്രേഷ്ടമായത്." (ദ,തു,ജ)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമത്തുൽ ബാഹിലീ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَعْطَتِ الْمَرْأَةُ مِنْ بَيْتِ زَوْجِهَا بِطِيبِ نَفْسٍ - غَيْرَ مُفْسِدَةٍ - كَانَ لَهَا مِثْلُ أَجْرِهِ، لَهَا مَا نَوَتْ حَسَنًا، وَلِلْخَازِنِ مِثْلُ ذَلِكَ". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ തന്റെ ഭർതൃഗൃഹത്തിൽ സന്മനസ്സോടെ -കുഴപ്പങ്ങൾ സൃഷ്ടിക്കാത്ത വിധം- ചെലവ് ചെയ്യുകയാണെങ്കിൽ അവൾക്ക് അവനെപ്പോലെ പ്രതിഫലമുണ്ട്. അവൾക്ക് അവളുദ്ദേശിച്ച നൻമയുണ്ട്. സൂക്ഷിപ്പുകാരനും തത്തുല്യമായതുണ്ട്." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، فِي الْمَرْأَةِ تَصَدَّقُ مِنْ بَيْتِ زَوْجِهَا؟ قَالَ: "لَا، إِلَّا مِنْ قُوتِهَا، وَالْأَجْرُ بَيْنَهُمَا، وَلَا يَحِلُّ لَهَا أَنْ تَصَدَّقَ مِنْ مَالِ زَوْجِهَا إِلَّا بِإِذْنِهِ". (د)', 'അബു ഹുറൈറയ്റ(റ): ഒരു സ്ത്രീ തന്റെ ഭർത്താവിന്റെ അനുവാദം കൂടാതെ ഭർതൃഗൃഹത്തിൽനിന്നും ദാനം ചെയ്താലുള്ള വിധി എന്താണ്? (എന്ന് തിരുമേനിയോട് ചോദിച്ചു). അവിടന്ന് പറഞ്ഞു: "പാടില്ല, അവൾക്ക് ലഭിച്ച ഭക്ഷണത്തിൽ നിന്നൊഴികെ. അതിന്റെ പ്രതിഫലം അവർക്കിരുവർക്കും കൂടിയുള്ളതാണ്. അവൾക്ക് ഭർത്താവിന്റെ അനുവാദമില്ലാതെ അദ്ദേഹത്തിന്റെ സ്വത്തിൽനിന്നും ദാനം നൽകാൻ പാടില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബു ഹുറൈറയ്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا فَتَحَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قَامَ خَطِيبًا، فَقَالَ فِي خُطْبَتِهِ: "لَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا". (ن)', 'അബ്ദുല്ലാഹിബിൻ അംറ്(റ): മക്കാവിജയഘട്ടത്തിൽ റസൂൽ(സ) എഴുന്നേറ്റ് നിന്ന് പ്രസംഗിച്ചപ്പോൾ ഇപ്രകാരം പറഞ്ഞു: "ഒരു ഭാര്യ തന്റെ ഭർത്താവിന്റെ സമ്മതമില്ലാതെ ദാനം ചെയ്യാൻ പാടില്ല." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബിൻ അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ عُمَيْرٍ رَضِيَ اللهُ عَنْهُ مَوْلَى ابِي اللَّحْمِ قَالَ: أَمَرَنِي مَوْلَايَ أَنْ أُقَدِّدَ لَحْمًا، فَجَاءَنِي مِسْكِينٌ، فَأَطْعَمْتُهُ مِنْهُ، فَعَلِمَ بِذَلِكَ مَوْلَايَ، فَضَرَبَنِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْتُ ذَلِكَ لَهُ، فَدَعَاهُ، فَقَالَ: "لِمَ ضَرَبْتَهُ؟". فَقَالَ: يُعْطِي طَعَامِي بِغَيْرِ أَنْ آمُرَهُ، فَقَالَ: "الْأَجْرُ بَيْنَكُمَا". (م,ن)', 'അബൂ ലഹ്മിന്റെ അടിമ, ഉമൈർ(റ): എന്നോട് എന്റെ യജമാനൻ മാംസം ചൂടാക്കാൻ കൽപ്പിച്ചു. അപ്പോൾ എന്റെ അടുത്ത് ഒരു മിസ്കീൻ വന്നു. ഞാൻ അവനെ ഭക്ഷിപ്പിച്ചു. അത് എന്റെ യജമാനൻ അറിഞ്ഞു. അദ്ദേഹം എന്നെ തല്ലി. അങ്ങനെ ഞാൻ പ്രവാചകർ(സ)യുടെ അടുക്കൽ ചെന്നു അതിനെക്കുറിച്ച് പറഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) എന്റെ യജമാനനെ വിളിച്ചു വരുത്തിയിട്ടു ചോദിച്ചു: "നീ എന്തിനാണ് അവനെ തല്ലിയത്?" അദ്ദേഹം പ്രതിവചിച്ചു: എന്റെ ഭക്ഷണം എന്റെ കൽപ്പന കൂടാതെ അവൻ ദാനം നൽകിയിരിക്കുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "അതിന്റെ പ്രതിഫലം നിങ്ങൾക്ക് രണ്ടുപേർക്കും കൂടിയാണ്." (മു,ന)', 'عُمَيْرٍ', 'അബൂ ലഹ്മിന്റെ അടിമ, ഉമൈർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَصُمِ الْمَرْأَةُ وَبَعْلُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ، وَلَا تَأْذَنْ فِي بَيْتِهِ وَهُوَ شَاهِدٌ إِلَّا بِإِذْنِهِ، وَمَا أَنْفَقَتْ مِنْ كَسْبِهِ مِنْ غَيْرِ أَمْرِهِ فَإِنَّ نِصْفَ أَجْرِهِ لَهُ". (م)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറയുകയുണ്ടായി: "ഭർത്താവ് വീട്ടിലുണ്ടായിരിക്കെ അദ്ദേഹത്തിന്റെ അനുമതി കൂടാതെ ഭാര്യ (സുന്നത്ത്) നോമ്പെടുക്കരുത്. അദ്ദേഹം സാക്ഷിയായിരിക്കെ അദ്ദേഹത്തിന്റെ വീട്ടിൽ പ്രവേശിക്കാൻ അദ്ദേഹത്തിന്റെ അനുവാദം കൂടാതെ അവൾ സമ്മതം നൽകരുത്. അദ്ദേഹത്തിന്റെ സമ്പാദ്യത്തിൽനിന്ന് അദ്ദേഹത്തിന്റെ കൽപ്പനയില്ലാതെ അവൾ ചെലവ് ചെയ്താൽ അതിന്റെ പകുതി പ്രതിഫലം അദ്ദേഹത്തിനാകുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ رَجُلٌ: لَأَتَصَدَّقَنَّ بِصَدَقَةٍ، فَخَرَجَ بِصَدَقَتِهِ فَوَضَعَهَا فِي يَدِ سَارِقٍ، فَأَصْبَحُوا يَتَحَدَّثُونَ: تُصُدِّقَ عَلَى سَارِقٍ، فَقَالَ: اللَّهُمَّ لَكَ الْحَمْدُ، لَأَتَصَدَّقَنَّ بِصَدَقَةٍ، فَخَرَجَ بِصَدَقَتِهِ فَوَضَعَهَا فِي يَدَيْ زَانِيَةٍ، فَأَصْبَحُوا يَتَحَدَّثُونَ: تُصُدِّقَ اللَّيْلَةَ عَلَى زَانِيَةٍ، فَقَالَ: اللَّهُمَّ لَكَ الْحَمْدُ عَلَى زَانِيَةٍ، لَأَتَصَدَّقَنَّ بِصَدَقَةٍ، فَخَرَجَ بِصَدَقَتِهِ فَوَضَعَهَا فِي يَدَيْ غَنِيٍّ، فَأَصْبَحُوا يَتَحَدَّثُونَ: تُصُدِّقَ عَلَى غَنِيٍّ، فَقَالَ: اللَّهُمَّ لَكَ الْحَمْدُ عَلَى سَارِقٍ، وَعَلَى زَانِيَةٍ، وَعَلَى غَنِيٍّ، فَأُتِيَ، فَقِيلَ لَهُ: أَمَّا صَدَقَتُكَ عَلَى سَارِقٍ، فَلَعَلَّهُ أَنْ يَسْتَعِفَّ عَنْ سَرِقَتِهِ، وَأَمَّا الزَّانِيَةُ فَلَعَلَّهَا أَنْ تَسْتَعِفَّ عَنْ زِنَاهَا، وَأَمَّا الْغَنِيُّ فَلَعَلَّهُ يَعْتَبِرُ فَيُنْفِقُ مِمَّا أَعْطَاهُ اللَّهُ". (ق,ن)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ പറഞ്ഞു: ഞാൻ ധർമ്മം നൽകുക തന്നെ ചെയ്യും. അങ്ങനെ അയാൾ ധർമ്മം കൊടുക്കാൻ തുടങ്ങി. ഒരു മോഷ്ടാവിന്റെ കയ്യിലാണ് അയാൾ അത് നൽകിയത്. ആളുകൾ പറയാൻ തുടങ്ങി: ഒരു മോഷ്ടാവിനാണ് ധർമ്മം നൽകപ്പെട്ടത്. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ നിനക്ക് സ്തുതി, ഞാൻ ധർമ്മം നൽകുക തന്നെചെയ്യും. അദ്ദേഹം വീണ്ടും ധർമ്മത്തിനുള്ളതുമായി പുറപ്പെട്ടു. അങ്ങനെ അദ്ദേഹം ഒരു വേശ്യയുടെ കരങ്ങളിലേക്കാണ് ആ ധർമ്മം വെച്ചു നീട്ടിയത്. ജനങ്ങൾ പറയാൻ തുടങ്ങി: ഒരു വേശ്യക്കാണല്ലോ രാത്രിയിൽ ധർമ്മം നൽകപ്പെട്ടത്? അദ്ദേഹം പറഞ്ഞു: ഒരു വേശ്യയുടെ കാര്യത്തിൽ അല്ലാഹുവേ നിനക്ക് സ്തുതി, ഞാൻ ധർമ്മം നൽകുകതന്നെ ചെയ്യും. അദ്ദേഹം മൂന്നാമതും ധർമ്മവുമായി പറപ്പെടുകയും അത് ഒരു ധനികന്റെ കയ്യിലേക്ക് നൽകുകയും ചെയ്തു. ആളുകൾ പറയാൻ തുടങ്ങി: ഒരു ധനികനാണ് ധർമ്മം നൽകപ്പെട്ടിട്ടുള്ളത്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ, മോഷ്ടാവിന്റെയും വേശ്യയുടെയും ധനികന്റെയും കാര്യത്തിൽ നിനക്ക് സ്തുതി. അപ്പോൾ അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് ഒരാൾ വന്ന് പറഞ്ഞു: താങ്കൾ മോഷ്ടാവിന് നൽകിയ ദാനം കാരണത്താൽ അവൻ മോഷണം നിർത്തി അധ്വാനിച്ച് ജീവിതം നയിച്ചേക്കാം. വേശ്യ അവളുടെ വ്യഭിചാരം വെടിഞ്ഞ് സംശുദ്ധ ജീവിതം നയിച്ചേക്കാം. ധനികൻ ഇതിൽ നിന്ന് പാഠം ഉൾക്കൊണ്ട് അല്ലാഹു അദ്ദേഹത്തിന് നൽകിയതിൽനിന്ന് ചെലവഴിച്ചേക്കാം." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 239, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ مَعْنِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَبِي وَجَدِّي، وَخَطَبَ عَلَيَّ فَأَنْكَحَنِي وَخَاصَمْتُ إِلَيْهِ، وَكَانَ أَبِي يَزِيدُ أَخْرَجَ دَنَانِيرَ يَتَصَدَّقُ بِهَا، فَوَضَعَهَا عِنْدَ رَجُلٍ فِي الْمَسْجِدِ، فَجِئْتُ فَأَخَذْتُهَا فَأَتَيْتُهُ بِهَا فَقَالَ: وَاللَّهِ مَا إِيَّاكَ أَرَدْتُ، فَخَاصَمْتُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَكَ مَا نَوَيْتَ يَا يَزِيدُ، وَلَكَ مَا أَخَذْتَ يَا مَعْنُ". (خ)', 'മഅ്നുബ്നു യസീദ്(റ): ഞാനും എന്റെ പിതാവും പിതാമഹനും റസൂൽ(സ)യെ ബൈഅത്ത് ചെയ്തു. എനിക്ക് വേണ്ടി അവിടന്ന് വിവാഹം അന്വേഷിച്ചു. എനിക്ക് വിവാഹം ചെയ്തു തരികയും ചെയ്തു. ഞാൻ റസൂൽ(സ)യോട് ഒരു വിഷയത്തിൽ ന്യായാന്യായം തേടി. അതായത് എന്റെ പിതാവായ യസീദ്(റ) ദാനം ചെയ്യാൻ ഏതാനും ദീനാറുകൾ പുറത്തെടുക്കുകയും പള്ളിയിൽ ഒരാളുടെ അരികിൽ വെക്കുകയും ചെയ്തു. ഞാൻ ചെന്ന് അത് എടുക്കുകയും അതുമായി പിതാവിന്റെ അടുക്കൽ ചെല്ലുകയും ചെയ്തു. പിതാവ് പറഞ്ഞു: അല്ലാഹു സത്യം ഞാൻ നിന്നെയല്ല ഉദ്ദേശിച്ചത്. അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് അതിലെ ന്യായാന്യായം തേടി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "യസീദേ, നിനക്ക് നീ ഉദ്ദേശിച്ചതുണ്ട്. മഅ്നേ, നിനക്ക് നീ എടുത്തതുമുണ്ട്." (ബു)', 'مَعْنِ بْنِ يَزِيدَ', 'മഅ്നുബ്നു യസീദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 240, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "يَا نِسَاءَ الْمُسْلِمَاتِ، لَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا، وَلَوْ فِرْسِنَ شَاةٍ". (م)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറയുമായിരുന്നു: "മുസ്‌ലിം സ്ത്രീകളെ! ഒരു അയൽവാസിയായ സ്ത്രീയും തന്റെ അയൽവാസിയായ സ്ത്രീക്ക് നൽകുന്ന ദാനത്തെ നിസ്സാരമായി ഗണിക്കരുത്. മാംസം കുറഞ്ഞ എല്ലുന്തിയ ഒരു ആടാണെങ്കിൽ പോലും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 240, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ: "إِيمَانٌ لَا شَكَّ فِيهِ، وَجِهَادٌ لَا غُلُولَ فِيهِ، وَحَجَّةٌ مَبْرُورَةٌ". قِيلَ: فَأَيُّ الصَّلَاةِ أَفْضَلُ؟ قَالَ: "طُولُ الْقُنُوتِ". قِيلَ: فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "جُهْدُ الْمُقِلِّ". قِيلَ: فَأَيُّ الْهِجْرَةِ أَفْضَلُ؟ قَالَ: "مَنْ هَجَرَ مَا حَرَّمَ اللَّهُ عَزَّ وَجَلَّ". قِيلَ: فَأَيُّ الْجِهَادِ أَفْضَلُ؟ قَالَ: "مَنْ جَاهَدَ الْمُشْرِكِينَ بِمَالِهِ وَنَفْسِهِ". قِيلَ: فَأَيُّ الْقَتْلِ أَشْرَفُ؟ قَالَ: "مَنْ أُهَرِيقَ دَمُهُ وَعُقِرَ جَوَادُهُ". (ن)', 'അബ്ദുല്ലാഹിബിൻ ഹുബ്ശീ അൽഖഥ്അമീ(റ): റസൂൽ(സ) ചോദിക്കപ്പെട്ടു: ഏത് പ്രവർത്തനമാണ് ഏറ്റവും ശ്രേഷ്ഠം? പ്രവാചകർ(സ) പ്രതിവചിച്ചു: "സംശയലേശമന്യേയുള്ള സത്യവിശ്വാസം, വിശ്വാസവഞ്ചന നടത്താതെ ചെയ്ത ധർമ്മസമരം, പുണ്യകരമായ ഹജ്ജ് എന്നിവയാണവ." പ്രവാചകർ(സ)യോട് ചോദിക്കപ്പെട്ടു: അപ്പോൾ ഏത് നമസ്കാരമാണ് ഏറ്റുവും ശ്രേഷ്ഠമായത്? തിരുമേനി(സ) പറഞ്ഞു: "ദീർഘമായ പ്രാർത്ഥന നടത്തിക്കൊണ്ടുള്ള നമസ്കാരം." അപ്പോൾ ഏറ്റവും വിശിഷ്ടമായ ദാനധർമ്മം ഏതാകുന്നു? എന്ന് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "സ്വന്തം അധ്വാനത്താലുള്ള തുച്ഛമായ വരുമാനം കൊണ്ടു കഷ്ടിച്ചു ജീവിക്കുന്നവന്റെ ദാനം." പ്രവാചകർ(സ)യോട് ചോദിക്കപ്പെട്ടു: ഏറ്റവും മഹത്തരമായ (ഹിജ്റ) പലായനം ഏതാണ്? തിരുമേനി(സ) പ്രതിവചിച്ചു: "അല്ലാഹു നിഷിദ്ധമാക്കിയത് വെടിഞ്ഞ് കൊണ്ട് പലായനം ചെയ്തവൻ." പ്രവാചകർ(സ)യോട് ചോദിക്കപ്പെട്ടു: ഏറ്റവും ഉൽകൃഷ്ടമായ ധർമ്മസമരമേതാണ്? അവിടന്ന് പറഞ്ഞു: "തന്റെ ധനം കൊണ്ടും ശരീരം കൊണ്ടും ബഹുദൈവാരാധകരോട് പടവെട്ടിയവൻ." പ്രവാചകർ(സ)യോട് ചോദിക്കപ്പെട്ടു: ഏറ്റവും മഹത്തായ രക്തസാക്ഷിത്വം ഏതാണ്? പ്രവാചകർ(സ) പറഞ്ഞു: "തന്റെ രക്തം ചിന്തപ്പെടുകയും പടക്കുതിര കൊല്ലപ്പെടുകയും ചെയ്തവന്റെ രക്തസാക്ഷിത്വം." (ന)', 'عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ', 'അബ്ദുല്ലാഹിബിൻ ഹുബ്ശീ അൽഖഥ്അമീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 240, 241, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَبَقَ دِرْهَمٌ مِائَةَ أَلْفِ دِرْهَمٍ". قَالُوا: يَا رَسُولَ اللَّهِ، وَكَيْفَ؟ قَالَ: "كَانَ رَجُلٌ لَهُ دِرْهَمَانِ: فَتَصَدَّقَ بِأَحَدِهِمَا، وَانْطَلَقَ رَجُلٌ إِلَى عُرْضِ مَالِهِ، فَأَخَذَ مِنْهُ مِائَةَ أَلْفِ دِرْهَمٍ فَتَصَدَّقَ بِهَا". وفي روايةٍ: "سَبَقَ دِرْهَمٌ مِائَةَ أَلْفٍ". قَالُوا: يَا رَسُولَ اللَّهِ وَكَيْفَ؟ قَالَ: "رَجُلٌ لَهُ دِرْهَمَانِ، فَأَخَذَ أَحَدَهُمَا فَتَصَدَّقَ بِهِ. وَرَجُلٌ لَهُ مَالٌ كَثِيرٌ، فَأَخَذَ مِنْ عُرْضِ مَالِهِ مِائَةَ أَلْفٍ، فَتَصَدَّقَ بِهَا". (ن)', 'അബൂഹുററൈ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ലക്ഷം ദിർഹമിനെ ഒരുദിർഹം കവച്ചു വെച്ചിരിക്കുന്നു." അനുചരർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! അതെങ്ങനെയാണ്? തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾക്ക് രണ്ട് ദിർഹമുണ്ടായിരുന്നു. അതിൽ ഒന്ന് അയാൾ ധർമ്മം ചെയ്തു. മറ്റൊരാൾ തന്റെ പണം ശേഖരിച്ചു വെച്ചിടത്തേക്ക് പോയി അതിൽനിന്നും ഒരു ലക്ഷം ദിർഹം എടുത്തു ദാനം ചെയ്തു." -മറ്റൊരു റിപ്പോർട്ടിൽ: "ഒരു ദിർഹം ഒരു ലക്ഷത്തെ കവച്ചു." എന്നാണ്- അപ്പോൾ സ്വഹാബികൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! അതെങ്ങനെയാണ്? തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾക്കു ആകെ രണ്ടു ദിർഹമുണ്ടായിരുന്നു. അദ്ദേഹം അതിൽ ഒരെണ്ണമെടുത്തു ദാനം ചെയ്തു. മറ്റൊരാൾക്ക് ധാരാളം ധനമുണ്ടായിരുന്നു. അയാൾ തന്റെ ധനശേഖരത്തിൽനിന്ന് ഒരു ലക്ഷം എടുത്ത് ദാനം നൽകി." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുററൈ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 241, 241, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=296), 1, 'وَفِي رِوَايَةٍ: "سَبَقَ دِرْهَمٌ مِائَةَ أَلْفٍ". قَالُوا: يَا رَسُولَ اللَّهِ وَكَيْفَ؟ قَالَ: "رَجُلٌ لَهُ دِرْهَمَانِ، فَأَخَذَ أَحَدَهُمَا فَتَصَدَّقَ بِهِ. وَرَجُلٌ لَهُ مَالٌ كَثِيرٌ، فَأَخَذَ مِنْ عُرْضِ مَالِهِ مِائَةَ أَلْفٍ، فَتَصَدَّقَ بِهَا". (ن)', 'മറ്റൊരു നിവേദനിൽ: "ഒരു ദിർഹം ഒരു ലക്ഷത്തെ കവച്ചു." എന്നാണ്- അപ്പോൾ സ്വഹാബികൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! അതെങ്ങനെയാണ്? തിരുമേനി(സ) പറഞ്ഞു: "ഒരാൾക്കു ആകെ രണ്ടു ദിർഹമുണ്ടായിരുന്നു. അദ്ദേഹം അതിൽ ഒരെണ്ണമെടുത്തു ദാനം ചെയ്തു. മറ്റൊരാൾക്ക് ധാരാളം ധനമുണ്ടായിരുന്നു. അയാൾ തന്റെ ധനശേഖരത്തിൽനിന്ന് ഒരു ലക്ഷം എടുത്ത് ദാനം നൽകി." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا بِالصَّدَقَةِ، فَمَا يَجِدُ أَحَدُنَا شَيْئًا يَتَصَدَّقُ بِهِ حَتَّى يَنْطَلِقَ إِلَى السُّوقِ، فَيَحْمِلَ عَلَى ظَهْرِهِ، فَيَجِيءَ بِالْمُدِّ فَيُعْطِيَهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنِّي لَأَعْرِفُ الْيَوْمَ رَجُلًا لَهُ مِائَةُ أَلْفٍ، مَا كَانَ لَهُ يَوْمَئِذٍ دِرْهَمٌ. (ن)', 'അബുമസ്ഊദ്(റ): റസൂൽ(സ) ഞങ്ങളോട് സദഖ നൽകാൻ നിർദ്ദേശിക്കാറുണ്ടായിരുന്നു. ഞങ്ങളിൽ ചിലർ ദാനം നൽകാൻ ഒന്നും കണ്ടെത്താതിരിക്കുകയും അങ്ങനെ അങ്ങാടിയിൽ പോയി മുതുകിൽ ചുമന്നു കൊണ്ടു വരികയും റസൂൽ(സ)യുടെ അടുക്കൽ ഒരു മുദ്ദ് ദാനം നൽകുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഇന്ന് ഒരു ലക്ഷം കയ്യിലിരിപ്പുള്ള ആൾക്ക് ആ ദിവസം ഒരു ദിർഹം പോലും ഇല്ലാത്ത അവസ്ഥയുണ്ടായത് എനിക്കറിയാം. (ന)', 'أَبِي مَسْعُودٍ', 'അബുമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 241, 241, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ بِالصَّدَقَةِ فَتَصَدَّقَ أَبُو عَقِيلٍ بِنِصْفِ صَاعٍ، وَجَاءَ إِنْسَانٌ بِشَيْءٍ أَكْثَرَ مِنْهُ، فَقَالَ الْمُنَافِقُونَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ لَغَنِيٌّ عَنْ صَدَقَةِ هَذَا، وَمَا فَعَلَ هَذَا الْآخَرُ إِلَّا رِيَاءً، فَنَزَلَتْ: {الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ} [التوبة: ٧٩] (م,ن)', 'അബുമസ്ഊദ്(റ): റസൂൽ(സ) ഞങ്ങളോട് സ്വദഖ നൽകാൻ നിർദ്ദേശിച്ചപ്പോൾ അബൂ അഖീൽ(റ) അരസ്വാഅ് ദാനം ചെയ്തു. മറ്റൊരു വ്യക്തി വന്ന് അതിനേക്കാൾ നൽകി. അപ്പോൾ കപടവിശ്വാസികൾ പറഞ്ഞു: അല്ലാഹു ഇത്തരം സദഖയിൽനിന്നും ഐശ്വര്യവാനാണ്. ഈ രണ്ടാമത്തെ വ്യക്തി ലോകമാന്യതക്ക് വേണ്ടി മാത്രമാണ് നൽകിയത്. ആ സന്ദർഭത്തിൽ ''സത്യവിശ്വാസികളിൽനിന്നും ദാനധർമങ്ങൾ ചെയ്യാൻ സ്വമേധയാ വരുന്ന ആളുകളെയും, സ്വന്തമായ അധ്വാനമല്ലാതെ മറ്റൊന്നും തന്നെ (ദാനമായി നൽകാൻ) കണ്ടെത്താത്ത ആളുകളെയും അധിക്ഷേപിക്കുന്നവരാണവർ'' (സുറത്തുത്തൗബ: 179) എന്ന വചനം അവതീർണ്ണമായി. (മു,ന)', 'أَبِي مَسْعُودٍ', 'അബുമസ്ഊദ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'التوبة: ٧٩', null, 242, 242, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنَ الْأَنْصَارِ سَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَعْطَاهُمْ، ثُمَّ سَأَلُوهُ فَأَعْطَاهُمْ، حَتَّى إِذَا نَفِدَ مَا عِنْدَهُ، قَالَ: "مَا يَكُنْ عِنْدِي مِنْ خَيْرٍ فَلَنْ أَدَّخِرَهُ عَنْكُمْ، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ، وَمَنْ يَصْبِرْ يُصَبِّرْهُ اللَّهُ، وَمَا أُعْطِيَ أَحَدٌ مِنْ عَطَاءٍ خَيْرٌ وَأَوْسَعُ مِنَ الصَّبْرِ". (ق)', 'അബുസഈദിൽ ഖുദ്‌രീ(റ): അൻസാരികളിൽപ്പെട്ട ചിലർ നബി(സ)യോട് യാചിച്ചപ്പോൾ അവിടന്ന് നൽകി. അവർ വീണ്ടും യാചിച്ചു. തിരുമേനി(സ) നൽകി. അങ്ങനെ നബി(സ)യുടെ പക്കലുള്ളത് തീർന്നപ്പോൾ അവിടന്ന് പറഞ്ഞു. "എന്റെ അടുക്കലുള്ളത് ഞാൻ നിങ്ങൾക്ക് നൽകാതെ സൂക്ഷിച്ചു വെക്കുകയില്ല തന്നെ. വല്ലവനും സ്വാഭിമാനാർത്ഥം യാചന വെടിഞ്ഞാൽ അല്ലാഹു അവന് അതിന് പ്രാപ്തി നൽകും. ആരെങ്കിലും പരാശ്രയം നേടാതെ ജീവിക്കാനാഗ്രഹിച്ചാൽ അല്ലാഹു അവനെ സ്വയം ധന്യനാക്കും. വല്ലവനും ക്ഷമിച്ചാൽ അല്ലാഹു അവന് ക്ഷമാശക്തി നൽകും. ക്ഷമയേക്കാൾ ഉൽകൃഷ്ടമായ ഒന്നും അല്ലാഹു ഒരാൾക്കും നൽകിയിട്ടില്ല." (ബു,മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രീ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 242, 242, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَدْ أَفْلَحَ مَنْ أَسْلَمَ وَرُزِقَ كَفَافًا، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംരിബിനിൽ ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ മുസ്‌ലിമാവുകയും ഉള്ളതു കൊണ്ട് മതിയാക്കാനുള്ള ഇച്ഛ നൽകപ്പെടുകയും, അല്ലാഹു തനിക്ക് നൽകിയതിൽ സംതൃപ്തി അടയുന്ന പ്രവണത അല്ലാഹു നൽകുകയും ചെയ്തവൻ തീർച്ചയായും വിജയിച്ചിരിക്കുന്നു." (മു)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംരിബിനിൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 242, 242, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْغَيْرَةِ مَا يُحِبُّ اللَّهُ عَزَّ وَجَلَّ، وَمِنْهَا مَا يَبْغُضُ اللَّهُ عَزَّ وَجَلَّ. وَمِنَ الْخُيَلَاءِ مَا يُحِبُّ اللَّهُ عَزَّ وَجَلَّ، وَمِنْهَا مَا يَبْغُضُ اللَّهُ عَزَّ وَجَلَّ. فَأَمَّا الْغَيْرَةُ الَّتِي يُحِبُّ اللَّهُ عَزَّ وَجَلَّ فَالْغَيْرَةُ فِي الرِّيبَةِ، وَأَمَّا الْغَيْرَةُ الَّتِي يَبْغُضُ اللَّهُ عَزَّ وَجَلَّ فَالْغَيْرَةُ فِي غَيْرِ رِيبَةٍ. وَالِاخْتِيَالُ الَّذِي يُحِبُّ اللَّهُ عَزَّ وَجَلَّ اخْتِيَالُ الرَّجُلِ بِنَفْسِهِ عِنْدَ الْقِتَالِ وَعِنْدَ الصَّدَقَةِ، وَالِاخْتِيَالُ الَّذِي يَبْغُضُ اللَّهُ عَزَّ وَجَلَّ الْخُيَلَاءُ فِي الْبَاطِلِ". (ن)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചായയും അഭിമാനത്തിൽ ചിലത് അല്ലാഹു ഇഷ്ടപ്പെടുന്നവയും, അല്ലാഹു വെറുക്കുന്നവയുമുണ്ട്. പൊങ്ങച്ചക്കാരിൽ ചിലരെ അല്ലാഹു ഇഷ്ടപ്പെടുകയും ചിലരെ വെറുക്കുകയും ചെയ്യുന്നു. എന്നാൽ സംശയാസ്പദമായ സാഹചര്യത്തിലുള്ള ഗൈറത്ത് അല്ലാഹു ഇഷ്ടപ്പെടുന്നതാണ്. മറിച്ച് സംശയാസ്പദമല്ലാത്തപ്പോഴുള്ള ഗൈറത്ത്(പൊങ്ങച്ചം) അല്ലാഹു വെറുക്കുന്നതിൽ പെട്ടതാണ്. ദാനധർമ്മത്തിന്റെയും യുദ്ധത്തിന്റെയും അവസരത്തിൽ തന്നെക്കുറിച്ച് പൊങ്ങച്ചം തോന്നുന്നതാണ് അല്ലാഹു ഇഷ്ടപ്പെടുന്ന പൊങ്ങച്ചം. നിരർത്ഥകമായ ദുരഭിമാനം വെച്ചു നടക്കുന്നവരുടെ ദുരഭിമാനം അല്ലാഹു വെറുക്കുന്ന ഇനത്തിൽ പ്പെട്ടതാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا وَتَصَدَّقُوا، وَالْبَسُوا فِي غَيْرِ إِسْرَافٍ وَلَا مَخِيلَةٍ". (ن)', 'അബ്ദുല്ലാഹിബിൻ അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ധൂർത്തും ദുരഭിമാനവും കാണിക്കാത്ത വിധം നിങ്ങൾ ഭക്ഷിക്കുകയും ദാനധർമ്മം ചെയ്യുകയും വസ്ത്രം ധരിക്കുകയും ചെയ്ത് കൊള്ളുക." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബിൻ അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ، وَلَا يَنْظُرُ إِلَيْهِمْ، وَلَا يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ". فَقَرَأَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو ذَرٍّ: خَابُوا وَخَسِرُوا، خَابُوا وَخَسِرُوا. قَالَ: "الْمُسْبِلُ إِزَارَهُ، وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ، وَالْمَنَّانُ عَطَاءَهُ". وفي روايةٍ: "الْمَنَّانُ بِمَا أَعْطَى، وَالْمُسْبِلُ إِزَارَهُ، وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ". (ن)', 'അബൂദർറ്(റ): നബി(സ)പറഞ്ഞു: "അന്ത്യദിനത്തിൽ പ്രതാപശാലിയും മഹത്വവാനുമായ അല്ലാഹു മൂന്ന് വിഭാഗത്തോട് സംസാരിക്കുകയോ അവരെ നോക്കുകയോ അവരെ പരിശുദ്ധപ്പെടുത്തുകയോ ഇല്ല. അവർക്ക് കഠിന ശിക്ഷയാണുള്ളത്." എന്നിട്ട് തിരുമേനി(സ) ആ ആയത്ത് പാരായണം ചെയ്തു. അപ്പോൾ അബുദർറ്(റ) പറഞ്ഞു: അവർക്ക് നാശം! അവർക്ക് നഷ്ടം! അവർക്ക് നാശം! അവർക്ക് നഷ്ടം. പ്രവാചകർ(സ) തുടർന്നു പറഞ്ഞു: "തന്റെ മുണ്ട് താഴ്ത്തിയിടുന്നവൻ, തന്റെ വിൽപ്പനച്ചരക്ക് കള്ള സത്യം ചെയ്തു കൊണ്ട് ചെലവഴിക്കുന്നവൻ, ചെയ്ത ദാനം എടുത്ത് പറയുന്നവൻ." മറ്റൊരു നിവേദനത്തിൽ: "താൻ നൽകിയത് എടുത്തു പറയുന്നവൻ, തന്റെ മുണ്ട് താഴ്ത്തിയിടുന്നവൻ, കള്ള ശപഥം ചെയ്ത് കൊണ്ട് കച്ചവടച്ചരക്ക് വിറ്റഴിക്കുന്നവൻ." എന്നാണുള്ളത്. (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=303), 1, 'وَفِي رِوَايَةٍ: "الْمَنَّانُ بِمَا أَعْطَى، وَالْمُسْبِلُ إِزَارَهُ، وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "താൻ നൽകിയത് എടുത്തു പറയുന്നവൻ, തന്റെ മുണ്ട് താഴ്ത്തിയിടുന്നവൻ, കള്ള ശപഥം ചെയ്ത് കൊണ്ട് കച്ചവടച്ചരക്ക് വിറ്റഴിക്കുന്നവൻ." എന്നാണുള്ളത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ: الشَّيْخُ الزَّانِي، وَالْعَائِلُ الْمَزْهُوُّ، وَالْإِمَامُ الْكَذَّابُ". (ن)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് വിഭാഗങ്ങളോട് അല്ലാഹു അന്ത്യദിനത്തിൽ സംസാരിക്കുകയില്ല. വ്യഭിചാരിയായ വൃദ്ധൻ, അഹന്ത നടിക്കുന്ന ദരിദ്രൻ, കളവ് പറയുന്ന ഭരണാധികാരി എന്നിവരാണവർ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 243, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُمَرَ عَلَى الصَّدَقَةِ، فَقِيلَ: مَنَعَ ابْنُ جَمِيلٍ وَخَالِدُ بْنُ الْوَلِيدِ وَالْعَبَّاسُ عَمُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا يَنْقِمُ ابْنُ جَمِيلٍ إِلَّا أَنَّهُ كَانَ فَقِيرًا فَأَغْنَاهُ اللَّهُ. وَأَمَّا خَالِدٌ فَإِنَّكُمْ تَظْلِمُونَ خَالِدًا، قَدِ احْتَبَسَ أَدْرَاعَهُ وَأَعْتَادَهُ فِي سَبِيلِ اللَّهِ. وَأَمَّا الْعَبَّاسُ فَهِيَ عَلَيَّ وَمِثْلُهَا مَعَهَا". ثُمَّ قَالَ: "يَا عُمَرُ، أَمَا شَعَرْتَ أَنَّ عَمَّ الرَّجُلِ صِنْوُ أَبِيهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഉമർ(റ)വിനെ സകാത്തിന്റെ ജോലി ഏൽപിച്ചു. അപ്പോൾ (റസൂൽ(സ)യോട്) പറയപ്പെട്ടു: ഇബ്നു ജമീൽ(റ)വും, ഖാലിദുബിനുൽ വലീദ്(റ)വും, റസൂലി(സ)ന്റെ പിതൃവ്യനായ അബ്ബാസ്(റ)വും (സകാത്തിന്റെ ജോലിയിൽ വ്യാപൃതരാവാതെ) വിലങ്ങിനിന്നിരിക്കുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ദരിദ്രനായിരുന്ന ഇബ്നു ജമീലിനെ അല്ലാഹു ധനികനാക്കി എന്നതു മാത്രമാണ് അദ്ദേഹത്തിന് ഈർഷ്യത ഉണ്ടാക്കിയത്. എന്നാൽ ഖാലിദിന്റെ കാര്യം പറഞ്ഞാൽ ഖാലിദിനോട് നിങ്ങൾ അതിക്രമം കാണിച്ചിരിക്കുകയാണ്. അദ്ദേഹം തന്റെ പടയങ്കിയും യുദ്ധസാമഗ്രികളും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ തടഞ്ഞുവെച്ചിരിക്കുകയാണ്. എന്നാൽ അബ്ബാസ്, അദ്ദേഹം തരാനുള്ളതും അതോടൊപ്പം അത് പോലുള്ള ഒന്നുകൂടി ഞാൻ നൽകാം." ശേഷം പറഞ്ഞു: "ഉമറേ നിനക്കറിയില്ലേ! ഒരാളുടെ പിതൃവ്യൻ അയാൾക്ക് തന്റെ പിതാവിനെപ്പോലെത്തന്നെയാണെന്നുള്ളത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 244, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ بُهَيْسَةَ فَزَارِية رَضِيَ اللهُ عَنْهَا قَالَتْ: اسْتَأْذَنَ أَبِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَخَلَ بَيْنَهُ وَبَيْنَ قَمِيصِهِ فَجَعَلَ يُقَبِّلُ وَيَلْتَزِمُ، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ؟ قَالَ: "الْمَاءُ". قَالَ: يَا نَبِيَّ اللَّهِ، مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ؟ قَالَ: "الْمِلْحُ". قَالَ: يَا رَسُولَ اللَّهِ، مَا الشَّيْءُ الَّذِي لَا يَحِلُّ مَنْعُهُ؟ قَالَ: "أَنْ تَفْعَلَ الْخَيْرَ خَيْرٌ لَكَ". (د,ن)', 'ബുഹൈസത്തു ഫസാരിയ്യ(റ): പ്രവാചകർ(സ)യുടെ അടുക്കൽ എന്റെ പിതാവ് പ്രവേശനാനുമതി തേടി. അങ്ങനെ അദ്ദേഹം തിരുമേനി(സ)ക്കും അവിടുത്തെ വസത്രത്തിനുമിടക്കായി കടന്നു ചെല്ലുകയും ശേഷം ചുംബിക്കുകയും ആലിംഗനം ചെയ്യുകയും ചെയ്തു. എന്നിട്ട് ചോദിച്ചു. അല്ലാഹുവിന്റെ റസൂലേ! എന്താണ് തടയൽ അനുവദനിയമല്ലാത്ത വസ്തു. റസൂൽ(സ) പറഞ്ഞു: "വെള്ളം." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ! എന്താണ് തടയൽ അനുവദനീയമല്ലാത്ത വസ്തു? അവിടന്ന് പറഞ്ഞു: "ഉപ്പ്." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്താണ് തടയൽ അനുവദനീയമല്ലാത്ത വസ്തു: പ്രവാചകൻ(സ)പറഞ്ഞു: "നീ നൻമ ചെയ്യുന്നതാണ് നിനക്ക് ഉത്തമം." (ദ,ന)', 'بُهَيْسَةَ فَزَارِية', 'ബുഹൈസത്തു ഫസാരിയ്യ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 244, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ: الْعَاقُّ لِوَالِدَيْهِ، وَالْمَرْأَةُ الْمُتَرَجِّلَةُ، وَالدَّيُّوثُ. وَثَلَاثَةٌ لَا يَدْخُلُونَ الْجَنَّةَ: الْعَاقُّ لِوَالِدَيْهِ، وَالْمُدْمِنُ عَلَى الْخَمْرِ، وَالْمَنَّانُ بِمَا أَعْطَى". (ن)', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്നു വിഭാഗക്കാരിലേക്ക് അല്ലാഹു അന്ത്യദിനത്തിൽ നോക്കുകയില്ല. മാതാപിതാക്കളെ കഷ്ടപ്പെടുത്തുന്നവൻ, പുരുഷവേഷം ധരിച്ച സ്ത്രീ, തന്റെ ആശ്രിതരോട് (ഭാര്യയോട്) കടപ്പാട് നിറവേറ്റാത്തവൻ എന്നിവരാണവർ. മൂന്നു വിഭാഗക്കാർ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല. മാതാപിതാക്കളെ കഷ്ടപ്പെടുത്തുന്നവൻ, സ്ഥിരമായി മദ്യപിക്കുന്നവൻ, നൽകിയതിന്റെ പേരിൽ നൽകപ്പെട്ടവനിൽനിന്ന് വിധേയത്വം തേടുന്നവൻ എന്നിവരാണവർ." (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 244, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا دَخَلَ الْمَسْجِدَ يَوْمَ الْجُمُعَةِ وَرَسُولُ اللَّهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَقَالَ: "صَلِّ رَكْعَتَيْنِ". ثُمَّ جَاءَ الْجُمُعَةَ الثَّانِيَةَ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَقَالَ: "صَلِّ رَكْعَتَيْنِ". ثُمَّ جَاءَ الْجُمُعَةَ الثَّالِثَةَ، فَقَالَ: "صَلِّ رَكْعَتَيْنِ". ثُمَّ قَالَ: "تَصَدَّقُوا". فَتَصَدَّقُوا، فَأَعْطَاهُ ثَوْبَيْنِ، ثُمَّ قَالَ: "تَصَدَّقُوا". فَطَرَحَ أَحَدَ ثَوْبَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَمْ تَرَوْا إِلَى هَذَا؟ أَنَّهُ دَخَلَ الْمَسْجِدَ بِهَيْئَةٍ بَذَّةٍ، فَرَجَوْتُ أَنْ تَفْطِنُوا لَهُ فَتَتَصَدَّقُوا عَلَيْهِ، فَلَمْ تَفْعَلُوا، فَقُلْتُ: تَصَدَّقُوا، فَتَصَدَّقْتُمْ، فَأَعْطَيْتُهُ ثَوْبَيْنِ، ثُمَّ قُلْتُ: تَصَدَّقُوا، فَطَرَحَ أَحَدَ ثَوْبَيْهِ، خُذْ ثَوْبَكَ". وَانْتَهَرَهُ. (ن)', 'അബുസഈദ്(റ): ഒരു വെള്ളിയാഴ്ച റസൂൽ(സ) ഖുതുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ഒരാൾ പള്ളിയിൽ പ്രവേശിച്ചു. അവിടന്ന് പറഞ്ഞു: "രണ്ട് രക്അത്ത് നമസ്കിക്കുക." തൊട്ടടുത്ത വെള്ളിയാഴ്ചയും റസൂൽ(സ) ഖുതുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ അദ്ദേഹം വന്നു. റസൂൽ(സ)പറഞ്ഞു: "രണ്ട് റക്അത്ത് നമസ്കരിക്കുക." ശേഷം തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ദാനധർമ്മങ്ങൾ ചെയ്യുക." അപ്പോൾ ആളുകൾ ദാനധർമ്മങ്ങൾ നൽകി. അങ്ങനെ ആ മനുഷ്യന് രണ്ടു വസ്ത്രങ്ങൾ തിരുമേനി(സ) നൽകി. പ്രവാചകർ(സ) വീണ്ടും പറഞ്ഞു: "നിങ്ങൾ ദാനധർമ്മങ്ങൾ ചെയ്യുക!" അപ്പോൾ അദ്ദേഹം (തനിക്കു കിട്ടിയ) രണ്ടിൽ ഒരു വസ്ത്രം ദാനമായി തിരിച്ചു കൊടുത്തു." റസൂൽ(സ) പറഞ്ഞു: "ഈ വ്യക്തിയിലേക്ക് നിങ്ങൾ നോക്കുന്നില്ലേ? അവൻ നഗ്നത വെളിപ്പെടും വിധത്തിലുള്ള വസ്ത്രം ധരിച്ചാണ് പള്ളിയിൽ വന്നത്. അപ്പോൾ നിങ്ങൾ അവനെ ശ്രദ്ധിക്കുകയും അവന് ദാനം നൽകുകയും ചെയ്യണമെന്ന് ഞാൻ ആഗ്രഹിച്ചു. പക്ഷേ നിങ്ങൾ അങ്ങിനെ ചെയ്തില്ല. ഞാൻ നിങ്ങളോട്, ദാന ധർമ്മങ്ങൾ നൽകൂ എന്ന് പറഞ്ഞു. അപ്പോൾ നിങ്ങൾ ദാന ധർമ്മങ്ങൾ നൽകി. ഞാൻ അവന് രണ്ട് വസ്ത്രങ്ങൾ നൽകി. എന്നിട്ട് ഞാൻ പറഞ്ഞു: നിങ്ങൾ ദാനം നൽകുക. അപ്പോൾ അയാൾ തനിക്കുലഭിച്ച രണ്ടു വസ്ത്രങ്ങളിൽ ഒരെണ്ണമിതാ ദാനമായി ഇട്ടുതന്നിരിക്കുന്നു. (ശേഷം പ്രവാചകർ(സ) ആ വസ്ത്രം അയാൾക്ക് നൽകിക്കൊണ്ട് പറഞ്ഞു:) നീ നിന്റെ വസ്ത്രം എടുത്തു കൊള്ളുക." ശേഷം അദ്ദേഹത്തെ പറഞ്ഞുവിട്ടു. (ന)', 'أَبِي سَعِيدٍ', 'അബുസഈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 245, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ حَمَلَ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ، ثُمَّ رَآهَا تُبَاعُ، فَأَرَادَ أَنْ يَشْتَرِيَهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَعُدْ فِي صَدَقَتِكَ". وفي روايةٍ: "لَا تَعْرِضْ فِي صَدَقَتِكَ". (ق,د,ت,ن)', 'ഉമർ(റ)വിൽ നിന്ന് ഇബ്നുഉമർ(റ): ഉമർ(റ) ഒരു കുതിരയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ദാനം നൽകി. അത് വിൽക്കാൻ വെച്ചതായി അദ്ദേഹം കണ്ടു. അപ്പോൾ അദ്ദേഹം അതു വാങ്ങാനുദ്ദേശിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ സദഖ മടക്കി എടുക്കരുത്." മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമാണ്: "നീ നിന്റെ സദഖയെ ഒരു വിൽപനച്ചരക്കാക്കരുത്." (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ، عَنْ عُمَرَ', 'ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 245, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=309), 1, 'وَفِي رِوَايَةٍ: "لَا تَعْرِضْ فِي صَدَقَتِكَ". (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമാണ്: "നീ നിന്റെ സദഖയെ ഒരു വിൽപനച്ചരക്കാക്കരുത്." (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: حَمَلْتُ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ، فَأَضَاعَهُ الَّذِي كَانَ عِنْدَهُ، وَأَرَدْتُ أَنْ أَبْتَاعَهُ مِنْهُ وَظَنَنْتُ أَنَّهُ بَائِعُهُ بِرُخْصٍ، فَسَأَلْتُ عَنْ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَا تَشْتَرِهِ وَإِنْ أَعْطَاكَهُ بِدِرْهَمٍ، فَإِنَّ الْعَائِدَ فِي صَدَقَتِهِ كَالْكَلْبِ يَعُودُ فِي قَيْئِهِ". (خ,ن)', 'ഉമർ(റ): ഞാൻ ദൈവമാർഗ്ഗത്തിൽ ഒരു കുതിരയെ നൽകി. അത് ഉണ്ടായിരുന്ന ആൾ അതിനെ (നഷ്ടപ്പെടുത്തി) വിൽപ്പനചെയ്യാൻ ഉദ്ദേശിച്ചു. അദ്ദേഹം അതിനെ തുഛമായ വിലയ്ക്ക് വിൽക്കുമെന്ന് ഞാൻ വിചാരിച്ചു. അത് വാങ്ങുന്നുത് സംബന്ധിച്ച് റസൂൽ(സ)യോട് ഞാൻ ചോദിച്ചു. തിരുമേനി(സ) പറഞ്ഞു: "അയാൾ അതിനെ ഒരു ദിർഹമിന് നിനക്ക് നൽകുകയാണെങ്കിൽ പോലും നീ അതിനെ വാങ്ങരുത്. ദാനധർമ്മമായി നൽകിയതിനെ തിരിച്ച് വാങ്ങുന്നവൻ ചർദ്ദിച്ചത് തിന്നുന്ന നായക്ക് തുല്യമായവനാണ്." (ബു,ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 246, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ عَتَّابَ بْنَ أَسِيدٍ أَنْ يَخْرُصَ الْعِنَبَ فَتُؤَدَّى زَكَاتُهُ زَبِيبًا، كَمَا تُؤَدَّى زَكَاةُ النَّخْلِ تَمْرًا. (ن)', 'സഈദ് ബിനിൽ മുസയ്യബ്(റ): റസൂൽ(സ) അത്താബുബ്നു അസീദിനോട്, ഈത്തപ്പനയുടെ സകാത്തായി കാരക്ക നൽകുന്നത് പോലെ, മുന്തിരി മതിച്ചു കണക്കാക്കുകയും അതിന്റെ സകാത്തായി ഉണക്ക മുന്തിരി നൽകുകയും ചെയ്യാൻ കൽപിച്ചു. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദ് ബിനിൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 246, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَتَتْهُ امْرَأَةٌ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ تَصَدَّقْتُ عَلَى أُمِّي بِجَارِيَةٍ، وَإِنَّهَا مَاتَتْ؟ قَالَ: "وَجَبَ أَجْرُكِ وَرَدَّهَا عَلَيْكِ الْمِيرَاثُ". قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهَا كَانَ عَلَيْهَا صَوْمُ شَهْرٍ، أَفَأَصُومُ عَنْهَا؟ قَالَ: "صُومِي عَنْهَا". قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهَا لَمْ تَحُجَّ قَطُّ، أَفَأَحُجُّ عَنْهَا؟ قَالَ: "نَعَمْ حُجِّي عَنْهَا". (م,د,ت,جه)', 'ബുറൈദ(റ): ഞാൻ പ്രവാചകർ(സ)യുടെ അടുത്തിരിക്കുമ്പോൾ ഒരു സ്ത്രീ വന്ന് അവിടത്തോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! ഞാൻ എന്റെ മാതാവിന് ഒരു അടിമസ്ത്രീയെ ദാനം നൽകിയിരുന്നു. എന്റെ ഉമ്മ മരിച്ചിരിക്കുന്നു! (ഇനി ആ അടിമസ്ത്രീയുടെ കാര്യത്തിലുള്ള മതവിധി എന്താണ്?) റസൂൽ(സ) പറഞ്ഞു: "നിനക്കുള്ള പ്രതിഫലം ഉറപ്പായി. അനന്തരാവകാശത്തിലൂടെ അത് നിനക്ക് തന്നെ തിരിച്ച് കിട്ടുകയും ചെയ്തു." ആ സ്ത്രീ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ! എന്റെ മാതാവിന് ഒരു മാസത്തെ നോമ്പെടുക്കാനുണ്ട്. അവർക്ക് പകരം ഞാൻ നോമ്പെടുത്താൽ മതിയാകുമോ? തിരുമേനി(സ) പറഞ്ഞു: "നീ അവർക്കു പകരം നോമ്പെടുത്തു കൊള്ളുക." ആ സ്ത്രീ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! അവർ ഒറ്റ തവണയും ഹജ്ജ് ചെയ്തിട്ടില്ല. അവർക്കു പകരമായി എനിക്ക് ഹജ്ജ് ചെയ്യാമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അവർക്ക് വേണ്ടി ഹജ്ജ് ചെയ്തു കൊള്ളുക." (മു,ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 246, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ: وَقَدْ بَعَثَهُ بَعْضُ الْأُمَرَاءِ عَلَى الصَّدَقَةِ، فَلَمَّا رَجَعَ قَالَ لِعِمْرَانَ: أَيْنَ الْمَالُ؟ قَالَ: وَلِلْمَالِ أَرْسَلْتَنِي؟ أَخَذْنَاهَا مِنْ حَيْثُ كُنَّا نَأْخُذُهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَوَضَعْنَاهَا حَيْثُ كُنَّا نَضَعُهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): അദ്ദേഹത്തെ സകാത്ത് ശേഖരണ വിതരണത്തിന് വേണ്ടി ഒരു ഭരണാധികാരി നിയോഗിച്ചിരുന്നു. അങ്ങനെ മടങ്ങി വന്നപ്പോൾ ഇംറാൻ(റ)വിനോട് ചോദിച്ചു: "ധനം എവിടെ?" അദ്ദേഹം പറഞ്ഞു: എന്നെ ധനത്തിനാണോ നിയോഗിച്ചത്.? റസൂൽ(സ)യുടെ കാലത്ത് ഞങ്ങൾ പിരിച്ചെടുത്തിരുന്നിടത്ത് നിന്ന് ഞങ്ങൾ പിരിച്ചെടുക്കുകയും തിരുമേനി(സ)യുടെ കാലത്തു നൽകിയിരുന്നിടത്തേക്ക് ഞങ്ങൾ അവ നൽകുകയും ചെയ്തിരിക്കുന്നു. (ദ,ജ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 246, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْجَاهِرُ بِالْقُرْآنِ كَالْجَاهِرِ بِالصَّدَقَةِ، وَالْمُسِرُّ بِالْقُرْآنِ كَالْمُسِرِّ بِالصَّدَقَةِ". (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ) റസൂൽ(സ) പറഞ്ഞു: "ദാനധർമ്മം പരസ്യമാക്കുന്നവനെപോലെയാണ് ഖുർആൻ ഉച്ചത്തിൽ പാരായണം ചെയ്യുന്നവൻ. ഖുർആൻ പതുക്കെ ഓതുന്നവൻ ദാനധർമ്മം രഹസ്യമായി നൽകിയവനെ പ്പോലെയാണ്." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّاعِي عَلَى الْأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ". (ن)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്നവനെപ്പോലെയാണ് പാവപ്പെട്ടവന്നും വിധവകൾക്കും വേണ്ടി യത്നിക്കുന്നവൻ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: الْإِمَامُ الْعَادِلُ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ رَبِّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ طَلَبَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ، فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا، حَتَّى لَا تَعْلَمَ يَمِينُهُ مَا تُنْفِقُ شِمَالُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ". (م)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ തണലല്ലാത്ത യാതൊരു തണലും ലഭിക്കാത്ത ദിനത്തിൽ ഏഴു വിഭാഗക്കാർക്ക് അല്ലാഹു തന്റെ തണൽ നൽകും: നീതിമാനായ ഭരണാധികാരി, തന്റെ നാഥനെ ആരാധിച്ചു വളർന്ന യുവാവ്, പള്ളികളുമായി തന്റെ ഹൃദയത്തെ നിത്യബന്ധമുണ്ടാക്കിയ വ്യക്തി, അല്ലാഹുവിന്ന് വേണ്ടി മാത്രം പരസ്പരം സ്നേഹിക്കുകയും അവനുവേണ്ടിമാത്രം പരസ്പരം വേർപിരിയുകയും ചെയ്ത രണ്ടു വ്യക്തികൾ, തറവാടിത്വവും ഭംഗിയുമുള്ള ഒരു സ്ത്രീ വേഴ്ച്ചക്ക് ക്ഷണിച്ചപ്പോൾ ഞാൻ അല്ലാഹുവിനെ ഭയപ്പെടുന്നു എന്ന് പ്രഖ്യാപിച്ച പുരുഷൻ, ദാനധർമ്മം നൽകുകയും തന്റെ ഇടതു കൈ ചെലവഴിച്ചത് വലതു കൈ അറിയാത്ത വിധം ഗോപ്യമാക്കുകയും ചെയ്തവൻ, അല്ലാഹുവിനെ ഒഴിഞ്ഞിരുന്ന് സ്മരിക്കുകയും അതുകാരണം തന്റെ ഇരു കണ്ണുകളിൽനിന്നും കണ്ണുനീർ നിറഞ്ഞൊഴുകയും ചെയ്ത മനുഷ്യൻ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ قَالَ: "اللَّهُمَّ صَلِّ عَلَيْهِمْ". فَأَتَاهُ أَبِي أَبُو أَوْفَى بِصَدَقَتِهِ، فَقَالَ: "اللَّهُمَّ صَلِّ عَلَى آلِ أَبِي أَوْفَى". (م)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫാ(റ): റസൂൽ(സ)യുടെ അടുക്കലേക്ക് ഒരു വിഭാഗം ആളുകൾ തങ്ങളുടെ ദാനധർമ്മങ്ങളുമായി വന്നാൽ അവിടന്ന് പ്രാർത്ഥിക്കും: "അല്ലാഹുവേ ഇവരുടെമേൽ നീ അനുഗ്രഹം ചൊരിയേണമേ." ഒരിക്കൽ എന്റെ പിതാവായ അബുഔഫാ(റ) സദഖയുമായി ചെന്നു. അപ്പോൾ അവിടന്ന് പ്രാർത്ഥിച്ചു. "അല്ലാഹുവേ അബുഔഫാ(റ)യുടെ കുടുംബത്തെ നീ അനുഗ്രഹിക്കേണമേ!" (മു)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫാ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَبِي مِنْ أَصْحَابِ الشَّجَرَةِ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ، قَالَ: "اللَّهُمَّ صَلِّ عَلَى آلِ فُلَانٍ". قَالَ: فَأَتَاهُ أَبِي بِصَدَقَتِهِ، فَقَالَ: "اللَّهُمَّ صَلِّ عَلَى آلِ أَبِي أَوْفَى". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): എന്റെ പിതാവ് മരച്ചുവട്ടിൽ ബൈഅത്ത് ചെയ്തവരിൽ പെട്ടവരാണ്. ഒരു സംഘം തങ്ങളുടെയടുക്കൽ സദഖയുമായി വന്നാൽ റസൂൽ(സ) അവർക്കു വേണ്ടി ഇപ്രകാരം പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ ഇന്നാലിന്ന കുടുബത്തെ നീ അനുഗ്രഹിക്കേണമേ!" അങ്ങനെ അബുഔഫാ(റ) തന്റെ സദഖയുമായി വന്നപ്പോൾ റസൂൽ(സ) പ്രാർത്ഥച്ചു: "അല്ലാഹുവേ അബുഔഫായുടെ കുടുംബത്തെ നീ അനുഗ്രഹിക്കേണമേ!" (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَعْطَيْتُمُ الزَّكَاةَ فَلَا تَنْسَوْا ثَوَابَهَا أَنْ تَقُولُوا: اللَّهُمَّ اجْعَلْهَا مَغْنَمًا وَلَا تَجْعَلْهَا مَغْرَمًا". (جه)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ സകാത്തു നൽകുകയാണെങ്കിൽ അതിന്റെ പ്രതിഫലത്തെ മറന്നു കളയരുത്. നിങ്ങൾ ഇപ്രകാരം പ്രാർത്ഥിക്കുക. അല്ലാഹുവേ ഇതിനെ നീ കടം വീട്ടാൻ പര്യാപ്തമായതാക്കണേ, കടം വീട്ടാൻ പര്യാപ്തമല്ലാത്തത് ആക്കരുതേ!" (ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نُخْرِجُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْفِطْرِ صَاعًا مِنْ طَعَامٍ، وَكَانَ طَعَامَنَا الشَّعِيرُ وَالزَّبِيبُ وَالْأَقِطُ وَالتَّمْرُ. وفي روايةٍ: لَا نُخْرِجُ غَيْرَهُ. (خ,ن)', 'അബുസഈദിൽ ഖുദ്‌രീ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കാലത്ത് ചെറിയ പെരുന്നാൾ ദിവസത്തിൽ ഒരു സ്വാഅ് ഭക്ഷണം നൽകാറുണ്ടായിരുന്നു. ബാർലിയും, ഉണക്ക മുന്തിരിയും, പാൽക്കട്ടിയും കാരക്കയും ഞങ്ങളുടെ ഭക്ഷണമായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: ഞങ്ങൾ മറ്റുള്ളവ നൽകാറില്ല. (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രീ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=320), 1, 'وَفِي رِوَايَةٍ: لَا نُخْرِجُ غَيْرَهُ. (خ,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: ഞങ്ങൾ മറ്റുള്ളവ നൽകാറില്ല. (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَقَةَ الْفِطْرِ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ تَمْرٍ، عَلَى الصَّغِيرِ وَالْكَبِيرِ، وَالْحُرِّ وَالْمَمْلُوكِ. (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) അടിമക്കും, സ്വതന്ത്രനും, വലിയവനും, ചെറിയവനും, ഒരു സ്വാഅ് കാരക്ക, അല്ലങ്കിൽ ഒരു സ്വാഅ് ബാർലി എന്ന തോതിൽ ഫിത്റ് സകാത്ത് നിർബ്ബന്ധമാക്കി. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ ثَعْلَبَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي صُعَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صَاعٌ مِنْ بُرٍّ - أَوْ قَمْحٍ - عَلَى كُلِّ اثْنَيْنِ، صَغِيرٍ أَوْ كَبِيرٍ، حُرٍّ أَوْ عَبْدٍ، ذَكَرٍ أَوْ أُنْثَى، غَنِيٍّ أَوْ فَقِيرٍ. أَمَّا غَنِيُّكُمْ فَيُزَكِّيهِ اللَّهُ، وَأَمَّا فَقِيرُكُمْ فَيَرُدُّ اللَّهُ تَعَالَى عَلَيْهِ أَكْثَرَ مِمَّا أَعْطَى". وفي روايةٍ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطِيبًا، فَأَمَرَ بِصَدَقَةِ الْفِطْرِ: صَاعِ تَمْرٍ، أَوْ صَاعِ شَعِيرٍ، عَنْ كُلِّ رَأْسٍ. وفي روايةٍ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ قَبْلَ الْفِطْرِ بِيَوْمَيْنِ. (د)', 'സഅ്ലബതുബ്നു അബ്ദുല്ലാഹിബ്നി അബീസ്വുഐർ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു വിഭാഗക്കാരിൽ ഓരോരുത്തരുടെ മേലിലും ഒരു സ്വാഅ് ധാന്യം - അല്ലെങ്കിൽ ഗോതമ്പ് - നിർബന്ധമാണ്. ചെറിയവനും വലിയവനും, സ്വതന്ത്രനും അടിമക്കും, ആണിനും പെണ്ണിനും, ധനികനും ദരിദ്രനും, എന്നാൽ നിങ്ങളിൽ ധനികൻ ഈ സകാത് മുഖേന അല്ലാഹു അവനെ പരിശുദ്ധനാക്കിയേക്കാം. എന്നാൽ നിങ്ങളിൽ ദരിദ്രന് ഇത് മുഖേന അവൻ നൽകിയതിനേക്കാൾ അധികമായി അല്ലാഹു തിരിച്ചു നൽകിയേക്കാം." മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) മിംബറിൽ പ്രസംഗിക്കാൻ നിന്നു. എന്നിട്ട് ഫിത്റ് സകാത്ത് നൽകാൻ വേണ്ടി ഇപ്രകാരം കൽപ്പിച്ചു. ഓരോ വ്യക്തിക്കും കാരക്കയിൽനിന്ന് ഒരു സ്വാഅ് കാരക്ക - അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി - എന്നിങ്ങനെ. മറ്റൊരു നിവേദനത്തിൽ റസൂൽ(സ) ചെറിയ പെരുന്നാളിന്റെ രണ്ടു ദിവസം മുമ്പാണ് ഇങ്ങനെ പ്രസംഗിച്ചത് എന്നുണ്ട്. (ദ)', 'ثَعْلَبَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي صُعَيْرٍ', 'സഅ്ലബതുബ്നു അബ്ദുല്ലാഹിബ്നി അബീസ്വുഐർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 248, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=322), 1, 'وَفِي رِوَايَةٍ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطِيبًا، فَأَمَرَ بِصَدَقَةِ الْفِطْرِ: صَاعِ تَمْرٍ، أَوْ صَاعِ شَعِيرٍ، عَنْ كُلِّ رَأْسٍ.', 'മറ്റൊരു നിവേദനത്തിൽ: അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) മിംബറിൽ പ്രസംഗിക്കാൻ നിന്നു. എന്നിട്ട് ഫിത്റ് സകാത്ത് നൽകാൻ വേണ്ടി ഇപ്രകാരം കൽപ്പിച്ചു. ഓരോ വ്യക്തിക്കും കാരക്കയിൽനിന്ന് ഒരു സ്വാഅ് കാരക്ക - അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി - എന്നിങ്ങനെ.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=322), 2, 'وَفِي رِوَايَةٍ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ قَبْلَ الْفِطْرِ بِيَوْمَيْنِ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ റസൂൽ(സ) ചെറിയ പെരുന്നാളിന്റെ രണ്ടു ദിവസം മുമ്പാണ് ഇങ്ങനെ പ്രസംഗിച്ചത് എന്നുണ്ട്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنِ الْحَسَنِ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي آخِرِ رَمَضَانَ عَلَى مِنْبَرِ الْبَصْرَةِ، فَقَالَ: أَخْرِجُوا صَدَقَةَ صَوْمِكُمْ، فَكَأَنَّ النَّاسَ لَمْ يَعْلَمُوا، فَقَالَ: مَنْ هَاهُنَا مِنْ أَهْلِ الْمَدِينَةِ؟ قُومُوا إِلَى إِخْوَانِكُمْ فَعَلِّمُوهُمْ فَإِنَّهُمْ لَا يَعْلَمُونَ، فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الصَّدَقَةَ صَاعًا مِنْ تَمْرٍ، أَوْ شَعِيرٍ، أَوْ نِصْفَ صَاعٍ مِنْ قَمْحٍ، عَلَى كُلِّ حُرٍّ أَوْ مَمْلُوكٍ، ذَكَرٍ أَوْ أُنْثَى، صَغِيرٍ أَوْ كَبِيرٍ. فَلَمَّا قَدِمَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ رَأَى رُخْصَ السِّعْرِ، قَالَ: قَدْ أَوْسَعَ اللَّهُ عَلَيْكُمْ، فَلَوْ جَعَلْتُمُوهُ صَاعًا مِنْ كُلِّ شَيْءٍ. (د,ن)', 'ഹസൻ(റ): ബസറയിലെ മിംബറിൽ ഇബ്നുഅബ്ബാസ്(റ) റമദാനിനിന്റെ അവസാനഘട്ടത്തിൽ ഇപ്രകാരം പ്രസംഗിച്ചു: നിങ്ങളുടെ നോമ്പിന്റെ സദഖനൽകുക. അപ്പോൾ ആളുകൾക്ക് അതിനെ സംബന്ധിച്ച് അറിയാത്തതു പോലെയുണ്ട്. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: മദീനക്കാർ ആരാണ് ഇവിടെയുള്ളത്? നിങ്ങൾ നിങ്ങളുടെ സഹോദരങ്ങളിലേക്ക് എഴുന്നേറ്റു ചെല്ലുക. എന്നിട്ടവരെ പഠിപ്പിക്കുക. അവർ ഇതു സംബന്ധിച്ച് ജ്ഞാനമില്ലാത്തവരാണ്. റസൂൽ(സ) ഓരോ സ്വതന്ത്രനും അടിമക്കും, പുരുഷനും സ്ത്രീക്കും, വലിയവനും ചെറിയവനും ഒരു സ്വാഅ് കാരക്കയോ ബാർലിയോ അല്ലെങ്കിൽ അര സ്വാഅ്ഗോതമ്പോ ഫിത്ർ സകാത്ത് നൽകൽ നിർബന്ധമാക്കിയിരിക്കുന്നു. അലി(റ) വന്നപ്പോൾ, വിലക്കൂടുതലുള്ള വസ്തു അളവ് കുറച്ച് നൽകാൻ ഇളവ് നൽകപ്പെട്ടതായി കണ്ടു, അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു നിങ്ങളുടെ മേൽ വിശാലത കാണിച്ചിരിക്കുന്നു. നിങ്ങൾ നൽകുന്ന ഓരോ വസ്തുവും ഓരോ സ്വാഅ് വീതം ആക്കിയിരുന്നുവെങ്കിൽ (ഗുണകരമായിരുന്നു). (ദ,ന)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَضَ زَكَاةَ الْفِطْرِ مِنْ رَمَضَانَ: صَاعٌ مِنْ تَمْرٍ، أَوْ صَاعٌ مِنْ شَعِيرٍ، عَلَى كُلِّ حُرٍّ أَوْ عَبْدٍ، ذَكَرٍ أَوْ أُنْثَى - وفي روايةٍ: وَالذَّكَرِ وَالْأُنْثَى - مِنَ الْمُسْلِمِينَ. زاد في روايةٍ: وَالصَّغِيرِ وَالْكَبِيرِ، وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ. (ق,د,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) റമദാനിൽ സകാത്തുൽഫിത്ർ ഇപ്രകാരം നിർബന്ധമാക്കി. ഓരോ സ്വതന്ത്രനും അടിമക്കും, പുരുഷനും സിത്രീക്കും, ഒരു സ്വാഅ് കാരക്കയോ, ഒരു സ്വാഅ് ബാർലിയോ വീതം നൽകൽ ബാദ്ധ്യതയുണ്ട്. മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരം വർദ്ധിപ്പിച്ചിട്ടുണ്ട്: ഓരോ വലിയവനും ചെറിയവനും (ബാദ്ധ്യതയുണ്ട്), ജനങ്ങൾ നമസ്കാര സ്ഥലത്തേക്ക് പുറപ്പെടുന്നതിന് മുമ്പ് അത് നൽകേണ്ടതാണ്. (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=324), 1, 'وَفِي رِوَايَةٍ: وَالذَّكَرِ وَالْأُنْثَى - مِنَ الْمُسْلِمِينَ. زاد في روايةٍ: وَالصَّغِيرِ وَالْكَبِيرِ، وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ. (ق,د,ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരം വർദ്ധിപ്പിച്ചിട്ടുണ്ട്: ഓരോ വലിയവനും ചെറിയവനും (ബാദ്ധ്യതയുണ്ട്), ജനങ്ങൾ നമസ്കാര സ്ഥലത്തേക്ക് പുറപ്പെടുന്നതിന് മുമ്പ് അത് നൽകേണ്ടതാണ്. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّاسُ يُخْرِجُونَ صَدَقَةَ الْفِطْرِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَاعًا مِنْ شَعِيرٍ أَوْ تَمْرٍ أَوْ سُلْتٍ أَوْ زَبِيبٍ، فَلَمَّا كَانَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ - وَكَثُرَتِ الْحِنْطَةُ - جَعَلَ عُمَرُ نِصْفَ صَاعِ حِنْطَةٍ، مَكَانَ صَاعٍ مِنْ تِلْكَ الْأَشْيَاءِ. (د,ن)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=325), 1, 'وَفِي رِوَايَةٍ: قَالَ عَبْدُ اللَّهِ رَضِيَ اللهُ عَنْهُ: فَعَدَلَ النَّاسُ بَعْدُ نِصْفَ صَاعٍ مِنْ بُرٍّ. قَالَ: وَكَانَ عَبْدُ اللَّهِ يُعْطِي التَّمْرَ، فَأُعْوِزَ أَهْلُ الْمَدِينَةِ التَّمْرَ عَامًا فَأَعْطَى الشَّعِيرَ. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: അബ്ദുല്ല(റ) പറയുന്നു: പിന്നീട് ആളുകൾ അര സ്വാഅ് ഗോതമ്പ് നൽകുന്നത് നീതിയുക്തമായി കണക്കാക്കി. അദ്ദേഹം പറയുന്നു: അബ്ദുല്ല(റ) കാരക്കയാണ് നൽകാറുള്ളത്. അങ്ങനെ മദീനക്കാർക്ക്, ഒരു വർഷം കാരക്കക്ക് ദൗർലഭ്യത വന്നു. അപ്പോൾ അദ്ദേഹം ബാർലി നൽകി. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُخْرِجُ - إِذْ كَانَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - زَكَاةَ الْفِطْرِ عَنْ كُلِّ صَغِيرٍ وَكَبِيرٍ، حُرٍّ أَوْ مَمْلُوكٍ: صَاعًا مِنْ طَعَامٍ، أَوْ صَاعًا مِنْ أَقِطٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ زَبِيبٍ. فَلَمْ نَزَلْ نُخْرِجُهُ حَتَّى قَدِمَ مُعَاوِيَةُ حَاجًّا أَوْ مُعْتَمِرًا، فَكَلَّمَ النَّاسَ عَلَى الْمِنْبَرِ، فَكَانَ فِيمَا كَلَّمَ بِهِ النَّاسَ أَنْ قَالَ: إِنِّي أَرَى أَنَّ مُدَّيْنِ مِنْ سَمْرَاءِ الشَّامِ تَعْدِلُ صَاعًا مِنْ تَمْرٍ. فَأَخَذَ النَّاسُ بِذَلِكَ، فَقَالَ أَبُو سَعِيدٍ: فَأَمَّا أَنَا فَلَا أَزَالُ أُخْرِجُهُ أَبَدًا مَا عِشْتُ. (ق,د,ت,ن,جه)', 'അബുസഈദിൽ ഖുദ്‌രി(റ): ഞങ്ങളിൽ റസൂൽ(സ) ഉണ്ടായിരിക്കെ ഞങ്ങളിലെ വലിയവന്റെയും ചെറിയവന്റെയും സ്വതന്ത്രന്റെയും അടിമയുടെയും പേരിൽ മുഖ്യാഹാരത്തിൽ നിന്ന് ഒരു സ്വാഅ്, അല്ലെങ്കിൽ ബാർലിയിൽ നിന്ന് ഒരു സ്വാഅ്, അല്ലെങ്കിൽ ഒരു സ്വാഅ് കാരക്ക, അല്ലെങ്കിൽ ഒരു സ്വാഅ് ഉണക്കമുന്തിരി എന്ന തോതിൽ നൽകിയിരുന്നു. ഞങ്ങൾ അതു നൽകികൊണ്ടിരുന്നു. അങ്ങനെ മുആവിയ(റ) ഹജ്ജിനോ ഉംറക്കോ പുറപ്പെടുകയും അവിടെ വെച്ച് മിംബറിൽ നിന്ന് പ്രസംഗിച്ചപ്പോൾ ഇപ്രകാരം പറയുകയും ചെയ്തു: ഒരു സ്വാഅ് കാരക്കക്ക് തുല്യമാണ് ശാമിലെ രണ്ട് മുദ്ദ് ഗോതമ്പെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. അപ്പോൾ ആളുകൾ അത് നൽകാൻ തുടങ്ങി. അപ്പോൾ അബുസഈദ്(റ) പറഞ്ഞു: എന്റെ ജീവിതത്തിലുട നീളം ഞാൻ അത് (ശാമിലെഗോതമ്പ്) ആയിരുന്നു (ഫിത്ർസകാത്തായി) നൽകിയിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബുസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُنَادِيًا فِي فِجَاجِ مَكَّةَ: "أَلَا، إِنَّ صَدَقَةَ الْفِطْرِ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ، ذَكَرٍ أَوْ أُنْثَى، حُرٍّ أَوْ عَبْدٍ، صَغِيرٍ أَوْ كَبِيرٍ، مُدَّانِ مِنْ قَمْحٍ، أَوْ سِوَاهُ صَاعٌ مِنْ طَعَامٍ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) എന്നെ മക്കയിലേക്ക് ഇപ്രകാരം വിളിച്ചു പറയാൻ നിയോഗിച്ചു: "അറിയുക, രണ്ടുമുദ്ദ് ഗോതമ്പ് അല്ലെങ്കിൽ മറ്റു ഭക്ഷ്യവസ്തുക്കളിൽനിന്ന് ഒരു സ്വാഅ് എന്നതോതിൽ മുസ്‌ലിമായ ഓരോ പുരുഷനും സ്ത്രീക്കും സ്വതന്ത്രനും അടിമക്കും, വലിയവനും ചെറിയവനും, ഫിത്റ് സ്കാത്ത് നൽകൽ നിർബന്ധമാണ്." (തു)
(ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['ന']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: ذَكَرَ فِي صَدَقَةِ الْفِطْرِ، قَالَ: صَاعًا مِنْ بُرٍّ، أَوْ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ سُلْتٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഫിത്ർ സകാത്തിന്റെ കാര്യത്തിൽ അദ്ദേഹം പ്രഖ്യാപനം നടത്തി. അദ്ദേഹം പറഞ്ഞു: ഒരു സ്വാഅ്ഗോതമ്പ്, അല്ലെങ്കിൽ ഒരു സ്വാഅ് കാരക്ക, അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി, അല്ലെങ്കിൽ ഒരു സ്വാഅ് തൊലിയില്ലാത്ത വെളുത്ത ബാർലി (എന്നിങ്ങനെയാണത്). (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ أَبِي رَجَاءٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ ابْنَ عَبَّاسٍ يَخْطُبُ عَلَى مِنْبَرِكُمْ، يَعْنِي مِنْبَرَ الْبَصْرَةِ، يَقُولُ: صَدَقَةُ الْفِطْرِ صَاعٌ مِنْ طَعَامٍ. (ن)', 'അബൂറജാഅ്(റ): ഇബ്നുഅബ്ബാസ്(റ) നിങ്ങളുടെ മിമ്പറിൽ വെച്ച് ഇപ്രകാരം പ്രസംഗിക്കുന്നതായി ഞാൻ കേട്ടു - ബസറയിലെ മിമ്പറാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത് -: ഫിത്ർ സകാത്ത് ഭക്ഷ്യവസ്തുക്കളിൽനിന്ന് ഒരു സ്വാഅ് ആകുന്നു. (ന)', 'أَبِي رَجَاءٍ', 'അബൂറജാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَكَاةَ الْفِطْرِ: صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، عَلَى الْحُرِّ وَالْعَبْدِ، وَالذَّكَرِ وَالْأُنْثَى، وَالصَّغِيرِ وَالْكَبِيرِ، مِنَ الْمُسْلِمِينَ. وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ. (ق,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഫിത്ർ സകാത്ത് നിർബന്ധമാക്കി. ഒരു സ്വാഅ് കാരക്ക, അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി എന്ന തോതിലാണത്. അത് മുസ്‌ലിമായ ഓരോ സ്വതന്ത്രനും അടിമക്കും, സ്ത്രീക്കും പുരുഷനും, വലിയവനും ചെറിയവനും ബാദ്ധ്യതയാണ്. ജനങ്ങൾ പെരുന്നാൾ നമസ്കാരത്തിന് പുറപ്പെടും മുമ്പ് അത് നൽകേണ്ടതുണ്ട്. (ബു,മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِزَكَاةِ الْفِطْرِ: صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ. قَالَ عَبْدُ اللَّهِ: فَجَعَلَ النَّاسُ عِدْلَهُ مُدَّيْنِ مِنْ حِنْطَةٍ. (ق,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരു സ്വാഅ് കാരക്ക അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി എന്നതോതിൽ സകാത്തുൽ ഫിത്ർ നൽകാൻ കൽപിച്ചു. ഇബ്നുഉമർ പറയുന്നു. പിന്നീട് ആളുകൾ രണ്ട് മുദ്ദ് ഗോതമ്പ് അതിന് തുല്യമായി പരിഗണിച്ച് നൽകാൻ തുടങ്ങി. (ബു,മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ، وَطُعْمَةً لِلْمَسَاكِينِ، فَمَنْ أَدَّاهَا قَبْلَ الصَّلَاةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ، وَمَنْ أَدَّاهَا بَعْدَ الصَّلَاةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നോമ്പുകാരൻ അശ്ലീലങ്ങളിൽനിന്നും വ്യർത്ഥ വാക്കുകളിൽനിന്നും പരിശുദ്ധിയാകാൻ വേണ്ടിയും, പാവപ്പെട്ടവർക്ക് ഭക്ഷണം ലഭിക്കാൻ വേണ്ടിയും ഫിത്ർ സകാത്ത് റസൂൽ(സ) നിർബന്ധമാക്കി. വല്ലവനും അതിനെ പെരുന്നാൾ നമസ്കാരത്തിന് മുമ്പ് നൽകിയാൽ അത് സ്വീകാര്യമായ ഫിത്ർസകാത്തായി കണക്കാക്കപ്പെടും. എന്നാൽ ആരെങ്കിലും അത് നമസ്കാരത്തിന് ശേഷം നൽകിയാൽ അത് സ്വദഖഃകളിൽ പെട്ട ഒന്നായി ഗണിക്കപ്പെടും. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ سَعْدِ بْنِ عَائِذٍ رَضِيَ اللهُ عَنْهُ، مُؤَذِّنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِصَدَقَةِ الْفِطْرِ: صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ سُلْتٍ. (جه)', 'തിരുമേനി(സ)യുടെ മുഅദ്ദിനായ സഅ്ദുബ്നു ആഇദ്(റ): റസൂൽ(സ) ഒരു സ്വാഅ് കാരക്ക, അല്ലെങ്കിൽ ഒരു സ്വാഅ് ബാർലി, അതുമല്ലെങ്കിൽ ഒരു സ്വാഅ് വെളുത്ത, തൊലിയില്ലാത്ത ബാർലി എന്നീ തോതിൽ ഫിത്ർ സകാത്ത് നൽകാൻ കൽപ്പിച്ചു. (ജ)', 'سَعْدِ بْنِ عَائِذٍ', 'തിരുമേനി(സ)യുടെ മുഅദ്ദിനായ സഅ്ദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الصَّاعُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُدًّا وَثُلُثًا، بِمُدِّكُمُ الْيَوْمَ، وَقَدْ زِيدَ فِيهِ. (خ,ن)', 'സാഇബുബ്നു യസീദ്(റ): റസൂൽ(സ) യുടെ കാലത്തുള്ള സ്വാഅ് എന്നത് ഒരു ''മുദ്ദി''നും അതിന്റെ മൂന്നിൽ ഒന്നിനും തുല്യമായതാണ്. അതായത് ഇന്ന് നിങ്ങൾ കണക്കാക്കുന്ന മുദ്ദും അതിനേക്കാൾ അൽപം കൂടുതലും. (ബു,ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمِكْيَالُ مِكْيَالُ أَهْلِ الْمَدِينَةِ، وَالْوَزْنُ وَزْنُ أَهْلِ مَكَّةَ". (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അളവ് കണക്കാക്കേണ്ടത് മദീനക്കാരുടെ അളവനുസരിച്ചാണ്, തൂക്കം മക്കക്കാരുടെ കണക്ക് അനുസരിച്ചും." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِزَكَاةِ الْفِطْرِ أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ. قَالَ: فَكَانَ ابْنُ عُمَرَ يُؤَدِّيهَا قَبْلَ ذَلِكَ بِالْيَوْمِ وَالْيَوْمَيْنِ. (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): ജനങ്ങൾ നമസ്കാരത്തിനു വേണ്ടി പുറപ്പെടുന്നതിനു മുമ്പുതന്നെ ഫിത്റ് സകാത്ത് കൊടുത്തുവീട്ടാൻ ഞങ്ങളോട് റസൂൽ(സ) കൽപിച്ചിരുന്നു. ഇബ്നുഉമർ(റ) അതിന്റെ ഒന്നോ രണ്ടോ ദിവസങ്ങൾ മുമ്പുതന്നെ അത് നൽകിയിരുന്നു. (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَصُومُ عَاشُورَاءَ وَنُؤَدِّي زَكَاةَ الْفِطْرِ، فَلَمَّا نَزَلَ رَمَضَانُ وَنَزَلَتِ الزَّكَاةُ لَمْ نُؤْمَرْ بِهِ وَلَمْ نُنْهَ عَنْهُ، وَكُنَّا نَفْعَلُهُ. وفي روايةٍ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَدَقَةِ الْفِطْرِ قَبْلَ أَنْ تَنْزِلَ الزَّكَاةُ فَلَمَّا نَزَلَتِ الزَّكَاةُ، لَمْ يَأْمُرْنَا وَلَمْ يَنْهَنَا، وَنَحْنُ نَفْعَلُهُ. (ن,جه)', 'ഖൈസുബ്നു സഅ്ദിബ്നി ഉബാദ(റ): ഞങ്ങൾ ആശൂറാഅ് നോമ്പെടുക്കുകയും സകാതുൽ ഫിത്ർ നൽകുകയും ചെയ്യാറുണ്ടിയിരുന്നു. അങ്ങനെ സകാത്ത് നിർബ്ബന്ധമാക്കിക്കൊണ്ടുള്ള ആയത്ത് ഇറങ്ങുകയും റമദാൻ വന്നെത്തുകയും ചെയ്തപ്പോൾ ഫിത്ർ സകാത്ത് നൽകാൻ ഞങ്ങളോട് കൽപ്പിക്കപ്പെടുകയോ നിരോധിക്കപ്പെടുകയോ ചെയ്തില്ല. ഞങ്ങൾ അത് നൽകും. മറ്റൊരു റിപ്പോർട്ടിൽ: സകാത്ത് നിർബ്ബന്ധമാക്കിക്കൊണ്ട് ആയത്തിറങ്ങും മുമ്പ് റസൂൽ(സ) ഞങ്ങളോട് സകാത്തുൽ ഫിത്ർ നൽകാൻ കൽപിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ സകാത്തിന്റെ ആയത്തിറങ്ങിയപ്പോൾ, ഞങ്ങളോട് ഫിത്ർ സകാത്ത് നൽകാൻ കൽപിക്കുകയോ നൽകേണ്ടെന്ന് വിലക്കുകയോ ചെയ്തില്ല. ഞങ്ങൾ അത് നൽകിക്കൊണ്ടിരുന്നു. (ന,ജ)', 'قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ', 'ഖൈസുബ്നു സഅ്ദിബ്നി ഉബാദ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=3 and h.hadith_no=337), 1, 'وَفِي رِوَايَةٍ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَدَقَةِ الْفِطْرِ قَبْلَ أَنْ تَنْزِلَ الزَّكَاةُ فَلَمَّا نَزَلَتِ الزَّكَاةُ، لَمْ يَأْمُرْنَا وَلَمْ يَنْهَنَا، وَنَحْنُ نَفْعَلُهُ. (ن,جه)', 'മറ്റൊരു നിവേദനിൽ: സകാത്ത് നിർബ്ബന്ധമാക്കിക്കൊണ്ട് ആയത്തിറങ്ങും മുമ്പ് റസൂൽ(സ) ഞങ്ങളോട് സകാത്തുൽ ഫിത്ർ നൽകാൻ കൽപിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ സകാത്തിന്റെ ആയത്തിറങ്ങിയപ്പോൾ, ഞങ്ങളോട് ഫിത്ർ സകാത്ത് നൽകാൻ കൽപിക്കുകയോ നൽകേണ്ടെന്ന് വിലക്കുകയോ ചെയ്തില്ല. ഞങ്ങൾ അത് നൽകിക്കൊണ്ടിരുന്നു. (ന,ജ)');
